    void drain_ratox_events_best_effort(bool publish) {
        if (ratox_service_ == nullptr) {
            refresh_ratox_snapshot_best_effort();
            return;
        }
        std::vector<interactive::RatoxServiceEvent> events =
            ratox_service_->drain_events();
        for (const interactive::RatoxServiceEvent &event : events) {
            ratox_event_count_ = std::max(ratox_event_count_, event.ordinal);
            const Status appended = runtime_.append_ratox_event(event);
            if (!appended.ok()) {
                record_projection_failure(appended);
            }
        }
        refresh_ratox_snapshot_best_effort();
        if (!events.empty()) {
            const interactive::RatoxServiceEvent &last = events.back();
            {
                std::scoped_lock lock(snapshot_mutex_);
                snapshot_.last_event =
                    "ratox-" + std::string(interactive::to_string(last.kind)) +
                    " friend=" + std::to_string(last.friend_number) +
                    " epoch=" + std::to_string(last.online_epoch);
            }
            if (publish) {
                publish_snapshot_best_effort();
            }
            record_diagnostic_best_effort(
                diagnostics::EventClass::ratox_state,
                events.back().error_code);
        }
    }

    Result<interactive::RatoxClientRoute> ratox_client_route(
        std::uint32_t friend_number) const {
        if (ratox_client_ == nullptr || authority_sessions_ == nullptr) {
            return Status{ErrorCode::unsupported,
                          "Ratox terminal client is not active"};
        }
        auto session = sessions_.get(friend_number);
        if (!session) return session.status();
        if (!protocol::is_application_ready(session.value()) ||
            !ratox_interactive_negotiated(session.value())) {
            return Status{ErrorCode::unavailable,
                          "Ratox peer route is not application-ready with feature 23"};
        }
        auto authority = authority_sessions_->get(friend_number);
        if (!authority) return authority.status();
        if (authority.value().online_epoch != session.value().online_epoch ||
            authority.value().claimant_state !=
                security::AuthorityClaimantState::proof_sent ||
            empty_principal(authority.value().local_claimant_principal)) {
            return Status{
                ErrorCode::unavailable,
                "Ratox peer has no authenticated local claimant for this "
                "online epoch"};
        }

        interactive::RatoxClientRoute route;
        route.friend_number = friend_number;
        route.online_epoch = session.value().online_epoch;
        route.principal_id = authority.value().local_claimant_principal;
        route.transcript_confirmed = true;
        route.feature_negotiated = true;
        route.claimant_authenticated = true;
        return route;
    }

    static constexpr std::size_t kMaximumPendingTerminalPackets = 1024U;

    void clear_terminal_packets_locked() noexcept {
        for (local::TerminalPacket &packet : terminal_packets_) {
            security::secure_wipe(packet.payload);
        }
        terminal_packets_.clear();
    }

    void fail_terminal_queue_locked(std::string detail) {
        if (terminal_stream_id_ == 0U || terminal_queue_failed_) return;
        clear_terminal_packets_locked();
        terminal_queue_failed_ = true;
        if (detail.empty()) {
            detail = "Ratox local terminal delivery queue failed";
        }
        if (detail.size() > 1024U) detail.resize(1024U);
        local::TerminalPacket packet;
        packet.type = local::TerminalPacketType::error;
        packet.stream_id = terminal_stream_id_;
        packet.status = ErrorCode::resource_exhausted;
        packet.payload.assign(detail.begin(), detail.end());
        // The queue was just cleared, so this explicit terminal failure cannot
        // itself exceed the packet-count bound.
        terminal_packets_.push_back(std::move(packet));
    }

    [[nodiscard]] bool queue_terminal_packet_locked(
        local::TerminalPacket packet) {
        if (terminal_stream_id_ == 0U || terminal_queue_failed_) {
            security::secure_wipe(packet.payload);
            return false;
        }
        packet.stream_id = terminal_stream_id_;
        if (terminal_packets_.size() >= kMaximumPendingTerminalPackets) {
            security::secure_wipe(packet.payload);
            fail_terminal_queue_locked(
                "Ratox local terminal delivery queue exhausted; the stream was "
                "aborted rather than dropping output");
            return false;
        }
        terminal_packets_.push_back(std::move(packet));
        return true;
    }

    void queue_terminal_error_locked(ErrorCode code, std::string detail) {
        local::TerminalPacket packet;
        packet.type = local::TerminalPacketType::error;
        packet.status = code == ErrorCode::ok ? ErrorCode::internal_error : code;
        if (detail.empty()) detail = "Ratox terminal request failed";
        if (detail.size() > 1024U) detail.resize(1024U);
        packet.payload.assign(detail.begin(), detail.end());
        static_cast<void>(queue_terminal_packet_locked(std::move(packet)));
    }

    [[nodiscard]] bool stage_terminal_output_locked() {
        if (ratox_client_ == nullptr || terminal_stream_id_ == 0U ||
            terminal_queue_failed_) {
            return false;
        }
        if (!terminal_opened_sent_) return true;
        while (terminal_packets_.size() < kMaximumPendingTerminalPackets) {
            auto replay = ratox_client_->read_output(
                terminal_output_cursor_, local::kTerminalMaxPayloadSize);
            if (!replay) {
                const interactive::RatoxClientSnapshot snapshot =
                    ratox_client_->snapshot();
                if (replay.status().code() == ErrorCode::not_found &&
                    terminal_output_cursor_ < snapshot.output.base_sequence) {
                    fail_terminal_queue_locked(
                        "Ratox local terminal output cursor fell behind "
                        "retained replay "
                        "without an ordered gap event");
                }
                return false;
            }
            if (replay.value().bytes.empty()) return true;
            local::TerminalPacket output;
            output.type = local::TerminalPacketType::output;
            output.sequence = replay.value().first_sequence;
            output.payload = std::move(replay).value().bytes;
            const std::uint64_t next = output.sequence +
                static_cast<std::uint64_t>(output.payload.size());
            if (!queue_terminal_packet_locked(std::move(output))) return false;
            terminal_output_cursor_ = next;
        }
        fail_terminal_queue_locked(
            "Ratox local terminal delivery queue exhausted while staging output");
        return false;
    }

    Status begin_local_terminal_locked(
        const local::TerminalOpenRequest &request,
        std::uint64_t stream_id) {
        if (ratox_client_ == nullptr) {
            return Status{ErrorCode::unsupported,
                          "Ratox terminal client is disabled"};
        }
        if (terminal_stream_id_ != 0U) {
            return Status{ErrorCode::resource_exhausted,
                          "another local terminal stream is already active"};
        }

        const bool peer_unspecified = std::all_of(
            request.peer_public_key.begin(), request.peer_public_key.end(),
            [](std::uint8_t byte) { return byte == 0U; });
        const bool session_unspecified = std::all_of(
            request.session_id.begin(), request.session_id.end(),
            [](std::uint8_t byte) { return byte == 0U; });
        const interactive::RatoxClientSnapshot existing =
            ratox_client_->snapshot();

        std::optional<std::uint32_t> friend_number;
        if (!peer_unspecified) {
            friend_number = friend_number_for_public_key(
                security::hex(request.peer_public_key));
        } else if (existing.peer_present) {
            friend_number = existing.peer_friend_number;
        }
        if (!friend_number) {
            return Status{ErrorCode::not_found,
                          "Ratox terminal peer is not present in the live friend map"};
        }

        auto route = ratox_client_route(*friend_number);
        if (!route) return route.status();
        auto attachment_nonce = security::random_nonce_128();
        if (!attachment_nonce) return attachment_nonce.status();

        Status started;
        const bool request_resume =
            request.mode == local::TerminalOpenMode::resume_only ||
            (request.mode == local::TerminalOpenMode::open_or_resume &&
             !session_unspecified);
        if (request_resume) {
            if (session_unspecified || existing.session_id != request.session_id) {
                return Status{ErrorCode::not_found,
                              "requested Ratox detached session is not retained locally"};
            }
            if (!ratox_controller_peer_public_key_) {
                return Status{ErrorCode::unavailable,
                              "Ratox retained session lost its stable peer identity"};
            }
            if (!peer_unspecified &&
                request.peer_public_key !=
                    *ratox_controller_peer_public_key_) {
                return Status{ErrorCode::unavailable,
                              "Ratox resume cannot change stable peer identity"};
            }
            if (!existing.peer_present ||
                existing.peer_friend_number != route.value().friend_number ||
                existing.principal_id != route.value().principal_id) {
                return Status{ErrorCode::unavailable,
                              "Ratox resume cannot change peer or authenticated principal"};
            }
            static_cast<void>(ratox_client_->drain_events());
            started = ratox_client_->begin_resume(
                route.value(), attachment_nonce.value());
        } else {
            auto session_id = security::random_nonce_128();
            if (!session_id) return session_id.status();
            ratox_client_->reset();
            started = ratox_client_->begin_open(
                route.value(), session_id.value(), attachment_nonce.value(),
                request.columns, request.rows);
        }
        if (!started.ok()) return started;
        if (!request_resume) {
            ratox_controller_peer_public_key_ = request.peer_public_key;
        }

        terminal_stream_id_ = stream_id;
        terminal_output_cursor_ = ratox_client_->snapshot().output.base_sequence;
        terminal_opened_sent_ = false;
        terminal_queue_failed_ = false;
        clear_terminal_packets_locked();
        return Status::success();
    }

    Status handle_terminal_packet(
        const local::TerminalPacket &packet,
        const local::PeerCredentials &credentials) {
        if (credentials.user_id != static_cast<std::uint64_t>(::geteuid())) {
            return Status{ErrorCode::unavailable,
                          "local terminal peer credential is not the agent user"};
        }
        std::unique_lock authority_lock(ratox_authority_effect_mutex_);
        std::scoped_lock client_lock(ratox_client_mutex_);

        if (packet.type == local::TerminalPacketType::open) {
            auto request = local::decode_terminal_open(packet.payload);
            if (!request) return request.status();
            const Status opened = begin_local_terminal_locked(
                request.value(), packet.stream_id);
            if (opened.ok()) notify_ratox_service();
            return opened;
        }
        if (terminal_stream_id_ == 0U || packet.stream_id != terminal_stream_id_) {
            return Status{ErrorCode::protocol_error,
                          "local terminal packet does not match the active stream"};
        }
        if (ratox_client_ == nullptr) {
            return Status{ErrorCode::unsupported,
                          "Ratox terminal client is disabled"};
        }

        switch (packet.type) {
            case local::TerminalPacketType::input: {
                const interactive::RatoxClientSnapshot snapshot =
                    ratox_client_->snapshot();
                if (packet.sequence != snapshot.input.next_sequence) {
                    return Status{ErrorCode::protocol_error,
                                  "local terminal input sequence is not the exact next byte"};
                }
                const Status queued =
                    ratox_client_->enqueue_input(packet.payload);
                if (queued.ok()) notify_ratox_service();
                return queued;
            }
            case local::TerminalPacketType::resize: {
                const Status resized = ratox_client_->resize(
                    read_u16(packet.payload, 0U), read_u16(packet.payload, 2U));
                if (resized.ok()) notify_ratox_service();
                return resized;
            }
            case local::TerminalPacketType::output_ack: {
                if (packet.sequence > terminal_output_cursor_) {
                    return Status{ErrorCode::protocol_error,
                                  "local terminal acknowledged output that was not delivered"};
                }
                const Status acknowledged =
                    ratox_client_->acknowledge_output(packet.sequence);
                if (acknowledged.ok()) notify_ratox_service();
                return acknowledged;
            }
            case local::TerminalPacketType::detach: {
                const Status detached = ratox_client_->detach();
                if (detached.ok()) notify_ratox_service();
                return detached;
            }
            case local::TerminalPacketType::close: {
                const Status closed = ratox_client_->close();
                if (closed.ok()) notify_ratox_service();
                return closed;
            }
            case local::TerminalPacketType::ping: {
                // Local PING is an end-to-end attachment heartbeat. The
                // controller reuses one exact remote Ratox PING for this
                // attachment, and translate_terminal_client_events_locked()
                // emits PONG only after the correlated remote PONG returns.
                const Status pinged = ratox_client_->ping();
                if (pinged.ok()) notify_ratox_service();
                return pinged;
            }
            case local::TerminalPacketType::open:
            case local::TerminalPacketType::opened:
            case local::TerminalPacketType::output:
            case local::TerminalPacketType::output_gap:
            case local::TerminalPacketType::exit_status:
            case local::TerminalPacketType::detached:
            case local::TerminalPacketType::closed:
            case local::TerminalPacketType::error:
            case local::TerminalPacketType::pong:
                return Status{ErrorCode::protocol_error,
                              "local terminal client sent a server-only packet type"};
        }
        return Status{ErrorCode::protocol_error,
                      "local terminal packet type is impossible"};
    }

    void translate_terminal_client_events_locked() {
        if (ratox_client_ == nullptr || terminal_stream_id_ == 0U ||
            terminal_queue_failed_) {
            return;
        }
        for (const interactive::RatoxClientEvent &event :
             ratox_client_->drain_events()) {
            if (terminal_queue_failed_) break;
            local::TerminalPacket packet;
            switch (event.kind) {
                case interactive::RatoxClientEventKind::opened:
                case interactive::RatoxClientEventKind::resumed: {
                    const interactive::RatoxClientSnapshot snapshot =
                        ratox_client_->snapshot();
                    local::TerminalOpened opened;
                    opened.session_id = snapshot.session_id;
                    opened.incarnation = snapshot.incarnation;
                    opened.generation = snapshot.generation;
                    opened.next_input_sequence = snapshot.input.next_sequence;
                    opened.next_output_sequence = snapshot.output.base_sequence;
                    terminal_output_cursor_ = opened.next_output_sequence;
                    auto payload = local::encode_terminal_opened(opened);
                    if (!payload) {
                        queue_terminal_error_locked(
                            payload.status().code(), payload.status().message());
                        continue;
                    }
                    packet.type = local::TerminalPacketType::opened;
                    packet.payload = std::move(payload).value();
                    if (!queue_terminal_packet_locked(std::move(packet))) break;
                    terminal_opened_sent_ = true;
                    // On RESUME, locally retained unacknowledged output must be
                    // delivered only after OPENED establishes its byte cursor.
                    static_cast<void>(stage_terminal_output_locked());
                    break;
                }
                case interactive::RatoxClientEventKind::output_available:
                    // Stage bytes at the exact event position. This guarantees
                    // OUTPUT precedes a later EXIT_STATUS or DETACHED event,
                    // even when both are drained in one server cycle.
                    static_cast<void>(stage_terminal_output_locked());
                    break;
                case interactive::RatoxClientEventKind::output_gap: {
                    // GAP is itself the ordered discontinuity. In particular,
                    // RESUME_RESULT may advance the replay base before OPENED;
                    // attempting to read the superseded cursor here would turn
                    // a valid remote gap into a local queue failure.
                    local::TerminalOutputGap gap;
                    gap.retained_base_sequence = event.sequence;
                    gap.produced_next_sequence = event.acknowledgement;
                    terminal_output_cursor_ = event.sequence;
                    auto payload = local::encode_terminal_output_gap(gap);
                    if (!payload) {
                        queue_terminal_error_locked(
                            payload.status().code(), payload.status().message());
                        continue;
                    }
                    packet.type = local::TerminalPacketType::output_gap;
                    packet.payload = std::move(payload).value();
                    static_cast<void>(
                        queue_terminal_packet_locked(std::move(packet)));
                    break;
                }
                case interactive::RatoxClientEventKind::detached:
                    static_cast<void>(stage_terminal_output_locked());
                    packet.type = local::TerminalPacketType::detached;
                    static_cast<void>(
                        queue_terminal_packet_locked(std::move(packet)));
                    break;
                case interactive::RatoxClientEventKind::route_lost:
                case interactive::RatoxClientEventKind::error:
                    static_cast<void>(stage_terminal_output_locked());
                    queue_terminal_error_locked(
                        event.error_code == ErrorCode::ok
                            ? ErrorCode::unavailable
                            : event.error_code,
                        event.detail);
                    break;
                case interactive::RatoxClientEventKind::exit_status: {
                    static_cast<void>(stage_terminal_output_locked());
                    local::TerminalExitStatus exit;
                    exit.kind = event.exit_kind;
                    exit.core_dumped = event.core_dumped;
                    exit.signal = event.signal;
                    exit.code = event.exit_code;
                    auto payload = local::encode_terminal_exit_status(exit);
                    if (!payload) {
                        queue_terminal_error_locked(
                            payload.status().code(), payload.status().message());
                        continue;
                    }
                    packet.type = local::TerminalPacketType::exit_status;
                    packet.payload = std::move(payload).value();
                    static_cast<void>(
                        queue_terminal_packet_locked(std::move(packet)));
                    break;
                }
                case interactive::RatoxClientEventKind::closed:
                    static_cast<void>(stage_terminal_output_locked());
                    packet.type = local::TerminalPacketType::closed;
                    static_cast<void>(
                        queue_terminal_packet_locked(std::move(packet)));
                    break;
                case interactive::RatoxClientEventKind::pong:
                    packet.type = local::TerminalPacketType::pong;
                    static_cast<void>(
                        queue_terminal_packet_locked(std::move(packet)));
                    break;
            }
        }
    }

    std::vector<local::TerminalPacket> drain_terminal_packets(
        std::uint64_t stream_id, std::size_t maximum_packets) {
        std::scoped_lock client_lock(ratox_client_mutex_);
        std::vector<local::TerminalPacket> packets;
        if (ratox_client_ == nullptr || terminal_stream_id_ == 0U ||
            stream_id != terminal_stream_id_ || maximum_packets == 0U) {
            return packets;
        }
        packets.reserve(maximum_packets);
        translate_terminal_client_events_locked();
        static_cast<void>(stage_terminal_output_locked());
        while (!terminal_packets_.empty() && packets.size() < maximum_packets) {
            packets.push_back(std::move(terminal_packets_.front()));
            terminal_packets_.pop_front();
        }
        return packets;
    }

    void handle_terminal_disconnect(
        std::uint64_t stream_id,
        const local::PeerCredentials &) {
        std::unique_lock authority_lock(ratox_authority_effect_mutex_);
        std::scoped_lock client_lock(ratox_client_mutex_);
        if (stream_id == 0U || stream_id != terminal_stream_id_) return;
        if (ratox_client_ != nullptr) {
            const interactive::RatoxClientState state =
                ratox_client_->snapshot().state;
            if (state == interactive::RatoxClientState::opening ||
                state == interactive::RatoxClientState::attached ||
                state == interactive::RatoxClientState::resuming ||
                state == interactive::RatoxClientState::closing) {
                static_cast<void>(ratox_client_->detach());
            }
        }
        clear_terminal_packets_locked();
        terminal_stream_id_ = 0U;
        terminal_output_cursor_ = 1U;
        terminal_opened_sent_ = false;
        terminal_queue_failed_ = false;
        notify_ratox_service();
    }

    void ratox_client_peer_offline_locked(
        std::uint32_t friend_number, std::uint64_t online_epoch) {
        ratox_retained_send_telemetry_.clear(
            interactive::RetainedSendLane::controller);
        if (ratox_client_ == nullptr || online_epoch == 0U) return;
        const Status detached = ratox_client_->peer_offline(
            friend_number, online_epoch);
        translate_terminal_client_events_locked();
        if (!detached.ok() && detached.code() != ErrorCode::not_found) {
            record_projection_failure(Status{
                detached.code(),
                "Ratox controller online-epoch detachment failed: " +
                    detached.message()});
        }
    }

    void service_ratox_client_locked() {
        if (ratox_client_ == nullptr) {
            ratox_retained_send_telemetry_.clear(
                interactive::RetainedSendLane::controller);
            return;
        }
        const Status progressed = ratox_client_->service();
        if (!progressed.ok()) {
            record_projection_failure(Status{
                progressed.code(),
                "Ratox controller service failed: " + progressed.message()});
        }

        if (ratox_pending_close_session_) {
            const interactive::RatoxClientSnapshot pending =
                ratox_client_->snapshot();
            if (pending.session_id != *ratox_pending_close_session_ ||
                pending.state == interactive::RatoxClientState::idle ||
                pending.state == interactive::RatoxClientState::detached ||
                pending.state == interactive::RatoxClientState::exited ||
                pending.state == interactive::RatoxClientState::failed) {
                ratox_pending_close_session_.reset();
            } else if (pending.state ==
                       interactive::RatoxClientState::attached) {
                const Status closed = ratox_client_->close();
                if (!closed.ok()) {
                    record_projection_failure(Status{
                        closed.code(),
                        "Ratox queued lifecycle close failed: " +
                            closed.message()});
                }
                ratox_pending_close_session_.reset();
            }
        }

        std::size_t sends = 0U;
        while (sends < kRatoxMaximumTransportSendsPerCycle) {
            const interactive::RatoxClientOutboundPacket *outbound =
                ratox_client_->peek_outbound();
            if (outbound == nullptr) {
                ratox_retained_send_telemetry_.clear(
                    interactive::RetainedSendLane::controller);
                break;
            }
            auto current = ratox_client_route(outbound->friend_number);
            const bool route_current = current &&
                current.value().online_epoch == outbound->online_epoch &&
                current.value().principal_id == outbound->principal_id;
            if (!route_current) {
                ratox_client_peer_offline_locked(
                    outbound->friend_number, outbound->online_epoch);
                ++sends;
                continue;
            }
            const std::uint32_t friend_number = outbound->friend_number;
            const std::uint64_t online_epoch = outbound->online_epoch;
            const Status queued = transport_.send_sensitive_lossless(
                friend_number, outbound->bytes(),
                ratox_client_transport_class(outbound->type));
            if (queued.ok()) {
                ratox_retained_send_telemetry_.clear(
                    interactive::RetainedSendLane::controller);
                const Status popped = ratox_client_->pop_outbound();
                if (!popped.ok()) {
                    record_projection_failure(popped);
                    break;
                }
                ++sends;
                continue;
            }
            if (retryable_protocol_send_error(queued.code())) {
                ratox_retained_send_telemetry_.observe_retryable(
                    interactive::RetainedSendLane::controller);
                break;
            }
            ratox_retained_send_telemetry_.clear(
                interactive::RetainedSendLane::controller);
            record_projection_failure(Status{
                queued.code(),
                "Ratox transport rejected a retained controller packet: " +
                    queued.message()});
            ratox_client_peer_offline_locked(friend_number, online_epoch);
            ++sends;
        }
        if (sends != 0U) {
            // A terminal controller observes remote OUTPUT before this event
            // thread necessarily reaches another publish-worthy transport
            // event.  Under sustained file traffic, relying on a later event
            // can leave the exact interactive execution/queue counters stale
            // for seconds even though INPUT or OUTPUT_ACK already completed.
            // Commit the counters at their admission boundary so R7 evidence
            // never depends on unrelated bulk projection cadence.
            refresh_ratox_snapshot_best_effort();
            publish_snapshot_best_effort();
        }
        if (terminal_server_ != nullptr) terminal_server_->notify();
    }

    Result<interactive::RatoxPeerContext> ratox_peer_context(
        std::uint32_t friend_number) {
        if (ratox_service_ == nullptr || authority_sessions_ == nullptr ||
            authority_ == nullptr) {
            return Status{ErrorCode::unsupported,
                          "Ratox terminal service is not active"};
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        if (!protocol::is_application_ready(session.value())) {
            return Status{ErrorCode::unavailable,
                          "Ratox packet arrived outside a confirmed IoTox session"};
        }
        if (!ratox_interactive_negotiated(session.value())) {
            return Status{ErrorCode::unsupported,
                          "Ratox feature bit 23 is not negotiated for this online epoch"};
        }
        auto authority_session = authority_sessions_->get(friend_number);
        if (!authority_session) {
            return authority_session.status();
        }
        if (authority_session.value().online_epoch !=
            session.value().online_epoch) {
            return Status{ErrorCode::unavailable,
                          "Ratox authority state belongs to a different online epoch"};
        }

        const security::AuthoritySnapshot authority = authority_->snapshot();
        const std::uint64_t terminal_capability =
            static_cast<std::uint64_t>(
                security::Capability::interactive_terminal);
        const bool authorized = authority_sessions_->authorized_at(
            friend_number, terminal_capability, authority);

        interactive::PrincipalId principal =
            authority_session.value().remote_principal;
        if (!empty_principal(principal)) {
            // Authentication is epoch-scoped and survives a later authority
            // head change solely so the host can return an explicit bounded
            // DENIED result. This map is never consulted for PTY effects.
            ratox_authenticated_routes_.insert_or_assign(
                friend_number,
                RatoxPrincipalRoute{
                    session.value().online_epoch, principal});
        } else {
            const auto remembered =
                ratox_authenticated_routes_.find(friend_number);
            if (remembered != ratox_authenticated_routes_.end() &&
                remembered->second.online_epoch ==
                    session.value().online_epoch) {
                principal = remembered->second.principal_id;
            }
        }
        if (empty_principal(principal)) {
            return Status{ErrorCode::unavailable,
                          "Ratox packet has no authenticated principal for this online epoch"};
        }
        if (authorized) {
            ratox_authority_routes_.insert_or_assign(
                friend_number,
                RatoxPrincipalRoute{
                    session.value().online_epoch, principal});
        } else {
            ratox_authority_routes_.erase(friend_number);
        }

        interactive::RatoxPeerContext peer;
        peer.friend_number = friend_number;
        peer.online_epoch = session.value().online_epoch;
        peer.principal_id = principal;
        peer.transcript_confirmed = true;
        peer.feature_negotiated = true;
        peer.terminal_authorized = authorized;
        return peer;
    }

    void inspect_incoming_ratox(const TransportEvent &event) {
        if (event.data.empty() ||
            event.data.front() != protocol::ratox::kPacketId) {
            return;
        }
        // A signed authority-head mutation and one Ratox effect admission are
        // a single ordered boundary. Both request-side PTY effects and
        // response-side controller state are fenced to the exact online epoch.
        std::unique_lock authority_effect_lock(
            ratox_authority_effect_mutex_);

        auto decoded = protocol::ratox::decode(event.data);
        if (decoded && ratox_client_ != nullptr &&
            interactive::is_ratox_client_inbound(decoded.value().type)) {
            auto route = ratox_client_route(event.friend_number);
            Status accepted{ErrorCode::unsupported,
                            "Ratox terminal client is not active"};
            if (route) {
                std::scoped_lock client_lock(ratox_client_mutex_);
                accepted = ratox_client_->receive(route.value(), event.data);
                // Project each controller event into the bounded local queue
                // before another remote frame can reorder terminal metadata
                // ahead of the output that caused it.
                translate_terminal_client_events_locked();
            } else {
                accepted = route.status();
            }
            if (!accepted.ok()) {
                std::scoped_lock lock(snapshot_mutex_);
                snapshot_.last_event =
                    "rejected Ratox controller packet friend=" +
                    std::to_string(event.friend_number) + " detail=" +
                    accepted.message();
            }
            if (terminal_server_ != nullptr) terminal_server_->notify();
            return;
        }

        auto peer = ratox_peer_context(event.friend_number);
        if (!peer) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected Ratox packet friend=" +
                std::to_string(event.friend_number) + " detail=" +
                peer.status().message();
            return;
        }
        const Status accepted = ratox_service_->receive(
            peer.value(), event.data, std::chrono::steady_clock::now());
        if (!accepted.ok()) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected Ratox packet friend=" +
                std::to_string(event.friend_number) + " detail=" +
                accepted.message();
        }
        drain_ratox_events_best_effort(true);
    }

    // Requires ratox_authority_effect_mutex_. RatoxService deliberately has
    // one Agent owner; route erasure, PTY detachment, client detachment, and
    // event projection must therefore be one ordered transition rather than
    // independent map/service operations on the event and control threads.
    void ratox_peer_offline_locked(
        std::uint32_t friend_number, std::uint64_t online_epoch) {
        ratox_retained_send_telemetry_.clear_all_active();
        ratox_authority_routes_.erase(friend_number);
        ratox_authenticated_routes_.erase(friend_number);
        if (online_epoch == 0U) return;
        if (ratox_service_ != nullptr) {
            const Status detached = ratox_service_->peer_offline(
                friend_number, online_epoch, std::chrono::steady_clock::now());
            if (!detached.ok() && detached.code() != ErrorCode::not_found) {
                record_projection_failure(Status{
                    detached.code(),
                    "Ratox online-epoch detachment failed: " +
                        detached.message()});
            }
            drain_ratox_events_best_effort(true);
        }
        {
            std::scoped_lock client_lock(ratox_client_mutex_);
            ratox_client_peer_offline_locked(friend_number, online_epoch);
        }
        if (terminal_server_ != nullptr) terminal_server_->notify();
    }

    void ratox_peer_offline_best_effort(
        std::uint32_t friend_number, std::uint64_t online_epoch) {
        std::scoped_lock authority_effect_lock(
            ratox_authority_effect_mutex_);
        ratox_peer_offline_locked(friend_number, online_epoch);
    }

    void service_ratox_best_effort() {
        if (ratox_service_ == nullptr && ratox_client_ == nullptr) {
            ratox_retained_send_telemetry_.clear_all_active();
            return;
        }
        // Keep authority-head replacement, bounded PTY progress, and retained
        // transport admission in one total order. Mutations that complete
        // before this cycle are reconciled before effects; mutations that
        // complete after it cannot retroactively invalidate already admitted
        // packets or PTY operations.
        // A synchronization worker may retain the authority-effect boundary
        // while it verifies and offers an object. Periodic Ratox progress is
        // best-effort, so waiting here would stall the sole transport event
        // pump and prevent it from observing the bounded sync queue. Skipping
        // this tick preserves the same total order: no Ratox effect occurs
        // until the current authority-bound effect releases the mutex.
        std::unique_lock authority_effect_lock(
            ratox_authority_effect_mutex_, std::try_to_lock);
        if (!authority_effect_lock.owns_lock()) return;
        const auto now = std::chrono::steady_clock::now();

        {
            std::scoped_lock client_lock(ratox_client_mutex_);
            service_ratox_client_locked();
        }
        if (ratox_service_ == nullptr) {
            ratox_retained_send_telemetry_.clear(
                interactive::RetainedSendLane::host);
            refresh_ratox_snapshot_best_effort();
            return;
        }

        if (authority_sessions_ != nullptr && authority_ != nullptr) {
            const security::AuthoritySnapshot current_authority =
                authority_->snapshot();
            const std::uint64_t terminal_capability =
                static_cast<std::uint64_t>(
                    security::Capability::interactive_terminal);

            // A transport route disappears when a peer goes offline, but the
            // corresponding PTY may intentionally remain detached for RESUME.
            // Reconcile those durable principal owners whenever the signed
            // authority head changes so an offline revocation cannot leave a
            // process alive until the peer reconnects.
            if (!ratox_authority_checked_tail_ ||
                *ratox_authority_checked_tail_ !=
                    current_authority.tail_digest) {
                for (const interactive::PrincipalId &principal_id :
                     ratox_service_->live_principals()) {
                    if (authority_->authorized(
                            principal_id, terminal_capability)) {
                        continue;
                    }
                    const Status revoked =
                        ratox_service_->principal_revoked(principal_id, now);
                    if (!revoked.ok() &&
                        revoked.code() != ErrorCode::not_found &&
                        revoked.code() != ErrorCode::unavailable) {
                        record_projection_failure(Status{
                            revoked.code(),
                            "Ratox detached-principal revocation failed: " +
                                revoked.message()});
                    }
                }

                // Do not cache an authority head that changed during the
                // reconciliation. A concurrent append is retried on the next
                // bounded event-loop cycle against its new exact digest.
                const security::AuthoritySnapshot verified_authority =
                    authority_->snapshot();
                if (verified_authority.tail_digest ==
                    current_authority.tail_digest) {
                    ratox_authority_checked_tail_ =
                        verified_authority.tail_digest;
                }
            }

            for (const security::PeerAuthoritySnapshot &authority_session :
                 authority_sessions_->list()) {
                auto session = sessions_.get(authority_session.friend_number);
                if (!session ||
                    session.value().online_epoch !=
                        authority_session.online_epoch ||
                    !ratox_interactive_negotiated(session.value())) {
                    continue;
                }
                if (!empty_principal(authority_session.remote_principal)) {
                    ratox_authenticated_routes_.insert_or_assign(
                        authority_session.friend_number,
                        RatoxPrincipalRoute{
                            authority_session.online_epoch,
                            authority_session.remote_principal});
                    if (authority_sessions_->authorized_at(
                            authority_session.friend_number,
                            terminal_capability, current_authority)) {
                        ratox_authority_routes_.insert_or_assign(
                            authority_session.friend_number,
                            RatoxPrincipalRoute{
                                authority_session.online_epoch,
                                authority_session.remote_principal});
                    }
                }
            }

            for (auto route = ratox_authenticated_routes_.begin();
                 route != ratox_authenticated_routes_.end();) {
                auto session = sessions_.get(route->first);
                const bool current_epoch = session &&
                    session.value().online_epoch ==
                        route->second.online_epoch &&
                    ratox_interactive_negotiated(session.value());
                if (current_epoch) {
                    ++route;
                } else {
                    route = ratox_authenticated_routes_.erase(route);
                }
            }

            for (auto route = ratox_authority_routes_.begin();
                 route != ratox_authority_routes_.end();) {
                auto session = sessions_.get(route->first);
                const bool current_epoch = session &&
                    session.value().online_epoch ==
                        route->second.online_epoch &&
                    ratox_interactive_negotiated(session.value());
                const bool authorized = current_epoch &&
                    authority_sessions_->authorized_at(
                        route->first, terminal_capability,
                        current_authority);
                if (authorized) {
                    ++route;
                    continue;
                }
                const Status revoked = ratox_service_->authority_revoked(
                    route->first, route->second.online_epoch,
                    route->second.principal_id, now);
                if (!revoked.ok() &&
                    revoked.code() != ErrorCode::not_found &&
                    revoked.code() != ErrorCode::unavailable) {
                    record_projection_failure(Status{
                        revoked.code(),
                        "Ratox authority revocation shutdown failed: " +
                            revoked.message()});
                }
                route = ratox_authority_routes_.erase(route);
            }
        }

        const Status progressed = ratox_service_->service(now);
        if (!progressed.ok()) {
            record_projection_failure(Status{
                progressed.code(),
                "Ratox process service failed: " + progressed.message()});
        }

        std::size_t sends = 0U;
        while (sends < kRatoxMaximumTransportSendsPerCycle) {
            const interactive::RatoxOutboundPacket *outbound =
                ratox_service_->peek_outbound();
            if (outbound == nullptr) {
                ratox_retained_send_telemetry_.clear(
                    interactive::RetainedSendLane::host);
                break;
            }
            auto session = sessions_.get(outbound->friend_number);
            const bool route_current = session &&
                session.value().online_epoch == outbound->online_epoch &&
                ratox_interactive_negotiated(session.value());
            if (!route_current) {
                ratox_peer_offline_locked(
                    outbound->friend_number, outbound->online_epoch);
                ++sends;
                continue;
            }

            if (outbound->terminal_authority_required) {
                auto current_peer = ratox_peer_context(
                    outbound->friend_number);
                const bool authority_current = current_peer &&
                    current_peer.value().online_epoch ==
                        outbound->online_epoch &&
                    current_peer.value().principal_id ==
                        outbound->principal_id &&
                    current_peer.value().terminal_authorized;
                if (!authority_current) {
                    // The packet was retained while authority was valid, but
                    // its exact friend/epoch/principal fence is no longer
                    // current. Purge the entire route before another packet is
                    // inspected; explicit DENIED admission replies never take
                    // this branch because they carry no authority dependency.
                    const std::uint32_t friend_number =
                        outbound->friend_number;
                    const std::uint64_t online_epoch =
                        outbound->online_epoch;
                    const interactive::PrincipalId principal_id =
                        outbound->principal_id;
                    const Status revoked =
                        ratox_service_->authority_revoked(
                            friend_number, online_epoch,
                            principal_id, now);
                    if (!revoked.ok() &&
                        revoked.code() != ErrorCode::not_found &&
                        revoked.code() != ErrorCode::unavailable) {
                        record_projection_failure(Status{
                            revoked.code(),
                            "Ratox pre-send authority fence failed: " +
                                revoked.message()});
                    }
                    ratox_authority_routes_.erase(friend_number);
                    ratox_retained_send_telemetry_.clear(
                        interactive::RetainedSendLane::host);
                    ++sends;
                    continue;
                }
            }

            const std::uint32_t friend_number = outbound->friend_number;
            const std::uint64_t online_epoch = outbound->online_epoch;
            const Status queued = transport_.send_sensitive_lossless(
                friend_number, outbound->bytes(),
                ratox_transport_class(outbound->traffic_class));
            if (queued.ok()) {
                ratox_retained_send_telemetry_.clear(
                    interactive::RetainedSendLane::host);
                const Status popped = ratox_service_->pop_outbound();
                if (!popped.ok()) {
                    record_projection_failure(popped);
                    break;
                }
                ++sends;
                continue;
            }
            if (retryable_protocol_send_error(queued.code())) {
                ratox_retained_send_telemetry_.observe_retryable(
                    interactive::RetainedSendLane::host);
                break;
            }
            ratox_retained_send_telemetry_.clear(
                interactive::RetainedSendLane::host);
            record_projection_failure(Status{
                queued.code(),
                "Ratox transport rejected a retained packet: " +
                    queued.message()});
            ratox_peer_offline_locked(friend_number, online_epoch);
            ++sends;
        }
        drain_ratox_events_best_effort(true);
    }

    void notify_ratox_service() noexcept {
        {
            std::scoped_lock lock(ratox_service_wake_mutex_);
            ++ratox_service_wake_generation_;
        }
        ratox_service_cv_.notify_one();
    }

    bool ratox_latency_active() {
        std::unique_lock authority_effect_lock(
            ratox_authority_effect_mutex_);
        if (ratox_service_ != nullptr) {
            const interactive::RatoxServiceSnapshot service =
                ratox_service_->snapshot();
            if (service.attached_sessions != 0U ||
                service.closing_sessions != 0U ||
                service.outbound_packets != 0U) {
                return true;
            }
        }
        std::scoped_lock client_lock(ratox_client_mutex_);
        if (ratox_client_ == nullptr) return false;
        switch (ratox_client_->snapshot().state) {
            case interactive::RatoxClientState::opening:
            case interactive::RatoxClientState::attached:
            case interactive::RatoxClientState::resuming:
            case interactive::RatoxClientState::closing:
                return true;
            case interactive::RatoxClientState::idle:
            case interactive::RatoxClientState::detached:
            case interactive::RatoxClientState::exited:
            case interactive::RatoxClientState::failed:
                return false;
        }
        return false;
    }

    void shutdown_ratox_best_effort() {
        ratox_retained_send_telemetry_.clear_all_active();
        std::scoped_lock authority_effect_lock(
            ratox_authority_effect_mutex_);
        if (ratox_service_ == nullptr) {
            return;
        }
        const Status started = ratox_service_->shutdown(
            std::chrono::steady_clock::now());
        if (!started.ok()) {
            record_projection_failure(Status{
                started.code(),
                "Ratox shutdown could not begin: " + started.message()});
        }

        const auto deadline =
            std::chrono::steady_clock::now() + std::chrono::seconds{10};
        while (true) {
            const Status progressed = ratox_service_->service(
                std::chrono::steady_clock::now());
            if (!progressed.ok()) {
                record_projection_failure(Status{
                    progressed.code(),
                    "Ratox shutdown service failed: " +
                        progressed.message()});
                break;
            }
            while (ratox_service_->peek_outbound() != nullptr) {
                const Status dropped = ratox_service_->pop_outbound();
                if (!dropped.ok()) {
                    record_projection_failure(dropped);
                    break;
                }
            }
            drain_ratox_events_best_effort(false);
            const interactive::RatoxServiceSnapshot state =
                ratox_service_->snapshot();
            if (state.running_processes == 0U ||
                std::chrono::steady_clock::now() >= deadline) {
                if (state.running_processes != 0U) {
                    record_projection_failure(Status{
                        ErrorCode::timeout,
                        "Ratox shutdown deadline elapsed with live PTY processes"});
                }
                break;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds{10});
        }
        ratox_authority_routes_.clear();
        ratox_authenticated_routes_.clear();
        refresh_ratox_snapshot_best_effort();
        publish_snapshot_best_effort();
    }

    Status synchronize_authority_session(std::uint32_t friend_number) {
        if (authority_sessions_ == nullptr || authority_ == nullptr) {
            return Status{ErrorCode::internal_error,
                          "authority session machinery is not initialized"};
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        const Status synchronized = authority_sessions_->synchronize_session(
            session.value(), authority_->snapshot(), unix_time_ms());
        publish_authority_sessions_best_effort();
        return synchronized;
    }

    Status send_authority_challenge(std::uint32_t friend_number) {
        std::scoped_lock send_lock(authority_send_mutex_);
        if (authority_sessions_ == nullptr || authority_ == nullptr) {
            return Status{ErrorCode::internal_error,
                          "authority session machinery is not initialized"};
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        auto current = authority_sessions_->get(friend_number);
        if (!current) {
            return current.status();
        }
        if (current.value().verifier_state !=
                security::AuthorityVerifierState::challenge_ready &&
            current.value().verifier_state !=
                security::AuthorityVerifierState::challenge_send_failed) {
            return Status{ErrorCode::unavailable,
                          "authority challenge is not awaiting its first successful enqueue"};
        }
        std::uint64_t message_id =
            current.value().local_challenge_message_id;
        security::AuthorityNonce nonce =
            current.value().local_challenge_nonce;
        if (message_id == 0U) {
            auto generated = security::random_u64_nonzero();
            if (!generated) {
                return generated.status();
            }
            message_id = generated.value();
            bool generated_nonce = false;
            for (std::size_t attempt = 0U; attempt < 4U; ++attempt) {
                const Status random = security::fill_random(nonce);
                if (!random.ok()) {
                    return random;
                }
                if (std::any_of(nonce.begin(), nonce.end(),
                                [](std::uint8_t value) { return value != 0U; })) {
                    generated_nonce = true;
                    break;
                }
            }
            if (!generated_nonce) {
                return Status{
                    ErrorCode::internal_error,
                    "operating-system random source repeatedly produced a "
                    "zero authority nonce"};
            }
        }
        auto frame = authority_sessions_->make_challenge_frame(
            session.value(), authority_->snapshot(), nonce, message_id,
            unix_time_ms());
        if (!frame) {
            return frame.status();
        }
        auto packet = protocol::encode(frame.value());
        if (!packet) {
            static_cast<void>(authority_sessions_->mark_challenge_send_failed(
                friend_number, packet.status().code(),
                packet.status().message(), unix_time_ms()));
            publish_authority_sessions_best_effort();
            return packet.status();
        }
        const Status queued =
            transport_.send_lossless(friend_number, packet.value());
        if (!queued.ok()) {
            static_cast<void>(authority_sessions_->mark_challenge_send_failed(
                friend_number, queued.code(), queued.message(),
                unix_time_ms()));
            publish_authority_sessions_best_effort();
            return queued;
        }
        const Status marked = authority_sessions_->mark_challenge_sent(
            friend_number, message_id, unix_time_ms());
        if (!marked.ok()) {
            publish_authority_sessions_best_effort();
            return marked;
        }
        record_protocol_frame(friend_number, "outgoing", frame.value());
        publish_authority_sessions_best_effort();
        return Status::success();
    }

    Status queue_authority_proof_frame(
        std::uint32_t friend_number, const protocol::Frame &frame) {
        auto packet = protocol::encode(frame);
        if (!packet) {
            static_cast<void>(authority_sessions_->mark_proof_send_failed(
                friend_number, packet.status().code(),
                packet.status().message(), unix_time_ms()));
            publish_authority_sessions_best_effort();
            return packet.status();
        }
        const Status queued =
            transport_.send_lossless(friend_number, packet.value());
        if (!queued.ok()) {
            static_cast<void>(authority_sessions_->mark_proof_send_failed(
                friend_number, queued.code(), queued.message(),
                unix_time_ms()));
            publish_authority_sessions_best_effort();
            return queued;
        }
        const Status marked = authority_sessions_->mark_proof_sent(
            friend_number, frame.message_id, unix_time_ms());
        if (!marked.ok()) {
            publish_authority_sessions_best_effort();
            return marked;
        }
        record_protocol_frame(friend_number, "outgoing", frame);
        publish_authority_sessions_best_effort();
        return Status::success();
    }

    Status send_authority_proof(
        std::uint32_t friend_number,
        std::span<const std::uint8_t, security::kAuthorityProofBytes> proof) {
        std::scoped_lock send_lock(authority_send_mutex_);
        if (authority_sessions_ == nullptr) {
            return Status{ErrorCode::internal_error,
                          "authority session machinery is not initialized"};
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        auto current = authority_sessions_->get(friend_number);
        if (!current) {
            return current.status();
        }
        std::uint64_t message_id = current.value().local_proof_message_id;
        if (message_id == 0U) {
            auto generated = security::random_u64_nonzero();
            if (!generated) {
                return generated.status();
            }
            message_id = generated.value();
        }
        auto frame = authority_sessions_->make_proof_frame(
            session.value(), proof, message_id, unix_time_ms());
        if (!frame) {
            return frame.status();
        }
        return queue_authority_proof_frame(friend_number, frame.value());
    }

    Status send_device_authority_proof(std::uint32_t friend_number) {
        if (authority_sessions_ == nullptr || !identity_.has_value()) {
            return Status{ErrorCode::internal_error,
                          "stable device authority signer is not initialized"};
        }
        auto body = authority_sessions_->prepare_proof_body(
            friend_number, identity_->public_key(), unix_time_ms());
        if (!body) {
            publish_authority_sessions_best_effort();
            return body.status();
        }
        auto proof = security::sign_authority_proof_body(
            body.value(), *identity_);
        if (!proof) {
            publish_authority_sessions_best_effort();
            return proof.status();
        }
        return send_authority_proof(friend_number, proof.value());
    }

    Status retry_authority_proof(std::uint32_t friend_number) {
        std::scoped_lock send_lock(authority_send_mutex_);
        if (authority_sessions_ == nullptr) {
            return Status{ErrorCode::internal_error,
                          "authority session machinery is not initialized"};
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        auto frame = authority_sessions_->make_frozen_proof_frame(
            session.value(), unix_time_ms());
        if (!frame) {
            return frame.status();
        }
        return queue_authority_proof_frame(friend_number, frame.value());
    }

    void advance_authority_session(std::uint32_t friend_number) {
        const Status synchronized = synchronize_authority_session(friend_number);
        if (!synchronized.ok()) {
            if (synchronized.code() != ErrorCode::unavailable) {
                record_projection_failure(synchronized);
            }
            return;
        }
        auto current = authority_sessions_->get(friend_number);
        if (!current) {
            record_projection_failure(current.status());
            return;
        }
        const bool challenge_retry =
            current.value().verifier_state ==
                security::AuthorityVerifierState::challenge_send_failed &&
            retryable_protocol_send_error(
                current.value().last_challenge_send_error_code);
        if (current.value().verifier_state ==
                security::AuthorityVerifierState::challenge_ready ||
            challenge_retry) {
            const Status sent = send_authority_challenge(friend_number);
            if (!sent.ok() &&
                !retryable_protocol_send_error(sent.code()) &&
                sent.code() != ErrorCode::unavailable) {
                record_projection_failure(Status{
                    sent.code(),
                    "IoTox authority challenge progression failed: " +
                        sent.message()});
            }
            current = authority_sessions_->get(friend_number);
            if (!current) {
                return;
            }
        }
        // The stable device principal is the ordinary machine-to-machine
        // claimant. Its secret never leaves this process: after the peer's
        // transcript-bound challenge arrives, sign that exact challenge and
        // send the frozen proof automatically. RecallRoot owner re-entry is a
        // separate, explicit recovery/administration lane and must not be
        // confused with a device proving its day-to-day principal.
        if (current.value().claimant_state ==
                security::AuthorityClaimantState::challenge_received) {
            const Status sent = send_device_authority_proof(friend_number);
            if (!sent.ok() &&
                !retryable_protocol_send_error(sent.code()) &&
                sent.code() != ErrorCode::unavailable) {
                record_projection_failure(Status{
                    sent.code(),
                    "IoTox stable-device authority proof failed: " +
                        sent.message()});
            }
            current = authority_sessions_->get(friend_number);
            if (!current) {
                return;
            }
        }
        if (current.value().claimant_state ==
                security::AuthorityClaimantState::proof_send_failed &&
            retryable_protocol_send_error(
                current.value().last_proof_send_error_code)) {
            const Status retried = retry_authority_proof(friend_number);
            if (!retried.ok() &&
                !retryable_protocol_send_error(retried.code())) {
                record_projection_failure(Status{
                    retried.code(),
                    "IoTox authority proof retry failed: " +
                        retried.message()});
            }
        }
    }

    void service_authority_sessions_best_effort() {
        if (authority_sessions_ == nullptr || authority_ == nullptr) {
            return;
        }
        for (const protocol::PeerSessionSnapshot &session : sessions_.list()) {
            if (!protocol::is_application_ready(session)) {
                continue;
            }
            advance_authority_session(session.friend_number);
        }
    }

    void handle_incoming_authority_challenge(
        std::uint32_t friend_number, const protocol::Frame &frame) {
        const Status synchronized = synchronize_authority_session(friend_number);
        if (!synchronized.ok()) {
            record_projection_failure(synchronized);
            return;
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            record_projection_failure(session.status());
            return;
        }
        const Status accepted = authority_sessions_->receive_challenge(
            session.value(), frame, unix_time_ms());
        publish_authority_sessions_best_effort();
        if (!accepted.ok()) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "authority-challenge-rejected friend=" +
                std::to_string(friend_number) + " detail=" +
                accepted.message();
        }
    }

    void handle_incoming_authority_proof(
        std::uint32_t friend_number, const protocol::Frame &frame) {
        const Status synchronized = synchronize_authority_session(friend_number);
        if (!synchronized.ok()) {
            record_projection_failure(synchronized);
            return;
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            record_projection_failure(session.status());
            return;
        }
        const Status accepted = authority_sessions_->receive_proof(
            session.value(), frame, *authority_, unix_time_ms());
        publish_authority_sessions_best_effort();
        std::scoped_lock lock(snapshot_mutex_);
        snapshot_.last_event = accepted.ok()
            ? "authority-principal-authorized friend=" +
                  std::to_string(friend_number)
            : "authority-proof-rejected friend=" +
                  std::to_string(friend_number) + " detail=" +
                  accepted.message();
    }

    Status send_remote_delegation_record(
        std::uint32_t friend_number,
        const security::AuthorityRecordBytes &record) {
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        if (!protocol::is_application_ready(session.value())) {
            return Status{ErrorCode::unavailable,
                          "remote delegation requires a confirmed IoTox session"};
        }
        auto payload = protocol::encode_delegation_request({record});
        if (!payload) {
            return payload.status();
        }
        auto message_id = security::random_u64_nonzero();
        if (!message_id) {
            return message_id.status();
        }
        protocol::Frame frame;
        frame.major = session.value().negotiated.selected.major;
        frame.minor = session.value().negotiated.selected.minor;
        frame.type = protocol::MessageType::pair_request;
        frame.message_id = message_id.value();
        frame.payload.assign(payload.value().begin(), payload.value().end());
        auto packet = protocol::encode(frame);
        if (!packet) {
            return packet.status();
        }
        const Status queued = transport_.send_lossless(
            friend_number, packet.value());
        if (queued.ok()) {
            record_protocol_frame(friend_number, "outgoing", frame);
            std::scoped_lock lock(delegation_mutex_);
            outgoing_delegations_[friend_number] = FrozenDelegationRequest{
                session.value().public_key, record, frame.message_id,
                std::nullopt};
        }
        return queued;
    }

    Status retry_remote_delegation_record(std::uint32_t friend_number) {
        FrozenDelegationRequest frozen;
        {
            std::scoped_lock lock(delegation_mutex_);
            const auto found = outgoing_delegations_.find(friend_number);
            if (found == outgoing_delegations_.end()) {
                return Status{ErrorCode::not_found,
                              "no frozen remote delegation is available for this friend"};
            }
            frozen = found->second;
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        if (session.value().public_key != frozen.transport_public_key) {
            return Status{ErrorCode::protocol_error,
                          "friend number now names a different transport key"};
        }
        return send_remote_delegation_record(friend_number, frozen.record);
    }

    void send_delegation_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &request,
        protocol::DelegationOutcome outcome) {
        const auto authority = authority_ != nullptr
            ? authority_->snapshot()
            : security::AuthoritySnapshot{};
        protocol::DelegationResult result;
        result.outcome = outcome;
        result.ownership_epoch = authority.ownership_epoch;
        result.authority_sequence = authority.sequence;
        result.authority_tail_digest = authority.tail_digest;
        auto payload = protocol::encode_delegation_result(result);
        auto message_id = security::random_u64_nonzero();
        if (!payload || !message_id) {
            record_projection_failure(
                !payload ? payload.status() : message_id.status());
            return;
        }
        protocol::Frame response;
        response.major = session.negotiated.selected.major;
        response.minor = session.negotiated.selected.minor;
        response.type = protocol::MessageType::pair_result;
        response.message_id = message_id.value();
        response.correlation_id = request.message_id;
        response.payload.assign(payload.value().begin(), payload.value().end());
        auto packet = protocol::encode(response);
        const Status queued = packet
            ? transport_.send_lossless(friend_number, packet.value())
            : packet.status();
        if (queued.ok()) {
            record_protocol_frame(friend_number, "outgoing", response);
        } else {
            record_projection_failure(queued);
        }
    }

    void handle_incoming_delegation_request(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        protocol::DelegationOutcome outcome =
            protocol::DelegationOutcome::malformed;
        if (frame.flags == 0U && frame.correlation_id == 0U &&
            frame.sequence == 0U && frame.expiry_unix_ms == 0U &&
            authority_ != nullptr && authority_sessions_ != nullptr &&
            sodium_.has_value()) {
            auto request = protocol::decode_delegation_request(frame.payload);
            auto peer = authority_sessions_->get(friend_number);
            if (request && peer) {
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                const protocol::DelegationApplication applied =
                    protocol::apply_remote_owner_mutation(
                        request.value().signed_record, *authority_,
                        peer.value(), *sodium_);
                outcome = applied.outcome;
                if (applied.ledger_changed) {
                    authority_sessions_->invalidate_local_authority(
                        authority_->snapshot(), unix_time_ms());
                    clear_command_results();
                    const Status projected = refresh_authority_projection();
                    if (!projected.ok()) {
                        outcome = protocol::DelegationOutcome::internal_error;
                    }
                    publish_authority_sessions_best_effort();
                    publish_snapshot_best_effort();
                }
            }
        }
        send_delegation_result(friend_number, session, frame, outcome);
    }

    void handle_incoming_delegation_result(
        std::uint32_t friend_number, const protocol::Frame &frame) {
        const bool envelope_valid = frame.flags == 0U &&
            frame.correlation_id != 0U && frame.sequence == 0U &&
            frame.expiry_unix_ms == 0U;
        auto result = envelope_valid
            ? protocol::decode_delegation_result(frame.payload)
            : Result<protocol::DelegationResult>{Status{
                  ErrorCode::protocol_error,
                  "remote delegation result envelope is malformed"}};
        bool correlated = false;
        if (result) {
            std::scoped_lock lock(delegation_mutex_);
            const auto found = outgoing_delegations_.find(friend_number);
            if (found != outgoing_delegations_.end() &&
                found->second.request_message_id == frame.correlation_id) {
                found->second.result = result.value();
                correlated = true;
            }
        }
        std::scoped_lock lock(snapshot_mutex_);
        snapshot_.last_event = result && correlated
            ? "remote-delegation-result friend=" +
                  std::to_string(friend_number) + " outcome=" +
                  protocol::to_string(result.value().outcome) + " sequence=" +
                  std::to_string(result.value().authority_sequence)
            : "remote-delegation-result-rejected friend=" +
                  std::to_string(friend_number);
    }

    enum class CommandResultSendState : std::uint8_t {
        ready = 0U,
        send_failed = 1U,
        sent = 2U,
        terminal_failure = 3U,
    };

    struct FrozenCommandResult {
        std::uint32_t friend_number{0U};
        std::uint64_t online_epoch{0U};
        std::uint64_t request_message_id{0U};
        std::vector<std::uint8_t> canonical_request;
        protocol::Frame response;
        std::vector<std::uint8_t> encoded_response;
        protocol::CommandOperation operation{
            protocol::CommandOperation::unknown};
        protocol::CommandOutcome outcome{
            protocol::CommandOutcome::internal_error};
        CommandResultSendState state{CommandResultSendState::ready};
        std::uint32_t send_attempts{0U};
        ErrorCode last_error_code{ErrorCode::ok};
        std::string last_error;
        std::uint64_t updated_unix_ms{0U};
    };

    using CommandResultKey =
        std::tuple<std::uint32_t, std::uint64_t, std::uint64_t>;

    [[nodiscard]] Status send_frozen_command_result(
        FrozenCommandResult &record) {
        ++record.send_attempts;
        const Status queued = transport_.send_lossless(
            record.friend_number, record.encoded_response);
        record.updated_unix_ms = unix_time_ms();
        if (!queued.ok()) {
            record.last_error_code = queued.code();
            record.last_error = queued.message();
            record.state = retryable_protocol_send_error(queued.code())
                               ? CommandResultSendState::send_failed
                               : CommandResultSendState::terminal_failure;
            return queued;
        }
        record.state = CommandResultSendState::sent;
        record.last_error_code = ErrorCode::ok;
        record.last_error.clear();
        record_protocol_frame(
            record.friend_number, "outgoing", record.response);
        return Status::success();
    }

    [[nodiscard]] Status send_durable_command_artifact(
        std::uint32_t friend_number,
        DurableCommandRecord &record,
        bool receipt,
        bool force_replay = false) {
        if (!command_admission_open_.load() || event_stop_.load()) {
            return Status{ErrorCode::unavailable,
                          "durable command delivery is stopped during shutdown"};
        }
        const CommandArtifact artifact = receipt
            ? CommandArtifact::receipt
            : CommandArtifact::result;
        std::vector<std::uint8_t> &canonical = receipt
            ? record.canonical_receipt
            : record.canonical_result;
        if (canonical.empty()) {
            return Status{ErrorCode::invalid_argument,
                          receipt
                              ? "durable command receipt is absent"
                              : "durable command result is absent"};
        }
        const std::uint64_t now = command_schedule_time_ms();
        const Status began = begin_command_delivery_attempt(
            record, artifact, now, {}, force_replay);
        if (!began.ok()) {
            return began;
        }
        const Status attempt_stored = update_command_record(record);
        if (!attempt_stored.ok()) {
            return Status{
                attempt_stored.code(),
                "durable command artifact was not sent because its attempt "
                "could not be committed: " +
                    attempt_stored.message()};
        }

        const Status queued = transport_.send_lossless(friend_number, canonical);
        CommandDeliveryState &delivery = receipt
            ? record.receipt_delivery
            : record.result_delivery;
        CommandDeliverySchedule &schedule =
            command_delivery_schedule(record, artifact);
        if (queued.ok()) {
            delivery = CommandDeliveryState::queued;
            schedule.last_error_code = ErrorCode::ok;
        } else {
            // `queued` means at least one exact copy was accepted by the local
            // Tox send queue. A later replay attempt cannot revoke that fact.
            // The sender's exact request retry remains the recovery trigger.
            if (delivery != CommandDeliveryState::queued) {
                delivery = retryable_protocol_send_error(queued.code())
                    ? CommandDeliveryState::send_failed
                    : CommandDeliveryState::terminal_failure;
            }
            schedule.last_error_code = queued.code();
        }
        record.updated_unix_ms = std::max(
            record.updated_unix_ms, command_schedule_time_ms());
        const Status stored = update_command_record(record);
        if (queued.ok()) {
            auto frame = protocol::decode(canonical);
            if (frame) {
                record_protocol_frame(friend_number, "outgoing", frame.value());
            }
        }
        if (!stored.ok()) {
            return Status{stored.code(),
                          "durable command delivery state could not be committed: " +
                              stored.message()};
        }
        return queued;
    }

    [[nodiscard]] Status send_ephemeral_command_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &request,
        std::vector<std::uint8_t> canonical_request,
        const protocol::CommandResultPayload &result) {
        auto prepared = make_command_result(
            friend_number, session, request,
            std::move(canonical_request), result);
        if (!prepared) {
            return prepared.status();
        }
        const Status queued = transport_.send_lossless(
            friend_number, prepared.value().encoded_response);
        if (queued.ok()) {
            record_protocol_frame(
                friend_number, "outgoing", prepared.value().response);
        }
        return queued;
    }

    void prune_command_results() {
        while (command_results_.size() >= kMaximumLiveCommandResults) {
            auto oldest = command_results_.end();
            for (auto current = command_results_.begin();
                 current != command_results_.end(); ++current) {
                if (current->second.state != CommandResultSendState::sent) {
                    continue;
                }
                if (oldest == command_results_.end() ||
                    current->second.updated_unix_ms <
                        oldest->second.updated_unix_ms) {
                    oldest = current;
                }
            }
            if (oldest == command_results_.end()) {
                return;
            }
            command_results_.erase(oldest);
        }
    }

    void erase_command_results(std::uint32_t friend_number) {
        std::scoped_lock lock(command_mutex_);
        for (auto current = command_results_.begin();
             current != command_results_.end();) {
            if (current->second.friend_number == friend_number) {
                current = command_results_.erase(current);
            } else {
                ++current;
            }
        }
    }

    void clear_command_results() {
        std::scoped_lock lock(command_mutex_);
        command_results_.clear();
    }

    void service_command_results_best_effort() {
        const auto now = std::chrono::steady_clock::now();
        if (now < next_command_service_) {
            return;
        }
        next_command_service_ = now + std::chrono::milliseconds(500);
        {
            std::scoped_lock lock(command_mutex_);
            for (auto &[key, record] : command_results_) {
                static_cast<void>(key);
                if (record.state != CommandResultSendState::send_failed ||
                    !retryable_protocol_send_error(record.last_error_code)) {
                    continue;
                }
                const Status retried = send_frozen_command_result(record);
                if (!retried.ok() &&
                    !retryable_protocol_send_error(retried.code())) {
                    record_projection_failure(Status{
                        retried.code(),
                        "frozen COMMAND_RESULT retry failed: " +
                            retried.message()});
                }
            }
        }

        if (command_store_ == nullptr) {
            return;
        }
        std::scoped_lock durable_lock(durable_command_mutex_);
        for (DurableCommandRecord record : order_command_outbox(
                 command_store_->snapshot().records)) {
            if (event_stop_.load()) {
                return;
            }
            if (record.key.direction != CommandDirection::incoming) {
                continue;
            }
            const auto friend_number =
                friend_number_for_command_peer(record.key.peer_public_key);
            if (!friend_number.has_value()) {
                continue;
            }
            auto session = sessions_.get(*friend_number);
            if (!session || !durable_commands_negotiated(session.value())) {
                continue;
            }
            const std::uint64_t service_now = command_schedule_time_ms();
            if (command_artifact_due(
                    record, CommandArtifact::receipt, service_now)) {
                const Status retried = send_durable_command_artifact(
                    *friend_number, record, true);
                if (!retried.ok() &&
                    !retryable_protocol_send_error(retried.code())) {
                    record_projection_failure(Status{
                        retried.code(),
                        "durable command receipt retry failed: " +
                            retried.message()});
                }
            }
            if (command_artifact_due(
                    record, CommandArtifact::result, service_now)) {
                const Status retried = send_durable_command_artifact(
                    *friend_number, record, false);
                if (!retried.ok() &&
                    !retryable_protocol_send_error(retried.code())) {
                    record_projection_failure(Status{
                        retried.code(),
                        "durable COMMAND_RESULT retry failed: " +
                            retried.message()});
                }
            }
        }
    }

    [[nodiscard]] Result<FrozenCommandResult> make_command_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &request,
        std::vector<std::uint8_t> canonical_request,
        const protocol::CommandResultPayload &result) {
        auto payload = protocol::encode_command_result(result);
        if (!payload) {
            return payload.status();
        }
        auto message_id = security::random_u64_nonzero();
        if (!message_id) {
            return message_id.status();
        }

        protocol::Frame response;
        response.major = session.negotiated.selected.major;
        response.minor = session.negotiated.selected.minor;
        response.type = protocol::MessageType::command_result;
        response.message_id = message_id.value();
        response.correlation_id = request.message_id;
        response.sequence = request.sequence;
        response.expiry_unix_ms = 0U;
        response.payload = std::move(payload).value();
        auto packet = protocol::encode(response);
        if (!packet) {
            return packet.status();
        }
        FrozenCommandResult record;
        record.friend_number = friend_number;
        record.online_epoch = session.online_epoch;
        record.request_message_id = request.message_id;
        record.canonical_request = std::move(canonical_request);
        record.response = std::move(response);
        record.encoded_response = std::move(packet).value();
        record.operation = result.operation;
        record.outcome = result.outcome;
        record.updated_unix_ms = unix_time_ms();
        return record;
    }

    void publish_peer_description_best_effort(std::uint32_t friend_number) {
        protocol::PeerDescriptionSnapshot description;
        {
            std::scoped_lock lock(description_mutex_);
            const auto found = descriptions_.find(friend_number);
            if (found == descriptions_.end()) {
                return;
            }
            description = found->second.snapshot;
        }
        auto key = peer_key_for(friend_number);
        if (!key) {
            record_projection_failure(key.status());
            return;
        }
        const Status published = runtime_.publish_peer_description(
            key.value(), description);
        if (!published.ok()) {
            record_projection_failure(published);
        }
    }

    Result<protocol::PeerDescriptionSnapshot> peer_description(
        std::uint32_t friend_number) const {
        std::scoped_lock lock(description_mutex_);
        const auto found = descriptions_.find(friend_number);
        if (found == descriptions_.end()) {
            return Status{ErrorCode::not_found,
                          "no device.describe request exists for that peer"};
        }
        return found->second.snapshot;
    }

    void invalidate_peer_description(
        std::uint32_t friend_number, std::uint64_t online_epoch,
        std::string detail) {
        bool changed = false;
        {
            std::scoped_lock lock(description_mutex_);
            const auto found = descriptions_.find(friend_number);
            if (found == descriptions_.end()) {
                return;
            }
            found->second.snapshot.online_epoch = online_epoch;
            found->second.snapshot.state =
                protocol::PeerDescriptionState::none;
            found->second.snapshot.sender_epoch = 0U;
            found->second.snapshot.request_message_id = 0U;
            found->second.snapshot.receipt_message_id = 0U;
            found->second.snapshot.receipt_stage =
                protocol::CommandReceiptStage::none;
            found->second.snapshot.result_message_id = 0U;
            found->second.snapshot.outcome =
                protocol::CommandOutcome::internal_error;
            found->second.snapshot.description.reset();
            found->second.snapshot.send_attempts = 0U;
            found->second.snapshot.last_send_error_code = ErrorCode::ok;
            found->second.snapshot.last_send_error.clear();
            found->second.snapshot.detail = std::move(detail);
            found->second.snapshot.updated_unix_ms = unix_time_ms();
            found->second.frozen_request = {};
            found->second.frozen_receipt_frame.clear();
            found->second.frozen_result_frame.clear();
            changed = true;
        }
        if (changed) {
            publish_peer_description_best_effort(friend_number);
        }
    }

    Result<DurableCommandRecord> admit_outgoing_command(
        std::uint32_t friend_number,
        const protocol::CommandRequest &request,
        CommandPriority priority,
        std::uint64_t ttl_ms) {
        if (!command_admission_open_.load()) {
            return Status{ErrorCode::unavailable,
                          "durable command admission is closed during shutdown"};
        }
        const auto policy =
            protocol::command_operation_policy(request.operation);
        if (!policy.has_value() ||
            !protocol::command_restart_safe(request.operation)) {
            return Status{ErrorCode::unsupported,
                          "only registered operations with an explicit restart "
                          "policy may enter the durable outbox"};
        }
        if (!policy->read_only && ttl_ms != 0U) {
            return Status{ErrorCode::invalid_argument,
                          "mutating commands do not accept expiry until their "
                          "post-start timeout contract is frozen"};
        }
        auto payload = protocol::encode_command_request(request);
        if (!payload) {
            return payload.status();
        }
        if (priority < CommandPriority::low || priority > CommandPriority::high) {
            return Status{ErrorCode::invalid_argument,
                          "durable command priority is invalid"};
        }
        if (command_store_ == nullptr) {
            return Status{ErrorCode::internal_error,
                          "durable command store is not initialized"};
        }
        auto peer = command_peer_key_for(friend_number);
        if (!peer) {
            return peer.status();
        }

        std::scoped_lock durable_lock(durable_command_mutex_);
        for (const DurableCommandRecord &candidate :
             command_store_->records_for_peer(
                 peer.value(), CommandDirection::outgoing)) {
            if (candidate.operation == request.operation &&
                !command_lifecycle_terminal(candidate.lifecycle)) {
                return Status{ErrorCode::unavailable,
                              protocol::to_string(request.operation) +
                                  " already has an unfinished durable request for this peer"};
            }
        }
        auto message_id = security::random_u64_nonzero();
        if (!message_id) {
            return message_id.status();
        }
        const std::uint64_t wall_now = unix_time_ms();
        const std::uint64_t schedule_now = command_schedule_time_ms();
        if (ttl_ms != 0U && !trusted_wall_clock_usable(wall_now)) {
            return Status{
                ErrorCode::unavailable,
                "expiring command admission requires an explicitly trusted "
                "non-rollback wall clock"};
        }
        if (ttl_ms != 0U &&
            wall_now > std::numeric_limits<std::uint64_t>::max() - ttl_ms) {
            return Status{ErrorCode::resource_exhausted,
                          "command expiry timestamp overflows uint64"};
        }
        protocol::Frame frame;
        frame.major = protocol::kProtocolMajor;
        frame.minor = protocol::kProtocolMinor;
        frame.type = protocol::MessageType::command;
        frame.message_id = message_id.value();
        frame.sequence = command_store_->local_sender_epoch();
        frame.expiry_unix_ms = ttl_ms == 0U ? 0U : wall_now + ttl_ms;
        frame.payload.assign(payload.value().begin(), payload.value().end());
        auto canonical = protocol::encode(frame);
        if (!canonical) {
            return canonical.status();
        }

        DurableCommandRecord record;
        record.key.direction = CommandDirection::outgoing;
        record.key.peer_public_key = peer.value();
        record.key.sender_epoch = frame.sequence;
        record.key.message_id = frame.message_id;
        record.direction = CommandDirection::outgoing;
        record.lifecycle = CommandLifecycle::reserved;
        record.operation = request.operation;
        record.outcome = protocol::CommandOutcome::internal_error;
        record.priority = priority;
        record.clock_requirement = ttl_ms == 0U
            ? CommandClockRequirement::none
            : CommandClockRequirement::trusted_wall;
        record.created_unix_ms = schedule_now;
        record.updated_unix_ms = schedule_now;
        record.expiry_unix_ms = frame.expiry_unix_ms;
        record.request_schedule.next_attempt_unix_ms =
            schedule_now > std::numeric_limits<std::uint64_t>::max() -
                      kDefaultCommandAdmissionDelayMs
            ? std::numeric_limits<std::uint64_t>::max()
            : schedule_now + kDefaultCommandAdmissionDelayMs;
        record.canonical_request = std::move(canonical).value();
        CommandInsertDisposition disposition{};
        const Status inserted = insert_command_record(record, &disposition);
        if (!inserted.ok()) {
            return inserted;
        }
        if (disposition != CommandInsertDisposition::inserted) {
            return Status{ErrorCode::protocol_error,
                          "new command identity collided with the durable journal"};
        }
        return record;
    }

    Result<bool> settle_outgoing_expiry(
        DurableCommandRecord &record,
        std::uint64_t now_unix_ms) {
        if (record.direction != CommandDirection::outgoing ||
            record.expiry_unix_ms == 0U ||
            command_lifecycle_terminal(record.lifecycle)) {
            return false;
        }
        if (!trusted_wall_clock_usable(now_unix_ms)) {
            return Status{
                ErrorCode::unavailable,
                "expiring durable command is held because wall-clock trust "
                "is unavailable"};
        }
        if (now_unix_ms < record.expiry_unix_ms) {
            return false;
        }
        record.lifecycle = record.request_schedule.attempts == 0U
            ? CommandLifecycle::expired
            : CommandLifecycle::timed_out_unconfirmed;
        record.outcome = protocol::CommandOutcome::expired;
        record.updated_unix_ms = std::max(
            record.updated_unix_ms, command_schedule_time_ms());
        const Status updated = update_command_record(record);
        if (!updated.ok()) {
            return updated;
        }
        return true;
    }

    Result<protocol::PeerDescriptionSnapshot> send_device_describe_request(
        std::uint32_t friend_number,
        bool recovery = false) {
        if (!recovery && !command_admission_open_.load()) {
            return Status{ErrorCode::unavailable,
                          "durable command admission is closed during shutdown"};
        }
        std::scoped_lock send_lock(description_send_mutex_);
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        if (!protocol::is_application_ready(session.value())) {
            return Status{ErrorCode::unavailable,
                          "device.describe requires a transcript-confirmed IoTox session"};
        }
        if (authority_sessions_ == nullptr) {
            return Status{ErrorCode::internal_error,
                          "authority session machinery is not initialized"};
        }
        auto authority = authority_sessions_->get(friend_number);
        if (!authority) {
            return authority.status();
        }
        if (authority.value().claimant_state !=
            security::AuthorityClaimantState::proof_sent) {
            return Status{
                ErrorCode::unavailable,
                "device.describe waits until the local stable-device proof "
                "has queued"};
        }

        const bool durable = durable_commands_negotiated(session.value());
        std::unique_lock<std::mutex> durable_lock(
            durable_command_mutex_, std::defer_lock);
        if (durable) {
            durable_lock.lock();
        }
        std::optional<CommandPeerKey> durable_peer;
        if (durable) {
            auto key = command_peer_key_for(friend_number);
            if (!key) {
                return key.status();
            }
            durable_peer = key.value();
            if (command_store_ == nullptr) {
                return Status{ErrorCode::internal_error,
                              "durable command store is not initialized"};
            }
        }

        protocol::Frame frame;
        bool retry = false;
        bool have_frame = false;
        {
            std::scoped_lock lock(description_mutex_);
            auto found = descriptions_.find(friend_number);
            if (found != descriptions_.end() &&
                found->second.snapshot.online_epoch !=
                    session.value().online_epoch) {
                descriptions_.erase(found);
                found = descriptions_.end();
            }
            if (found != descriptions_.end() &&
                found->second.snapshot.state ==
                    protocol::PeerDescriptionState::awaiting_result &&
                !recovery) {
                return Status{ErrorCode::unavailable,
                              "device.describe already awaits a result for this peer epoch"};
            }
            if (found != descriptions_.end() &&
                found->second.snapshot.state ==
                    protocol::PeerDescriptionState::send_failed &&
                retryable_protocol_send_error(
                    found->second.snapshot.last_send_error_code) &&
                found->second.snapshot.request_message_id != 0U) {
                frame = found->second.frozen_request;
                retry = true;
                have_frame = true;
            }
        }

        std::optional<DurableCommandRecord> durable_record;
        if (durable && !have_frame) {
            for (const DurableCommandRecord &candidate :
                 command_store_->records_for_peer(
                     *durable_peer, CommandDirection::outgoing)) {
                if (candidate.operation !=
                        protocol::CommandOperation::device_describe ||
                    command_lifecycle_terminal(candidate.lifecycle)) {
                    continue;
                }
                auto decoded = protocol::decode(candidate.canonical_request);
                if (!decoded) {
                    return Status{decoded.status().code(),
                                  "stored device.describe request is unreadable: " +
                                      decoded.status().message()};
                }
                if (decoded.value().major !=
                        session.value().negotiated.selected.major ||
                    decoded.value().minor !=
                        session.value().negotiated.selected.minor) {
                    return Status{
                        ErrorCode::unsupported,
                        "a pending durable device.describe request uses a "
                        "different negotiated protocol version"};
                }
                frame = decoded.value();
                durable_record = candidate;
                retry = true;
                have_frame = true;

                PeerDescriptionEntry recovered;
                recovered.frozen_request = frame;
                recovered.snapshot.friend_number = friend_number;
                recovered.snapshot.online_epoch =
                    session.value().online_epoch;
                recovered.snapshot.sender_epoch = frame.sequence;
                recovered.snapshot.request_message_id = frame.message_id;
                recovered.snapshot.send_attempts =
                    candidate.request_schedule.attempts;
                recovered.snapshot.outcome = candidate.outcome;
                recovered.snapshot.state =
                    protocol::PeerDescriptionState::send_failed;
                recovered.snapshot.last_send_error_code =
                    candidate.request_schedule.last_error_code;
                recovered.snapshot.detail = "recovered an unfinished durable "
                                            "device.describe request after "
                                            "restart or reconnect";
                recovered.snapshot.updated_unix_ms = unix_time_ms();
                if (!candidate.canonical_receipt.empty()) {
                    auto receipt_frame =
                        protocol::decode(candidate.canonical_receipt);
                    if (receipt_frame) {
                        auto receipt = protocol::decode_command_receipt(
                            receipt_frame.value().payload);
                        if (receipt) {
                            recovered.frozen_receipt_frame =
                                candidate.canonical_receipt;
                            recovered.snapshot.receipt_message_id =
                                receipt_frame.value().message_id;
                            recovered.snapshot.receipt_stage =
                                receipt.value().stage;
                        }
                    }
                }
                {
                    std::scoped_lock lock(description_mutex_);
                    descriptions_[friend_number] = std::move(recovered);
                }
                break;
            }
        }

        if (!have_frame) {
            auto payload = protocol::encode_command_request(
                protocol::CommandRequest{
                    protocol::CommandOperation::device_describe});
            if (!payload) {
                return payload.status();
            }
            auto message_id = security::random_u64_nonzero();
            if (!message_id) {
                return message_id.status();
            }
            frame.major = session.value().negotiated.selected.major;
            frame.minor = session.value().negotiated.selected.minor;
            frame.type = protocol::MessageType::command;
            frame.message_id = message_id.value();
            frame.correlation_id = 0U;
            frame.sequence = durable
                ? command_store_->local_sender_epoch()
                : 0U;
            frame.expiry_unix_ms = 0U;
            frame.payload.assign(payload.value().begin(),
                                 payload.value().end());
            auto canonical = protocol::encode(frame);
            if (!canonical) {
                return canonical.status();
            }

            if (durable) {
                const std::uint64_t now = command_schedule_time_ms();
                DurableCommandRecord record;
                record.key.direction = CommandDirection::outgoing;
                record.key.peer_public_key = *durable_peer;
                record.key.sender_epoch = frame.sequence;
                record.key.message_id = frame.message_id;
                record.direction = CommandDirection::outgoing;
                record.lifecycle = CommandLifecycle::reserved;
                record.operation =
                    protocol::CommandOperation::device_describe;
                record.outcome =
                    protocol::CommandOutcome::internal_error;
                record.created_unix_ms = now;
                record.updated_unix_ms = now;
                record.request_schedule.next_attempt_unix_ms =
                    now + kDefaultCommandAdmissionDelayMs;
                record.canonical_request = canonical.value();
                CommandInsertDisposition disposition{};
                const Status stored = insert_command_record(
                    record, &disposition);
                if (!stored.ok()) {
                    return stored;
                }
                if (disposition != CommandInsertDisposition::inserted) {
                    return Status{
                        ErrorCode::protocol_error,
                        "new device.describe message id collided with an "
                        "existing durable command"};
                }
                durable_record = std::move(record);
            }

            PeerDescriptionEntry entry;
            entry.frozen_request = frame;
            entry.snapshot.friend_number = friend_number;
            entry.snapshot.online_epoch = session.value().online_epoch;
            entry.snapshot.sender_epoch = frame.sequence;
            entry.snapshot.request_message_id = frame.message_id;
            entry.snapshot.outcome =
                protocol::CommandOutcome::internal_error;
            entry.snapshot.detail = durable
                ? "durable device.describe request committed before transport"
                : "legacy device.describe request reserved";
            entry.snapshot.updated_unix_ms = unix_time_ms();
            {
                std::scoped_lock lock(description_mutex_);
                descriptions_[friend_number] = std::move(entry);
            }
        } else if (durable && !durable_record.has_value()) {
            DurableCommandKey key;
            key.direction = CommandDirection::outgoing;
            key.peer_public_key = *durable_peer;
            key.sender_epoch = frame.sequence;
            key.message_id = frame.message_id;
            auto found = command_store_->find(key);
            if (!found) {
                return found.status();
            }
            if (!found.value().has_value()) {
                return Status{
                    ErrorCode::not_found,
                    "the reserved durable device.describe request is missing "
                    "from its journal"};
            }
            durable_record = found.value().value();
        }

        if (durable) {
            auto expired = settle_outgoing_expiry(
                *durable_record, unix_time_ms());
            if (!expired) {
                return expired.status();
            }
            if (expired.value()) {
                {
                    std::scoped_lock lock(description_mutex_);
                    auto found = descriptions_.find(friend_number);
                    if (found != descriptions_.end()) {
                        found->second.snapshot.state =
                            protocol::PeerDescriptionState::expired;
                        found->second.snapshot.outcome =
                            protocol::CommandOutcome::expired;
                        found->second.snapshot.detail =
                            durable_record->lifecycle ==
                                    CommandLifecycle::timed_out_unconfirmed
                                ? "request TTL elapsed after a committed "
                                  "delivery attempt; "
                                  "outcome is unconfirmed"
                                : "request TTL elapsed before its first "
                                  "delivery attempt";
                        found->second.snapshot.updated_unix_ms = unix_time_ms();
                    }
                }
                publish_peer_description_best_effort(friend_number);
                return peer_description(friend_number);
            }
        }

        if (durable && !command_artifact_due(
                *durable_record, CommandArtifact::request,
                command_schedule_time_ms())) {
            publish_peer_description_best_effort(friend_number);
            return peer_description(friend_number);
        }

        {
            std::scoped_lock lock(description_mutex_);
            auto found = descriptions_.find(friend_number);
            if (found == descriptions_.end() ||
                found->second.snapshot.request_message_id != frame.message_id) {
                return Status{ErrorCode::unavailable,
                              "device.describe reservation changed before send"};
            }
            ++found->second.snapshot.send_attempts;
            found->second.snapshot.state =
                protocol::PeerDescriptionState::awaiting_result;
            found->second.snapshot.last_send_error_code = ErrorCode::ok;
            found->second.snapshot.last_send_error.clear();
            found->second.snapshot.detail = retry
                ? "retrying the exact frozen device.describe frame"
                : "sending the frozen device.describe frame";
            found->second.snapshot.updated_unix_ms = unix_time_ms();
        }

        if (durable) {
            if (!command_admission_open_.load()) {
                return Status{ErrorCode::unavailable,
                              "durable command delivery is stopped during shutdown"};
            }
            const Status began = begin_command_delivery_attempt(
                *durable_record, CommandArtifact::request,
                command_schedule_time_ms());
            if (!began.ok()) {
                return began;
            }
            const Status attempt_stored =
                update_command_record(*durable_record);
            if (!attempt_stored.ok()) {
                return Status{
                    attempt_stored.code(),
                    "device.describe was not sent because its durable "
                    "attempt could not be committed: " +
                        attempt_stored.message()};
            }
        }
        publish_peer_description_best_effort(friend_number);

        auto packet = protocol::encode(frame);
        Status queued = packet
            ? transport_.send_lossless(friend_number, packet.value())
            : packet.status();

        Status durable_after_send = Status::success();
        if (durable) {
            durable_record->request_schedule.last_error_code =
                queued.ok() ? ErrorCode::ok : queued.code();
            durable_record->updated_unix_ms = std::max(
                durable_record->updated_unix_ms,
                command_schedule_time_ms());
            durable_after_send = update_command_record(*durable_record);
        }

        {
            std::scoped_lock lock(description_mutex_);
            auto found = descriptions_.find(friend_number);
            if (found == descriptions_.end() ||
                found->second.snapshot.request_message_id != frame.message_id) {
                return Status{ErrorCode::unavailable,
                              "device.describe reservation changed during send"};
            }
            if (!queued.ok()) {
                found->second.snapshot.state =
                    protocol::PeerDescriptionState::send_failed;
                found->second.snapshot.last_send_error_code = queued.code();
                found->second.snapshot.last_send_error = queued.message();
                found->second.snapshot.detail =
                    retryable_protocol_send_error(queued.code())
                        ? "local toxcore enqueue failed; exact durable retry is pending"
                        : "local toxcore enqueue failed and is not retryable";
            } else if (!durable_after_send.ok()) {
                found->second.snapshot.state =
                    protocol::PeerDescriptionState::internal_error;
                found->second.snapshot.last_send_error_code =
                    durable_after_send.code();
                found->second.snapshot.last_send_error =
                    durable_after_send.message();
                found->second.snapshot.detail =
                    "request entered the local Tox queue, but the post-send "
                    "journal "
                    "update failed; the frozen request remains recoverable";
            } else {
                found->second.snapshot.state =
                    protocol::PeerDescriptionState::awaiting_result;
                found->second.snapshot.last_send_error_code = ErrorCode::ok;
                found->second.snapshot.last_send_error.clear();
                found->second.snapshot.detail =
                    durable ? "request accepted by the local Tox send queue; "
                              "awaiting "
                              "durable receipt and COMMAND_RESULT"
                            : "request accepted by the local Tox send queue; "
                              "awaiting "
                              "COMMAND_RESULT";
            }
            found->second.snapshot.updated_unix_ms = unix_time_ms();
        }
        publish_peer_description_best_effort(friend_number);
        if (!queued.ok() && !retryable_protocol_send_error(queued.code())) {
            return queued;
        }
        if (queued.ok()) {
            record_protocol_frame(friend_number, "outgoing", frame);
        }
        if (!durable_after_send.ok()) {
            return durable_after_send;
        }
        return peer_description(friend_number);
    }

    Result<DurableCommandRecord> send_generic_command_request(
        std::uint32_t friend_number,
        const protocol::CommandRequest &request,
        bool recovery = false) {
        if (!recovery && !command_admission_open_.load()) {
            return Status{ErrorCode::unavailable,
                          "durable command admission is closed during shutdown"};
        }
        const auto policy =
            protocol::command_operation_policy(request.operation);
        if (!policy.has_value() ||
            !protocol::command_restart_safe(request.operation) ||
            request.operation == protocol::CommandOperation::device_describe) {
            return Status{ErrorCode::invalid_argument,
                          "generic sender requires a registered restart-safe "
                          "non-description operation"};
        }
        auto session = sessions_.get(friend_number);
        if (!session) {
            return session.status();
        }
        if (!protocol::is_application_ready(session.value()) ||
            !durable_commands_negotiated(session.value())) {
            return Status{ErrorCode::unavailable,
                          "generic command requires a confirmed durable IoTox session"};
        }
        if (authority_sessions_ == nullptr || command_store_ == nullptr) {
            return Status{ErrorCode::internal_error,
                          "durable command machinery is not initialized"};
        }
        auto authority = authority_sessions_->get(friend_number);
        if (!authority) {
            return authority.status();
        }
        if (authority.value().claimant_state !=
            security::AuthorityClaimantState::proof_sent) {
            return Status{ErrorCode::unavailable,
                          "generic command waits for the local stable-device proof"};
        }

        std::scoped_lock durable_lock(durable_command_mutex_);
        auto peer = command_peer_key_for(friend_number);
        if (!peer) {
            return peer.status();
        }

        std::optional<DurableCommandRecord> selected;
        for (const auto &candidate : command_store_->records_for_peer(
                 peer.value(), CommandDirection::outgoing)) {
            if (candidate.operation == request.operation &&
                !command_lifecycle_terminal(candidate.lifecycle)) {
                selected = candidate;
                break;
            }
        }
        if (selected.has_value() && !recovery) {
            return Status{ErrorCode::unavailable,
                          protocol::to_string(request.operation) +
                              " already has a nonterminal durable request for this peer"};
        }
        protocol::Frame frame;
        if (selected.has_value()) {
            auto decoded = protocol::decode(selected->canonical_request);
            if (!decoded) {
                return Status{decoded.status().code(),
                              "stored generic command request is unreadable: " +
                                  decoded.status().message()};
            }
            frame = decoded.value();
            if (frame.major != session.value().negotiated.selected.major ||
                frame.minor != session.value().negotiated.selected.minor) {
                return Status{ErrorCode::unsupported,
                              "stored generic command uses a different protocol version"};
            }
        } else {
            auto payload = protocol::encode_command_request(request);
            if (!payload) {
                return payload.status();
            }
            auto message_id = security::random_u64_nonzero();
            if (!message_id) {
                return message_id.status();
            }
            frame.major = session.value().negotiated.selected.major;
            frame.minor = session.value().negotiated.selected.minor;
            frame.type = protocol::MessageType::command;
            frame.message_id = message_id.value();
            frame.sequence = command_store_->local_sender_epoch();
            frame.payload.assign(payload.value().begin(), payload.value().end());
            auto canonical = protocol::encode(frame);
            if (!canonical) {
                return canonical.status();
            }
            DurableCommandRecord record;
            record.key.direction = CommandDirection::outgoing;
            record.key.peer_public_key = peer.value();
            record.key.sender_epoch = frame.sequence;
            record.key.message_id = frame.message_id;
            record.direction = CommandDirection::outgoing;
            record.lifecycle = CommandLifecycle::reserved;
            record.operation = request.operation;
            record.outcome = protocol::CommandOutcome::internal_error;
            record.created_unix_ms = command_schedule_time_ms();
            record.updated_unix_ms = record.created_unix_ms;
            record.request_schedule.next_attempt_unix_ms =
                record.created_unix_ms + kDefaultCommandAdmissionDelayMs;
            record.canonical_request = canonical.value();
            CommandInsertDisposition disposition{};
            const Status inserted = insert_command_record(record, &disposition);
            if (!inserted.ok()) {
                return inserted;
            }
            if (disposition != CommandInsertDisposition::inserted) {
                return Status{ErrorCode::protocol_error,
                              "new generic command identity collided with the durable journal"};
            }
            selected = std::move(record);
        }

        auto expired = settle_outgoing_expiry(*selected, unix_time_ms());
        if (!expired) {
            return expired.status();
        }
        if (expired.value()) {
            return *selected;
        }

        if (!command_artifact_due(
                *selected, CommandArtifact::request,
                command_schedule_time_ms())) {
            return *selected;
        }
        if (!command_admission_open_.load()) {
            return Status{ErrorCode::unavailable,
                          "durable command delivery is stopped during shutdown"};
        }
        const Status began = begin_command_delivery_attempt(
            *selected, CommandArtifact::request,
            command_schedule_time_ms());
        if (!began.ok()) {
            return began;
        }
        const Status attempt = update_command_record(*selected);
        if (!attempt.ok()) {
            return Status{attempt.code(),
                          "generic command attempt was not committed before transport: " +
                              attempt.message()};
        }

        const Status queued = transport_.send_lossless(
            friend_number, selected->canonical_request);
        selected->request_schedule.last_error_code =
            queued.ok() ? ErrorCode::ok : queued.code();
        selected->updated_unix_ms =
            std::max(selected->updated_unix_ms,
                     command_schedule_time_ms());
        const Status persisted = update_command_record(*selected);
        if (!persisted.ok()) {
            return persisted;
        }
        if (queued.ok()) {
            record_protocol_frame(friend_number, "outgoing", frame);
        } else if (!retryable_protocol_send_error(queued.code())) {
            return queued;
        }
        return *selected;
    }

    void service_device_descriptions_best_effort() {
        std::vector<std::uint32_t> retry;
        {
            std::scoped_lock lock(description_mutex_);
            for (const auto &[friend_number, entry] : descriptions_) {
                if (entry.snapshot.state ==
                        protocol::PeerDescriptionState::send_failed &&
                    retryable_protocol_send_error(
                        entry.snapshot.last_send_error_code)) {
                    retry.push_back(friend_number);
                }
            }
        }
        for (const std::uint32_t friend_number : retry) {
            auto sent = send_device_describe_request(friend_number, true);
            if (!sent && !retryable_protocol_send_error(sent.status().code())) {
                record_projection_failure(Status{
                    sent.status().code(),
                    "device.describe automatic retry failed: " +
                        sent.status().message()});
            }
        }
    }

    void service_durable_command_recovery_best_effort() {
        if (command_store_ == nullptr || authority_sessions_ == nullptr) {
            return;
        }

        DurableCommandSnapshot snapshot = command_store_->snapshot();
        const std::uint64_t recovery_now = unix_time_ms();
        if (trusted_wall_clock_usable(recovery_now)) {
            const std::uint64_t now = recovery_now;
            for (DurableCommandRecord record : snapshot.records) {
                if (record.direction != CommandDirection::outgoing ||
                    record.expiry_unix_ms == 0U ||
                    command_lifecycle_terminal(record.lifecycle) ||
                    now < record.expiry_unix_ms) {
                    continue;
                }
                std::scoped_lock durable_lock(durable_command_mutex_);
                auto current = command_store_->find(record.key);
                if (!current || !current.value().has_value()) {
                    continue;
                }
                auto expired = settle_outgoing_expiry(
                    current.value().value(), now);
                if (!expired) {
                    record_projection_failure(Status{
                        expired.status().code(),
                        "unable to settle expired outgoing command: " +
                            expired.status().message()});
                }
            }
            snapshot = command_store_->snapshot();
        }
        std::vector<std::pair<std::uint32_t, DurableCommandRecord>>
            outgoing;
        std::vector<std::pair<std::uint32_t, DurableCommandRecord>> incoming;
        for (const DurableCommandRecord &record :
             order_command_outbox(snapshot.records)) {
            if (command_lifecycle_terminal(record.lifecycle) ||
                !protocol::command_restart_safe(record.operation)) {
                continue;
            }
            const auto friend_number =
                friend_number_for_command_peer(record.key.peer_public_key);
            if (!friend_number.has_value()) {
                continue;
            }
            if (record.key.direction == CommandDirection::outgoing) {
                if (!command_artifact_due(
                        record, CommandArtifact::request,
                        command_schedule_time_ms())) {
                    continue;
                }
                if (record.request_schedule.last_error_code != ErrorCode::ok &&
                    !retryable_protocol_send_error(
                        record.request_schedule.last_error_code)) {
                    continue;
                }
                outgoing.emplace_back(*friend_number, record);
            } else {
                incoming.emplace_back(*friend_number, record);
            }
        }

        // The sender can always retry one frozen restart-safe request. The send
        // path reconstructs the live ratox-style projection from the signed
        // journal, waits for transcript and claimant proof readiness, then
        // queues exactly the previously committed bytes.
        for (const auto &[friend_number, record] : outgoing) {
            if (event_stop_.load()) {
                return;
            }
            if (record.operation ==
                protocol::CommandOperation::device_describe) {
                auto recovered = send_device_describe_request(
                    friend_number, true);
                if (!recovered &&
                    !retryable_protocol_send_error(recovered.status().code())) {
                    record_projection_failure(Status{
                        recovered.status().code(),
                        "durable outgoing device.describe recovery failed: " +
                            recovered.status().message()});
                }
            } else {
                auto frame = protocol::decode(record.canonical_request);
                auto command = frame
                    ? protocol::decode_command_request(frame.value().payload)
                    : Result<protocol::CommandRequest>{frame.status()};
                if (!command) {
                    record_projection_failure(
                        Status{command.status().code(),
                               "durable outgoing command recovery "
                               "could not decode its frozen request: " +
                                   command.status().message()});
                    continue;
                }
                auto recovered = send_generic_command_request(
                    friend_number, command.value(), true);
                if (!recovered &&
                    !retryable_protocol_send_error(recovered.status().code())) {
                    record_projection_failure(Status{
                        recovered.status().code(),
                        "durable outgoing generic command recovery failed: " +
                            recovered.status().message()});
                }
            }
        }

        // Read-only operations reconstruct current observations. The one
        // mutable operation reconstructs one bounded desired value and may
        // reapply it because its operation table explicitly declares desired-
        // state idempotence. No other effect enters this recovery path.
        for (const auto &[friend_number, record] : incoming) {
            auto session = sessions_.get(friend_number);
            auto authority = authority_sessions_->get(friend_number);
            if (!session || !durable_commands_negotiated(session.value()) ||
                !authority || !authority.value().remote_authorized) {
                continue;
            }
            auto frame = protocol::decode(record.canonical_request);
            if (!frame) {
                record_projection_failure(Status{
                    frame.status().code(),
                    "stored incoming durable request cannot be resumed: " +
                        frame.status().message()});
                continue;
            }
            if (frame.value().major != session.value().negotiated.selected.major ||
                frame.value().minor != session.value().negotiated.selected.minor) {
                continue;
            }
            handle_incoming_durable_command(
                friend_number, session.value(), frame.value(),
                record.canonical_request, true);
        }
    }

    void handle_incoming_command_receipt(
        std::uint32_t friend_number, const protocol::Frame &frame) {
        auto session = sessions_.get(friend_number);
        if (!session) {
            record_projection_failure(session.status());
            return;
        }
        if (!durable_commands_negotiated(session.value()) ||
            frame.flags != 0U || frame.sequence == 0U ||
            frame.expiry_unix_ms != 0U || frame.correlation_id == 0U) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected malformed or unnegotiated command receipt friend=" +
                std::to_string(friend_number);
            return;
        }
        auto receipt = protocol::decode_command_receipt(frame.payload);
        if (!receipt) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected malformed command receipt payload friend=" +
                std::to_string(friend_number) + " detail=" +
                receipt.status().message();
            return;
        }
        auto canonical = protocol::encode(frame);
        if (!canonical) {
            record_projection_failure(canonical.status());
            return;
        }
        std::scoped_lock durable_lock(durable_command_mutex_);
        auto peer_key = command_peer_key_for(friend_number);
        if (!peer_key) {
            record_projection_failure(peer_key.status());
            return;
        }
        DurableCommandKey key;
        key.direction = CommandDirection::outgoing;
        key.peer_public_key = peer_key.value();
        key.sender_epoch = frame.sequence;
        key.message_id = frame.correlation_id;
        auto stored = command_store_->find(key);
        if (!stored) {
            record_projection_failure(stored.status());
            return;
        }
        if (!stored.value().has_value() ||
            stored.value()->direction != CommandDirection::outgoing) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "ignored unmatched durable command receipt friend=" +
                std::to_string(friend_number) + " correlation=" +
                std::to_string(frame.correlation_id);
            return;
        }
        DurableCommandRecord record = stored.value().value();
        if (!record.canonical_receipt.empty() &&
            record.canonical_receipt != canonical.value()) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "command-receipt-conflict friend=" +
                std::to_string(friend_number) + " correlation=" +
                std::to_string(frame.correlation_id);
            return;
        }
        const bool exact_duplicate =
            !record.canonical_receipt.empty();
        if (!exact_duplicate) {
            record.canonical_receipt = canonical.value();
            record.receipt_delivery = CommandDeliveryState::observed;
            if (record.lifecycle == CommandLifecycle::reserved ||
                record.lifecycle == CommandLifecycle::locally_queued) {
                record.lifecycle = CommandLifecycle::received;
            }
            auto authority = authority_sessions_ != nullptr
                ? authority_sessions_->get(friend_number)
                : Result<security::PeerAuthoritySnapshot>{Status{
                      ErrorCode::internal_error,
                      "authority session machinery is not initialized"}};
            if (authority) {
                record.peer_principal =
                    authority.value().peer_verifier_device;
                record.ownership_epoch =
                    authority.value().peer_authority_epoch;
                record.authority_sequence =
                    authority.value().peer_authority_sequence;
            }
            record.updated_unix_ms = std::max(
                record.updated_unix_ms, command_schedule_time_ms());
            const Status updated = update_command_record(record);
            if (!updated.ok()) {
                record_projection_failure(Status{
                    updated.code(),
                    "unable to commit received command receipt: " +
                        updated.message()});
                return;
            }
        }

        bool matched = false;
        bool changed_conflict = false;
        {
            std::scoped_lock lock(description_mutex_);
            auto found = descriptions_.find(friend_number);
            if (found != descriptions_.end() &&
                found->second.snapshot.online_epoch ==
                    session.value().online_epoch &&
                found->second.snapshot.request_message_id ==
                    frame.correlation_id &&
                found->second.snapshot.sender_epoch == frame.sequence) {
                matched = true;
                if (!found->second.frozen_receipt_frame.empty() &&
                    found->second.frozen_receipt_frame != canonical.value()) {
                    changed_conflict = true;
                    found->second.snapshot.state =
                        protocol::PeerDescriptionState::conflict;
                    found->second.snapshot.outcome =
                        protocol::CommandOutcome::conflict;
                    found->second.snapshot.detail =
                        "a second non-identical receipt reused the reserved correlation";
                } else {
                    found->second.frozen_receipt_frame = canonical.value();
                    found->second.snapshot.receipt_message_id =
                        frame.message_id;
                    found->second.snapshot.receipt_stage =
                        receipt.value().stage;
                    found->second.snapshot.detail =
                        "peer durably recorded the request; awaiting COMMAND_RESULT";
                }
                found->second.snapshot.updated_unix_ms = unix_time_ms();
            }
        }
        if (matched) {
            publish_peer_description_best_effort(friend_number);
        }
        std::scoped_lock lock(snapshot_mutex_);
        if (!matched) {
            snapshot_.last_event =
                "durable command receipt committed without a live "
                "description projection friend=" +
                std::to_string(friend_number);
        } else if (changed_conflict) {
            snapshot_.last_event =
                "device.describe receipt conflict friend=" +
                std::to_string(friend_number);
        } else {
            snapshot_.last_event = exact_duplicate
                ? "duplicate exact durable command receipt ignored friend=" +
                      std::to_string(friend_number)
                : "durable command receipt accepted friend=" +
                      std::to_string(friend_number) + " stage=" +
                      protocol::to_string(receipt.value().stage);
        }
    }

    void handle_incoming_command_result(
        std::uint32_t friend_number, const protocol::Frame &frame) {
        auto session = sessions_.get(friend_number);
        if (!session) {
            record_projection_failure(session.status());
            return;
        }
        const bool durable = durable_commands_negotiated(session.value());
        std::unique_lock<std::mutex> durable_lock(
            durable_command_mutex_, std::defer_lock);
        if (durable) {
            durable_lock.lock();
        }
        if (frame.flags != 0U ||
            (durable ? frame.sequence == 0U : frame.sequence != 0U) ||
            frame.expiry_unix_ms != 0U || frame.correlation_id == 0U) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected malformed COMMAND_RESULT envelope friend=" +
                std::to_string(friend_number);
            return;
        }
        auto result = protocol::decode_command_result(frame.payload);
        if (!result) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected malformed COMMAND_RESULT payload friend=" +
                std::to_string(friend_number) + " detail=" +
                result.status().message();
            return;
        }
        auto canonical = protocol::encode(frame);
        if (!canonical) {
            record_projection_failure(canonical.status());
            return;
        }
        auto authority = authority_sessions_ != nullptr
            ? authority_sessions_->get(friend_number)
            : Result<security::PeerAuthoritySnapshot>{Status{
                  ErrorCode::internal_error,
                  "authority session machinery is not initialized"}};

        bool durable_exact_duplicate = false;
        if (durable) {
            auto peer_key = command_peer_key_for(friend_number);
            if (!peer_key) {
                record_projection_failure(peer_key.status());
                return;
            }
            DurableCommandKey key;
            key.direction = CommandDirection::outgoing;
            key.peer_public_key = peer_key.value();
            key.sender_epoch = frame.sequence;
            key.message_id = frame.correlation_id;
            auto stored = command_store_->find(key);
            if (!stored) {
                record_projection_failure(stored.status());
                return;
            }
            if (!stored.value().has_value() ||
                stored.value()->direction != CommandDirection::outgoing) {
                std::scoped_lock lock(snapshot_mutex_);
                snapshot_.last_event =
                    "ignored unmatched durable COMMAND_RESULT friend=" +
                    std::to_string(friend_number) + " correlation=" +
                    std::to_string(frame.correlation_id);
                return;
            }
            DurableCommandRecord record = stored.value().value();
            if (result.value().operation != record.operation) {
                std::scoped_lock lock(snapshot_mutex_);
                snapshot_.last_event = "rejected durable COMMAND_RESULT with "
                                       "mismatched operation friend=" +
                                       std::to_string(friend_number);
                return;
            }
            if (record.operation ==
                    protocol::CommandOperation::profile_status_set &&
                result.value().outcome ==
                    protocol::CommandOutcome::succeeded) {
                auto request_frame = protocol::decode(
                    record.canonical_request);
                auto request_payload = request_frame
                    ? protocol::decode_command_request(
                          request_frame.value().payload)
                    : Result<protocol::CommandRequest>{
                          request_frame.status()};
                auto evidence =
                    protocol::decode_profile_status_evidence(
                        result.value().body);
                if (!request_payload || !evidence ||
                    !request_payload.value().desired_profile_status
                         .has_value() ||
                    evidence.value().desired !=
                        *request_payload.value().desired_profile_status ||
                    evidence.value().observed !=
                        *request_payload.value().desired_profile_status) {
                    std::scoped_lock lock(snapshot_mutex_);
                    snapshot_.last_event =
                        "rejected profile.status.set result without "
                        "exact convergence evidence friend=" +
                        std::to_string(friend_number);
                    return;
                }
            }
            if (!record.canonical_result.empty()) {
                durable_exact_duplicate =
                    record.canonical_result == canonical.value();
                if (!durable_exact_duplicate) {
                    std::scoped_lock lock(snapshot_mutex_);
                    snapshot_.last_event =
                        "durable command result conflict friend=" +
                        std::to_string(friend_number) + " correlation=" +
                        std::to_string(frame.correlation_id);
                    return;
                }
            } else {
                record.lifecycle =
                    lifecycle_for_outcome(result.value().outcome);
                record.outcome = result.value().outcome;
                record.result_message_id = frame.message_id;
                record.correlation_id = frame.correlation_id;
                record.canonical_result = canonical.value();
                record.result_delivery = CommandDeliveryState::observed;
                if (authority) {
                    record.peer_principal =
                        authority.value().peer_verifier_device;
                    record.ownership_epoch =
                        authority.value().peer_authority_epoch;
                    record.authority_sequence =
                        authority.value().peer_authority_sequence;
                }
                record.updated_unix_ms = std::max(
                    record.updated_unix_ms, command_schedule_time_ms());
                const Status updated = update_command_record(record);
                if (!updated.ok()) {
                    record_projection_failure(Status{
                        updated.code(),
                        "unable to commit durable COMMAND_RESULT: " +
                            updated.message()});
                    return;
                }
            }
        }

        bool exact_duplicate = false;
        bool unmatched_result = false;
        {
            std::scoped_lock lock(description_mutex_);
            const auto found = descriptions_.find(friend_number);
            if (found == descriptions_.end() ||
                found->second.snapshot.online_epoch !=
                    session.value().online_epoch ||
                found->second.snapshot.request_message_id !=
                    frame.correlation_id ||
                found->second.snapshot.sender_epoch != frame.sequence) {
                unmatched_result = true;
            } else {
                PeerDescriptionEntry &entry = found->second;
                if (!entry.frozen_result_frame.empty()) {
                    exact_duplicate =
                        entry.frozen_result_frame == canonical.value();
                    if (!exact_duplicate) {
                        entry.snapshot.state =
                            protocol::PeerDescriptionState::conflict;
                        entry.snapshot.outcome =
                            protocol::CommandOutcome::conflict;
                        entry.snapshot.detail =
                            "a second non-identical result reused the reserved correlation";
                        entry.snapshot.updated_unix_ms = unix_time_ms();
                    }
                } else if (result.value().operation !=
                           protocol::CommandOperation::device_describe) {
                    entry.snapshot.state =
                        protocol::PeerDescriptionState::conflict;
                    entry.snapshot.outcome =
                        protocol::CommandOutcome::conflict;
                    entry.snapshot.result_message_id = frame.message_id;
                    entry.snapshot.detail =
                        "COMMAND_RESULT operation does not match device.describe";
                    entry.snapshot.updated_unix_ms = unix_time_ms();
                    entry.frozen_result_frame = canonical.value();
                } else {
                    entry.frozen_result_frame = canonical.value();
                    entry.snapshot.result_message_id = frame.message_id;
                    entry.snapshot.outcome = result.value().outcome;
                    entry.snapshot.description.reset();
                    switch (result.value().outcome) {
                        case protocol::CommandOutcome::succeeded: {
                            auto description = protocol::decode_device_description(
                                result.value().body);
                            if (!description) {
                                entry.snapshot.state =
                                    protocol::PeerDescriptionState::malformed;
                                entry.snapshot.outcome =
                                    protocol::CommandOutcome::malformed;
                                entry.snapshot.detail =
                                    description.status().message();
                                break;
                            }
                            if (description.value().protocol !=
                                session.value().negotiated.selected) {
                                entry.snapshot.state =
                                    protocol::PeerDescriptionState::conflict;
                                entry.snapshot.outcome =
                                    protocol::CommandOutcome::conflict;
                                entry.snapshot.detail =
                                    "device description protocol does not "
                                    "match the confirmed session";
                                break;
                            }
                            if (!authority ||
                                description.value().device_principal !=
                                    authority.value().peer_verifier_device) {
                                entry.snapshot.state =
                                    protocol::PeerDescriptionState::conflict;
                                entry.snapshot.outcome =
                                    protocol::CommandOutcome::conflict;
                                entry.snapshot.detail =
                                    "device description principal does not "
                                    "match the peer challenge verifier";
                                break;
                            }
                            entry.snapshot.state =
                                protocol::PeerDescriptionState::succeeded;
                            entry.snapshot.description = description.value();
                            entry.snapshot.detail =
                                "peer description accepted and bound to "
                                "the authority challenge principal";
                            break;
                        }
                        case protocol::CommandOutcome::denied:
                            entry.snapshot.state =
                                protocol::PeerDescriptionState::denied;
                            entry.snapshot.detail =
                                "peer denied device.describe";
                            break;
                        case protocol::CommandOutcome::malformed:
                            entry.snapshot.state =
                                protocol::PeerDescriptionState::malformed;
                            entry.snapshot.detail =
                                "peer rejected the request as malformed";
                            break;
                        case protocol::CommandOutcome::unsupported:
                            entry.snapshot.state =
                                protocol::PeerDescriptionState::unsupported;
                            entry.snapshot.detail =
                                "peer does not support device.describe";
                            break;
                        case protocol::CommandOutcome::expired:
                            entry.snapshot.state =
                                protocol::PeerDescriptionState::expired;
                            entry.snapshot.detail =
                                "peer reports that the request expired";
                            break;
                        case protocol::CommandOutcome::conflict:
                            entry.snapshot.state =
                                protocol::PeerDescriptionState::conflict;
                            entry.snapshot.detail =
                                "peer reports a command conflict";
                            break;
                        case protocol::CommandOutcome::internal_error:
                            entry.snapshot.state =
                                protocol::PeerDescriptionState::internal_error;
                            entry.snapshot.detail =
                                "peer reported an internal error";
                            break;
                    }
                    entry.snapshot.updated_unix_ms = unix_time_ms();
                }
            }
        }
        if (unmatched_result) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "ignored unmatched COMMAND_RESULT friend=" +
                std::to_string(friend_number) + " correlation=" +
                std::to_string(frame.correlation_id);
            return;
        }
        publish_peer_description_best_effort(friend_number);
        std::scoped_lock lock(snapshot_mutex_);
        snapshot_.last_event = (exact_duplicate || durable_exact_duplicate)
            ? "duplicate exact device.describe result ignored friend=" +
                  std::to_string(friend_number)
            : "device.describe result accepted friend=" +
                  std::to_string(friend_number) + " outcome=" +
                  protocol::to_string(result.value().outcome);
    }

    void handle_incoming_durable_command(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame,
        const std::vector<std::uint8_t> &canonical_request,
        bool recovery = false) {
        if (!command_admission_open_.load()) {
            return;
        }
        std::scoped_lock durable_lock(durable_command_mutex_);
        protocol::CommandResultPayload early_result;
        early_result.operation = protocol::CommandOperation::unknown;
        early_result.outcome = protocol::CommandOutcome::malformed;

        auto request = protocol::decode_command_request(frame.payload);
        if (!request) {
            early_result.outcome =
                request.status().code() == ErrorCode::unsupported
                    ? protocol::CommandOutcome::unsupported
                    : protocol::CommandOutcome::malformed;
            const Status sent = send_ephemeral_command_result(
                friend_number, session, frame, canonical_request,
                early_result);
            if (!sent.ok()) {
                record_projection_failure(Status{
                    sent.code(),
                    "unable to answer malformed durable COMMAND: " +
                        sent.message()});
            }
            return;
        }
        early_result.operation = request.value().operation;
        if (request.value().operation ==
                protocol::CommandOperation::update_stage &&
            ((session.negotiated.shared_features &
              protocol::feature_bit(
                  protocol::Feature::signed_ota_v1)) == 0U ||
             update_store_ == nullptr)) {
            early_result.outcome = protocol::CommandOutcome::unsupported;
            const Status sent = send_ephemeral_command_result(
                friend_number, session, frame, canonical_request,
                early_result);
            if (!sent.ok()) {
                record_projection_failure(Status{
                    sent.code(),
                    "unable to answer unnegotiated update.stage COMMAND: " +
                        sent.message()});
            }
            return;
        }
        const auto request_policy = protocol::command_operation_policy(
            request.value().operation);
        if (frame.flags != 0U || frame.correlation_id != 0U ||
            frame.sequence == 0U ||
            (request_policy.has_value() && !request_policy->read_only &&
             frame.expiry_unix_ms != 0U)) {
            const Status sent = send_ephemeral_command_result(
                friend_number, session, frame, canonical_request,
                early_result);
            if (!sent.ok()) {
                record_projection_failure(Status{
                    sent.code(),
                    "unable to answer malformed durable COMMAND envelope: " +
                        sent.message()});
            }
            return;
        }
        if (command_store_ == nullptr) {
            record_projection_failure(Status{
                ErrorCode::internal_error,
                "durable command store is not initialized"});
            return;
        }
        auto peer_key = command_peer_key_for(friend_number);
        if (!peer_key) {
            record_projection_failure(peer_key.status());
            return;
        }

        DurableCommandKey key;
        key.direction = CommandDirection::incoming;
        key.peer_public_key = peer_key.value();
        key.sender_epoch = frame.sequence;
        key.message_id = frame.message_id;
        auto existing = command_store_->find(key);
        if (!existing) {
            record_projection_failure(existing.status());
            return;
        }

        DurableCommandRecord record;
        bool duplicate = false;
        if (existing.value().has_value()) {
            record = existing.value().value();
            if (record.direction != CommandDirection::incoming ||
                record.canonical_request != canonical_request) {
                protocol::CommandResultPayload conflict;
                conflict.operation = request.value().operation;
                conflict.outcome = protocol::CommandOutcome::conflict;
                const Status sent = send_ephemeral_command_result(
                    friend_number, session, frame, canonical_request,
                    conflict);
                std::scoped_lock lock(snapshot_mutex_);
                snapshot_.last_event = sent.ok()
                    ? "durable command key conflict answered friend=" +
                          std::to_string(friend_number)
                    : "durable command key conflict answer failed friend=" +
                          std::to_string(friend_number) + " detail=" +
                          sent.message();
                return;
            }
            duplicate = true;
        } else {
            auto receipt_payload = protocol::encode_command_receipt(
                protocol::CommandReceipt{
                    protocol::CommandReceiptStage::received});
            if (!receipt_payload) {
                record_projection_failure(receipt_payload.status());
                return;
            }
            auto receipt_message_id = security::random_u64_nonzero();
            if (!receipt_message_id) {
                record_projection_failure(receipt_message_id.status());
                return;
            }
            protocol::Frame receipt_frame;
            receipt_frame.major = session.negotiated.selected.major;
            receipt_frame.minor = session.negotiated.selected.minor;
            receipt_frame.type = protocol::MessageType::acknowledgement;
            receipt_frame.message_id = receipt_message_id.value();
            receipt_frame.correlation_id = frame.message_id;
            receipt_frame.sequence = frame.sequence;
            receipt_frame.expiry_unix_ms = 0U;
            receipt_frame.payload.assign(
                receipt_payload.value().begin(),
                receipt_payload.value().end());
            auto canonical_receipt = protocol::encode(receipt_frame);
            if (!canonical_receipt) {
                record_projection_failure(canonical_receipt.status());
                return;
            }

            const std::uint64_t now = command_schedule_time_ms();
            record.key = key;
            record.direction = CommandDirection::incoming;
            record.lifecycle = CommandLifecycle::received;
            record.operation = request.value().operation;
            record.outcome =
                protocol::CommandOutcome::internal_error;
            record.receipt_delivery = CommandDeliveryState::pending;
            record.created_unix_ms = now;
            record.updated_unix_ms = now;
            record.expiry_unix_ms = frame.expiry_unix_ms;
            record.clock_requirement = frame.expiry_unix_ms == 0U
                ? CommandClockRequirement::none
                : CommandClockRequirement::trusted_wall;
            record.receipt_schedule.next_attempt_unix_ms = now;
            record.canonical_request = canonical_request;
            record.canonical_receipt =
                std::move(canonical_receipt).value();
            CommandInsertDisposition disposition{};
            const Status inserted = insert_command_record(
                record, &disposition);
            if (!inserted.ok()) {
                record_projection_failure(Status{
                    inserted.code(), "durable COMMAND was not admitted because "
                                     "its receipt could not be committed: " +
                                         inserted.message()});
                return;
            }
            if (disposition != CommandInsertDisposition::inserted) {
                auto raced = command_store_->find(key);
                if (!raced || !raced.value().has_value()) {
                    record_projection_failure(Status{
                        ErrorCode::protocol_error,
                        "durable command insertion raced without a recoverable record"});
                    return;
                }
                record = raced.value().value();
                duplicate = true;
            }
        }

        if (!record.canonical_receipt.empty()) {
            const Status receipt_sent = send_durable_command_artifact(
                friend_number, record, true, duplicate && !recovery);
            if (!receipt_sent.ok() &&
                !retryable_protocol_send_error(receipt_sent.code())) {
                record_projection_failure(Status{
                    receipt_sent.code(),
                    "durable command receipt send failed: " +
                        receipt_sent.message()});
            }
        }
        if (command_lifecycle_terminal(record.lifecycle)) {
            const Status result_sent = send_durable_command_artifact(
                friend_number, record, false, duplicate && !recovery);
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                result_sent.ok()
                    ? "durable command duplicate replayed exact "
                      "terminal result friend=" +
                          std::to_string(friend_number)
                    : "durable command terminal replay failed friend=" +
                          std::to_string(friend_number) +
                          " detail=" + result_sent.message();
            return;
        }

        if (record.clock_requirement == CommandClockRequirement::trusted_wall &&
            !trusted_wall_clock_usable(unix_time_ms())) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "durable expiring command held for uncertain wall clock friend=" +
                std::to_string(friend_number);
            return;
        }

        protocol::CommandResultPayload result;
        result.operation = request.value().operation;
        result.outcome = protocol::CommandOutcome::malformed;
        std::unique_lock<std::mutex> update_operation_lock(
            update_operation_mutex_, std::defer_lock);
        const std::uint64_t now = unix_time_ms();
        const security::AuthoritySnapshot authority_snapshot =
            authority_ != nullptr
                ? authority_->snapshot()
                : security::AuthoritySnapshot{};
        const bool expired = frame.expiry_unix_ms != 0U &&
                             frame.expiry_unix_ms <= now;
        const bool authorized = !expired &&
            authority_sessions_ != nullptr && authority_ != nullptr &&
            authority_sessions_->authorized_at(
                friend_number,
                protocol::required_capabilities(request.value().operation),
                authority_snapshot);
        auto authority_session = authority_sessions_ != nullptr
            ? authority_sessions_->get(friend_number)
            : Result<security::PeerAuthoritySnapshot>{Status{
                  ErrorCode::internal_error,
                  "authority-session registry is unavailable"}};
        const bool continuing_admitted_effect =
            record.lifecycle == CommandLifecycle::admitted ||
            record.lifecycle == CommandLifecycle::started;
        if (continuing_admitted_effect && !expired &&
            (!authorized || !authority_session ||
             authority_session.value().remote_principal !=
                 record.peer_principal ||
             authority_snapshot.ownership_epoch !=
                 record.ownership_epoch)) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "durable command recovery held for its original "
                "current principal and ownership epoch friend=" +
                std::to_string(friend_number);
            return;
        }

        if (expired) {
            result.outcome = protocol::CommandOutcome::expired;
        } else if (!authorized) {
            result.outcome = protocol::CommandOutcome::denied;
        } else {
            if (!authority_session) {
                result.outcome =
                    protocol::CommandOutcome::internal_error;
            } else {
                if (request.value().operation ==
                    protocol::CommandOperation::update_stage) {
                    update_operation_lock.lock();
                }
                if (record.lifecycle == CommandLifecycle::received) {
                    record.lifecycle = CommandLifecycle::admitted;
                    record.peer_principal =
                        authority_session.value().remote_principal;
                    record.ownership_epoch =
                        authority_snapshot.ownership_epoch;
                    record.authority_sequence =
                        authority_snapshot.sequence;
                    record.updated_unix_ms = std::max(
                        record.updated_unix_ms,
                        command_schedule_time_ms());
                    const Status admitted = update_command_record(record);
                    if (!admitted.ok()) {
                        record_projection_failure(Status{
                            admitted.code(),
                            "durable command admission could not be committed: " +
                                admitted.message()});
                        return;
                    }
                }
                if (record.lifecycle == CommandLifecycle::admitted) {
                    record.lifecycle = CommandLifecycle::started;
                    record.updated_unix_ms = std::max(
                        record.updated_unix_ms,
                        command_schedule_time_ms());
                    const Status started = update_command_record(record);
                    if (!started.ok()) {
                        record_projection_failure(Status{
                            started.code(),
                            "durable command start could not be committed: " +
                                started.message()});
                        return;
                    }
                }

                if (request_policy.has_value() &&
                    !request_policy->read_only &&
                    command_effect_witness_runtime_) {
                    auto witnessed =
                        reconcile_command_effect_frontier(true);
                    if (!witnessed) {
                        record_projection_failure(Status{
                            witnessed.status().code(),
                            "mutable command effect was not attempted because its exact started frontier could not be witnessed: " +
                                witnessed.status().message()});
                        return;
                    }
                }

                if (!identity_.has_value()) {
                    result.outcome =
                        protocol::CommandOutcome::internal_error;
                } else {
                    CommandExecutionContext context;
                    context.revision_number = kRevisionNumber;
                    context.version_major = kVersionMajor;
                    context.version_minor = kVersionMinor;
                    context.version_patch = kVersionPatch;
                    context.protocol = session.negotiated.selected;
                    context.device_principal = identity_->public_key();
                    context.supported_features = selected_supported_features_;
                    context.offered_operations = offered_operation_mask();
                    bool execution_context_ready = true;
                    if (request.value().operation ==
                        protocol::CommandOperation::system_summary) {
                        auto summary = collect_system_summary();
                        if (!summary) {
                            result.outcome =
                                protocol::CommandOutcome::internal_error;
                            execution_context_ready = false;
                            record_projection_failure(Status{
                                summary.status().code(),
                                "system summary collection failed: " +
                                    summary.status().message()});
                        } else {
                            context.system_summary = summary.value();
                        }
                    }
                    if (request.value().operation ==
                        protocol::CommandOperation::profile_status_set) {
                        if (!request.value().desired_profile_status.has_value()) {
                            result.outcome =
                                protocol::CommandOutcome::internal_error;
                            execution_context_ready = false;
                        } else {
                            const Status applied = transport_.set_self_status(
                                transport_profile_status(*request.value()
                                    .desired_profile_status));
                            if (!applied.ok()) {
                                record_projection_failure(
                                    Status{applied.code(),
                                           "profile.status.set provider effect "
                                           "or savedata "
                                           "persistence failed; durable "
                                           "lifecycle remains started: " +
                                               applied.message()});
                                return;
                            } else {
                                auto profile = refresh_profile();
                                if (!profile) {
                                    record_projection_failure(Status{
                                        profile.status().code(),
                                        "profile.status.set provider read-back "
                                        "failed; "
                                        "durable lifecycle remains started: " +
                                            profile.status().message()});
                                    return;
                                } else {
                                    context.observed_profile_status =
                                        command_profile_status(
                                            profile.value().status);
                                    publish_snapshot_best_effort();
                                }
                            }
                        }
                    }
                    if (request.value().operation ==
                        protocol::CommandOperation::update_stage) {
                        if (!request.value().expected_update_head.has_value() ||
                            update_store_ == nullptr) {
                            result.outcome =
                                protocol::CommandOutcome::internal_error;
                            execution_context_ready = false;
                        } else {
                            auto staged = stage_update_head(
                                update_store_->policy().namespace_id,
                                *request.value().expected_update_head);
                            if (!staged.ok()) {
                                result.outcome =
                                    staged.status().code() ==
                                                ErrorCode::protocol_error ||
                                            staged.status().code() ==
                                                ErrorCode::invalid_argument
                                        ? protocol::CommandOutcome::conflict
                                        : protocol::CommandOutcome::internal_error;
                                execution_context_ready = false;
                                record_projection_failure(Status{
                                    staged.status().code(),
                                    "update.stage failed closed: " +
                                        staged.status().message()});
                            } else {
                                protocol::UpdateStageEvidence evidence;
                                evidence.duplicate = staged.value().duplicate;
                                evidence.release_sequence =
                                    staged.value().state.candidate.sequence;
                                evidence.accepted_head =
                                    *request.value().expected_update_head;
                                evidence.manifest_record = staged.value()
                                    .state.candidate.manifest_record;
                                context.update_stage_evidence = evidence;
                            }
                        }
                    }
                    if (execution_context_ready) {
                        auto executed = execute_command(
                            request.value(), context);
                        if (!executed) {
                            result.outcome =
                                protocol::CommandOutcome::internal_error;
                            record_projection_failure(Status{
                                executed.status().code(),
                                "command executor failed: " +
                                    executed.status().message()});
                        } else {
                            result = std::move(executed).value();
                        }
                    }
                }
            }
        }

        auto prepared = make_command_result(
            friend_number, session, frame, canonical_request, result);
        if (!prepared) {
            record_projection_failure(prepared.status());
            return;
        }
        record.lifecycle = lifecycle_for_outcome(result.outcome);
        record.outcome = result.outcome;
        record.result_message_id =
            prepared.value().response.message_id;
        record.correlation_id = frame.message_id;
        record.canonical_result =
            prepared.value().encoded_response;
        record.result_delivery = CommandDeliveryState::pending;
        record.updated_unix_ms = std::max(
            record.updated_unix_ms, command_schedule_time_ms());
        record.result_schedule.next_attempt_unix_ms =
            record.updated_unix_ms;
        const Status completed = update_command_record(record);
        if (!completed.ok()) {
            record_projection_failure(Status{
                completed.code(), "durable command result was not sent because "
                                  "completion could not be committed: " +
                                      completed.message()});
            return;
        }
        const Status result_sent = send_durable_command_artifact(
            friend_number, record, false);
        std::scoped_lock lock(snapshot_mutex_);
        if (!result_sent.ok()) {
            snapshot_.last_event =
                "durable command result send failed friend=" +
                std::to_string(friend_number) + " operation=" +
                protocol::to_string(result.operation) + " outcome=" +
                protocol::to_string(result.outcome) + " detail=" +
                result_sent.message();
            return;
        }
        snapshot_.last_event =
            (duplicate ? "durable command resumed friend="
                       : "durable command handled friend=") +
            std::to_string(friend_number) + " operation=" +
            protocol::to_string(result.operation) + " outcome=" +
            protocol::to_string(result.outcome);
    }

    void handle_incoming_command(
        std::uint32_t friend_number, const protocol::Frame &frame) {
        auto session = sessions_.get(friend_number);
        if (!session) {
            record_projection_failure(session.status());
            return;
        }
        auto canonical_request = protocol::encode(frame);
        if (!canonical_request) {
            record_projection_failure(canonical_request.status());
            return;
        }
        if (durable_commands_negotiated(session.value())) {
            handle_incoming_durable_command(
                friend_number, session.value(), frame,
                canonical_request.value());
            return;
        }
        const CommandResultKey key{
            friend_number, session.value().online_epoch, frame.message_id};
        std::scoped_lock command_lock(command_mutex_);
        auto existing = command_results_.find(key);
        if (existing != command_results_.end()) {
            if (existing->second.canonical_request !=
                canonical_request.value()) {
                std::scoped_lock lock(snapshot_mutex_);
                snapshot_.last_event =
                    "command-message-id-conflict friend=" +
                    std::to_string(friend_number) + " message-id=" +
                    std::to_string(frame.message_id);
                return;
            }
            const Status resent =
                send_frozen_command_result(existing->second);
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = resent.ok()
                ? "command-duplicate-replied friend=" +
                      std::to_string(friend_number) + " message-id=" +
                      std::to_string(frame.message_id)
                : "command-duplicate-result-send-failed friend=" +
                      std::to_string(friend_number) + " message-id=" +
                      std::to_string(frame.message_id) + " detail=" +
                      resent.message();
            return;
        }

        protocol::CommandResultPayload result;
        result.operation = protocol::CommandOperation::unknown;
        result.outcome = protocol::CommandOutcome::malformed;
        const std::uint64_t now = unix_time_ms();

        auto request = protocol::decode_command_request(frame.payload);
        if (!request) {
            result.outcome = request.status().code() == ErrorCode::unsupported
                                 ? protocol::CommandOutcome::unsupported
                                 : protocol::CommandOutcome::malformed;
        } else {
            result.operation = request.value().operation;
            const auto policy = protocol::command_operation_policy(
                request.value().operation);
            if (!policy.has_value() || !policy->read_only) {
                result.outcome = protocol::CommandOutcome::unsupported;
            } else if (frame.flags != 0U || frame.correlation_id != 0U ||
                frame.sequence != 0U) {
                result.outcome = protocol::CommandOutcome::malformed;
            } else if (frame.expiry_unix_ms != 0U &&
                       frame.expiry_unix_ms <= now) {
                result.outcome = protocol::CommandOutcome::expired;
            } else if (authority_sessions_ == nullptr ||
                       authority_ == nullptr ||
                       !authority_sessions_->authorized_at(
                           friend_number,
                           protocol::required_capabilities(
                               request.value().operation),
                           authority_->snapshot())) {
                result.outcome = protocol::CommandOutcome::denied;
            } else {
                if (!identity_.has_value()) {
                    result.outcome =
                        protocol::CommandOutcome::internal_error;
                } else {
                    CommandExecutionContext context;
                    context.revision_number = kRevisionNumber;
                    context.version_major = kVersionMajor;
                    context.version_minor = kVersionMinor;
                    context.version_patch = kVersionPatch;
                    context.protocol = session.value().negotiated.selected;
                    context.device_principal = identity_->public_key();
                    context.supported_features = selected_supported_features_;
                    context.offered_operations = offered_operation_mask();
                    if (request.value().operation ==
                        protocol::CommandOperation::system_summary) {
                        auto summary = collect_system_summary();
                        if (summary) {
                            context.system_summary = summary.value();
                        }
                    }
                    auto executed = execute_command(request.value(), context);
                    if (!executed) {
                        result.outcome =
                            protocol::CommandOutcome::internal_error;
                    } else {
                        result = std::move(executed).value();
                    }
                }
            }
        }

        prune_command_results();
        if (command_results_.size() >= kMaximumLiveCommandResults) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "command-result-capacity-exhausted friend=" +
                std::to_string(friend_number);
            return;
        }
        auto prepared = make_command_result(
            friend_number, session.value(), frame,
            std::move(canonical_request).value(), result);
        if (!prepared) {
            record_projection_failure(prepared.status());
            return;
        }
        auto [inserted, fresh] = command_results_.emplace(
            key, std::move(prepared).value());
        static_cast<void>(fresh);
        const Status sent = send_frozen_command_result(inserted->second);
        std::scoped_lock lock(snapshot_mutex_);
        if (!sent.ok()) {
            snapshot_.last_event =
                "command-result-send-failed friend=" +
                std::to_string(friend_number) + " operation=" +
                protocol::to_string(result.operation) + " outcome=" +
                protocol::to_string(result.outcome) + " detail=" +
                sent.message();
            return;
        }
        snapshot_.last_event =
            "command-handled friend=" + std::to_string(friend_number) +
            " operation=" + protocol::to_string(result.operation) +
            " outcome=" + protocol::to_string(result.outcome);
    }

    Status send_hello(std::uint32_t friend_number) {
        std::scoped_lock send_lock(session_send_mutex_);
        auto current = sessions_.get(friend_number);
        if (!current) {
            return current.status();
        }
        std::uint64_t message_id = current.value().local_hello_message_id;
        if (message_id == 0U) {
            auto generated = security::random_u64_nonzero();
            if (!generated) {
                return generated.status();
            }
            message_id = generated.value();
        }
        auto frame = sessions_.make_hello_frame(friend_number, message_id);
        if (!frame) {
            return frame.status();
        }
        auto packet = protocol::encode(frame.value());
        if (!packet) {
            static_cast<void>(sessions_.mark_hello_send_failed(
                friend_number, packet.status().code(),
                packet.status().message(), unix_time_ms()));
            publish_sessions_best_effort();
            return packet.status();
        }
        const Status queued =
            transport_.send_lossless(friend_number, packet.value());
        if (!queued.ok()) {
            static_cast<void>(sessions_.mark_hello_send_failed(
                friend_number, queued.code(), queued.message(),
                unix_time_ms()));
            publish_sessions_best_effort();
            return queued;
        }
        const Status marked = sessions_.mark_hello_sent(
            friend_number, message_id, unix_time_ms());
        if (!marked.ok()) {
            publish_sessions_best_effort();
            return marked;
        }
        record_protocol_frame(friend_number, "outgoing", frame.value());
        publish_sessions_best_effort();
        return Status::success();
    }

    Status send_confirmation(std::uint32_t friend_number) {
        std::scoped_lock send_lock(session_send_mutex_);
        auto current = sessions_.get(friend_number);
        if (!current) {
            return current.status();
        }
        std::uint64_t message_id =
            current.value().local_confirmation_message_id;
        if (message_id == 0U) {
            auto generated = security::random_u64_nonzero();
            if (!generated) {
                return generated.status();
            }
            message_id = generated.value();
        }
        auto frame = sessions_.make_confirmation_frame(
            friend_number, message_id);
        if (!frame) {
            return frame.status();
        }
        auto packet = protocol::encode(frame.value());
        if (!packet) {
            static_cast<void>(sessions_.mark_confirmation_send_failed(
                friend_number, packet.status().code(),
                packet.status().message(), unix_time_ms()));
            publish_sessions_best_effort();
            return packet.status();
        }
        const Status queued =
            transport_.send_lossless(friend_number, packet.value());
        if (!queued.ok()) {
            static_cast<void>(sessions_.mark_confirmation_send_failed(
                friend_number, queued.code(), queued.message(),
                unix_time_ms()));
            publish_sessions_best_effort();
            return queued;
        }
        const Status marked = sessions_.mark_confirmation_sent(
            friend_number, message_id, unix_time_ms());
        if (!marked.ok()) {
            publish_sessions_best_effort();
            return marked;
        }
        record_protocol_frame(friend_number, "outgoing", frame.value());
        publish_sessions_best_effort();
        return Status::success();
    }

    void advance_protocol_session(std::uint32_t friend_number) {
        auto session = sessions_.get(friend_number);
        if (!session || !session.value().connected) {
            return;
        }
        if (!session.value().hello_sent) {
            const Status sent = send_hello(friend_number);
            if (!sent.ok()) {
                if (!retryable_protocol_send_error(sent.code())) {
                    record_projection_failure(Status{
                        sent.code(), "IoTox HELLO progression failed: " +
                                         sent.message()});
                }
                return;
            }
            session = sessions_.get(friend_number);
            if (!session) {
                record_projection_failure(session.status());
                return;
            }
        }
        if (session.value().hello_sent && session.value().hello_received &&
            session.value().negotiated.compatible &&
            !session.value().confirmation_sent) {
            const Status confirmed = send_confirmation(friend_number);
            if (!confirmed.ok() &&
                !retryable_protocol_send_error(confirmed.code())) {
                record_projection_failure(Status{
                    confirmed.code(),
                    "IoTox transcript confirmation failed: " +
                        confirmed.message()});
            }
        }
    }

    void service_protocol_sessions_best_effort() {
        const auto now = std::chrono::steady_clock::now();
        if (now < next_protocol_service_) {
            return;
        }
        next_protocol_service_ = now + std::chrono::milliseconds(500);

        for (const protocol::PeerSessionSnapshot &session : sessions_.list()) {
            if (!session.connected ||
                protocol::is_application_ready(session)) {
                continue;
            }
            switch (session.state) {
                case protocol::PeerSessionState::incompatible_version:
                case protocol::PeerSessionState::incompatible_features:
                case protocol::PeerSessionState::malformed_frame:
                case protocol::PeerSessionState::malformed_hello:
                case protocol::PeerSessionState::conflicting_hello:
                case protocol::PeerSessionState::malformed_confirmation:
                case protocol::PeerSessionState::conflicting_confirmation:
                    continue;
                case protocol::PeerSessionState::offline:
                case protocol::PeerSessionState::hello_send_failed:
                    if (!retryable_protocol_send_error(
                            session.last_hello_send_error_code)) {
                        continue;
                    }
                    break;
                case protocol::PeerSessionState::confirmation_send_failed:
                    if (!retryable_protocol_send_error(
                            session.last_confirmation_send_error_code)) {
                        continue;
                    }
                    break;
                case protocol::PeerSessionState::awaiting_hello:
                case protocol::PeerSessionState::awaiting_confirmation:
                case protocol::PeerSessionState::confirmed:
                    break;
            }
            advance_protocol_session(session.friend_number);
        }
        service_authority_sessions_best_effort();
        service_private_route_inventories_best_effort();
        service_route_workers_best_effort();
        service_sync_pending_offers_best_effort();
        service_durable_command_recovery_best_effort();
        service_device_descriptions_best_effort();
        service_command_results_best_effort();
    }

    void service_private_route_inventories_best_effort() {
        if (!config_.security.private_route_bindings_enabled ||
            authority_sessions_ == nullptr || sodium_ == std::nullopt ||
            identity_ == std::nullopt || !local_private_route_set_ ||
            signed_local_private_route_set_.empty()) {
            return;
        }

        std::vector<routes::PrivateRoutePrimaryEdge> current_edges;
        for (const security::PeerAuthoritySnapshot &authority :
             authority_sessions_->list()) {
            if (!authority.connected || !authority.remote_authorized ||
                empty_principal(authority.remote_principal)) {
                continue;
            }
            auto session = sessions_.get(authority.friend_number);
            if (!session || !protocol::is_application_ready(session.value()) ||
                session.value().online_epoch != authority.online_epoch ||
                session.value().public_key !=
                    authority.transport_public_key ||
                (session.value().negotiated.shared_features &
                 protocol::feature_bit(
                     protocol::Feature::private_route_binding_v2)) == 0U) {
                continue;
            }
            current_edges.push_back(
                routes::PrivateRoutePrimaryEdge{
                    session.value(), authority});
        }
        std::sort(
            current_edges.begin(), current_edges.end(),
            [](const auto &left, const auto &right) {
                return left.session.friend_number <
                    right.session.friend_number;
            });
        const Status retained = private_route_inventories_.replace_active_edges(
            current_edges, *sodium_);
        if (!retained.ok()) {
            record_projection_failure(retained);
            return;
        }

        for (const routes::PrivateRoutePrimaryEdge &edge : current_edges) {
            auto outbound = std::find_if(
                private_route_inventory_sends_.begin(),
                private_route_inventory_sends_.end(),
                [&edge](const PrivateRouteInventorySend &candidate) {
                    return candidate.friend_number ==
                        edge.session.friend_number;
                });
            const bool same_transport_peer =
                outbound != private_route_inventory_sends_.end() &&
                outbound->transport_public_key == edge.session.public_key;
            if (outbound != private_route_inventory_sends_.end() &&
                same_transport_peer &&
                edge.session.online_epoch < outbound->online_epoch) {
                record_projection_failure(Status{
                    ErrorCode::protocol_error,
                    "private route inventory service observed a stale primary epoch"});
                continue;
            }
            if (outbound != private_route_inventory_sends_.end() &&
                same_transport_peer &&
                edge.session.online_epoch == outbound->online_epoch &&
                outbound->remote_principal !=
                    edge.authority.remote_principal) {
                record_projection_failure(
                    Status{ErrorCode::protocol_error,
                           "private route inventory authority "
                           "changed within one primary epoch"});
                continue;
            }
            if (outbound == private_route_inventory_sends_.end() ||
                !same_transport_peer ||
                edge.session.online_epoch > outbound->online_epoch) {
                if (outbound == private_route_inventory_sends_.end()) {
                    if (private_route_inventory_sends_.size() >= 64U) {
                        record_projection_failure(Status{
                            ErrorCode::resource_exhausted,
                            "private route inventory send bound is exhausted"});
                        continue;
                    }
                    private_route_inventory_sends_.push_back(
                        PrivateRouteInventorySend{});
                    outbound = std::prev(
                        private_route_inventory_sends_.end());
                }
                auto message_id = security::random_u64_nonzero();
                if (!message_id) {
                    record_projection_failure(message_id.status());
                    continue;
                }
                auto frame = routes::make_private_route_inventory_frame(
                    signed_local_private_route_set_,
                    *local_private_route_set_, edge.session,
                    edge.authority, *identity_, *sodium_,
                    message_id.value());
                if (!frame) {
                    record_projection_failure(frame.status());
                    continue;
                }
                outbound->friend_number = edge.session.friend_number;
                outbound->transport_public_key = edge.session.public_key;
                outbound->online_epoch = edge.session.online_epoch;
                outbound->remote_principal =
                    edge.authority.remote_principal;
                outbound->frame = std::move(frame).value();
                outbound->sent = false;
            }
            if (outbound->sent) continue;
            auto packet = protocol::encode(outbound->frame);
            if (!packet) {
                record_projection_failure(packet.status());
                continue;
            }
            const Status sent = transport_.send_lossless(
                outbound->friend_number, packet.value());
            if (!sent.ok()) {
                if (!retryable_protocol_send_error(sent.code())) {
                    record_projection_failure(Status{
                        sent.code(),
                        "private route inventory send failed: " +
                            sent.message()});
                }
                continue;
            }
            outbound->sent = true;
            record_protocol_frame(
                outbound->friend_number, "outgoing", outbound->frame);
        }
    }

    void handle_incoming_private_route_inventory(
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (!config_.security.private_route_bindings_enabled ||
            authority_sessions_ == nullptr || sodium_ == std::nullopt) {
            record_projection_failure(Status{
                ErrorCode::unsupported, "private route inventory arrived while "
                                        "its construction gate was disabled"});
            return;
        }
        auto authority = authority_sessions_->get(session.friend_number);
        if (!authority) {
            record_projection_failure(Status{
                authority.status().code(),
                "private route inventory has no primary authority edge: " +
                    authority.status().message()});
            return;
        }
        auto admitted = private_route_inventories_.receive(
            frame, session, authority.value(), *sodium_);
        if (!admitted) {
            record_projection_failure(Status{
                admitted.status().code(),
                "private route inventory rejected: " +
                    admitted.status().message()});
            return;
        }
        std::scoped_lock lock(snapshot_mutex_);
        snapshot_.last_event =
            std::string("private-route-inventory-") +
            (admitted.value().kind ==
                     routes::PrivateRouteInventoryAdmissionKind::accepted
                 ? "accepted"
                 : "replayed") +
            " friend=" + std::to_string(session.friend_number) +
            " epoch=" + std::to_string(session.online_epoch) +
            " generation=" + std::to_string(
                admitted.value().context.inventory.route_set.generation);
    }

    void service_route_workers_best_effort() {
        if (route_worker_supervisor_ == nullptr ||
            authority_sessions_ == nullptr || !route_coordinator_) {
            return;
        }

        if (config_.security.private_route_bindings_enabled) {
            const Status replaced =
                route_worker_supervisor_->replace_private_route_contexts(
                    private_route_inventories_.contexts());
            if (!replaced.ok()) {
                record_projection_failure(replaced);
                return;
            }
        } else {
            std::vector<routes::RemoteRouteTrust> trust;
            for (const security::PeerAuthoritySnapshot &authority :
                 authority_sessions_->list()) {
                if (!authority.connected || !authority.remote_authorized ||
                    empty_principal(authority.remote_principal)) {
                    continue;
                }
                auto session = sessions_.get(authority.friend_number);
                if (!session ||
                    !protocol::is_application_ready(session.value()) ||
                    session.value().online_epoch != authority.online_epoch ||
                    session.value().public_key !=
                        authority.transport_public_key) {
                    continue;
                }
                auto coordinator_key =
                    parse_tox_public_key(authority.transport_public_key);
                if (!coordinator_key) {
                    static_cast<void>(
                        route_worker_supervisor_->replace_remote_trust({}));
                    record_projection_failure(coordinator_key.status());
                    return;
                }
                trust.push_back(routes::RemoteRouteTrust{
                    authority.remote_principal, coordinator_key.value(), 1U,
                    authority.online_epoch});
            }
            std::sort(
                trust.begin(), trust.end(),
                [](const routes::RemoteRouteTrust &left,
                   const routes::RemoteRouteTrust &right) {
                    return left.coordinator_tox_public_key <
                        right.coordinator_tox_public_key;
                });
            const Status trusted =
                route_worker_supervisor_->replace_remote_trust(
                    std::move(trust));
            if (!trusted.ok()) {
                record_projection_failure(trusted);
                return;
            }
        }

        const auto workers = route_worker_supervisor_->snapshot();
        {
            std::scoped_lock route_lock(route_coordinator_mutex_);
            for (const routes::WorkerSessionSnapshot &worker : workers) {
                const routes::CoordinatorSnapshot state =
                    route_coordinator_->snapshot();
                const auto member = std::find_if(
                    state.members.begin(), state.members.end(),
                    [&worker](const routes::MemberSnapshot &candidate) {
                        return candidate.policy.tox_public_key ==
                               worker.policy.tox_public_key;
                    });
                if (member == state.members.end() ||
                    member->worker_id != worker.worker_id) {
                    continue;
                }
                const bool reciprocal = worker.application_ready &&
                                        worker.local_binding_sent &&
                                        worker.remote_binding_authenticated;
                if (!reciprocal) {
                    if (member->lifecycle == routes::Lifecycle::authenticated ||
                        member->lifecycle == routes::Lifecycle::ready) {
                        const Status closed =
                            route_coordinator_->authentication_lost(
                                worker.policy.tox_public_key, worker.worker_id);
                        if (!closed.ok())
                            record_projection_failure(closed);
                    }
                    continue;
                }
                if (member->lifecycle == routes::Lifecycle::connecting) {
                    routes::RouteProof proof;
                    proof.tox_public_key = worker.policy.tox_public_key;
                    proof.stable_device_principal =
                        state.stable_device_principal;
                    proof.route_set_generation = state.generation;
                    proof.route_protocol_version =
                        routes::kRouteProtocolVersion;
                    proof.connection_class = worker.policy.connection_class;
                    proof.worker_id = worker.worker_id;
                    proof.transcript_confirmed = true;
                    auto signed_network =
                        routes::network_class_from_stack(worker.network);
                    if (!signed_network) {
                        record_projection_failure(
                            signed_network.status());
                        continue;
                    }
                    proof.network_class = signed_network.value();
                    const Status authenticated =
                        route_coordinator_->authenticate(proof);
                    if (!authenticated.ok()) {
                        record_projection_failure(authenticated);
                        continue;
                    }
                }
                const routes::CoordinatorSnapshot authenticated_state =
                    route_coordinator_->snapshot();
                const auto authenticated_member = std::find_if(
                    authenticated_state.members.begin(),
                    authenticated_state.members.end(),
                    [&worker](const routes::MemberSnapshot &candidate) {
                        return candidate.policy.tox_public_key ==
                               worker.policy.tox_public_key;
                    });
                if (authenticated_member != authenticated_state.members.end() &&
                    authenticated_member->lifecycle ==
                        routes::Lifecycle::authenticated) {
                    const Status ready = route_coordinator_->mark_ready(
                        worker.policy.tox_public_key, worker.worker_id);
                    if (!ready.ok())
                        record_projection_failure(ready);
                }
            }
        }
        service_auxiliary_sync_best_effort(workers);
    }

    void apply_auxiliary_sync_frame(
        const sync::SyncTransferCarrier &carrier,
        const security::SigningPublicKey &principal,
        protocol::Frame frame) {
        std::scoped_lock authority_effect_lock(
            ratox_authority_effect_mutex_);
        auto context = auxiliary_sync_context_locked(carrier, principal);
        if (!context) {
            if (context.status().code() != ErrorCode::unavailable &&
                context.status().code() != ErrorCode::not_found) {
                record_projection_failure(context.status());
            }
            return;
        }
        record_protocol_frame(carrier.friend_number, "incoming", frame);
        if (frame.type ==
                protocol::MessageType::sync_content_object_request ||
            frame.type == protocol::MessageType::
                              sync_content_availability_request) {
            if (sync_content_publisher_ == nullptr ||
                !context.value().content_transfer_negotiated) {
                record_projection_failure(Status{
                    ErrorCode::unsupported,
                    "auxiliary content publisher is not negotiated"});
                return;
            }
            auto handled =
                frame.type ==
                        protocol::MessageType::sync_content_object_request
                    ? sync_content_publisher_->handle(context.value(), frame)
                    : sync_content_publisher_->handle_availability(
                          context.value(), frame);
            if (!handled) {
                record_projection_failure(handled.status());
                return;
            }
            const Status sent = send_sync_frame(
                context.value(), handled.value().response);
            if (!sent.ok()) record_projection_failure(sent);
            return;
        }
        if (frame.type ==
            protocol::MessageType::sync_content_object_result) {
            if (sync_content_subscriber_ == nullptr ||
                !context.value().content_transfer_negotiated) {
                return;
            }
            const Status handled =
                sync_content_subscriber_->handle_object_result(
                    context.value(), frame);
            if (!handled.ok() && handled.code() != ErrorCode::not_found &&
                handled.code() != ErrorCode::unavailable) {
                record_projection_failure(handled);
            }
            return;
        }
        if (frame.type ==
            protocol::MessageType::sync_content_availability_result) {
            if (sync_content_subscriber_ == nullptr ||
                !context.value().content_transfer_negotiated) {
                return;
            }
            auto handled =
                sync_content_subscriber_->handle_availability_result(
                    context.value(), frame);
            if (!handled) {
                if (handled.status().code() != ErrorCode::not_found &&
                    handled.status().code() != ErrorCode::unavailable) {
                    record_projection_failure(handled.status());
                }
                return;
            }
            for (const sync::SyncContentDispatch &request : handled.value()) {
                const Status sent =
                    send_sync_frame(request.context, request.frame);
                if (!sent.ok()) {
                    record_projection_failure(sent);
                    return;
                }
            }
            return;
        }
        if (frame.type == protocol::MessageType::sync_object_request ||
            frame.type == protocol::MessageType::sync_range_request) {
            auto handled = sync_publisher_->handle(context.value(), frame);
            if (!handled) {
                record_projection_failure(handled.status());
                return;
            }
            const Status sent = send_sync_frame(
                context.value(), handled.value().response);
            if (!sent.ok()) record_projection_failure(sent);
            return;
        }
        if (frame.type == protocol::MessageType::sync_range_result) {
            const Status handled = sync_subscriber_->handle_range_result(
                context.value(), frame);
            if (!handled.ok() &&
                handled.code() != ErrorCode::not_found &&
                handled.code() != ErrorCode::unavailable) {
                record_projection_failure(handled);
            }
            return;
        }
        auto handled = sync_subscriber_->handle_object_result(
            context.value(), frame);
        if (!handled) {
            if (handled.status().code() != ErrorCode::not_found &&
                handled.status().code() != ErrorCode::unavailable) {
                record_projection_failure(handled.status());
            }
            return;
        }
        for (const protocol::Frame &request : handled.value()) {
            const Status sent = send_sync_frame(
                context.value(), request);
            if (!sent.ok()) {
                record_projection_failure(sent);
                return;
            }
        }
    }

    void apply_auxiliary_sync_terminal(
        const sync::SyncTransferCarrier &carrier,
        const security::SigningPublicKey &principal,
        routes::WorkerTransferTerminalEvent terminal) {
        std::scoped_lock authority_effect_lock(
            ratox_authority_effect_mutex_);
        auto context = auxiliary_sync_context_locked(carrier, principal);
        if (!context) return;
        if (sync_content_subscriber_ != nullptr &&
            context.value().content_transfer_negotiated) {
            auto content_handled = sync_content_subscriber_->handle_terminal(
                context.value(), terminal.transfer, terminal.outcome,
                terminal.failure);
            if (content_handled) {
                for (const sync::SyncContentDispatch &request :
                     content_handled.value()) {
                    const Status sent =
                        send_sync_frame(request.context, request.frame);
                    if (!sent.ok()) {
                        record_projection_failure(sent);
                        return;
                    }
                }
                return;
            }
            if (content_handled.status().code() != ErrorCode::not_found) {
                if (content_handled.status().code() !=
                    ErrorCode::unavailable) {
                    record_projection_failure(content_handled.status());
                }
                return;
            }
        }
        std::string detail = std::move(terminal.transfer.detail);
        terminal.transfer.detail.clear();
        auto handled = sync_subscriber_->handle_terminal(
            context.value(), terminal.transfer, terminal.outcome,
            terminal.failure, std::move(detail));
        if (!handled) {
            if (handled.status().code() != ErrorCode::not_found &&
                handled.status().code() != ErrorCode::unavailable) {
                record_projection_failure(handled.status());
            }
            return;
        }
        for (const protocol::Frame &request : handled.value()) {
            const Status sent = send_sync_frame(context.value(), request);
            if (!sent.ok()) {
                record_projection_failure(sent);
                return;
            }
        }
    }

    void remember_sync_qualification_fault_population(
        const routes::ToxPublicKey &route_key, std::uint64_t worker_id) {
        sync_qualification_fault_route_key_ = route_key;
        sync_qualification_fault_worker_id_ = worker_id;
        sync_qualification_affected_jobs_.clear();
        sync_qualification_affected_content_jobs_.clear();
        for (const sync::SyncPullSnapshot &pull :
             sync_subscriber_->snapshot()) {
            if (pull.transfer_carrier.carrier_class ==
                    sync::SyncCarrierClass::auxiliary &&
                pull.transfer_carrier.route_key == route_key &&
                pull.transfer_carrier.worker_id == worker_id &&
                pull.state != sync::SyncPullState::complete &&
                pull.state != sync::SyncPullState::failed) {
                sync_qualification_affected_jobs_.push_back(pull.job_id);
            }
        }
        if (sync_content_subscriber_ != nullptr) {
            for (const sync::SyncContentPullSnapshot &pull :
                 sync_content_subscriber_->snapshot()) {
                const bool occupies_carrier = std::any_of(
                    pull.source_carriers.begin(),
                    pull.source_carriers.end(),
                    [&route_key, worker_id](
                        const sync::SyncContentSourceSnapshot &source) {
                        return source.transfer_carrier.carrier_class ==
                                   sync::SyncCarrierClass::auxiliary &&
                               source.transfer_carrier.route_key == route_key &&
                               source.transfer_carrier.worker_id == worker_id;
                    });
                if (occupies_carrier &&
                    pull.state != sync::SyncContentPullState::complete &&
                    pull.state != sync::SyncContentPullState::failed &&
                    pull.state != sync::SyncContentPullState::cancelled) {
                    sync_qualification_affected_content_jobs_.push_back(
                        pull.job_id);
                }
            }
        }
        sync_qualification_affected_job_count_.store(
            sync_qualification_affected_jobs_.size() +
                sync_qualification_affected_content_jobs_.size(),
            std::memory_order_relaxed);
    }

    void service_auxiliary_sync_best_effort(
        std::span<const routes::WorkerSessionSnapshot> workers) {
        if (sync_publisher_ == nullptr || sync_subscriber_ == nullptr ||
            route_worker_supervisor_ == nullptr) {
            return;
        }
        const std::vector<AuxiliarySyncCarrierState> current =
            qualified_auxiliary_sync_carriers(workers);
        std::vector<AuxiliarySyncCarrierState> previous;
        std::size_t recovered_routes = 0U;
        bool qualification_fault_route_recovered = false;
        {
            std::scoped_lock carrier_lock(sync_auxiliary_carrier_mutex_);
            previous = sync_auxiliary_carriers_;
            for (const AuxiliarySyncCarrierState &prior : previous) {
                if (std::find(current.begin(), current.end(), prior) ==
                    current.end()) {
                    sync_auxiliary_offline_routes_.insert(
                        prior.carrier.route_key);
                }
            }
            for (const AuxiliarySyncCarrierState &candidate : current) {
                if (sync_auxiliary_offline_routes_.erase(
                        candidate.carrier.route_key) != 0U) {
                    ++recovered_routes;
                    if (candidate.carrier.route_key ==
                        sync_qualification_fault_route_key_) {
                        qualification_fault_route_recovered = true;
                    }
                }
            }
            sync_auxiliary_carriers_ = current;
        }
        for (const AuxiliarySyncCarrierState &prior : previous) {
            if (std::find(current.begin(), current.end(), prior) !=
                current.end()) {
                continue;
            }
            std::scoped_lock authority_effect_lock(
                ratox_authority_effect_mutex_);
            {
                const auto pulls = sync_subscriber_->snapshot();
                const std::uint64_t blocked = static_cast<std::uint64_t>(
                    std::count_if(
                        pulls.begin(), pulls.end(),
                        [&prior](const sync::SyncPullSnapshot &pull) {
                            return pull.state ==
                                       sync::SyncPullState::awaiting_objects &&
                                   pull.transfer_carrier == prior.carrier &&
                                   !sync::sync_route_reassignment_allowed(
                                       pull.route_failover_policy);
                        }));
                if (blocked != 0U) {
                    sync_auxiliary_fail_closed_jobs_.fetch_add(
                        blocked, std::memory_order_relaxed);
                }
            }
            sync_publisher_->carrier_offline(prior.carrier);
            if (sync_content_publisher_ != nullptr) {
                sync_content_publisher_->carrier_offline(prior.carrier);
            }
            if (sync_content_subscriber_ != nullptr) {
                sync_content_subscriber_->carrier_offline(prior.carrier);
            }
            const Status fenced =
                sync_subscriber_->carrier_offline(prior.carrier);
            sync_auxiliary_carrier_losses_.fetch_add(
                1U, std::memory_order_relaxed);
            if (!fenced.ok() &&
                fenced.code() != ErrorCode::not_found) {
                record_projection_failure(fenced);
            }
        }
        if (recovered_routes != 0U) {
            sync_auxiliary_recoveries_.fetch_add(
                recovered_routes, std::memory_order_relaxed);
        }
        const bool qualification_fault_route_ready = std::any_of(
            current.begin(), current.end(),
            [this](const AuxiliarySyncCarrierState &candidate) {
                return candidate.carrier.route_key ==
                           sync_qualification_fault_route_key_ &&
                       candidate.carrier.worker_id !=
                           sync_qualification_fault_worker_id_;
            });
        if ((qualification_fault_route_recovered ||
             qualification_fault_route_ready) &&
            sync_qualification_fault_count_.load(
                std::memory_order_relaxed) <
                config_.sync.qualification_stop_count) {
            // A repeated qualification fault may be armed only after the
            // previously stopped identity has become ready again. Use the
            // exact current route-key/new-worker level as well as the
            // offline-set edge: the replacement can become qualified in the
            // same service pass that consumes that edge. This keeps one
            // replacement available and gives each loss its own bounded
            // recovery transition.
            sync_qualification_recovery_started_.store(
                false, std::memory_order_relaxed);
        }
        if (qualification_fault_route_ready &&
            !sync_qualification_deferred_frames_.empty()) {
            // The repeated-fault seam must not let the replacement carrier
            // finish affected work before the exact stopped identity has
            // returned. Release only after that identity is authenticated and
            // present in `current`; ordinary one-fault and production paths
            // never populate this queue.
            std::scoped_lock authority_effect_lock(
                ratox_authority_effect_mutex_);
            while (!sync_qualification_deferred_frames_.empty()) {
                DeferredQualificationSyncFrame &deferred =
                    sync_qualification_deferred_frames_.front();
                const Status sent = send_sync_frame(
                    deferred.context, deferred.frame);
                if (!sent.ok()) {
                    record_projection_failure(sent);
                    break;
                }
                sync_qualification_deferred_frames_.pop_front();
                sync_qualification_deferred_frame_count_.fetch_sub(
                    1U, std::memory_order_relaxed);
                sync_qualification_deferred_frame_releases_.fetch_add(
                    1U, std::memory_order_relaxed);
            }
        }

        Status frame_drain = Status::success();
        bool frame_work_admitted = false;
        {
            // Hold parent admission while destructively draining the worker
            // queue. Every removed event is therefore installed in the
            // bounded parent queue in the same transition; ordinary work can
            // never consume the capacity between those two effects.
            std::scoped_lock work_lock(sync_work_mutex_);
            if (sync_work_accepting_ && !sync_work_stop_ &&
                sync_work_queue_.size() <
                    config_.sync.maximum_worker_queue) {
                const std::size_t available =
                    config_.sync.maximum_worker_queue -
                    sync_work_queue_.size();
                auto frame_events =
                    route_worker_supervisor_->take_sync_frame_events(
                        available);
                if (!frame_events) {
                    frame_drain = frame_events.status();
                } else {
                    for (routes::WorkerSyncFrameEvent &event :
                         frame_events.value()) {
                        sync::SyncTransferCarrier carrier;
                        carrier.carrier_class =
                            sync::SyncCarrierClass::auxiliary;
                        carrier.route_key = event.route_key;
                        carrier.worker_id = event.worker_id;
                        carrier.friend_number = event.friend_number;
                        carrier.online_epoch = event.online_epoch;
                        carrier.remote_route_generation =
                            event.remote_route_generation;
                        carrier.remote_coordinator_route_key =
                            event.remote_coordinator_route_key;
                        carrier.primary_authority_online_epoch =
                            event.primary_authority_online_epoch;
                        sync_work_queue_.push_back(
                            [this, carrier,
                             principal = event.remote_stable_principal,
                             frame = std::move(event.frame)]() mutable {
                                apply_auxiliary_sync_frame(
                                    carrier, principal, std::move(frame));
                            });
                        ++sync_work_admitted_;
                        frame_work_admitted = true;
                    }
                }
            }
        }
        if (!frame_drain.ok()) record_projection_failure(frame_drain);
        if (frame_work_admitted) sync_work_cv_.notify_one();

        const std::vector<routes::WorkerTransferSnapshot> transfers =
            route_worker_supervisor_->transfers();
        const std::uint64_t qualification_fault_count =
            sync_qualification_fault_count_.load(
                std::memory_order_relaxed);
        const bool qualification_fault_ready =
            qualification_fault_count == 0U ||
            (!sync_qualification_recovery_started_.load(
                 std::memory_order_relaxed) &&
             current.size() >= 2U);
        if (config_.sync.qualification_stop_after_receive_bytes != 0U &&
            qualification_fault_count <
                config_.sync.qualification_stop_count &&
            qualification_fault_ready) {
            if (sync_qualification_armed_fault_.has_value() &&
                std::chrono::steady_clock::now() >=
                    sync_qualification_armed_fault_->due) {
                const ArmedQualificationFault target =
                    *sync_qualification_armed_fault_;
                const Status stopped =
                    route_worker_supervisor_
                        ->stop_worker_for_qualification(
                            target.route_key, target.worker_id);
                if (stopped.ok()) {
                    remember_sync_qualification_fault_population(
                        target.route_key, target.worker_id);
                    sync_qualification_fault_position_.store(
                        target.position,
                        std::memory_order_relaxed);
                    sync_qualification_fault_injected_.store(
                        true, std::memory_order_relaxed);
                    sync_qualification_fault_count_.fetch_add(
                        1U, std::memory_order_relaxed);
                    sync_qualification_fault_armed_.store(
                        false, std::memory_order_relaxed);
                    sync_qualification_armed_fault_.reset();
                    return;
                }
                if (stopped.code() != ErrorCode::unavailable) {
                    record_projection_failure(stopped);
                }
            } else if (!sync_qualification_armed_fault_.has_value()) {
                const auto candidate = std::find_if(
                    transfers.begin(), transfers.end(),
                    [this, &current](
                        const routes::WorkerTransferSnapshot &transfer) {
                        if (transfer.transfer.direction !=
                                FileTransferDirection::incoming ||
                            transfer.transfer.state !=
                                FileTransferState::active ||
                            transfer.transfer.position <
                                config_.sync
                                    .qualification_stop_after_receive_bytes ||
                            transfer.transfer.position >=
                                transfer.transfer.file_size ||
                            (config_.sync
                                     .qualification_receive_route_key &&
                             transfer.route_key !=
                                 *config_.sync
                                      .qualification_receive_route_key) ||
                            (config_.sync
                                     .qualification_receive_file_bytes != 0U &&
                             transfer.transfer.file_size !=
                                 config_.sync
                                     .qualification_receive_file_bytes)) {
                            return false;
                        }
                        return std::any_of(
                            current.begin(), current.end(),
                            [&transfer](
                                const AuxiliarySyncCarrierState &carrier) {
                                return carrier.carrier.route_key ==
                                           transfer.route_key &&
                                       carrier.carrier.worker_id ==
                                           transfer.worker_id;
                            });
                    });
                if (candidate != transfers.end()) {
                    sync_qualification_armed_fault_.emplace(
                        ArmedQualificationFault{
                            candidate->route_key,
                            candidate->worker_id,
                            candidate->transfer.position,
                            std::chrono::steady_clock::now() +
                                config_.sync
                                    .qualification_route_fault_delay});
                    sync_qualification_fault_position_.store(
                        candidate->transfer.position,
                        std::memory_order_relaxed);
                    sync_qualification_fault_armed_.store(
                        true, std::memory_order_relaxed);
                    if (config_.sync.qualification_route_fault_delay.count() ==
                        0) {
                        // Immediate faults retain their historical same-pass
                        // behavior; a nonzero delay exposes one shared arm
                        // edge for cancel/loss interleaving science.
                        const ArmedQualificationFault target =
                            *sync_qualification_armed_fault_;
                        const Status stopped =
                            route_worker_supervisor_
                                ->stop_worker_for_qualification(
                                    target.route_key, target.worker_id);
                        if (stopped.ok()) {
                            remember_sync_qualification_fault_population(
                                target.route_key, target.worker_id);
                            sync_qualification_fault_injected_.store(
                                true, std::memory_order_relaxed);
                            sync_qualification_fault_count_.fetch_add(
                                1U, std::memory_order_relaxed);
                            sync_qualification_fault_armed_.store(
                                false, std::memory_order_relaxed);
                            sync_qualification_armed_fault_.reset();
                            return;
                        }
                        if (stopped.code() != ErrorCode::unavailable) {
                            record_projection_failure(stopped);
                        }
                    }
                }
            }
        }
        if (config_.sync.qualification_stop_after_cancelled_pull &&
            !sync_qualification_fault_injected_.load(
                std::memory_order_relaxed)) {
            const auto pulls = sync_subscriber_->snapshot();
            const auto cancelled = std::find_if(
                pulls.begin(), pulls.end(),
                [](const sync::SyncPullSnapshot &pull) {
                    return pull.state == sync::SyncPullState::cancelled &&
                           pull.cancellation_settled &&
                           pull.transfer_carrier.carrier_class ==
                               sync::SyncCarrierClass::auxiliary;
                });
            if (cancelled != pulls.end()) {
                const auto exact_worker = std::find_if(
                    workers.begin(), workers.end(),
                    [&cancelled](
                        const routes::WorkerSessionSnapshot &worker) {
                        return worker.policy.role == routes::Role::bulk &&
                               worker.transport_running &&
                               worker.policy.tox_public_key ==
                                   cancelled->transfer_carrier.route_key &&
                               worker.worker_id ==
                                   cancelled->transfer_carrier.worker_id;
                    });
                if (exact_worker != workers.end()) {
                    const Status stopped =
                        route_worker_supervisor_
                            ->stop_worker_for_qualification(
                                exact_worker->policy.tox_public_key,
                                exact_worker->worker_id);
                    if (stopped.ok()) {
                        remember_sync_qualification_fault_population(
                            exact_worker->policy.tox_public_key,
                            exact_worker->worker_id);
                        sync_qualification_fault_injected_.store(
                            true, std::memory_order_relaxed);
                        sync_qualification_fault_count_.fetch_add(
                            1U, std::memory_order_relaxed);
                        return;
                    }
                    if (stopped.code() != ErrorCode::unavailable) {
                        record_projection_failure(stopped);
                    }
                }
            }
        }
        for (const routes::WorkerTransferSnapshot &transfer : transfers) {
            if (transfer.transfer.direction !=
                    FileTransferDirection::incoming ||
                transfer.transfer.state != FileTransferState::offered ||
                !transfer.transfer.has_file_id) {
                continue;
            }
            const auto route = std::find_if(
                current.begin(), current.end(),
                [&transfer](const AuxiliarySyncCarrierState &candidate) {
                    return candidate.carrier.route_key ==
                               transfer.route_key &&
                           candidate.carrier.worker_id ==
                               transfer.worker_id &&
                           candidate.carrier.friend_number ==
                               transfer.transfer.friend_number;
                });
            if (route == current.end()) continue;
            const Status admitted = queue_sync_work(
                [this, carrier = route->carrier,
                 principal = route->remote_principal,
                 offer = transfer.transfer] {
                    std::scoped_lock authority_effect_lock(
                        ratox_authority_effect_mutex_);
                    auto context = auxiliary_sync_context_locked(
                        carrier, principal);
                    if (!context) return;
                    if (sync_content_subscriber_ != nullptr &&
                        context.value().content_transfer_negotiated) {
                        auto content_claimed =
                            sync_content_subscriber_->handle_offer(
                                context.value(), offer);
                        if (content_claimed && content_claimed.value()) {
                            return;
                        }
                        if (!content_claimed) {
                            if (content_claimed.status().code() !=
                                    ErrorCode::not_found &&
                                content_claimed.status().code() !=
                                    ErrorCode::unavailable) {
                                record_projection_failure(
                                    content_claimed.status());
                            }
                            return;
                        }
                    }
                    auto claimed = sync_subscriber_->handle_offer(
                        context.value(), offer);
                    if (!claimed &&
                        claimed.status().code() != ErrorCode::not_found &&
                        claimed.status().code() !=
                            ErrorCode::unavailable) {
                        record_projection_failure(claimed.status());
                    }
                });
            if (!admitted.ok() &&
                admitted.code() != ErrorCode::resource_exhausted) {
                record_projection_failure(admitted);
            }
        }

        Status terminal_drain = Status::success();
        bool terminal_work_admitted = false;
        {
            std::scoped_lock work_lock(sync_work_mutex_);
            const std::size_t terminal_bound =
                config_.file_transfers.max_active_receives +
                config_.sync.maximum_worker_queue;
            if (sync_work_accepting_ && !sync_work_stop_ &&
                sync_terminal_work_queue_.size() < terminal_bound) {
                const std::size_t available = std::min(
                    terminal_bound - sync_terminal_work_queue_.size(),
                    config_.sync.maximum_worker_queue);
                auto terminal_events =
                    route_worker_supervisor_->take_transfer_terminal_events(
                        available);
                if (!terminal_events) {
                    terminal_drain = terminal_events.status();
                } else {
                    for (routes::WorkerTransferTerminalEvent &terminal :
                         terminal_events.value()) {
                        const auto route = std::find_if(
                            current.begin(), current.end(),
                            [&terminal](
                                const AuxiliarySyncCarrierState &candidate) {
                                return candidate.carrier.route_key ==
                                           terminal.route_key &&
                                       candidate.carrier.worker_id ==
                                           terminal.worker_id &&
                                       candidate.carrier.friend_number ==
                                           terminal.transfer.friend_number;
                            });
                        if (route == current.end()) {
                            sync_auxiliary_stale_terminals_.fetch_add(
                                1U, std::memory_order_relaxed);
                            continue;
                        }
                        sync_terminal_work_queue_.push_back(
                            [this, carrier = route->carrier,
                             principal = route->remote_principal,
                             terminal = std::move(terminal)]() mutable {
                                apply_auxiliary_sync_terminal(
                                    carrier, principal,
                                    std::move(terminal));
                            });
                        ++sync_work_admitted_;
                        terminal_work_admitted = true;
                    }
                }
            }
        }
        if (!terminal_drain.ok()) {
            record_projection_failure(terminal_drain);
        }
        if (terminal_work_admitted) sync_work_cv_.notify_one();

        std::scoped_lock authority_effect_lock(
            ratox_authority_effect_mutex_);
        for (const sync::SyncPullSnapshot &pull :
             sync_subscriber_->snapshot()) {
            if (pull.state != sync::SyncPullState::awaiting_objects ||
                pull.transfer_carrier.carrier_class !=
                    sync::SyncCarrierClass::auxiliary ||
                std::any_of(
                    current.begin(), current.end(),
                    [&pull](const AuxiliarySyncCarrierState &candidate) {
                        return candidate.carrier ==
                            pull.transfer_carrier;
                    })) {
                continue;
            }
            if (!sync::sync_route_reassignment_allowed(
                    pull.route_failover_policy)) {
                continue;
            }
            auto primary_session = sessions_.get(pull.friend_number);
            if (!primary_session ||
                primary_session.value().online_epoch !=
                    pull.online_epoch) {
                continue;
            }
            auto context = sync_peer_context_locked(
                pull.friend_number, primary_session.value());
            if (!context) continue;
            const std::vector<AuxiliarySyncCarrierState> candidates =
                current_auxiliary_sync_carriers();
            if (pull.requested_objects <= pull.committed_objects ||
                pull.requested_objects - pull.committed_objects >
                    std::numeric_limits<std::uint32_t>::max()) {
                record_projection_failure(Status{
                    ErrorCode::protocol_error,
                    "live sync reassignment has invalid pending work"});
                continue;
            }
            const auto required_work = static_cast<std::uint32_t>(
                pull.requested_objects - pull.committed_objects);
            auto replacement = sync::select_sync_route(
                config_.sync.route_selection_policy, candidates,
                context.value().peer_authority.remote_principal,
                pull.transfer_carrier, required_work,
                pull.route_class);
            if (!replacement) {
                if (replacement.status().code() != ErrorCode::unavailable) {
                    record_projection_failure(replacement.status());
                }
                continue;
            }
            context.value().transfer_carrier = replacement.value().carrier;
            context.value().range_transfer_negotiated =
                context.value().range_transfer_negotiated &&
                replacement.value().range_transfer_negotiated;
            auto reassigned =
                sync_subscriber_->reassign_transfer_carrier(
                    pull.job_id, context.value());
            if (!reassigned) {
                if (reassigned.status().code() !=
                        ErrorCode::unavailable) {
                    record_projection_failure(reassigned.status());
                }
                continue;
            }
            sync_auxiliary_reassignments_.fetch_add(
                1U, std::memory_order_relaxed);
            if (config_.sync.route_selection_policy ==
                sync::SyncRouteSelectionPolicy::adaptive) {
                sync_auxiliary_adaptive_selections_.fetch_add(
                    1U, std::memory_order_relaxed);
            } else {
                sync_auxiliary_fixed_selections_.fetch_add(
                    1U, std::memory_order_relaxed);
            }
            const bool defer_until_fault_route_recovers =
                qualification_fault_count != 0U &&
                qualification_fault_count <
                    config_.sync.qualification_stop_count;
            for (const protocol::Frame &request : reassigned.value()) {
                if (defer_until_fault_route_recovers) {
                    if (sync_qualification_deferred_frames_.size() >=
                        config_.sync.maximum_worker_queue) {
                        record_projection_failure(Status{
                            ErrorCode::resource_exhausted,
                            "repeated qualification request hold exhausted its "
                            "bounded queue"});
                        break;
                    }
                    sync_qualification_deferred_frames_.push_back(
                        DeferredQualificationSyncFrame{
                            context.value(), request});
                    sync_qualification_deferred_frame_count_.fetch_add(
                        1U, std::memory_order_relaxed);
                    continue;
                }
                const Status sent = send_sync_frame(
                    context.value(), request);
                if (!sent.ok()) {
                    record_projection_failure(sent);
                    break;
                }
            }
        }

        const std::uint64_t injected_fault_count =
            sync_qualification_fault_count_.load(
                std::memory_order_relaxed);
        const bool qualification_loss_accounted =
            injected_fault_count != 0U &&
            sync_auxiliary_carrier_losses_.load(
                std::memory_order_relaxed) >= injected_fault_count;
        if (sync_qualification_fault_injected_.load(
                std::memory_order_relaxed) &&
            qualification_loss_accounted &&
            !sync_qualification_recovery_started_.load(
                std::memory_order_relaxed)) {
            const auto pulls = sync_subscriber_->snapshot();
            const auto content_pulls =
                sync_content_subscriber_ == nullptr
                    ? std::vector<sync::SyncContentPullSnapshot>{}
                    : sync_content_subscriber_->snapshot();
            // Each recovery is a qualification-only, one-budget-unit effect.
            // Bind it to every pull that occupied the exact stopped
            // incarnation when the fault committed. A single unrelated pull
            // must not revive a carrier while affected work is still bound to
            // that incarnation.
            const bool more_faults_planned =
                injected_fault_count <
                config_.sync.qualification_stop_count;
            const bool has_affected_population =
                !sync_qualification_affected_jobs_.empty() ||
                !sync_qualification_affected_content_jobs_.empty();
            const bool sync_population_released = std::all_of(
                    sync_qualification_affected_jobs_.begin(),
                    sync_qualification_affected_jobs_.end(),
                    [this, &pulls, more_faults_planned](
                        std::uint64_t affected_job) {
                        const auto pull = std::find_if(
                            pulls.begin(), pulls.end(),
                            [affected_job](
                                const sync::SyncPullSnapshot &candidate) {
                                return candidate.job_id == affected_job;
                            });
                        return pull != pulls.end() &&
                               (pull->state == sync::SyncPullState::complete ||
                                pull->state ==
                                    sync::SyncPullState::cancelled ||
                                (more_faults_planned &&
                                 (pull->transfer_carrier.route_key !=
                                      sync_qualification_fault_route_key_ ||
                                  pull->transfer_carrier.worker_id !=
                                      sync_qualification_fault_worker_id_)));
                    });
            const bool content_population_released = std::all_of(
                sync_qualification_affected_content_jobs_.begin(),
                sync_qualification_affected_content_jobs_.end(),
                [&content_pulls](std::uint64_t affected_job) {
                    const auto pull = std::find_if(
                        content_pulls.begin(), content_pulls.end(),
                        [affected_job](
                            const sync::SyncContentPullSnapshot &candidate) {
                            return candidate.job_id == affected_job;
                        });
                    return pull != content_pulls.end() &&
                           (pull->state ==
                                sync::SyncContentPullState::complete ||
                            pull->state ==
                                sync::SyncContentPullState::failed ||
                            pull->state ==
                                sync::SyncContentPullState::cancelled);
                });
            const bool affected_population_released =
                has_affected_population && sync_population_released &&
                content_population_released;
            const auto stopped = std::find_if(
                workers.begin(), workers.end(),
                [this](const routes::WorkerSessionSnapshot &worker) {
                    return worker.policy.role == routes::Role::bulk &&
                           !worker.transport_running &&
                           worker.policy.tox_public_key ==
                               sync_qualification_fault_route_key_ &&
                           worker.worker_id ==
                               sync_qualification_fault_worker_id_;
                });
            if (affected_population_released && stopped != workers.end()) {
                bool expected = false;
                if (sync_qualification_recovery_started_
                        .compare_exchange_strong(
                            expected, true, std::memory_order_relaxed)) {
                    Status recovering;
                    {
                        std::scoped_lock route_lock(
                            route_coordinator_mutex_);
                        recovering = route_coordinator_->begin_recovery(
                            stopped->policy.tox_public_key,
                            stopped->worker_id,
                            routes::Failure::transport);
                    }
                    if (!recovering.ok()) {
                        record_projection_failure(recovering);
                        return;
                    }
                    auto restarted = route_worker_supervisor_
                        ->restart_worker_for_qualification(
                            stopped->policy.tox_public_key,
                            stopped->worker_id);
                    if (!restarted) {
                        {
                            std::scoped_lock route_lock(
                                route_coordinator_mutex_);
                            static_cast<void>(
                                route_coordinator_->mark_unavailable(
                                    stopped->policy.tox_public_key,
                                    stopped->worker_id,
                                    routes::Failure::transport));
                        }
                        record_projection_failure(restarted.status());
                        return;
                    }
                    Status connecting;
                    {
                        std::scoped_lock route_lock(
                            route_coordinator_mutex_);
                        connecting = route_coordinator_->begin_connecting(
                            stopped->policy.tox_public_key,
                            restarted.value());
                    }
                    if (!connecting.ok()) {
                        record_projection_failure(connecting);
                        return;
                    }
                }
            }
        }
    }

    void service_sync_pending_offers_best_effort() {
        if (sync_subscriber_ == nullptr)
            return;
        const std::vector<FileTransferRecord> transfers = transfers_.list();
        if (transfers.empty()) {
            sync_offer_retry_cursor_ = 0U;
            return;
        }

        // One bounded pass never attempts more than the qualified per-Agent
        // receive ceiling. Advance a stable cyclic cursor even across
        // unrelated offers so a full ledger cannot create a hot loop or
        // starve a later exact-FileId sync offer.
        const std::size_t start = sync_offer_retry_cursor_ % transfers.size();
        const std::size_t count =
            std::min(transfers.size(), kQualifiedSingleAgentTransferCeiling);
        for (std::size_t offset = 0U; offset < count; ++offset) {
            const FileTransferRecord &offer =
                transfers[(start + offset) % transfers.size()];
            if (offer.direction != FileTransferDirection::incoming ||
                offer.state != FileTransferState::offered ||
                !offer.has_file_id) {
                continue;
            }
            auto session = sessions_.get(offer.friend_number);
            if (!session || !protocol::is_application_ready(session.value()) ||
                (session.value().negotiated.shared_features &
                 protocol::feature_bit(protocol::Feature::state_sync_v1)) ==
                    0U) {
                continue;
            }
            std::scoped_lock authority_effect_lock(
                ratox_authority_effect_mutex_);
            auto context =
                sync_peer_context_locked(offer.friend_number, session.value());
            if (!context) {
                if (context.status().code() != ErrorCode::not_found &&
                    context.status().code() != ErrorCode::unavailable) {
                    record_projection_failure(context.status());
                }
                continue;
            }
            if (sync_tree_subscriber_ != nullptr &&
                context.value().tree_transfer_negotiated) {
                auto claimed =
                    sync_tree_subscriber_->handle_offer(context.value(), offer);
                if (!claimed) {
                    if (claimed.status().code() != ErrorCode::not_found &&
                        claimed.status().code() != ErrorCode::unavailable) {
                        record_projection_failure(claimed.status());
                    }
                    continue;
                }
                if (claimed.value()) continue;
            }
            bool content_claimed = false;
            if (sync_content_subscriber_ != nullptr &&
                context.value().content_transfer_negotiated) {
                auto claimed = sync_content_subscriber_->handle_offer(
                    context.value(), offer);
                if (!claimed) {
                    if (claimed.status().code() != ErrorCode::not_found &&
                        claimed.status().code() != ErrorCode::unavailable) {
                        record_projection_failure(claimed.status());
                    }
                    continue;
                }
                content_claimed = claimed.value();
            }
            if (content_claimed)
                continue;
            auto claimed =
                sync_subscriber_->handle_offer(context.value(), offer);
            if (!claimed && claimed.status().code() != ErrorCode::not_found &&
                claimed.status().code() != ErrorCode::unavailable) {
                record_projection_failure(claimed.status());
            }
        }
        sync_offer_retry_cursor_ = (start + count) % transfers.size();
    }

    void retire_peer_application_epoch(std::uint32_t friend_number,
                                       std::uint64_t online_epoch,
                                       std::uint64_t now_unix_ms,
                                       std::string_view reason) {
        if (sync_publisher_ != nullptr) {
            sync_publisher_->peer_offline(friend_number, online_epoch);
        }
        if (sync_subscriber_ != nullptr) {
            sync_subscriber_->peer_offline(friend_number, online_epoch);
        }
        if (sync_content_publisher_ != nullptr) {
            sync_content_publisher_->peer_offline(friend_number, online_epoch);
        }
        if (sync_content_subscriber_ != nullptr) {
            sync_content_subscriber_->peer_offline(friend_number, online_epoch);
        }
        if (sync_tree_publisher_ != nullptr) {
            sync_tree_publisher_->peer_offline(friend_number, online_epoch);
        }
        if (sync_tree_subscriber_ != nullptr) {
            for (const sync::TreeV2Dispatch &dispatch :
                 sync_tree_subscriber_->peer_offline(friend_number,
                                                     online_epoch)) {
                const Status sent =
                    send_sync_frame(dispatch.context, dispatch.frame);
                if (!sent.ok()) record_projection_failure(sent);
            }
        }
        ratox_peer_offline_best_effort(friend_number, online_epoch);
        if (authority_sessions_ != nullptr) {
            const Status authority_offline =
                authority_sessions_->peer_offline(friend_number, now_unix_ms);
            if (!authority_offline.ok() &&
                authority_offline.code() != ErrorCode::not_found) {
                record_projection_failure(authority_offline);
            }
        }
        erase_command_results(friend_number);
        invalidate_peer_description(friend_number, online_epoch,
                                    std::string(reason));
    }

    void handle_friend_connection(const TransportEvent &event) {
        refresh_peers_best_effort();
        auto key = peer_key_for(event.friend_number);
        if (!key) {
            record_projection_failure(key.status());
            return;
        }
        const std::uint64_t now = unix_time_ms();
        const Status ensured = sessions_.ensure_offline_peer(
            event.friend_number, key.value(), now);
        if (!ensured.ok()) {
            record_projection_failure(ensured);
            return;
        }
        auto before = sessions_.get(event.friend_number);
        if (!before) {
            record_projection_failure(before.status());
            return;
        }

        if (event.connection_status ==
            static_cast<int>(toxcore::abi::kConnectionNone)) {
            retire_peer_application_epoch(
                event.friend_number, before.value().online_epoch, now,
                "peer went offline; the online-epoch request was invalidated");
            const Status offline =
                sessions_.peer_offline(event.friend_number, now);
            if (!offline.ok()) {
                record_projection_failure(offline);
            }
            publish_sessions_best_effort();
            publish_authority_sessions_best_effort();
            return;
        }

        bool should_send = !before.value().connected;
        protocol::SessionNonce nonce = before.value().local.session_nonce;
        if (should_send) {
            auto generated = security::random_nonce_128();
            if (!generated) {
                record_projection_failure(generated.status());
                return;
            }
            nonce = generated.value();
        }
        auto online =
            sessions_.peer_online(event.friend_number, key.value(),
                                  event.connection_status, nonce, now);
        if (!online) {
            record_projection_failure(online.status());
            publish_sessions_best_effort();
            return;
        }
        publish_sessions_best_effort();
        if (should_send) {
            const Status sent = send_hello(event.friend_number);
            if (!sent.ok() && !retryable_protocol_send_error(sent.code())) {
                record_projection_failure(
                    Status{sent.code(),
                           "automatic IoTox HELLO failed: " + sent.message()});
            }
        }
    }

    void handle_incoming_hello(std::uint32_t friend_number,
                               const protocol::Frame &frame) {
        auto key = peer_key_for(friend_number);
        if (!key) {
            record_projection_failure(key.status());
            return;
        }
        const auto before = sessions_.get(friend_number);
        const std::uint64_t now = unix_time_ms();
        const Status accepted =
            sessions_.receive_hello(friend_number, key.value(), frame, now);
        const auto after = sessions_.get(friend_number);
        publish_sessions_best_effort();
        if (accepted.ok()) {
            if (before && after &&
                after.value().online_epoch > before.value().online_epoch) {
                retire_peer_application_epoch(
                    friend_number, before.value().online_epoch, now,
                    "peer advanced its durable application incarnation");
            }
            advance_protocol_session(friend_number);
            auto confirmed = sessions_.get(friend_number);
            if (confirmed &&
                protocol::is_application_ready(confirmed.value())) {
                advance_authority_session(friend_number);
            }
        } else {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = "protocol-session-rejected friend=" +
                                   std::to_string(friend_number) +
                                   " detail=" + accepted.message();
        }
    }

    void handle_incoming_confirmation(std::uint32_t friend_number,
                                      const protocol::Frame &frame) {
        auto key = peer_key_for(friend_number);
        if (!key) {
            record_projection_failure(key.status());
            return;
        }
        const Status accepted = sessions_.receive_confirmation(
            friend_number, key.value(), frame, unix_time_ms());
        publish_sessions_best_effort();
        if (accepted.ok()) {
            advance_protocol_session(friend_number);
            auto confirmed = sessions_.get(friend_number);
            if (confirmed &&
                protocol::is_application_ready(confirmed.value())) {
                advance_authority_session(friend_number);
            }
        } else {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = "protocol-confirmation-rejected friend=" +
                                   std::to_string(friend_number) +
                                   " detail=" + accepted.message();
        }
    }

    void inspect_incoming_lossless(const TransportEvent &event) {
        if (event.data.empty() ||
            event.data.front() != protocol::kToxLosslessPacketId) {
            return;
        }
        auto frame = protocol::decode(event.data);
        if (!frame) {
            static_cast<void>(sessions_.mark_malformed_frame(
                event.friend_number,
                "rejected malformed IoTox frame: " + frame.status().message(),
                unix_time_ms()));
            publish_sessions_best_effort();
            record_projection_failure(
                Status{ErrorCode::protocol_error,
                       "rejected malformed IoTox frame from friend " +
                           std::to_string(event.friend_number) + ": " +
                           frame.status().message()});
            return;
        }
        record_protocol_frame(event.friend_number, "incoming", frame.value());
        if (frame.value().type == protocol::MessageType::hello) {
            handle_incoming_hello(event.friend_number, frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::capabilities) {
            handle_incoming_confirmation(event.friend_number, frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::authority_challenge) {
            handle_incoming_authority_challenge(event.friend_number,
                                                frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::authority_proof) {
            handle_incoming_authority_proof(event.friend_number, frame.value());
            return;
        }

        auto session = sessions_.get(event.friend_number);
        if (!session) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "ignored IoTox application frame without peer session type=" +
                protocol::to_string(frame.value().type) +
                " friend=" + std::to_string(event.friend_number);
            return;
        }
        const Status admitted =
            protocol::validate_application_frame_for_session(session.value(),
                                                             frame.value());
        if (!admitted.ok()) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected IoTox application frame type=" +
                protocol::to_string(frame.value().type) +
                " friend=" + std::to_string(event.friend_number) +
                " detail=" + admitted.message();
            return;
        }
        if (frame.value().type ==
            protocol::MessageType::private_route_inventory) {
            handle_incoming_private_route_inventory(session.value(),
                                                    frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::command) {
            handle_incoming_command(event.friend_number, frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::acknowledgement) {
            handle_incoming_command_receipt(event.friend_number, frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::command_result) {
            handle_incoming_command_result(event.friend_number, frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::pair_request) {
            handle_incoming_delegation_request(event.friend_number,
                                               session.value(), frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::pair_result) {
            handle_incoming_delegation_result(event.friend_number,
                                              frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::sync_head_result) {
            handle_incoming_sync_head_result(event.friend_number,
                                             session.value(), frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::sync_object_result) {
            handle_incoming_sync_object_result(event.friend_number,
                                               session.value(), frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::sync_range_result) {
            handle_incoming_sync_range_result(event.friend_number,
                                              session.value(), frame.value());
            return;
        }
        if (frame.value().type ==
            protocol::MessageType::sync_content_object_result) {
            handle_incoming_sync_content_result(event.friend_number,
                                                session.value(), frame.value());
            return;
        }
        if (frame.value().type ==
            protocol::MessageType::sync_content_availability_result) {
            handle_incoming_sync_content_availability_result(
                event.friend_number, session.value(), frame.value());
            return;
        }
        if (frame.value().type ==
            protocol::MessageType::sync_tree_inventory_result) {
            handle_incoming_sync_tree_inventory_result(
                event.friend_number, session.value(), frame.value());
            return;
        }
        if (frame.value().type ==
            protocol::MessageType::sync_tree_object_result) {
            handle_incoming_sync_tree_object_result(
                event.friend_number, session.value(), frame.value());
            return;
        }
        if (frame.value().type ==
                protocol::MessageType::sync_tree_inventory_request ||
            frame.value().type ==
                protocol::MessageType::sync_tree_object_request) {
            handle_incoming_sync_tree_request(event.friend_number,
                                              session.value(), frame.value());
            return;
        }
        if (frame.value().type ==
                protocol::MessageType::sync_content_object_request ||
            frame.value().type ==
                protocol::MessageType::sync_content_availability_request) {
            handle_incoming_sync_content_request(
                event.friend_number, session.value(), frame.value());
            return;
        }
        if (frame.value().type == protocol::MessageType::sync_head_request ||
            frame.value().type == protocol::MessageType::sync_object_request ||
            frame.value().type == protocol::MessageType::sync_range_request) {
            handle_incoming_sync_request(event.friend_number, session.value(),
                                         frame.value());
            return;
        }

        std::scoped_lock lock(snapshot_mutex_);
        snapshot_.last_event =
            "admitted unhandled IoTox application frame type=" +
            protocol::to_string(frame.value().type) +
            " friend=" + std::to_string(event.friend_number);
    }

    Result<sync::SyncPeerContext>
    sync_peer_context_locked(std::uint32_t friend_number,
                             const protocol::PeerSessionSnapshot &session) {
        if (authority_ == nullptr || authority_sessions_ == nullptr ||
            !protocol::is_application_ready(session) ||
            session.friend_number != friend_number ||
            session.online_epoch == 0U) {
            return Status{
                ErrorCode::unavailable,
                "synchronization peer session is not application-ready"};
        }
        auto peer = authority_sessions_->get(friend_number);
        if (!peer)
            return peer.status();
        if (!peer.value().connected ||
            peer.value().online_epoch != session.online_epoch ||
            peer.value().transport_public_key != session.public_key) {
            return Status{ErrorCode::unavailable,
                          "synchronization authority proof is not bound to the "
                          "current transport epoch"};
        }
        auto route_key = parse_tox_public_key(session.public_key);
        if (!route_key)
            return route_key.status();
        sync::SyncPeerContext context;
        context.friend_number = friend_number;
        context.online_epoch = session.online_epoch;
        context.authority_route_key = route_key.value();
        context.authority = authority_->snapshot();
        context.peer_authority = std::move(peer).value();
        context.transfer_carrier.carrier_class =
            sync::SyncCarrierClass::primary;
        context.transfer_carrier.route_key = route_key.value();
        context.transfer_carrier.worker_id = session.online_epoch;
        context.transfer_carrier.friend_number = friend_number;
        context.transfer_carrier.online_epoch = session.online_epoch;
        context.range_transfer_negotiated =
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_ranges_v1)) !=
            0U;
        context.content_transfer_negotiated =
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_content_v2)) !=
            0U;
        context.tree_transfer_negotiated =
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_tree_v2)) !=
            0U;
        context.tree_checkpoint_negotiated =
            (session.negotiated.shared_features &
             protocol::feature_bit(
                 protocol::Feature::state_sync_tree_checkpoint_v2)) != 0U;
        return context;
    }

    std::vector<AuxiliarySyncCarrierState> qualified_auxiliary_sync_carriers(
        std::span<const routes::WorkerSessionSnapshot> workers) const {
        std::vector<AuxiliarySyncCarrierState> result;
        if (!route_coordinator_)
            return result;
        routes::CoordinatorSnapshot coordinator;
        {
            std::scoped_lock route_lock(route_coordinator_mutex_);
            coordinator = route_coordinator_->snapshot();
        }
        for (const routes::WorkerSessionSnapshot &worker : workers) {
            if (worker.policy.role != routes::Role::bulk ||
                !worker.transport_running || !worker.application_ready ||
                !worker.local_binding_sent ||
                !worker.remote_binding_authenticated ||
                worker.online_epoch == 0U ||
                worker.remote_route_generation == 0U ||
                std::all_of(worker.remote_coordinator_route_key.begin(),
                            worker.remote_coordinator_route_key.end(),
                            [](std::uint8_t byte) { return byte == 0U; }) ||
                worker.primary_authority_online_epoch == 0U ||
                empty_principal(worker.remote_stable_principal)) {
                continue;
            }
            const auto member = std::find_if(
                coordinator.members.begin(), coordinator.members.end(),
                [&worker](const routes::MemberSnapshot &candidate) {
                    return candidate.policy.tox_public_key ==
                               worker.policy.tox_public_key &&
                           candidate.worker_id == worker.worker_id &&
                           candidate.lifecycle == routes::Lifecycle::ready;
                });
            if (member == coordinator.members.end())
                continue;
            sync::SyncTransferCarrier carrier;
            carrier.carrier_class = sync::SyncCarrierClass::auxiliary;
            carrier.route_key = worker.policy.tox_public_key;
            carrier.worker_id = worker.worker_id;
            carrier.friend_number = worker.friend_number;
            carrier.online_epoch = worker.online_epoch;
            carrier.remote_route_generation = worker.remote_route_generation;
            carrier.remote_coordinator_route_key =
                worker.remote_coordinator_route_key;
            carrier.primary_authority_online_epoch =
                worker.primary_authority_online_epoch;
            result.push_back(AuxiliarySyncCarrierState{
                carrier, worker.remote_stable_principal, worker.network,
                member->policy.maximum_active_work, member->admitted_work,
                member->restarts, worker.range_transfer_negotiated,
                worker.content_transfer_negotiated});
        }
        std::sort(result.begin(), result.end(),
                  [](const AuxiliarySyncCarrierState &left,
                     const AuxiliarySyncCarrierState &right) {
                      if (left.remote_principal != right.remote_principal) {
                          return left.remote_principal < right.remote_principal;
                      }
                      if (left.carrier.route_key != right.carrier.route_key) {
                          return left.carrier.route_key <
                                 right.carrier.route_key;
                      }
                      return left.carrier.worker_id < right.carrier.worker_id;
                  });
        return result;
    }

    std::vector<AuxiliarySyncCarrierState>
    current_auxiliary_sync_carriers() const {
        std::vector<AuxiliarySyncCarrierState> current;
        {
            std::scoped_lock carrier_lock(sync_auxiliary_carrier_mutex_);
            current = sync_auxiliary_carriers_;
        }
        if (!route_coordinator_)
            return {};

        routes::CoordinatorSnapshot coordinator;
        {
            std::scoped_lock route_lock(route_coordinator_mutex_);
            coordinator = route_coordinator_->snapshot();
        }
        std::vector<AuxiliarySyncCarrierState> refreshed;
        refreshed.reserve(current.size());
        for (AuxiliarySyncCarrierState candidate : current) {
            const auto member = std::find_if(
                coordinator.members.begin(), coordinator.members.end(),
                [&candidate](const routes::MemberSnapshot &state) {
                    return state.policy.tox_public_key ==
                               candidate.carrier.route_key &&
                           state.worker_id == candidate.carrier.worker_id &&
                           state.lifecycle == routes::Lifecycle::ready;
                });
            if (member == coordinator.members.end())
                continue;
            candidate.maximum_work = member->policy.maximum_active_work;
            candidate.admitted_work = member->admitted_work;
            candidate.restart_count = member->restarts;
            refreshed.push_back(std::move(candidate));
        }
        return refreshed;
    }

    Result<sync::SyncPeerContext> auxiliary_sync_context_locked(
        const sync::SyncTransferCarrier &carrier,
        const security::SigningPublicKey &remote_principal) {
        if (carrier.carrier_class != sync::SyncCarrierClass::auxiliary ||
            empty_principal(remote_principal)) {
            return Status{ErrorCode::invalid_argument,
                          "auxiliary sync context fence is invalid"};
        }
        if (route_worker_supervisor_ == nullptr) {
            return Status{ErrorCode::unavailable,
                          "auxiliary sync worker supervisor is absent"};
        }
        const std::vector<routes::WorkerSessionSnapshot> workers =
            route_worker_supervisor_->snapshot();
        const auto live_worker = std::find_if(
            workers.begin(), workers.end(),
            [&carrier,
             &remote_principal](const routes::WorkerSessionSnapshot &worker) {
                return worker.policy.role == routes::Role::bulk &&
                       worker.policy.tox_public_key == carrier.route_key &&
                       worker.worker_id == carrier.worker_id &&
                       worker.transport_running && worker.application_ready &&
                       worker.local_binding_sent &&
                       worker.remote_binding_authenticated &&
                       worker.friend_number == carrier.friend_number &&
                       worker.online_epoch == carrier.online_epoch &&
                       worker.remote_route_generation ==
                           carrier.remote_route_generation &&
                       worker.remote_stable_principal == remote_principal &&
                       worker.remote_coordinator_route_key ==
                           carrier.remote_coordinator_route_key &&
                       worker.primary_authority_online_epoch ==
                           carrier.primary_authority_online_epoch;
            });
        if (live_worker == workers.end()) {
            return Status{
                ErrorCode::unavailable,
                "auxiliary sync worker incarnation is no longer live"};
        }
        bool range_transfer_negotiated = false;
        bool content_transfer_negotiated = false;
        {
            std::scoped_lock carrier_lock(sync_auxiliary_carrier_mutex_);
            const auto current = std::find_if(
                sync_auxiliary_carriers_.begin(),
                sync_auxiliary_carriers_.end(),
                [&carrier, &remote_principal](
                    const AuxiliarySyncCarrierState &candidate) {
                    return candidate.carrier == carrier &&
                           candidate.remote_principal == remote_principal;
                });
            if (current == sync_auxiliary_carriers_.end()) {
                return Status{
                    ErrorCode::unavailable,
                    "auxiliary sync carrier incarnation is no longer ready"};
            }
            range_transfer_negotiated = current->range_transfer_negotiated;
            content_transfer_negotiated =
                current->content_transfer_negotiated;
        }
        std::vector<security::PeerAuthoritySnapshot> authorities =
            authority_sessions_->list();
        std::sort(authorities.begin(), authorities.end(),
                  [](const security::PeerAuthoritySnapshot &left,
                     const security::PeerAuthoritySnapshot &right) {
                      return left.friend_number < right.friend_number;
                  });
        for (const security::PeerAuthoritySnapshot &authority : authorities) {
            if (!authority.connected || !authority.remote_authorized ||
                authority.remote_principal != remote_principal ||
                authority.online_epoch !=
                    carrier.primary_authority_online_epoch) {
                continue;
            }
            auto session = sessions_.get(authority.friend_number);
            if (!session || !protocol::is_application_ready(session.value()) ||
                session.value().online_epoch != authority.online_epoch ||
                (session.value().negotiated.shared_features &
                 protocol::feature_bit(protocol::Feature::state_sync_v1)) ==
                    0U) {
                continue;
            }
            auto authority_route =
                parse_tox_public_key(session.value().public_key);
            if (!authority_route || authority_route.value() !=
                                        carrier.remote_coordinator_route_key) {
                continue;
            }
            auto context = sync_peer_context_locked(authority.friend_number,
                                                    session.value());
            if (!context)
                return context.status();
            context.value().transfer_carrier = carrier;
            context.value().range_transfer_negotiated =
                context.value().range_transfer_negotiated &&
                range_transfer_negotiated;
            context.value().content_transfer_negotiated =
                context.value().content_transfer_negotiated &&
                content_transfer_negotiated;
            return context;
        }
        return Status{
            ErrorCode::unavailable,
            "auxiliary sync carrier has no current primary authority session"};
    }

    Status send_sync_frame(const sync::SyncPeerContext &context,
                           const protocol::Frame &frame) {
        if (context.transfer_carrier.carrier_class ==
            sync::SyncCarrierClass::auxiliary) {
            if (route_worker_supervisor_ == nullptr ||
                (frame.type != protocol::MessageType::sync_object_request &&
                 frame.type != protocol::MessageType::sync_object_result &&
                 frame.type != protocol::MessageType::sync_range_request &&
                 frame.type != protocol::MessageType::sync_range_result &&
                 frame.type !=
                     protocol::MessageType::sync_content_object_request &&
                 frame.type !=
                     protocol::MessageType::sync_content_object_result &&
                 frame.type != protocol::MessageType::
                                   sync_content_availability_request &&
                 frame.type != protocol::MessageType::
                                   sync_content_availability_result)) {
                return Status{
                    ErrorCode::unsupported,
                    "auxiliary sync carrier permits only object/range/content frames"};
            }
            if ((frame.type == protocol::MessageType::sync_range_request ||
                 frame.type == protocol::MessageType::sync_range_result) &&
                !context.range_transfer_negotiated) {
                return Status{
                    ErrorCode::unsupported,
                    "auxiliary sync carrier did not negotiate range sync"};
            }
            if ((frame.type ==
                     protocol::MessageType::sync_content_object_request ||
                 frame.type ==
                     protocol::MessageType::sync_content_object_result ||
                 frame.type == protocol::MessageType::
                                   sync_content_availability_request ||
                 frame.type == protocol::MessageType::
                                   sync_content_availability_result) &&
                !context.content_transfer_negotiated) {
                return Status{
                    ErrorCode::unsupported,
                    "auxiliary sync carrier did not negotiate content sync"};
            }
            const Status sent = route_worker_supervisor_->send_sync_frame(
                context.transfer_carrier.route_key,
                context.transfer_carrier.worker_id, frame);
            if (sent.ok()) {
                record_protocol_frame(context.transfer_carrier.friend_number,
                                      "outgoing", frame);
            }
            return sent;
        }
        auto packet = protocol::encode(frame);
        if (!packet)
            return packet.status();
        const Status sent =
            transport_.send_lossless(context.friend_number, packet.value());
        if (sent.ok()) {
            record_protocol_frame(context.friend_number, "outgoing", frame);
        }
        return sent;
    }

    void
    handle_incoming_sync_request(std::uint32_t friend_number,
                                 const protocol::PeerSessionSnapshot &session,
                                 const protocol::Frame &frame) {
        if (sync_publisher_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_v1)) == 0U) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected unadvertised synchronization request friend=" +
                std::to_string(friend_number);
            return;
        }
        if (frame.type == protocol::MessageType::sync_range_request &&
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_ranges_v1)) ==
                0U) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "rejected unnegotiated synchronization range request friend=" +
                std::to_string(friend_number);
            return;
        }
        const std::uint64_t online_epoch = session.online_epoch;
        const Status admitted = queue_sync_work([this, friend_number,
                                                 online_epoch, frame] {
            auto current = sessions_.get(friend_number);
            if (!current || current.value().online_epoch != online_epoch) {
                return;
            }
            std::scoped_lock authority_effect_lock(
                ratox_authority_effect_mutex_);
            auto context =
                sync_peer_context_locked(friend_number, current.value());
            if (!context) {
                record_projection_failure(context.status());
                return;
            }
            auto handled = sync_publisher_->handle(context.value(), frame);
            if (!handled) {
                record_projection_failure(handled.status());
                return;
            }
            auto packet = protocol::encode(handled.value().response);
            const Status queued =
                packet ? transport_.send_lossless(friend_number, packet.value())
                       : packet.status();
            if (!queued.ok()) {
                record_projection_failure(queued);
                return;
            }
            record_protocol_frame(friend_number, "outgoing",
                                  handled.value().response);
        });
        if (!admitted.ok())
            record_projection_failure(admitted);
    }

    void handle_incoming_sync_content_request(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_content_publisher_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_content_v2)) ==
                0U) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = "rejected unadvertised content "
                                   "synchronization request friend=" +
                                   std::to_string(friend_number);
            return;
        }
        const std::uint64_t online_epoch = session.online_epoch;
        const Status admitted = queue_sync_work([this, friend_number,
                                                 online_epoch, frame] {
            auto current = sessions_.get(friend_number);
            if (!current || current.value().online_epoch != online_epoch) {
                return;
            }
            std::scoped_lock authority_effect_lock(
                ratox_authority_effect_mutex_);
            auto context =
                sync_peer_context_locked(friend_number, current.value());
            if (!context) {
                record_projection_failure(context.status());
                return;
            }
            auto handled =
                frame.type == protocol::MessageType::sync_content_object_request
                    ? sync_content_publisher_->handle(context.value(), frame)
                    : sync_content_publisher_->handle_availability(
                          context.value(), frame);
            if (!handled) {
                record_projection_failure(handled.status());
                return;
            }
            const Status sent =
                send_sync_frame(context.value(), handled.value().response);
            if (!sent.ok())
                record_projection_failure(sent);
        });
        if (!admitted.ok())
            record_projection_failure(admitted);
    }

    void handle_incoming_sync_tree_request(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_tree_publisher_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_tree_v2)) ==
                0U) {
            return;
        }
        const std::uint64_t online_epoch = session.online_epoch;
        const Status admitted =
            queue_sync_work([this, friend_number, online_epoch, frame] {
                auto current = sessions_.get(friend_number);
                if (!current || current.value().online_epoch != online_epoch)
                    return;
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                auto context =
                    sync_peer_context_locked(friend_number, current.value());
                if (!context) {
                    record_projection_failure(context.status());
                    return;
                }
                auto handled =
                    sync_tree_publisher_->handle(context.value(), frame);
                if (!handled) {
                    record_projection_failure(handled.status());
                    return;
                }
                const Status sent =
                    send_sync_frame(context.value(), handled.value().response);
                if (!sent.ok()) record_projection_failure(sent);
            });
        if (!admitted.ok()) record_projection_failure(admitted);
    }

    void handle_incoming_sync_tree_inventory_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_tree_subscriber_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_tree_v2)) ==
                0U) {
            return;
        }
        const std::uint64_t online_epoch = session.online_epoch;
        const Status admitted =
            queue_sync_work([this, friend_number, online_epoch, frame] {
                auto current = sessions_.get(friend_number);
                if (!current || current.value().online_epoch != online_epoch)
                    return;
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                auto context =
                    sync_peer_context_locked(friend_number, current.value());
                if (!context) {
                    record_projection_failure(context.status());
                    return;
                }
                auto requests = sync_tree_subscriber_->handle_inventory_result(
                    context.value(), frame);
                if (!requests) {
                    if (requests.status().code() != ErrorCode::not_found &&
                        requests.status().code() != ErrorCode::unavailable) {
                        record_projection_failure(requests.status());
                    }
                    return;
                }
                for (const sync::TreeV2Dispatch &request : requests.value()) {
                    const Status sent =
                        send_sync_frame(request.context, request.frame);
                    if (!sent.ok()) {
                        record_projection_failure(sent);
                        return;
                    }
                }
            });
        if (!admitted.ok()) record_projection_failure(admitted);
    }

    void handle_incoming_sync_tree_object_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_tree_subscriber_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_tree_v2)) ==
                0U) {
            return;
        }
        std::scoped_lock authority_effect_lock(ratox_authority_effect_mutex_);
        auto context = sync_peer_context_locked(friend_number, session);
        auto handled = context
            ? sync_tree_subscriber_->handle_object_result(context.value(),
                                                          frame)
            : Result<std::vector<sync::TreeV2Dispatch>>{context.status()};
        if (!handled) {
            if (handled.status().code() != ErrorCode::not_found &&
                handled.status().code() != ErrorCode::unavailable) {
                record_projection_failure(handled.status());
            }
            return;
        }
        for (const sync::TreeV2Dispatch &request : handled.value()) {
            const Status sent = send_sync_frame(request.context, request.frame);
            if (!sent.ok()) {
                record_projection_failure(sent);
                return;
            }
        }
    }

    void handle_incoming_sync_head_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_subscriber_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_v1)) == 0U) {
            return;
        }
        const std::uint64_t online_epoch = session.online_epoch;
        const Status admitted = queue_sync_work([this, friend_number,
                                                 online_epoch, frame] {
            auto current = sessions_.get(friend_number);
            if (!current || current.value().online_epoch != online_epoch) {
                return;
            }
            std::scoped_lock authority_effect_lock(
                ratox_authority_effect_mutex_);
            auto context =
                sync_peer_context_locked(friend_number, current.value());
            if (!context) {
                record_projection_failure(context.status());
                return;
            }
            if (sync_content_subscriber_ != nullptr) {
                const auto content_pulls = sync_content_subscriber_->snapshot();
                const auto content_pull = std::find_if(
                    content_pulls.begin(), content_pulls.end(),
                    [friend_number, online_epoch,
                     &frame](const sync::SyncContentPullSnapshot &candidate) {
                        return candidate.friend_number == friend_number &&
                               candidate.online_epoch == online_epoch &&
                               candidate.job_id == frame.correlation_id;
                    });
                if (content_pull != content_pulls.end()) {
                    auto requests =
                        sync_content_subscriber_->handle_head_result(
                            context.value(), frame);
                    if (!requests) {
                        record_projection_failure(requests.status());
                        return;
                    }
                    for (const sync::SyncContentDispatch &request :
                         requests.value()) {
                        const Status queued =
                            send_sync_frame(request.context, request.frame);
                        if (!queued.ok()) {
                            record_projection_failure(queued);
                            return;
                        }
                    }
                    return;
                }
            }
            const auto pulls = sync_subscriber_->snapshot();
            const auto pull = std::find_if(
                pulls.begin(), pulls.end(),
                [friend_number, online_epoch,
                 &frame](const sync::SyncPullSnapshot &candidate) {
                    return candidate.friend_number == friend_number &&
                           candidate.online_epoch == online_epoch &&
                           candidate.head_request_message_id ==
                               frame.correlation_id;
                });
            if (pull == pulls.end()) {
                return;
            }
            if (pull->state == sync::SyncPullState::awaiting_objects) {
                if (pull->transfer_carrier.carrier_class ==
                    sync::SyncCarrierClass::auxiliary) {
                    auto auxiliary = auxiliary_sync_context_locked(
                        pull->transfer_carrier,
                        context.value().peer_authority.remote_principal);
                    if (!auxiliary)
                        return;
                    context.value() = std::move(auxiliary).value();
                } else {
                    context.value().transfer_carrier = pull->transfer_carrier;
                }
                auto requests = sync_subscriber_->handle_head_result(
                    context.value(), frame);
                if (!requests) {
                    record_projection_failure(requests.status());
                    return;
                }
                for (const protocol::Frame &request : requests.value()) {
                    const Status queued =
                        send_sync_frame(context.value(), request);
                    if (!queued.ok()) {
                        record_projection_failure(queued);
                        return;
                    }
                }
                return;
            }
            const std::vector<AuxiliarySyncCarrierState> candidates =
                current_auxiliary_sync_carriers();
            auto carrier = sync::select_sync_route(
                config_.sync.route_selection_policy, candidates,
                context.value().peer_authority.remote_principal, std::nullopt,
                1U, pull->route_class);
            if (carrier) {
                context.value().transfer_carrier = carrier.value().carrier;
                context.value().range_transfer_negotiated =
                    context.value().range_transfer_negotiated &&
                    carrier.value().range_transfer_negotiated;
                if (config_.sync.route_selection_policy ==
                    sync::SyncRouteSelectionPolicy::adaptive) {
                    sync_auxiliary_adaptive_selections_.fetch_add(
                        1U, std::memory_order_relaxed);
                } else {
                    sync_auxiliary_fixed_selections_.fetch_add(
                        1U, std::memory_order_relaxed);
                }
            } else if (carrier.status().code() != ErrorCode::unavailable) {
                record_projection_failure(carrier.status());
            } else if (pull->route_class !=
                       sync::SyncRouteClassConstraint::any) {
                // Keep the exact HEAD request live. An operator retry can
                // replay it after the required route class becomes ready;
                // never consume the result through the primary carrier.
                return;
            }
            auto requests =
                sync_subscriber_->handle_head_result(context.value(), frame);
            if (!requests) {
                record_projection_failure(requests.status());
                return;
            }
            for (const protocol::Frame &request : requests.value()) {
                const Status queued = send_sync_frame(context.value(), request);
                if (!queued.ok()) {
                    record_projection_failure(queued);
                    return;
                }
            }
        });
        if (!admitted.ok())
            record_projection_failure(admitted);
    }

    void handle_incoming_sync_object_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_subscriber_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_v1)) == 0U) {
            return;
        }
        std::scoped_lock authority_effect_lock(ratox_authority_effect_mutex_);
        auto context = sync_peer_context_locked(friend_number, session);
        if (!context) {
            record_projection_failure(context.status());
            return;
        }
        auto handled =
            sync_subscriber_->handle_object_result(context.value(), frame);
        if (!handled) {
            record_projection_failure(handled.status());
            return;
        }
        for (const protocol::Frame &request : handled.value()) {
            const Status sent = send_sync_frame(context.value(), request);
            if (!sent.ok()) {
                record_projection_failure(sent);
                return;
            }
        }
    }

    void handle_incoming_sync_range_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_subscriber_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_ranges_v1)) ==
                0U) {
            return;
        }
        std::scoped_lock authority_effect_lock(ratox_authority_effect_mutex_);
        auto context = sync_peer_context_locked(friend_number, session);
        const Status handled =
            context
                ? sync_subscriber_->handle_range_result(context.value(), frame)
                : context.status();
        if (!handled.ok())
            record_projection_failure(handled);
    }

    void handle_incoming_sync_content_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_content_subscriber_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_content_v2)) ==
                0U) {
            return;
        }
        std::scoped_lock authority_effect_lock(ratox_authority_effect_mutex_);
        auto context = sync_peer_context_locked(friend_number, session);
        const Status handled =
            context ? sync_content_subscriber_->handle_object_result(
                          context.value(), frame)
                    : context.status();
        if (!handled.ok() && handled.code() != ErrorCode::not_found &&
            handled.code() != ErrorCode::unavailable) {
            record_projection_failure(handled);
        }
    }

    void handle_incoming_sync_content_availability_result(
        std::uint32_t friend_number,
        const protocol::PeerSessionSnapshot &session,
        const protocol::Frame &frame) {
        if (sync_content_subscriber_ == nullptr ||
            (session.negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_content_v2)) ==
                0U) {
            return;
        }
        const std::uint64_t online_epoch = session.online_epoch;
        const Status admitted = queue_sync_work(
            [this, friend_number, online_epoch, frame] {
                auto current = sessions_.get(friend_number);
                if (!current || current.value().online_epoch != online_epoch)
                    return;
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                auto context =
                    sync_peer_context_locked(friend_number, current.value());
                if (!context) {
                    record_projection_failure(context.status());
                    return;
                }
                auto requests =
                    sync_content_subscriber_->handle_availability_result(
                        context.value(), frame);
                if (!requests) {
                    if (requests.status().code() != ErrorCode::not_found &&
                        requests.status().code() != ErrorCode::unavailable) {
                        record_projection_failure(requests.status());
                    }
                    return;
                }
                for (const sync::SyncContentDispatch &request :
                     requests.value()) {
                    const Status sent =
                        send_sync_frame(request.context, request.frame);
                    if (!sent.ok()) {
                        record_projection_failure(sent);
                        return;
                    }
                }
            });
        if (!admitted.ok())
            record_projection_failure(admitted);
    }

    std::vector<local::FriendRequestRecord> pending_friend_requests() const {
        std::vector<local::FriendRequestRecord> requests;
        std::scoped_lock lock(request_mutex_);
        requests.reserve(pending_requests_.size());
        for (const auto &[key, request] : pending_requests_) {
            static_cast<void>(key);
            requests.push_back(request);
        }
        return requests;
    }

    bool has_friend_request(std::span<const std::uint8_t> public_key) const {
        const std::string key = bytes_hex(public_key);
        std::scoped_lock lock(request_mutex_);
        return pending_requests_.contains(key);
    }

    void record_friend_request(const TransportEvent &event) {
        if (event.public_key.size() != toxcore::abi::kPublicKeySize) {
            record_projection_failure(Status{
                ErrorCode::protocol_error,
                "incoming friend request did not contain a 32-byte public key"});
            return;
        }
        local::FriendRequestRecord request;
        std::copy_n(event.public_key.begin(), request.public_key.size(),
                    request.public_key.begin());
        request.received_unix_ms = unix_time_ms();
        request.message = event.data;
        const std::string key = bytes_hex(event.public_key);
        std::size_t count = 0U;
        Status published = Status::success();
        {
            // One same-key request arrival or local decision is committed at a
            // time. The operation lock covers toxcore mutation, the live inbox,
            // and its disposable filesystem projection; the request lock keeps
            // list readers independent of unrelated friendship operations.
            std::scoped_lock operation_lock(friendship_operation_mutex_);
            std::scoped_lock request_lock(request_mutex_);
            published = runtime_.publish_friend_request(
                event, request.received_unix_ms);
            if (published.ok()) {
                pending_requests_[key] = request;
                count = pending_requests_.size();
            }
        }
        if (!published.ok()) {
            record_projection_failure(published);
            append_friend_lifecycle_best_effort(
                "toxcore", "request-received", key,
                "projection-failed", published);
            return;
        }
        {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.pending_request_count = count;
        }
        // The request directory is already observable at this point. Publish
        // its aggregate count before journal I/O so readers do not see a live
        // inbox paired with an arbitrarily stale status projection.
        publish_snapshot_best_effort();
        append_friend_lifecycle_best_effort("toxcore", "request-received", key,
                                            "pending", Status::success(),
                                            std::nullopt,
                                            "incoming Tox request is live; no "
                                            "friendship or IoTox authority has "
                                            "been granted");
    }

    Status forget_friend_request(
        std::span<const std::uint8_t> public_key, bool require_existing) {
        const std::string key = bytes_hex(public_key);
        std::size_t count = 0U;
        Status removed = Status::success();
        {
            // Keep a same-key callback from recreating or withdrawing half of
            // the live record while the operator decision is being committed.
            std::scoped_lock lock(request_mutex_);
            const auto found = pending_requests_.find(key);
            if (require_existing && found == pending_requests_.end()) {
                return Status{ErrorCode::not_found,
                              "no pending friend request exists for that public key"};
            }
            pending_requests_.erase(key);
            count = pending_requests_.size();
            removed = runtime_.remove_friend_request(public_key);
        }
        {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.pending_request_count = count;
        }
        return removed;
    }

    void refresh_transfer_snapshot() {
        const std::vector<FileTransferRecord> records = transfers_.list();
        const Status projected = runtime_.publish_transfers(records);
        if (!projected.ok()) {
            record_projection_failure(projected);
        }

        std::vector<std::pair<std::uint32_t, std::string>> peers;
        {
            std::scoped_lock lock(peer_mutex_);
            peers.reserve(peer_keys_.size());
            for (const auto &[friend_number, public_key] : peer_keys_) {
                peers.emplace_back(friend_number, public_key);
            }
        }
        for (const auto &[friend_number, public_key] : peers) {
            std::vector<FileTransferRecord> peer_records;
            for (const FileTransferRecord &record : records) {
                if (record.friend_number == friend_number) {
                    peer_records.push_back(record);
                }
            }
            const Status peer_projected = runtime_.publish_peer_transfers(
                public_key, peer_records);
            if (!peer_projected.ok()) {
                record_projection_failure(peer_projected);
            }
        }

        std::size_t offers = 0U;
        std::size_t active = 0U;
        for (const FileTransferRecord &record : records) {
            if (record.direction == FileTransferDirection::incoming &&
                record.state == FileTransferState::offered) {
                ++offers;
            } else {
                ++active;
            }
        }
        std::scoped_lock lock(snapshot_mutex_);
        snapshot_.incoming_file_offer_count = offers;
        snapshot_.active_file_transfer_count = active;
    }

    void record_file_transport_event(
        const TransportEvent &event, const Status &manager_status) {
        switch (event.kind) {
            case TransportEventKind::file_offer:
            case TransportEventKind::file_control:
                break;
            case TransportEventKind::file_chunk_request:
                // Non-terminal chunk requests are high-volume transfer
                // mechanics. Their current position is projected in files/;
                // journaling every request would let one large transfer consume
                // the bounded semantic history. Preserve terminal completion
                // and every manager failure.
                if (manager_status.ok() && event.requested_length != 0U) {
                    return;
                }
                break;
            case TransportEventKind::file_chunk:
                // Likewise, retain only the zero-length terminal receive event
                // unless the manager rejected a chunk. Never copy payload bytes
                // into the semantic file journal.
                if (manager_status.ok() && !event.data.empty()) {
                    return;
                }
                break;
            default:
                return;
        }

        auto public_key = peer_key_for(event.friend_number);
        if (!public_key) {
            record_projection_failure(public_key.status());
            return;
        }

        local::PeerFileTransportEvent journal;
        journal.unix_ms = unix_time_ms();
        journal.event = event;
        journal.manager_status = manager_status;
        const std::vector<FileTransferRecord> records = transfers_.list();
        for (const FileTransferRecord &record : records) {
            if (record.friend_number != event.friend_number ||
                record.file_number != event.file_number) {
                continue;
            }
            if (event.kind == TransportEventKind::file_offer &&
                record.direction != FileTransferDirection::incoming) {
                continue;
            }
            if (event.kind == TransportEventKind::file_chunk &&
                record.direction != FileTransferDirection::incoming) {
                continue;
            }
            if (event.kind == TransportEventKind::file_chunk_request &&
                record.direction != FileTransferDirection::outgoing) {
                continue;
            }
            journal.has_transfer = true;
            journal.transfer = record;
            break;
        }
        const Status appended = runtime_.append_peer_file_transport(
            public_key.value(), journal);
        if (!appended.ok()) {
            record_projection_failure(appended);
        }
    }

    void event_main() noexcept {
        try {
            while (!event_stop_.load()) {
                std::optional<TransportEvent> event =
                    transport_.poll_event(std::chrono::milliseconds(100));
                if (event) {
                    // Ratox INPUT and OUTPUT frames may contain live terminal
                    // bytes. Keep the transport event alive through metadata
                    // journaling, then wipe its backing allocation on every
                    // normal and exceptional exit from this dispatch scope.
                    ScopedSensitiveEventDataWipe sensitive_payload{
                        ratox_transport_payload(*event)
                            ? &event->data
                            : nullptr};
                    const bool publish_event = apply_event(*event);
                    if (publish_event) {
                        const Status journaled = runtime_.append_event(*event);
                        if (!journaled.ok()) {
                            std::scoped_lock lock(snapshot_mutex_);
                            snapshot_.last_event = journaled.message();
                        }
                        publish_snapshot_best_effort();
                    }
                    const bool ratox_relevant =
                        event->kind == TransportEventKind::friend_connection ||
                        event->kind == TransportEventKind::friend_removed ||
                        (event->kind == TransportEventKind::lossless_packet &&
                         !event->data.empty() &&
                         event->data.front() == protocol::ratox::kPacketId);
                    if (ratox_relevant) notify_ratox_service();
                }
                // Let tox_iterate make progress on the owner thread before
                // servicing retry state. Session handshakes retry only local
                // enqueue failures. Durable COMMAND requests follow their
                // signed schedule until application receipt/result, while
                // locally owned receipt/result lanes stop after enqueue.
                service_protocol_sessions_best_effort();
            }
        } catch (const std::exception &exception) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = "event-pump-failed: " + std::string(exception.what());
        } catch (...) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = "event-pump-failed: unknown exception";
        }
    }

    void service_update_adapter_best_effort() {
        if (update_store_ == nullptr ||
            update_service_adapter_ == nullptr ||
            !protocol_incarnation_lease_.has_value()) {
            return;
        }
        std::scoped_lock update_lock(update_operation_mutex_);
        const update::LinuxServiceSnapshot before =
            update_service_adapter_->snapshot();
        const Status serviced = update_service_adapter_->poll();
        const update::LinuxServiceSnapshot after =
            update_service_adapter_->snapshot();
        if (after.phase != before.phase) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "linux-service-v1 phase=" +
                std::string(update::linux_service_phase_name(after.phase)) +
                " sequence=" +
                std::to_string(after.release_sequence);
        }
        const bool failed =
            after.phase == update::LinuxServicePhase::failed ||
            after.phase == update::LinuxServicePhase::exited;
        if (!failed) {
            if (!serviced.ok()) record_projection_failure(serviced);
            return;
        }
        const std::optional<update::UpdateState> state =
            update_store_->snapshot();
        if (!state.has_value() ||
            state->phase != update::UpdatePhase::awaiting_health ||
            !after.candidate) {
            if (!serviced.ok()) record_projection_failure(serviced);
            return;
        }
        auto rolled = update_store_->expire_health(
            protocol_incarnation_lease_->incarnation());
        if (!rolled.ok()) {
            record_projection_failure(Status{
                rolled.status().code(),
                "linux-service-v1 failure rollback failed closed: " +
                    rolled.status().message()});
            return;
        }
        {
            std::scoped_lock lock(update_health_mutex_);
            update_health_deadline_.reset();
        }
        const Status recovered = launch_selected_update_service();
        if (!recovered.ok()) {
            record_projection_failure(Status{
                recovered.code(), "linux-service-v1 candidate rolled back but "
                                  "confirmed service recovery failed: " +
                                      recovered.message()});
            return;
        }
        {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "linux-service-v1 candidate-failed rollback-count=" +
                std::to_string(rolled.value().rollback_count);
        }
        publish_snapshot_best_effort();
    }

    void service_update_health_best_effort() {
        if (update_store_ == nullptr ||
            !protocol_incarnation_lease_.has_value()) {
            return;
        }
        bool expired = false;
        {
            std::scoped_lock lock(update_health_mutex_);
            if (update_health_deadline_.has_value() &&
                std::chrono::steady_clock::now() >=
                    *update_health_deadline_) {
                update_health_deadline_.reset();
                expired = true;
            }
        }
        if (!expired) return;
        std::scoped_lock update_lock(update_operation_mutex_);
        auto rolled = update_store_->expire_health(
            protocol_incarnation_lease_->incarnation());
        if (!rolled.ok()) {
            const std::optional<update::UpdateState> state =
                update_store_->snapshot();
            if (state.has_value() &&
                state->phase == update::UpdatePhase::awaiting_health &&
                state->health_incarnation ==
                    protocol_incarnation_lease_->incarnation()) {
                std::scoped_lock lock(update_health_mutex_);
                update_health_deadline_ =
                    std::chrono::steady_clock::now() +
                    std::chrono::seconds(1);
            }
            record_projection_failure(Status{
                rolled.status().code(),
                "signed-update health expiry failed closed: " +
                    rolled.status().message()});
            return;
        }
        {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "signed-update-health-expired rollback-count=" +
                std::to_string(rolled.value().rollback_count);
        }
        if (config_.update.linux_service_enabled) {
            const Status recovered = launch_selected_update_service();
            if (!recovered.ok()) {
                record_projection_failure(Status{
                    recovered.code(),
                    "signed-update health rollback selected service recovery failed: " +
                        recovered.message()});
            }
        }
        publish_snapshot_best_effort();
    }

    void service_main() noexcept {
        try {
            while (!event_stop_.load()) {
                std::uint64_t observed_generation = 0U;
                {
                    std::scoped_lock lock(ratox_service_wake_mutex_);
                    observed_generation = ratox_service_wake_generation_;
                }

                const bool latency_active = ratox_latency_active();
                if (latency_active != ratox_latency_mode_active_) {
                    const std::chrono::milliseconds interval = latency_active
                        ? std::min(
                              config_.transport.maximum_iteration_interval,
                              config_.interactive
                                  .active_transport_iteration_interval)
                        : config_.transport.maximum_iteration_interval;
                    const Status adjusted =
                        transport_.set_maximum_iteration_interval(interval);
                    if (!adjusted.ok()) {
                        record_projection_failure(Status{
                            adjusted.code(),
                            "unable to adjust Ratox-active toxcore cadence: " +
                                adjusted.message()});
                    } else {
                        ratox_latency_mode_active_ = latency_active;
                        {
                            std::scoped_lock lock(snapshot_mutex_);
                            snapshot_.ratox_latency_mode_active =
                                latency_active;
                        }
                        publish_snapshot_best_effort();
                    }
                }

                service_ratox_best_effort();
                service_update_adapter_best_effort();
                service_update_health_best_effort();
                service_sync_automation_best_effort();

                const Status carrier_status = transfers_.service_carrier();
                if (!carrier_status.ok() &&
                    carrier_status.code() != ErrorCode::unavailable) {
                    record_projection_failure(Status{
                        carrier_status.code(),
                        "file carrier service failed: " +
                            carrier_status.message()});
                }

                const std::chrono::milliseconds interval = latency_active
                    ? config_.interactive.active_service_interval
                    : std::chrono::milliseconds(20);
                std::unique_lock lock(ratox_service_wake_mutex_);
                ratox_service_cv_.wait_for(lock, interval, [this, observed_generation] {
                    return event_stop_.load() ||
                        ratox_service_wake_generation_ != observed_generation;
                });
            }
        } catch (const std::exception &exception) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event =
                "service-loop-failed: " + std::string(exception.what());
        } catch (...) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = "service-loop-failed: unknown exception";
        }
    }

    static std::optional<FileTransferRecord> incoming_transfer_for(
        const std::vector<FileTransferRecord> &records,
        std::uint32_t friend_number, std::uint32_t file_number) {
        const auto found = std::find_if(
            records.begin(), records.end(),
            [friend_number, file_number](const FileTransferRecord &record) {
                return record.direction == FileTransferDirection::incoming &&
                    record.friend_number == friend_number &&
                    record.file_number == file_number;
            });
        return found == records.end()
            ? std::optional<FileTransferRecord>{}
            : std::optional<FileTransferRecord>{*found};
    }

    void service_sync_local_cancel_best_effort(
        std::uint32_t friend_number, std::uint32_t file_number,
        const std::optional<FileTransferRecord> &before,
        const Status &manager_status) {
        TransportEvent event;
        event.kind = TransportEventKind::file_control;
        event.friend_number = friend_number;
        event.file_number = file_number;
        event.file_control = TransferControl::cancel;
        service_sync_file_event_best_effort(event, before, manager_status);
    }

    void service_sync_file_event_best_effort(
        const TransportEvent &event,
        const std::optional<FileTransferRecord> &before,
        const Status &manager_status) {
        if (sync_subscriber_ == nullptr)
            return;
        // Lossless control packets, messages, diagnostics, and unrelated
        // transport events have no synchronization file effect. Reject them
        // before the authority-effect mutex: a publisher worker may retain
        // that boundary during object verification, and waiting here would
        // prevent the event pump from admitting the next bounded sync request.
        if (event.kind != TransportEventKind::file_offer && !before)
            return;

        auto session = sessions_.get(event.friend_number);
        if (!session || !protocol::is_application_ready(session.value()) ||
            (session.value().negotiated.shared_features &
             protocol::feature_bit(protocol::Feature::state_sync_v1)) == 0U) {
            return;
        }
        std::scoped_lock authority_effect_lock(ratox_authority_effect_mutex_);
        auto context =
            sync_peer_context_locked(event.friend_number, session.value());
        if (!context) {
            if (context.status().code() != ErrorCode::not_found &&
                context.status().code() != ErrorCode::unavailable) {
                record_projection_failure(context.status());
            }
            return;
        }

        const std::vector<FileTransferRecord> after = transfers_.list();
        if (event.kind == TransportEventKind::file_offer &&
            manager_status.ok()) {
            const auto offer = incoming_transfer_for(after, event.friend_number,
                                                     event.file_number);
            if (!offer)
                return;
            if (sync_tree_subscriber_ != nullptr &&
                context.value().tree_transfer_negotiated) {
                auto claimed = sync_tree_subscriber_->handle_offer(
                    context.value(), *offer);
                if (!claimed) {
                    if (claimed.status().code() != ErrorCode::not_found &&
                        claimed.status().code() != ErrorCode::unavailable) {
                        record_projection_failure(claimed.status());
                    }
                    return;
                }
                if (claimed.value()) return;
            }
            bool content_claimed = false;
            if (sync_content_subscriber_ != nullptr &&
                context.value().content_transfer_negotiated) {
                auto claimed = sync_content_subscriber_->handle_offer(
                    context.value(), *offer);
                if (!claimed) {
                    if (claimed.status().code() != ErrorCode::not_found &&
                        claimed.status().code() != ErrorCode::unavailable) {
                        record_projection_failure(claimed.status());
                    }
                    return;
                }
                content_claimed = claimed.value();
            }
            if (content_claimed)
                return;
            auto claimed =
                sync_subscriber_->handle_offer(context.value(), *offer);
            if (!claimed && claimed.status().code() != ErrorCode::not_found) {
                record_projection_failure(claimed.status());
            }
            return;
        }

        if (!before || incoming_transfer_for(after, event.friend_number,
                                             event.file_number)) {
            return;
        }

        FileTransferRecord terminal = *before;
        routes::WorkerTransferOutcome outcome =
            routes::WorkerTransferOutcome::failed;
        ErrorCode failure =
            manager_status.ok() ? ErrorCode::io_error : manager_status.code();
        std::string detail =
            manager_status.ok()
                ? "incoming sync transfer ended without a completion event"
                : manager_status.message();
        if (event.kind == TransportEventKind::file_chunk &&
            event.data.empty() && manager_status.ok()) {
            terminal.state = FileTransferState::completed;
            terminal.position = event.file_position;
            outcome = routes::WorkerTransferOutcome::completed;
            failure = ErrorCode::ok;
            detail =
                "c-toxcore receive completed and staging file was published";
        } else if ((event.kind == TransportEventKind::file_control &&
                    event.file_control == TransferControl::cancel) ||
                   event.kind == TransportEventKind::friend_connection ||
                   event.kind == TransportEventKind::friend_removed) {
            terminal.state = FileTransferState::cancelled;
            outcome = routes::WorkerTransferOutcome::cancelled;
            failure = ErrorCode::ok;
            detail = "sync transfer was cancelled before object commit";
        } else {
            terminal.state = FileTransferState::failed;
        }
        const std::uint64_t online_epoch = session.value().online_epoch;
        const Status admitted = queue_sync_terminal_work(
            [this, friend_number = event.friend_number, online_epoch,
             terminal = std::move(terminal), outcome, failure,
             detail = std::move(detail)]() mutable {
                auto current = sessions_.get(friend_number);
                if (!current || current.value().online_epoch != online_epoch) {
                    return;
                }
                std::scoped_lock terminal_authority_effect_lock(
                    ratox_authority_effect_mutex_);
                auto fresh_context =
                    sync_peer_context_locked(friend_number, current.value());
                if (fresh_context && sync_tree_subscriber_ != nullptr &&
                    fresh_context.value().tree_transfer_negotiated) {
                    auto tree_handled = sync_tree_subscriber_->handle_terminal(
                        fresh_context.value(), terminal, outcome, failure);
                    if (tree_handled) {
                        for (const sync::TreeV2Dispatch &request :
                             tree_handled.value()) {
                            const Status queued =
                                send_sync_frame(request.context, request.frame);
                            if (!queued.ok()) {
                                record_projection_failure(queued);
                                return;
                            }
                        }
                        return;
                    }
                    if (tree_handled.status().code() != ErrorCode::not_found) {
                        if (tree_handled.status().code() !=
                            ErrorCode::unavailable) {
                            record_projection_failure(tree_handled.status());
                        }
                        return;
                    }
                }
                if (fresh_context && sync_content_subscriber_ != nullptr &&
                    fresh_context.value().content_transfer_negotiated) {
                    auto content_handled =
                        sync_content_subscriber_->handle_terminal(
                        fresh_context.value(), terminal, outcome, failure);
                    if (content_handled) {
                        for (const sync::SyncContentDispatch &request :
                             content_handled.value()) {
                            const Status queued = send_sync_frame(
                                request.context, request.frame);
                            if (!queued.ok()) {
                                record_projection_failure(queued);
                                return;
                            }
                        }
                        return;
                    }
                    if (content_handled.status().code() !=
                        ErrorCode::not_found) {
                        if (content_handled.status().code() !=
                            ErrorCode::unavailable) {
                            record_projection_failure(
                                content_handled.status());
                        }
                        return;
                    }
                }
                Result<std::vector<protocol::Frame>> handled =
                    fresh_context
                        ? sync_subscriber_->handle_terminal(
                              fresh_context.value(), terminal, outcome, failure,
                              std::move(detail))
                        : Result<std::vector<protocol::Frame>>{
                              fresh_context.status()};
                if (!handled) {
                    if (handled.status().code() != ErrorCode::not_found &&
                        handled.status().code() != ErrorCode::unavailable) {
                        record_projection_failure(handled.status());
                    }
                    return;
                }
                for (const protocol::Frame &request : handled.value()) {
                    const Status queued =
                        send_sync_frame(fresh_context.value(), request);
                    if (!queued.ok()) {
                        record_projection_failure(queued);
                        return;
                    }
                }
            });
        if (!admitted.ok())
            record_projection_failure(admitted);
    }

    bool apply_event(const TransportEvent &event) {
        {
            std::scoped_lock lock(snapshot_mutex_);
            ++snapshot_.event_count;
            snapshot_.dropped_event_count =
                std::max(snapshot_.dropped_event_count, event.dropped_events_before);
            snapshot_.last_event = to_string(event.kind);
            if (event.kind == TransportEventKind::backend_ready) {
                snapshot_.backend = event.message;
            } else if (event.kind == TransportEventKind::self_connection) {
                snapshot_.self_connection = transport_connection_name(event.connection_status);
            }
        }
        if (event.kind == TransportEventKind::self_connection) {
            record_diagnostic_best_effort(
                diagnostics::EventClass::transport_state);
        }

        std::optional<FileTransferRecord> sync_transfer_before;
        if (sync_subscriber_ != nullptr &&
            (event.kind == TransportEventKind::file_chunk ||
             event.kind == TransportEventKind::file_control ||
             event.kind == TransportEventKind::friend_connection ||
             event.kind == TransportEventKind::friend_removed)) {
            sync_transfer_before = incoming_transfer_for(
                transfers_.list(), event.friend_number, event.file_number);
        }
        const Status transfer_status = transfers_.handle_event(event);
        service_sync_file_event_best_effort(
            event, sync_transfer_before, transfer_status);
        record_file_transport_event(event, transfer_status);
        if (!transfer_status.ok()) {
            std::scoped_lock lock(snapshot_mutex_);
            snapshot_.last_event = "file-transfer-failed: " + transfer_status.message();
        }

        const bool routine_file_progress = transfer_status.ok() &&
            ((event.kind == TransportEventKind::file_chunk_request &&
              event.requested_length != 0U) ||
             (event.kind == TransportEventKind::file_chunk &&
              !event.data.empty()));
        bool publish_event = true;
        if (routine_file_progress) {
            const auto now = std::chrono::steady_clock::now();
            if (now < next_file_progress_projection_) {
                publish_event = false;
            } else {
                next_file_progress_projection_ =
                    now + kFileProgressProjectionInterval;
            }
        } else if (event.kind == TransportEventKind::file_offer ||
                   event.kind == TransportEventKind::file_control ||
                   event.kind == TransportEventKind::file_chunk_request ||
                   event.kind == TransportEventKind::file_chunk) {
            next_file_progress_projection_ = {};
        }
        if (publish_event) {
            // Per-chunk atomic directory replacement and status publication
            // amplify one 1371-byte toxcore chunk into dozens of filesystem
            // operations. The manager still consumes every required event;
            // only disposable progress projections/journal samples are
            // coalesced. Local `files` queries force an exact refresh.
            refresh_transfer_snapshot();
        }

        switch (event.kind) {
            case TransportEventKind::friend_request:
                record_friend_request(event);
                break;
            case TransportEventKind::friend_connection:
                handle_friend_connection(event);
                break;
            case TransportEventKind::friend_removed: {
                std::string public_key;
                if (event.public_key.size() == toxcore::abi::kPublicKeySize) {
                    public_key = bytes_hex(event.public_key);
                } else {
                    auto mapped = peer_key_for(event.friend_number);
                    if (mapped) {
                        public_key = mapped.value();
                    }
                }
                erase_transport_peer_application_state(event.friend_number);
                refresh_peers_best_effort();
                publish_sessions_best_effort();
                publish_authority_sessions_best_effort();
                if (!public_key.empty()) {
                    append_friend_lifecycle_best_effort(
                        "toxcore", "peer-removed-event", public_key, "observed",
                        Status::success(), event.friend_number,
                        "transport owner thread reported that this public key "
                        "no longer "
                        "has a local Tox friendship");
                }
                break;
            }
            case TransportEventKind::friend_added:
                refresh_peers_best_effort();
                if (event.public_key.size() == toxcore::abi::kPublicKeySize) {
                    append_friend_lifecycle_best_effort(
                        "toxcore", "peer-added-event",
                        bytes_hex(event.public_key), "observed",
                        Status::success(), event.friend_number,
                        event.message.empty()
                            ? "transport owner thread reported a new local Tox friendship"
                            : event.message);
                }
                break;
            case TransportEventKind::friend_name:
            case TransportEventKind::friend_status_message:
            case TransportEventKind::friend_status:
            case TransportEventKind::friend_typing:
                refresh_peers_best_effort();
                break;
            case TransportEventKind::message_sent:
            case TransportEventKind::friend_message:
            case TransportEventKind::friend_read_receipt:
                if (event.kind == TransportEventKind::friend_read_receipt) {
                    {
                        std::scoped_lock lock(receipt_mutex_);
                        if (received_receipts_.size() >= 1024U) {
                            received_receipts_.erase(received_receipts_.begin());
                        }
                        received_receipts_.insert_or_assign(
                            message_receipt_key(
                                event.friend_number, event.message_id),
                            std::chrono::steady_clock::now());
                    }
                    receipt_cv_.notify_all();
                }
                record_peer_message(event);
                break;
            case TransportEventKind::lossy_packet:
                handle_incoming_probe(event);
                break;
            case TransportEventKind::lossless_packet:
                if (!event.data.empty() &&
                    event.data.front() == interactive::kLosslessProbePacketId) {
                    handle_incoming_probe(event);
                } else if (!event.data.empty() &&
                           event.data.front() ==
                               protocol::ratox::kPacketId) {
                    inspect_incoming_ratox(event);
                } else {
                    inspect_incoming_lossless(event);
                }
                break;
            case TransportEventKind::backend_ready:
            case TransportEventKind::self_connection:
            case TransportEventKind::file_offer:
            case TransportEventKind::file_control:
            case TransportEventKind::file_chunk_request:
            case TransportEventKind::file_chunk:
            case TransportEventKind::bootstrap:
            case TransportEventKind::tcp_relay:
            case TransportEventKind::diagnostic:
                break;
        }
        return publish_event;
    }

    [[nodiscard]] std::uint64_t offered_operation_mask() const noexcept {
        std::uint64_t mask = protocol::implemented_operation_mask();
        if (update_store_ == nullptr) {
            mask &= ~protocol::kUpdateStageOperationBit;
        }
        return mask;
    }

    Result<update::UpdateStageResult> stage_update_head(
        std::string_view namespace_id,
        const sync::Digest &expected_head) {
        if (update_store_ == nullptr || !identity_.has_value() ||
            !sodium_.has_value()) {
            return Status{ErrorCode::unavailable,
                          "signed updates are not enabled"};
        }
        if (namespace_id != update_store_->policy().namespace_id) {
            return Status{ErrorCode::protocol_error,
                          "update-stage namespace differs from update policy"};
        }
        std::scoped_lock maintenance_lock(sync_namespace_mutation_mutex_);
        auto namespace_policy = sync_namespaces_.resolve(namespace_id);
        if (!namespace_policy.ok()) return namespace_policy.status();
        if (namespace_policy.value().engine != sync::Engine::range_v1) {
            return Status{ErrorCode::unsupported,
                          "update-stage requires a range-v1 namespace"};
        }
        auto transaction = sync::SyncNamespaceTransaction::acquire(
            namespace_policy.value());
        if (!transaction.ok()) return transaction.status();
        auto witness = sync_guarded_state_witness(namespace_policy.value());
        if (!witness) return witness.status();
        if (witness.value()) {
            const Status witnessed = witness.value()->verify_read(
                namespace_policy.value(), transaction.value());
            if (!witnessed.ok()) return witnessed;
        }
        sync::AcceptedHeadStore heads(
            namespace_policy.value().root, witness.value());
        auto accepted = heads.load(
            namespace_policy.value(), identity_->public_key(), *sodium_);
        if (!accepted.ok()) return accepted.status();
        if (!accepted.value().has_value() ||
            accepted.value()->record != expected_head) {
            return Status{ErrorCode::protocol_error,
                          "update-stage requires the exact current accepted HEAD"};
        }
        const sync::SyncObjectRecord artifact{
            sync::SyncObjectKind::artifact,
            accepted.value()->artifact,
            accepted.value()->artifact_bytes};
        sync::SyncInstallSeams seams;
        seams.hash_file = sync::hash_sync_file_sha256;
        const Status verified = sync::verify_sync_object(
            namespace_policy.value(), artifact, transaction.value(), seams);
        if (!verified.ok()) return verified;
        return update_store_->stage(
            sync::sync_object_path(namespace_policy.value(), artifact));
    }

    Result<std::vector<std::uint8_t>> render_update_status() const {
        if (update_store_ == nullptr) {
            return local::text_payload("enabled=0\n");
        }
        const update::UpdateStartupResult startup =
            update_store_->startup_result();
        const std::optional<update::UpdateState> state =
            update_store_->snapshot();
        std::ostringstream output;
        output << "enabled=1 namespace="
               << update_store_->policy().namespace_id
               << " target=" << update_store_->policy().target
               << " startup="
               << update::startup_disposition_name(startup.disposition)
               << " health-timeout-ms="
               << update_store_->policy().health_timeout_ms
               << " payload-kind="
               << update::payload_kind_name(
                      update_store_->policy().payload_kind);
        if (update_store_->policy().payload_kind ==
            update::PayloadKind::linux_service_v1) {
            if (update_service_adapter_ == nullptr) {
                output << " service-phase=inactive service-pid=-1"
                          " service-ready=0 service-image-sealed=0";
            } else {
                const update::LinuxServiceSnapshot service =
                    update_service_adapter_->snapshot();
                output << " service-phase="
                       << update::linux_service_phase_name(service.phase)
                       << " service-pid=" << service.process_id
                       << " service-sequence="
                       << service.release_sequence
                       << " service-candidate="
                       << (service.candidate ? 1 : 0)
                       << " service-ready="
                       << (service.phase ==
                                   update::LinuxServicePhase::ready
                               ? 1
                               : 0)
                       << " service-image-sealed="
                       << (service.image_sealed ? 1 : 0);
            }
        }
        if (!state.has_value()) {
            output << " phase=empty generation=0 rollback-count=0\n";
        } else {
            output << " phase=" << update::update_phase_name(state->phase)
                   << " generation=" << state->generation
                   << " rollback-count=" << state->rollback_count
                   << " confirmed-sequence=" << state->confirmed.sequence
                   << " candidate-sequence=" << state->candidate.sequence
                   << " applied-incarnation="
                   << state->applied_incarnation
                   << " health-incarnation="
                   << state->health_incarnation
                   << " last-failed-sequence="
                   << state->last_failed_sequence;
            if (state->confirmed.present()) {
                output << " confirmed-version="
                       << std::quoted(state->confirmed.version)
                       << " confirmed-manifest-record="
                       << bytes_hex(state->confirmed.manifest_record);
            }
            if (state->candidate.present()) {
                output << " candidate-version="
                       << std::quoted(state->candidate.version)
                       << " candidate-manifest-record="
                       << bytes_hex(state->candidate.manifest_record);
            }
            output << '\n';
        }
        const std::string rendered = output.str();
        if (rendered.size() > local::kControlMaxPayloadSize) {
            return Status{ErrorCode::resource_exhausted,
                          "signed-update status exceeds local control capacity"};
        }
        return local::text_payload(rendered);
    }

    local::ControlPacket handle_control(
        const local::ControlPacket &request,
        const local::PeerCredentials &) {
        switch (request.operation) {
            case local::ControlOperation::ping:
                if (!request.payload.empty()) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument, "ping payload must be empty"});
                }
                return response_for(request, Status::success(), local::text_payload("pong\n"));

            case local::ControlOperation::inspect:
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument, "inspect payload must be empty"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(local::RuntimeTree::render_snapshot(snapshot())));

            case local::ControlOperation::diagnostics_export: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "diagnostics export payload must be empty"});
                }
                if (diagnostics_recorder_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "diagnostic flight recorder is unavailable"});
                }
                diagnostics::NamespaceHealthExport namespace_health;
                {
                    std::scoped_lock namespace_lock(
                        sync_namespace_mutation_mutex_);
                    for (const sync::NamespacePolicy &policy :
                         sync_namespaces_.list()) {
                        if (policy.engine != sync::Engine::tree_v2) continue;
                        ++namespace_health.total_namespaces;
                        auto health = sync::load_namespace_health(
                            policy, identity_->public_key(), *sodium_);
                        if (!health) {
                            if (health.status().code() == ErrorCode::not_found)
                                ++namespace_health.absent_records;
                            else
                                ++namespace_health.invalid_records;
                            continue;
                        }
                        ++namespace_health.verified_records;
                        switch (health.value().level) {
                            case sync::NamespaceHealthLevel::green:
                                ++namespace_health.green_namespaces;
                                break;
                            case sync::NamespaceHealthLevel::yellow:
                                ++namespace_health.yellow_namespaces;
                                break;
                            case sync::NamespaceHealthLevel::red:
                                ++namespace_health.red_namespaces;
                                break;
                        }
                        const auto &observed = health.value().observation;
                        if (!sync::namespace_health_policy_current(
                                policy, health.value(), *sodium_)) {
                            ++namespace_health.stale_policy_namespaces;
                        }
                        if ((observed.flags &
                             sync::kHealthCustodyComplete) != 0U)
                            ++namespace_health.complete_custody_namespaces;
                        else
                            ++namespace_health.partial_custody_namespaces;
                        if (observed.conflicts != 0U)
                            ++namespace_health.conflict_namespaces;
                        namespace_health.missing_objects = saturated_add(
                            namespace_health.missing_objects,
                            observed.missing_objects);
                        namespace_health.missing_bytes = saturated_add(
                            namespace_health.missing_bytes,
                            observed.desired_bytes - observed.verified_bytes);
                        if ((observed.flags &
                             sync::kHealthAutomationStalled) != 0U) {
                            ++namespace_health.automation_stalled_namespaces;
                        }
                        if ((observed.flags &
                             sync::kHealthStorePressure) != 0U)
                            ++namespace_health.store_pressure_namespaces;
                        if ((observed.flags &
                             sync::kHealthSourceExhausted) != 0U) {
                            ++namespace_health.source_exhausted_namespaces;
                        }
                        namespace_health.source_absent_results =
                            saturated_add(
                                namespace_health.source_absent_results,
                                observed.source_absent);
                        namespace_health.source_unavailable_results =
                            saturated_add(
                                namespace_health.source_unavailable_results,
                                observed.source_unavailable);
                        namespace_health.maximum_automation_failure_streak =
                            std::max(
                                namespace_health
                                    .maximum_automation_failure_streak,
                                observed.consecutive_automation_failures);
                    }
                }
                auto host_capabilities = diagnostic_host_capabilities(
                    config_.interactive.delegated_cgroup_root);
                if (!host_capabilities)
                    return response_for(request, host_capabilities.status());
                auto exported = diagnostics_recorder_->redacted_export(
                    diagnostic_observation(
                        diagnostics::EventClass::current_snapshot),
                    diagnostic_write_failures_.load(), namespace_health,
                    host_capabilities.value());
                if (!exported) {
                    return response_for(request, exported.status());
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(std::move(exported).value()));
            }

            case local::ControlOperation::peer_alias_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "peer alias list payload must be empty"});
                }
                if (peer_alias_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "peer alias store is unavailable"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(peer_alias::render_snapshot(
                        peer_alias_store_->snapshot())));
            }

            case local::ControlOperation::peer_alias_set: {
                if (peer_alias_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "peer alias store is unavailable"});
                }
                auto entry = peer_alias::decode_set_request(request.payload);
                if (!entry) return response_for(request, entry.status());
                auto peers = refresh_peers();
                if (!peers) return response_for(request, peers.status());
                const bool present = std::any_of(
                    peers.value().begin(), peers.value().end(),
                    [&entry](const TransportPeer &peer) {
                        return std::equal(
                            peer.public_key.begin(), peer.public_key.end(),
                            entry.value().public_key.begin());
                    });
                if (!present) {
                    return response_for(
                        request,
                        Status{ErrorCode::not_found,
                               "a new alias may bind only a current Tox friend"});
                }
                auto mutation = peer_alias_store_->set(
                    entry.value().name, entry.value().public_key);
                if (!mutation) return response_for(request, mutation.status());
                return response_for(
                    request, Status::success(), local::text_payload(
                        peer_alias::render_mutation(
                            "set", entry.value().name, mutation.value())));
            }

            case local::ControlOperation::peer_alias_rename: {
                if (peer_alias_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "peer alias store is unavailable"});
                }
                auto names = peer_alias::decode_rename_request(request.payload);
                if (!names) return response_for(request, names.status());
                auto mutation = peer_alias_store_->rename(
                    names.value().first, names.value().second);
                if (!mutation) return response_for(request, mutation.status());
                return response_for(
                    request, Status::success(), local::text_payload(
                        peer_alias::render_mutation(
                            "rename", names.value().second,
                            mutation.value())));
            }

            case local::ControlOperation::peer_alias_remove: {
                if (peer_alias_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "peer alias store is unavailable"});
                }
                auto name = peer_alias::decode_name_request(request.payload);
                if (!name) return response_for(request, name.status());
                auto mutation = peer_alias_store_->remove(name.value());
                if (!mutation) return response_for(request, mutation.status());
                return response_for(
                    request, Status::success(), local::text_payload(
                        peer_alias::render_mutation(
                            "remove", name.value(), mutation.value())));
            }

            case local::ControlOperation::peer_alias_resolve: {
                if (peer_alias_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "peer alias store is unavailable"});
                }
                auto name = peer_alias::decode_name_request(request.payload);
                if (!name) return response_for(request, name.status());
                auto key = peer_alias_store_->resolve(name.value());
                if (!key) return response_for(request, key.status());
                return response_for(
                    request, Status::success(),
                    std::vector<std::uint8_t>(key.value().begin(),
                                              key.value().end()));
            }

            case local::ControlOperation::peer_invitation_create: {
                auto create_request =
                    peer_invitation::decode_create_request(request.payload);
                if (!create_request) {
                    return response_for(request, create_request.status());
                }
                const std::string encoded_address = transport_.address_hex();
                auto decoded_address = security::decode_hex_exact(
                    encoded_address, toxcore::abi::kAddressSize,
                    "current Tox address");
                if (!decoded_address) {
                    return response_for(request, decoded_address.status());
                }
                peer_invitation::ToxAddress address{};
                std::copy(decoded_address.value().begin(),
                          decoded_address.value().end(), address.begin());
                auto invitation = peer_invitation::create(
                    create_request.value(), address, unix_time_ms(),
                    *identity_, *sodium_);
                if (!invitation) {
                    return response_for(request, invitation.status());
                }
                return response_for(
                    request, Status::success(),
                    std::vector<std::uint8_t>(
                        invitation.value().begin(),
                        invitation.value().end()));
            }

            case local::ControlOperation::transport_interactive_evidence: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "transport interactive evidence payload must be empty"});
                }
                const TransportTrafficStats traffic =
                    transport_.stats().interactive;
                return response_for(
                    request, Status::success(),
                    local::encode_interactive_transport_evidence({
                        traffic.executed_commands,
                        traffic.total_queue_wait_us}));
            }

            case local::ControlOperation::ratox_client_session_list: {
                if (request.payload.size() != 0U &&
                    request.payload.size() !=
                        local::kTerminalPeerPublicKeyBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "terminal session list requires zero or one peer public key"});
                }
                interactive::RatoxClientSnapshot client;
                std::optional<std::array<
                    std::uint8_t,
                    local::kTerminalPeerPublicKeyBytes>> stable_peer;
                {
                    std::scoped_lock client_lock(ratox_client_mutex_);
                    if (ratox_client_ == nullptr) {
                        return response_for(
                            request,
                            Status{ErrorCode::unsupported,
                                   "Ratox terminal client is disabled"});
                    }
                    client = ratox_client_->snapshot();
                    stable_peer = ratox_controller_peer_public_key_;
                }
                if (!client.peer_present || !stable_peer ||
                    client.state == interactive::RatoxClientState::idle ||
                    client.state == interactive::RatoxClientState::exited ||
                    client.state == interactive::RatoxClientState::failed) {
                    return response_for(
                        request, Status::success(), local::text_payload(""));
                }
                const std::string peer = security::hex(*stable_peer);
                if (!request.payload.empty()) {
                    const std::string selected = security::hex(request.payload);
                    if (selected != peer) {
                        return response_for(
                            request, Status::success(), local::text_payload(""));
                    }
                }
                std::ostringstream output;
                output << "session=" << security::hex(client.session_id)
                       << " peer=" << peer
                       << " principal=" << security::hex(client.principal_id)
                       << " state=" << interactive::to_string(client.state)
                       << " incarnation=" << client.incarnation
                       << " generation=" << client.generation
                       << " next-input=" << client.input.next_sequence
                       << " output-base=" << client.output.base_sequence
                       << " output-next=" << client.output.next_sequence
                       << '\n';
                return response_for(
                    request, Status::success(),
                    local::text_payload(output.str()));
            }

            case local::ControlOperation::ratox_client_session_close: {
                if (request.payload.size() != local::kTerminalSessionIdBytes &&
                    request.payload.size() !=
                        local::kTerminalSessionIdBytes +
                            local::kTerminalPeerPublicKeyBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "terminal close requires a session ID and optional peer public key"});
                }
                interactive::SessionId selected_session{};
                std::copy_n(
                    request.payload.begin(), selected_session.size(),
                    selected_session.begin());
                std::unique_lock authority_lock(
                    ratox_authority_effect_mutex_);
                std::scoped_lock client_lock(ratox_client_mutex_);
                if (ratox_client_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "Ratox terminal client is disabled"});
                }
                const interactive::RatoxClientSnapshot client =
                    ratox_client_->snapshot();
                if (!client.peer_present ||
                    !ratox_controller_peer_public_key_ ||
                    client.session_id != selected_session) {
                    return response_for(
                        request,
                        Status{ErrorCode::not_found,
                               "Ratox terminal session is not retained locally"});
                }
                if (request.payload.size() > selected_session.size()) {
                    const std::span<const std::uint8_t> selected_peer{
                        request.payload.data() +
                            static_cast<std::ptrdiff_t>(selected_session.size()),
                        local::kTerminalPeerPublicKeyBytes};
                    if (!std::equal(
                            selected_peer.begin(), selected_peer.end(),
                            ratox_controller_peer_public_key_->begin())) {
                        return response_for(
                            request,
                            Status{ErrorCode::not_found,
                                   "Ratox terminal session does not belong to that peer"});
                    }
                }
                if (client.state == interactive::RatoxClientState::closing) {
                    return response_for(
                        request, Status::success(),
                        local::text_payload("close=already-closing\n"));
                }
                if (client.state == interactive::RatoxClientState::attached) {
                    const Status closed = ratox_client_->close();
                    if (!closed.ok()) return response_for(request, closed);
                    notify_ratox_service();
                    return response_for(
                        request, Status::success(),
                        local::text_payload("close=queued\n"));
                }
                if (client.state == interactive::RatoxClientState::detached) {
                    auto route = ratox_client_route(client.peer_friend_number);
                    if (!route) return response_for(request, route.status());
                    auto nonce = security::random_nonce_128();
                    if (!nonce) return response_for(request, nonce.status());
                    static_cast<void>(ratox_client_->drain_events());
                    const Status resumed = ratox_client_->begin_resume(
                        route.value(), nonce.value());
                    if (!resumed.ok()) return response_for(request, resumed);
                    ratox_pending_close_session_ = selected_session;
                    notify_ratox_service();
                    return response_for(
                        request, Status::success(),
                        local::text_payload("close=resume-then-close-queued\n"));
                }
                return response_for(
                    request,
                    Status{ErrorCode::unavailable,
                           "Ratox terminal session cannot be closed in its current lifecycle state"});
            }

            case local::ControlOperation::address:
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument, "address payload must be empty"});
                }
                return response_for(
                    request, Status::success(), local::text_payload(snapshot().address + "\n"));

            case local::ControlOperation::route_inventory_show: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "route-inventory-show payload must be empty"});
                }
                if (!route_coordinator_) {
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            "mode=single\nroute-set-configured=0\n"));
                }
                const std::vector<routes::WorkerSessionSnapshot> workers =
                    route_worker_supervisor_ != nullptr
                        ? route_worker_supervisor_->snapshot()
                        : std::vector<routes::WorkerSessionSnapshot>{};
                std::scoped_lock route_lock(route_coordinator_mutex_);
                auto rendered = routes::render_coordinator_snapshot(
                    route_coordinator_->snapshot(), *sodium_);
                if (!rendered) {
                    return response_for(request, rendered.status());
                }
                std::ostringstream output;
                output << rendered.value()
                       << "auxiliary-worker-count=" << workers.size() << '\n';
                for (const routes::WorkerSessionSnapshot &worker : workers) {
                    auto network_class =
                        routes::network_class_from_stack(worker.network);
                    if (!network_class) {
                        return response_for(request, network_class.status());
                    }
                    output << "auxiliary-worker="
                           << security::hex(worker.policy.tox_public_key)
                           << " worker-id=" << worker.worker_id
                           << " network-class="
                           << routes::to_string(network_class.value())
                           << " transport-running="
                           << (worker.transport_running ? 1 : 0)
                           << " application-ready="
                           << (worker.application_ready ? 1 : 0)
                           << " hello-sent="
                           << (worker.hello_sent ? 1 : 0)
                           << " hello-received="
                           << (worker.hello_received ? 1 : 0)
                           << " hello-send-attempts="
                           << worker.hello_send_attempts
                           << " confirmation-sent="
                           << (worker.confirmation_sent ? 1 : 0)
                           << " confirmation-received="
                           << (worker.confirmation_received ? 1 : 0)
                           << " confirmation-send-attempts="
                           << worker.confirmation_send_attempts
                           << " local-binding-sent="
                           << (worker.local_binding_sent ? 1 : 0)
                           << " remote-binding-authenticated="
                           << (worker.remote_binding_authenticated ? 1 : 0)
                           << " online-epoch=" << worker.online_epoch
                           << " range-negotiated="
                           << (worker.range_transfer_negotiated ? 1 : 0)
                           << " content-negotiated="
                           << (worker.content_transfer_negotiated ? 1 : 0)
                           << " sync-frame-events="
                           << worker.sync_frame_events_queued
                           << " sync-frames-received="
                           << worker.sync_frames_received
                           << " sync-frames-rejected="
                           << worker.sync_frames_rejected
                           << " last-failure="
                           << routes::to_string(worker.last_failure) << '\n';
                }
                std::string response = output.str();
                if (response.size() > local::kControlMaxPayloadSize) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "route inventory exceeds local control capacity"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(std::move(response)));
            }

            case local::ControlOperation::sync_namespace_install: {
                if (sync_publisher_ == nullptr ||
                    sync_subscriber_ == nullptr ||
                    config_.sync.policy_store_root.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "synchronization is not enabled"});
                }
                if (request.payload.empty() ||
                    request.payload.size() >
                        sync::kMaximumNamespaceRecordBytes) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-namespace-install requires "
                                        "one bounded canonical record"});
                }
                if (config_.security.witness_sync_guarded_state) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::unavailable,
                            "witnessed namespace creation requires stop, policy commit, per-namespace enrollment, and restart"});
                }
                auto policy = sync::decode_namespace_policy(
                    request.payload);
                if (!policy) {
                    return response_for(request, policy.status());
                }
                std::scoped_lock namespace_lock(
                    sync_namespace_mutation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto installed = sync::install_namespace_policy(
                    config_.sync.policy_store_root, policy.value(),
                    static_cast<std::uint32_t>(::geteuid()));
                if (!installed) {
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync namespace installation failed");
                    if (!reconciled.ok()) {
                        return response_for(request, reconciled);
                    }
                    return response_for(request, installed.status());
                }
                const Status witnessed = commit_sync_policy_mutation(
                    "sync namespace installation committed");
                if (!witnessed.ok())
                    return response_for(request, witnessed);

                bool reload =
                    installed.value().disposition ==
                    sync::NamespaceInstallDisposition::installed;
                if (!reload) {
                    auto live = sync_namespaces_.resolve(policy.value().id);
                    reload = !live || live.value() != policy.value();
                }
                if (reload) {
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync namespace installation committed");
                    if (!reconciled.ok())
                        return response_for(request, reconciled);
                }
                const sync::RegistrySnapshot state =
                    sync_namespaces_.snapshot();
                std::ostringstream output;
                output << "namespace=" << policy.value().id
                       << " decision="
                       << (installed.value().disposition ==
                                   sync::NamespaceInstallDisposition::installed
                               ? "installed"
                               : "duplicate")
                       << " generation=" << state.generation
                       << " namespaces=" << state.namespaces << '\n';
                return response_for(
                    request, Status::success(),
                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_namespace_update: {
                if (sync_publisher_ == nullptr ||
                    sync_subscriber_ == nullptr ||
                    config_.sync.policy_store_root.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "synchronization is not enabled"});
                }
                if (request.payload.empty() ||
                    request.payload.size() >
                        sync::kMaximumNamespaceRecordBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-namespace-update requires one bounded canonical record"});
                }
                auto policy = sync::decode_namespace_policy(
                    request.payload);
                if (!policy) {
                    return response_for(request, policy.status());
                }
                std::scoped_lock namespace_lock(
                    sync_namespace_mutation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                const auto automation =
                    sync_automation_scheduler_.snapshot();
                if (std::any_of(
                        automation.begin(), automation.end(),
                        [&policy](const auto &runtime) {
                            return runtime.namespace_id == policy.value().id &&
                                runtime.mode !=
                                    sync::SyncAutomationMode::disabled;
                        })) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "disable sync automation before updating its namespace"});
                }
                if (sync_publisher_->snapshot().retained_replays != 0U) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::unavailable,
                            "sync namespace mutation requires publisher replay "
                            "state to drain after peer disconnect"});
                }
                const Status ready =
                    sync_subscriber_->namespace_mutation_ready(
                        policy.value().id);
                if (!ready.ok()) return response_for(request, ready);
                auto updated = sync::update_namespace_policy(
                    config_.sync.policy_store_root, policy.value(),
                    static_cast<std::uint32_t>(::geteuid()));
                if (!updated) {
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync namespace update failed");
                    if (!reconciled.ok()) {
                        return response_for(request, reconciled);
                    }
                    return response_for(request, updated.status());
                }
                const Status witnessed = commit_sync_policy_mutation(
                    "sync namespace update committed");
                if (!witnessed.ok())
                    return response_for(request, witnessed);
                bool reload = updated.value().disposition ==
                    sync::NamespaceUpdateDisposition::updated;
                if (!reload) {
                    auto live = sync_namespaces_.resolve(policy.value().id);
                    reload = !live || live.value() != policy.value();
                }
                if (reload) {
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync namespace update committed");
                    if (!reconciled.ok())
                        return response_for(request, reconciled);
                }
                const sync::RegistrySnapshot state =
                    sync_namespaces_.snapshot();
                std::ostringstream output;
                output << "namespace=" << policy.value().id
                       << " decision="
                       << (updated.value().disposition ==
                                   sync::NamespaceUpdateDisposition::updated
                               ? "updated"
                               : "duplicate")
                       << " generation=" << state.generation
                       << " namespaces=" << state.namespaces << '\n';
                return response_for(
                    request, Status::success(),
                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_namespace_remove: {
                if (sync_publisher_ == nullptr ||
                    sync_subscriber_ == nullptr ||
                    config_.sync.policy_store_root.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "synchronization is not enabled"});
                }
                const std::string namespace_id(
                    request.payload.begin(), request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-namespace-remove requires one valid namespace id"});
                }
                if (config_.security.witness_sync_guarded_state) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::unavailable,
                            "witnessed namespace removal requires an explicit stop and re-anchor ceremony"});
                }
                std::scoped_lock namespace_lock(
                    sync_namespace_mutation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                const auto automation =
                    sync_automation_scheduler_.snapshot();
                const auto automated = std::find_if(
                    automation.begin(), automation.end(),
                    [&namespace_id](const auto &runtime) {
                        return runtime.namespace_id == namespace_id &&
                            runtime.mode !=
                                sync::SyncAutomationMode::disabled;
                    });
                if (automated != automation.end()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "disable sync automation before removing its namespace"});
                }
                if (sync_publisher_->snapshot().retained_replays != 0U) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::unavailable,
                            "sync namespace mutation requires publisher replay "
                            "state to drain after peer disconnect"});
                }
                const Status ready =
                    sync_subscriber_->namespace_mutation_ready(namespace_id);
                if (!ready.ok()) return response_for(request, ready);
                auto removed = sync::remove_namespace_policy(
                    config_.sync.policy_store_root, namespace_id,
                    static_cast<std::uint32_t>(::geteuid()));
                if (!removed) {
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync namespace removal failed");
                    if (!reconciled.ok()) {
                        return response_for(request, reconciled);
                    }
                    return response_for(request, removed.status());
                }
                const Status witnessed = commit_sync_policy_mutation(
                    "sync namespace removal committed");
                if (!witnessed.ok())
                    return response_for(request, witnessed);
                bool reload = removed.value().disposition ==
                    sync::NamespaceRemoveDisposition::removed;
                if (!reload) {
                    reload = sync_namespaces_.resolve(namespace_id).ok();
                }
                if (reload) {
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync namespace removal committed");
                    if (!reconciled.ok())
                        return response_for(request, reconciled);
                }
                const sync::RegistrySnapshot state =
                    sync_namespaces_.snapshot();
                std::ostringstream output;
                output << "namespace=" << namespace_id << " decision="
                       << (removed.value().disposition ==
                                   sync::NamespaceRemoveDisposition::removed
                               ? "removed"
                               : "absent")
                       << " generation=" << state.generation
                       << " namespaces=" << state.namespaces << '\n';
                return response_for(
                    request, Status::success(),
                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_namespace_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-namespace-list payload must be empty"});
                }
                if (sync_publisher_ == nullptr ||
                    sync_subscriber_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "synchronization is not enabled"});
                }
                std::ostringstream output;
                const sync::RegistrySnapshot state =
                    sync_namespaces_.snapshot();
                output << "generation=" << state.generation
                       << " namespaces=" << state.namespaces
                       << " activation-enabled="
                       << state.enabled_namespaces << '\n';
                for (const sync::NamespacePolicy &policy :
                     sync_namespaces_.list()) {
                    output << "namespace=" << policy.id
                           << " engine="
                           << sync::engine_name(policy.engine)
                           << " activation="
                           << (policy.activation ==
                                       sync::ActivationMode::disabled
                                   ? "disabled"
                                   : "manual")
                           << " writers=" << policy.writers.size()
                           << " subscribers="
                           << policy.subscribers.size()
                           << " maximum-artifact-bytes="
                           << policy.quotas.maximum_artifact_bytes
                           << " maximum-manifest-bytes="
                           << policy.quotas.maximum_manifest_bytes;
                    if (policy.engine == sync::Engine::tree_v2) {
                        output << " metadata="
                               << sync::tree_v2_metadata_mode_name(
                                      policy.projection.metadata)
                               << " includes="
                               << policy.projection.includes.size()
                               << " excludes="
                               << policy.projection.excludes.size();
                    }
                    output << '\n';
                }
                const std::string rendered = output.str();
                if (rendered.size() > local::kControlMaxPayloadSize) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "sync namespace projection exceeds local control capacity"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(rendered));
            }

            case local::ControlOperation::sync_repair: {
                if (request.payload.empty() || request.payload.size() > 64U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-repair requires one valid namespace id"});
                }
                if (sync_publisher_ == nullptr || sync_subscriber_ == nullptr) {
                    return response_for(request,
                                        Status{ErrorCode::unavailable,
                                               "synchronization is not enabled"});
                }
                const std::string namespace_id(request.payload.begin(),
                                               request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-repair namespace id is invalid"});
                }
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                auto witness = sync_guarded_state_witness(policy.value());
                if (!witness)
                    return response_for(request, witness.status());
                if (policy.value().engine == sync::Engine::tree_v2) {
                    if (!sodium_) {
                        return response_for(
                            request,
                            Status{
                                ErrorCode::unavailable,
                                "tree-v2 verification requires cryptography"});
                    }
                    auto transaction =
                        sync::SyncNamespaceTransaction::acquire(policy.value());
                    if (!transaction)
                        return response_for(request, transaction.status());
                    auto tree_witness =
                        tree_v2_state_witness(policy.value());
                    if (!tree_witness)
                        return response_for(request, tree_witness.status());
                    auto automations = sync_automation_store_->load(
                        identity_->public_key(), *sodium_);
                    if (!automations)
                        return response_for(request, automations.status());
                    const auto automation = std::find_if(
                        automations.value().begin(), automations.value().end(),
                        [&namespace_id](
                            const sync::SyncAutomationPolicy &candidate) {
                            return candidate.namespace_id == namespace_id;
                        });
                    if (automation != automations.value().end() &&
                        !automation->source_path.empty()) {
                        auto reconciled = reconcile_tree_v2_workspace_cached(
                            policy.value(), automation->source_path,
                            transaction.value(),
                            tree_witness.value());
                        if (!reconciled)
                            return response_for(request, reconciled.status());
                    }
                    sync::TreeV2BranchStore store(
                        policy.value().root, std::nullopt,
                        tree_witness.value());
                    const Status prepared =
                        store.prepare(policy.value(), transaction.value());
                    if (!prepared.ok()) return response_for(request, prepared);
                    auto frontier = store.load_frontier(
                        policy.value(), *sodium_, transaction.value());
                    if (!frontier)
                        return response_for(request, frontier.status());
                    // Content verification must not report success while one
                    // of the signed semantic roots is unreadable. These stores
                    // intentionally validate only: corrupt authority-bearing
                    // bytes remain in place for explicit operator recovery.
                    sync::TreeV2WorkspaceStore workspace_store(
                        policy.value().root);
                    auto workspace = workspace_store.load(
                        policy.value(), identity_->public_key(), *sodium_,
                        &transaction.value());
                    if (!workspace)
                        return response_for(request, workspace.status());
                    sync::TreeV2MaintenanceStore maintenance_store(
                        policy.value().root);
                    auto maintenance = maintenance_store.load(
                        policy.value(), identity_->public_key(), *sodium_,
                        transaction.value());
                    if (!maintenance)
                        return response_for(request, maintenance.status());
                    struct RepairObject {
                        std::uint64_t bytes{0U};
                        bool selected{false};
                    };
                    std::map<sync::Digest, RepairObject> unique_objects;
                    for (const sync::TreeV2Snapshot &snapshot :
                         frontier.value()) {
                        for (const sync::TreeV2Entry &entry :
                             snapshot.manifest.entries) {
                            if (entry.kind != sync::TreeV2EntryKind::file)
                                continue;
                            const auto [found, inserted] =
                                unique_objects.emplace(entry.content,
                                                       RepairObject{
                                                           entry.content_bytes,
                                                           false});
                            if (!inserted &&
                                found->second.bytes != entry.content_bytes) {
                                return response_for(
                                    request,
                                    Status{ErrorCode::protocol_error,
                                           "tree-v2 digest has conflicting "
                                           "signed sizes"});
                            }
                            found->second.selected =
                                found->second.selected ||
                                sync::tree_v2_path_selected(
                                    policy.value(), entry.path, false);
                        }
                    }
                    std::uint64_t object_bytes = 0U;
                    std::uint64_t selected_objects = 0U;
                    for (const auto &[digest, object] : unique_objects) {
                        if (!object.selected) continue;
                        const Status verified =
                            sync::verify_tree_v2_object_file(
                                sync::tree_v2_object_path(policy.value(),
                                                          digest),
                                digest, object.bytes);
                        if (!verified.ok())
                            return response_for(request, verified);
                        if (object_bytes >
                            std::numeric_limits<std::uint64_t>::max() -
                                object.bytes) {
                            return response_for(
                                request,
                                Status{ErrorCode::resource_exhausted,
                                       "tree-v2 verified byte count overflows"});
                        }
                        object_bytes += object.bytes;
                        ++selected_objects;
                    }
                    const bool custody_complete =
                        policy.value().projection.includes.empty() &&
                        policy.value().projection.excludes.empty();
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            "namespace=" + namespace_id +
                            " engine=tree-v2 branches=" +
                            std::to_string(frontier.value().size()) +
                            " metadata=verified rollback-witness=" +
                            (tree_witness.value() ? "1" : "0") +
                            " workspace=" +
                            (workspace.value() ? "present" : "absent") +
                            " maintenance=" +
                            (maintenance.value().mutation == 0U ? "absent"
                                                                : "present") +
                            " custody=" +
                            (custody_complete ? "complete" : "partial") +
                            " manifest-file-objects=" +
                            std::to_string(unique_objects.size()) +
                            " selected-objects=" +
                            std::to_string(selected_objects) +
                            " skipped-objects=" +
                            std::to_string(unique_objects.size() -
                                           selected_objects) +
                            " selected-bytes=" +
                            std::to_string(object_bytes) +
                            " verified=1\n"));
                }
                if (policy.value().engine == sync::Engine::content_v2) {
                    sync::SyncContentMaintenanceSeams content_seams;
                    content_seams.cancel_requested = [this] {
                        return !running_.load() || shutdown_requested_.load();
                    };
                    auto repaired = sync::repair_sync_content_store(policy.value(),
                                                                    content_seams);
                    if (!repaired)
                        return response_for(request, repaired.status());
                    std::ostringstream output;
                    output << "namespace=" << namespace_id << " engine=content-v2"
                           << " inspected=" << repaired.value().inspected_objects
                           << " inspected-bytes="
                           << repaired.value().inspected_bytes
                           << " verified=" << repaired.value().verified_objects
                           << " quarantined="
                           << repaired.value().quarantined_objects
                           << " quarantined-bytes="
                           << repaired.value().quarantined_bytes << '\n';
                    return response_for(request, Status::success(),
                                        local::text_payload(output.str()));
                }
                sync::SyncInstallSeams seams;
                seams.hash_file = sync::hash_sync_file_sha256;
                seams.cancel_requested = [this] {
                    return !running_.load() || shutdown_requested_.load();
                };
                auto repaired =
                    sync::repair_sync_object_store(policy.value(), seams);
                if (!repaired) {
                    return response_for(request, repaired.status());
                }
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " inspected=" << repaired.value().inspected_objects
                       << " inspected-bytes=" << repaired.value().inspected_bytes
                       << " verified=" << repaired.value().verified_objects
                       << " quarantined=" << repaired.value().quarantined_objects
                       << " quarantined-bytes="
                       << repaired.value().quarantined_bytes << '\n';
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_namespace_health: {
                if (request.payload.size() < 2U ||
                    request.payload.size() > 65U || request.payload[0U] > 1U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-health requires cached|refresh and one namespace id"});
                }
                if (!identity_ || !sodium_ || sync_tree_subscriber_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "tree-v2 synchronization health is not enabled"});
                }
                const bool refresh = request.payload[0U] == 1U;
                const std::string namespace_id(request.payload.begin() + 1,
                                               request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-health namespace id is invalid"});
                }
                std::scoped_lock namespace_lock(
                    sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "sync-health currently requires a tree-v2 namespace"});
                }

                Result<sync::NamespaceHealthRecord> health =
                    sync::load_namespace_health(
                        policy.value(), identity_->public_key(), *sodium_);
                if (refresh) {
                    auto transaction = sync::SyncNamespaceTransaction::acquire(
                        policy.value());
                    if (!transaction)
                        return response_for(request, transaction.status());
                    auto tree_witness =
                        tree_v2_state_witness(policy.value());
                    if (!tree_witness)
                        return response_for(request, tree_witness.status());
                    sync::NamespaceHealthObservation observation;
                    observation.observed_unix_ms = unix_time_ms();
                    observation.flags =
                        sync::kHealthPolicyVerified |
                        sync::kHealthMembershipVerified |
                        sync::kHealthFrontierVerified |
                        sync::kHealthMaintenanceVerified;
                    observation.namespace_writers =
                        policy.value().writers.size();
                    observation.subscribers =
                        policy.value().subscribers.size();
                    observation.store_limit_bytes =
                        policy.value().quotas.maximum_store_bytes;
                    if (policy.value().projection.includes.empty() &&
                        policy.value().projection.excludes.empty()) {
                        observation.flags |= sync::kHealthCustodyComplete;
                    }

                    sync::TreeV2BranchStore branches{
                        std::filesystem::path(policy.value().root),
                        std::nullopt, tree_witness.value()};
                    auto frontier = branches.load_frontier(
                        policy.value(), *sodium_, transaction.value());
                    if (!frontier)
                        return response_for(request, frontier.status());
                    observation.frontier_writers = frontier.value().size();
                    sync::TreeV2MaintenanceStore maintenance{
                        std::filesystem::path(policy.value().root),
                        tree_witness.value()};
                    auto maintenance_state = maintenance.load(
                        policy.value(), identity_->public_key(), *sodium_,
                        transaction.value());
                    if (!maintenance_state)
                        return response_for(request,
                                            maintenance_state.status());
                    observation.writer_cutoffs =
                        maintenance_state.value().cutoffs.size();

                    std::optional<sync::TreeV2MergeResult> merged;
                    if (!frontier.value().empty()) {
                        auto result = sync::merge_tree_v2_snapshots(
                            policy.value(), frontier.value(), *sodium_);
                        if (!result)
                            return response_for(request, result.status());
                        observation.conflicts = result.value().conflicts.size();
                        merged = std::move(result).value();
                    }
                    struct HealthObject {
                        std::uint64_t bytes{0U};
                        bool selected{false};
                    };
                    std::map<sync::Digest, HealthObject> objects;
                    std::set<sync::Digest> manifests;
                    for (const sync::TreeV2Snapshot &snapshot :
                         frontier.value()) {
                        auto record_bytes = sync::encode_tree_v2_branch_head(
                            policy.value(), snapshot.head);
                        auto manifest_bytes = sync::encode_tree_v2_manifest(
                            policy.value(), snapshot.manifest);
                        if (!record_bytes || !manifest_bytes) {
                            return response_for(
                                request,
                                record_bytes ? manifest_bytes.status()
                                             : record_bytes.status());
                        }
                        observation.store_bytes = saturated_add(
                            observation.store_bytes,
                            record_bytes.value().size());
                        if (manifests.insert(snapshot.head.manifest).second) {
                            observation.store_bytes = saturated_add(
                                observation.store_bytes,
                                manifest_bytes.value().size());
                        }
                        for (const sync::TreeV2Entry &entry :
                             snapshot.manifest.entries) {
                            if (entry.kind != sync::TreeV2EntryKind::file)
                                continue;
                            const auto [found, inserted] = objects.emplace(
                                entry.content,
                                HealthObject{entry.content_bytes, false});
                            if (!inserted &&
                                found->second.bytes != entry.content_bytes) {
                                return response_for(
                                    request,
                                    Status{ErrorCode::protocol_error,
                                           "sync health found conflicting signed object sizes"});
                            }
                            found->second.selected =
                                found->second.selected ||
                                sync::tree_v2_path_selected(
                                    policy.value(), entry.path, false);
                        }
                    }
                    for (const auto &[digest, object] : objects) {
                        if (!object.selected) continue;
                        ++observation.desired_objects;
                        observation.desired_bytes = saturated_add(
                            observation.desired_bytes, object.bytes);
                        observation.store_bytes = saturated_add(
                            observation.store_bytes, object.bytes);
                        const Status verified =
                            sync::verify_tree_v2_object_file(
                                sync::tree_v2_object_path(policy.value(),
                                                          digest),
                                digest, object.bytes);
                        if (!verified.ok()) continue;
                        ++observation.verified_objects;
                        observation.verified_bytes = saturated_add(
                            observation.verified_bytes, object.bytes);
                    }
                    observation.missing_objects =
                        observation.desired_objects -
                        observation.verified_objects;
                    if (observation.missing_objects == 0U)
                        observation.flags |=
                            sync::kHealthSelectedCoverageComplete;
                    if (observation.store_bytes >
                        observation.store_limit_bytes -
                            observation.store_limit_bytes / 5U) {
                        observation.flags |= sync::kHealthStorePressure;
                    }

                    sync::TreeV2WorkspaceStore workspaces{
                        std::filesystem::path(policy.value().root),
                        tree_witness.value()};
                    auto workspace = workspaces.load(
                        policy.value(), identity_->public_key(), *sodium_,
                        &transaction.value());
                    if (!workspace)
                        return response_for(request, workspace.status());
                    if (workspace.value()) {
                        observation.flags |= sync::kHealthWorkspacePresent;
                        if (workspace.value()->phase ==
                            sync::TreeV2WorkspacePhase::stable) {
                            observation.flags |= sync::kHealthWorkspaceStable;
                        }
                        if (merged) {
                            auto manifest = sync::tree_v2_manifest_digest(
                                policy.value(), merged->manifest, *sodium_);
                            if (!manifest)
                                return response_for(request,
                                                    manifest.status());
                            if (workspace.value()->phase ==
                                    sync::TreeV2WorkspacePhase::stable &&
                                workspace.value()->active_manifest ==
                                    manifest.value()) {
                                observation.flags |=
                                    sync::kHealthWorkspaceCurrent;
                                auto scan = sync::scan_tree_v2_worktree(
                                    policy.value(), workspace.value()->worktree,
                                    merged->manifest,
                                    identity_->public_key(), 1U, nullptr);
                                if (scan && !scan.value().changed) {
                                    observation.flags |=
                                        sync::kHealthWorktreeClean;
                                }
                            }
                        }
                    }

                    const auto runtimes =
                        sync_automation_scheduler_.snapshot();
                    const auto runtime = std::find_if(
                        runtimes.begin(), runtimes.end(),
                        [&namespace_id](const auto &candidate) {
                            return candidate.namespace_id == namespace_id &&
                                   candidate.mode !=
                                       sync::SyncAutomationMode::disabled;
                        });
                    if (runtime != runtimes.end()) {
                        observation.flags |=
                            sync::kHealthAutomationConfigured;
                        observation.consecutive_automation_failures =
                            std::max(
                                runtime->consecutive_periodic_failures,
                                runtime->consecutive_activation_failures);
                        if (observation.consecutive_automation_failures >= 3U)
                            observation.flags |=
                                sync::kHealthAutomationStalled;
                    }
                    const auto pulls = sync_tree_subscriber_->snapshot();
                    const auto pull = std::find_if(
                        pulls.rbegin(), pulls.rend(),
                        [&namespace_id](const auto &candidate) {
                            return candidate.namespace_id == namespace_id;
                        });
                    if (pull != pulls.rend() && pull->sources != 0U) {
                        observation.flags |= sync::kHealthSourceObserved;
                        observation.source_count = pull->sources;
                        observation.source_absent = pull->absent_results;
                        observation.source_unavailable =
                            pull->unavailable_results;
                        if (pull->state == sync::TreeV2PullState::failed &&
                            pull->detail.find(
                                "no registered tree-v2 source offered") !=
                                std::string::npos) {
                            observation.flags |=
                                sync::kHealthSourceExhausted;
                        }
                    }
                    health = sync::commit_namespace_health(
                        policy.value(), std::move(observation), *identity_,
                        *sodium_);
                }
                if (!health) return response_for(request, health.status());
                const auto &record = health.value();
                const auto &observed = record.observation;
                const bool policy_current =
                    sync::namespace_health_policy_current(
                        policy.value(), record, *sodium_);
                std::ostringstream output;
                output
                    << "iotox-sync-health-v1 namespace=" << namespace_id
                    << " observation=" << (refresh ? "fresh" : "cached")
                    << " sequence=" << record.sequence << " level="
                    << sync::namespace_health_level_name(record.level)
                    << " policy-current=" << (policy_current ? 1 : 0)
                    << " engine=" << sync::engine_name(observed.engine)
                    << " custody="
                    << ((observed.flags & sync::kHealthCustodyComplete) != 0U
                            ? "complete"
                            : "partial")
                    << " frontier-writers=" << observed.frontier_writers
                    << " namespace-writers=" << observed.namespace_writers
                    << " subscribers=" << observed.subscribers
                    << " writer-cutoffs=" << observed.writer_cutoffs
                    << " conflicts=" << observed.conflicts
                    << " desired-objects=" << observed.desired_objects
                    << " verified-objects=" << observed.verified_objects
                    << " missing-objects=" << observed.missing_objects
                    << " desired-bytes=" << observed.desired_bytes
                    << " verified-bytes=" << observed.verified_bytes
                    << " accounted-store-bytes=" << observed.store_bytes
                    << " store-limit-bytes=" << observed.store_limit_bytes
                    << " workspace="
                    << ((observed.flags & sync::kHealthWorkspacePresent) != 0U
                            ? ((observed.flags &
                                sync::kHealthWorkspaceStable) != 0U
                                   ? "stable"
                                   : "pending")
                            : "absent")
                    << " converged="
                    << ((observed.flags & sync::kHealthWorkspaceCurrent) != 0U
                            ? 1
                            : 0)
                    << " worktree-clean="
                    << ((observed.flags & sync::kHealthWorktreeClean) != 0U
                            ? 1
                            : 0)
                    << " automation="
                    << ((observed.flags &
                         sync::kHealthAutomationConfigured) != 0U
                            ? ((observed.flags &
                                sync::kHealthAutomationStalled) != 0U
                                   ? "stalled"
                                   : "healthy")
                            : "manual")
                    << " automation-failure-streak="
                    << observed.consecutive_automation_failures
                    << " source-observed="
                    << ((observed.flags & sync::kHealthSourceObserved) != 0U
                            ? 1
                            : 0)
                    << " sources=" << observed.source_count
                    << " source-absent=" << observed.source_absent
                    << " source-unavailable="
                    << observed.source_unavailable << " signed=1"
                    << " rollback-witness=0 backup-certified=0\n";
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_gc: {
                if (request.payload.size() < 2U || request.payload.size() > 65U ||
                    request.payload[0U] > 1U) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "sync-gc requires a mode byte and valid namespace id"});
                }
                if (sync_publisher_ == nullptr || sync_subscriber_ == nullptr ||
                    !identity_.has_value() || !sodium_.has_value()) {
                    return response_for(request,
                                        Status{ErrorCode::unavailable,
                                               "synchronization is not enabled"});
                }
                const std::string namespace_id(request.payload.begin() + 1,
                                               request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(request,
                                        Status{ErrorCode::invalid_argument,
                                               "sync-gc namespace id is invalid"});
                }
                std::scoped_lock maintenance_lock(sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                auto witness = sync_guarded_state_witness(policy.value());
                if (!witness)
                    return response_for(request, witness.status());
                if (policy.value().engine == sync::Engine::tree_v2) {
                    auto transaction =
                        sync::SyncNamespaceTransaction::acquire(policy.value());
                    if (!transaction)
                        return response_for(request, transaction.status());
                    auto tree_witness =
                        tree_v2_state_witness(policy.value());
                    if (!tree_witness)
                        return response_for(request, tree_witness.status());
                    if (request.payload[0U] == 0U) {
                        auto plan = sync::plan_tree_v2_gc(
                            policy.value(), identity_->public_key(), *sodium_,
                            transaction.value(), tree_witness.value());
                        if (!plan)
                            return response_for(request, plan.status());
                        std::ostringstream output;
                        output << "namespace=" << namespace_id
                               << " engine=tree-v2 mode=dry-run"
                               << " reachable=" << plan.value().reachable.size()
                               << " reachable-bytes="
                               << plan.value().reachable_bytes
                               << " candidates="
                               << plan.value().candidates.size()
                               << " candidate-bytes="
                               << plan.value().candidate_bytes
                               << " checkpoint-floors="
                               << plan.value().checkpoint_floors
                               << " pinned-roots="
                               << plan.value().pinned_roots
                               << " custody="
                               << (plan.value().custody_complete
                                       ? "complete"
                                       : "partial")
                               << " manifest-file-objects="
                               << plan.value().manifest_file_objects
                               << " selected-file-objects="
                               << plan.value().selected_file_objects
                               << " skipped-file-objects="
                               << plan.value().skipped_file_objects
                               << " selected-file-bytes="
                               << plan.value().selected_file_bytes
                               << " skipped-file-bytes="
                               << plan.value().skipped_file_bytes
                               << " recoverable=1 purge=disabled\n";
                        return response_for(
                            request, Status::success(),
                            local::text_payload(output.str()));
                    }
                    auto outcome = sync::quarantine_tree_v2_gc(
                        policy.value(), identity_->public_key(), *sodium_,
                        transaction.value(), tree_witness.value());
                    if (!outcome.ok()) {
                        return response_for(
                            request,
                            Status{outcome.status.code(),
                                   outcome.status.message() +
                                       "; moved=" +
                                       std::to_string(outcome.moved) +
                                       " moved-bytes=" +
                                       std::to_string(outcome.moved_bytes)});
                    }
                    std::ostringstream output;
                    output << "namespace=" << namespace_id
                           << " engine=tree-v2 mode=quarantine"
                           << " candidates="
                           << outcome.plan.candidates.size()
                           << " moved=" << outcome.moved
                           << " moved-bytes=" << outcome.moved_bytes
                           << " custody="
                           << (outcome.plan.custody_complete ? "complete"
                                                            : "partial")
                           << " selected-file-objects="
                           << outcome.plan.selected_file_objects
                           << " skipped-file-objects="
                           << outcome.plan.skipped_file_objects
                           << " recoverable=1 purge=disabled\n";
                    return response_for(request, Status::success(),
                                        local::text_payload(output.str()));
                }
                if (policy.value().engine == sync::Engine::content_v2) {
                    if (request.payload[0U] == 0U) {
                        auto plan = sync::plan_sync_content_reachability_from_store(
                            policy.value(), identity_->public_key(), *sodium_,
                            witness.value());
                        if (!plan)
                            return response_for(request, plan.status());
                        std::ostringstream output;
                        output << "namespace=" << namespace_id
                               << " engine=content-v2 mode=dry-run consistent="
                               << (plan.value().consistent() ? 1 : 0)
                               << " traversal-complete="
                               << (plan.value().traversal_complete ? 1 : 0)
                               << " rollback-guard-consistent="
                               << (plan.value().rollback_guard_consistent ? 1 : 0)
                               << " rooted=" << plan.value().rooted.size()
                               << " rooted-bytes=" << plan.value().rooted_bytes
                               << " candidates=" << plan.value().unreferenced.size()
                               << " candidate-bytes="
                               << plan.value().unreferenced_bytes
                               << " purge=disabled\n";
                        return response_for(request, Status::success(),
                                            local::text_payload(output.str()));
                    }
                    sync::SyncContentMaintenanceSeams content_seams;
                    content_seams.cancel_requested = [this] {
                        return !running_.load() || shutdown_requested_.load();
                    };
                    auto outcome = sync::quarantine_unreferenced_sync_content(
                        policy.value(), identity_->public_key(), *sodium_,
                        content_seams, witness.value());
                    if (!outcome.ok()) {
                        std::ostringstream message;
                        message << outcome.status.message()
                                << "; moved=" << outcome.moved.size()
                                << " moved-bytes=" << outcome.moved_bytes
                                << " durable=" << outcome.durable_objects
                                << " durable-bytes=" << outcome.durable_bytes;
                        return response_for(
                            request, Status{outcome.status.code(), message.str()});
                    }
                    const std::size_t candidates =
                        outcome.plan ? outcome.plan->unreferenced.size() : 0U;
                    std::ostringstream output;
                    output << "namespace=" << namespace_id
                           << " engine=content-v2 mode=quarantine"
                           << " candidates=" << candidates
                           << " moved=" << outcome.moved.size()
                           << " moved-bytes=" << outcome.moved_bytes
                           << " durable=" << outcome.durable_objects
                           << " durable-bytes=" << outcome.durable_bytes
                           << " cancelled=" << (outcome.cancelled ? 1 : 0)
                           << " purge=disabled\n";
                    return response_for(request, Status::success(),
                                        local::text_payload(output.str()));
                }
                if (request.payload[0U] == 0U) {
                    auto plan = sync::plan_sync_gc_quarantine(
                        policy.value(), identity_->public_key(), *sodium_,
                        witness.value());
                    if (!plan)
                        return response_for(request, plan.status());
                    std::ostringstream output;
                    output << "namespace=" << namespace_id
                           << " mode=dry-run consistent="
                           << (plan.value().reachability.consistent() ? 1 : 0)
                           << " descriptor-pinned="
                           << (plan.value().descriptor_pinned ? 1 : 0)
                           << " rooted=" << plan.value().reachability.rooted.size()
                           << " rooted-bytes="
                           << plan.value().reachability.rooted_bytes
                           << " candidates=" << plan.value().candidates.size()
                           << " candidate-bytes="
                           << plan.value().reachability.unreferenced_bytes
                           << " purge=disabled\n";
                    return response_for(request, Status::success(),
                                        local::text_payload(output.str()));
                }
                sync::SyncGcSeams seams;
                seams.cancel_requested = [this] {
                    return !running_.load() || shutdown_requested_.load();
                };
                auto outcome = sync::quarantine_unreferenced_sync_objects(
                    policy.value(), identity_->public_key(), *sodium_, seams,
                    witness.value());
                if (!outcome.ok()) {
                    std::ostringstream message;
                    message << outcome.status.message()
                            << "; moved=" << outcome.moved.size()
                            << " moved-bytes=" << outcome.moved_bytes
                            << " durable=" << outcome.durable_objects
                            << " durable-bytes=" << outcome.durable_bytes;
                    return response_for(
                        request, Status{outcome.status.code(), message.str()});
                }
                const std::size_t candidates =
                    outcome.plan ? outcome.plan->candidates.size() : 0U;
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " mode=quarantine candidates=" << candidates
                       << " moved=" << outcome.moved.size()
                       << " moved-bytes=" << outcome.moved_bytes
                       << " durable=" << outcome.durable_objects
                       << " durable-bytes=" << outcome.durable_bytes
                       << " cancelled=" << (outcome.cancelled ? 1 : 0)
                       << " purge=disabled\n";
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_tree_interest:
            case local::ControlOperation::sync_tree_interest_clear: {
                const bool clear =
                    request.operation ==
                    local::ControlOperation::sync_tree_interest_clear;
                std::string namespace_id;
                std::vector<std::string> includes;
                std::vector<std::string> excludes;
                if (clear) {
                    namespace_id.assign(request.payload.begin(),
                                        request.payload.end());
                } else {
                    if (request.payload.size() < 4U) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "sync-interest payload is incomplete"});
                    }
                    const std::size_t namespace_bytes = request.payload[0U];
                    const std::size_t include_count = request.payload[1U];
                    const std::size_t exclude_count = request.payload[2U];
                    if (namespace_bytes == 0U || namespace_bytes > 64U ||
                        include_count >
                            sync::kMaximumTreeV2SelectionRules ||
                        exclude_count >
                            sync::kMaximumTreeV2SelectionRules ||
                        request.payload.size() < 3U + namespace_bytes) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "sync-interest header is invalid"});
                    }
                    namespace_id.assign(
                        request.payload.begin() + 3,
                        request.payload.begin() +
                            static_cast<std::ptrdiff_t>(3U + namespace_bytes));
                    std::size_t offset = 3U + namespace_bytes;
                    const auto decode_rules =
                        [&](std::size_t count,
                            std::vector<std::string> &destination) -> Status {
                        for (std::size_t index = 0U; index < count; ++index) {
                            if (offset > request.payload.size() ||
                                request.payload.size() - offset < 2U) {
                                return Status{
                                    ErrorCode::invalid_argument,
                                    "sync-interest rule is truncated"};
                            }
                            const std::size_t bytes =
                                read_u16(request.payload, offset);
                            offset += 2U;
                            if (bytes == 0U ||
                                bytes > request.payload.size() - offset) {
                                return Status{
                                    ErrorCode::invalid_argument,
                                    "sync-interest rule length is invalid"};
                            }
                            destination.emplace_back(
                                request.payload.begin() +
                                    static_cast<std::ptrdiff_t>(offset),
                                request.payload.begin() +
                                    static_cast<std::ptrdiff_t>(offset + bytes));
                            offset += bytes;
                        }
                        return Status::success();
                    };
                    Status decoded = decode_rules(include_count, includes);
                    if (decoded.ok())
                        decoded = decode_rules(exclude_count, excludes);
                    if (!decoded.ok() || offset != request.payload.size()) {
                        return response_for(
                            request,
                            decoded.ok()
                                ? Status{ErrorCode::invalid_argument,
                                         "sync-interest payload has trailing bytes"}
                                : decoded);
                    }
                }
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-interest namespace is invalid"});
                }
                if (!identity_ || !sodium_ ||
                    sync_tree_subscriber_ == nullptr ||
                    sync_tree_publisher_ == nullptr ||
                    config_.sync.policy_store_root.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync-interest requires enabled sync services"});
                }
                const bool inspect = !clear && includes.empty() &&
                                     excludes.empty();
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "sync-interest requires tree-v2"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                std::string decision = "observed";
                if (!inspect) {
                    const Status ready =
                        sync_tree_subscriber_->namespace_mutation_ready(
                            namespace_id);
                    if (!ready.ok()) return response_for(request, ready);
                    if (sync_tree_publisher_->snapshot().retained_replays !=
                        0U) {
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "sync-interest waits for publisher replay state to drain"});
                    }
                    sync::TreeV2WorkspaceStore workspaces{
                        policy.value().root, tree_witness.value()};
                    auto workspace = workspaces.load(
                        policy.value(), identity_->public_key(), *sodium_,
                        &transaction.value());
                    if (!workspace)
                        return response_for(request, workspace.status());
                    if (workspace.value() &&
                        workspace.value()->phase !=
                            sync::TreeV2WorkspacePhase::stable) {
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "sync-interest refuses a pending worktree exchange"});
                    }
                    policy.value().projection.includes = std::move(includes);
                    policy.value().projection.excludes = std::move(excludes);
                    const Status valid =
                        sync::validate_namespace_policy(policy.value());
                    if (!valid.ok()) return response_for(request, valid);
                    auto updated = sync::update_namespace_policy(
                        config_.sync.policy_store_root, policy.value(),
                        static_cast<std::uint32_t>(::geteuid()));
                    if (!updated) {
                        const Status reconciled =
                            reconcile_sync_namespace_registry(
                                "sync-interest update failed");
                        if (!reconciled.ok())
                            return response_for(request, reconciled);
                        return response_for(request, updated.status());
                    }
                    const Status witnessed = commit_sync_policy_mutation(
                        "sync-interest update committed");
                    if (!witnessed.ok())
                        return response_for(request, witnessed);
                    decision =
                        updated.value().disposition ==
                                sync::NamespaceUpdateDisposition::updated
                            ? "updated"
                            : "duplicate";
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync-interest update committed");
                    if (!reconciled.ok())
                        return response_for(request, reconciled);
                    policy = sync_namespaces_.resolve(namespace_id);
                    if (!policy)
                        return response_for(request, policy.status());
                }
                bool projection_current = false;
                sync::TreeV2WorkspaceStore workspaces{
                    policy.value().root, tree_witness.value()};
                auto workspace = workspaces.load(
                    policy.value(), identity_->public_key(), *sodium_,
                    &transaction.value());
                if (!workspace)
                    return response_for(request, workspace.status());
                if (workspace.value() &&
                    workspace.value()->phase ==
                        sync::TreeV2WorkspacePhase::stable) {
                    auto manifest = sync::load_tree_v2_stored_manifest(
                        policy.value(), workspace.value()->active_manifest,
                        *sodium_, transaction.value());
                    projection_current =
                        manifest && sync::tree_v2_projection_marker_matches(
                                        policy.value(), manifest.value(),
                                        workspace.value()->worktree, *sodium_);
                }
                const bool custody_complete =
                    policy.value().projection.includes.empty() &&
                    policy.value().projection.excludes.empty();
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " engine=tree-v2 decision=" << decision
                       << " custody-intent="
                       << (custody_complete ? "complete" : "partial")
                       << " projection-current="
                       << (projection_current ? 1 : 0)
                       << " includes="
                       << policy.value().projection.includes.size()
                       << " excludes="
                       << policy.value().projection.excludes.size()
                       << " remote-path-authority=none\n";
                const auto render_rules = [&output](std::string_view kind,
                                                    const auto &rules) {
                    for (const std::string &rule : rules) {
                        output << kind << "-hex="
                               << bytes_hex(std::span<const std::uint8_t>{
                                      reinterpret_cast<const std::uint8_t *>(
                                          rule.data()),
                                      rule.size()})
                               << '\n';
                    }
                };
                render_rules("include", policy.value().projection.includes);
                render_rules("exclude", policy.value().projection.excludes);
                const std::string rendered = output.str();
                if (rendered.size() > local::kControlMaxPayloadSize) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "sync-interest response exceeds local control capacity"});
                }
                return response_for(request, Status::success(),
                                    local::text_payload(rendered));
            }

            case local::ControlOperation::sync_tree_checkpoint: {
                const std::string namespace_id(request.payload.begin(),
                                               request.payload.end());
                if (!sync::valid_namespace_id(namespace_id) || !identity_ ||
                    !sodium_ || sync_automation_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-checkpoint requires one valid tree-v2 namespace"});
                }
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_, sync_automation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request, Status{ErrorCode::unsupported,
                                        "sync-checkpoint requires tree-v2"});
                }
                auto automations = live_sync_automation_policies();
                if (!automations)
                    return response_for(request, automations.status());
                const auto automation = std::find_if(
                    automations.value().begin(), automations.value().end(),
                    [&namespace_id](const auto &candidate) {
                        return candidate.namespace_id == namespace_id &&
                               (candidate.mode ==
                                    sync::SyncAutomationMode::writable ||
                                candidate.mode ==
                                    sync::SyncAutomationMode::bidirectional);
                    });
                if (automation == automations.value().end()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync-checkpoint requires writable automation"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                auto checkpointed = sync::checkpoint_tree_v2_workspace(
                    policy.value(), automation->source_path, *identity_,
                    *sodium_, transaction.value(), tree_witness.value());
                if (!checkpointed)
                    return response_for(request, checkpointed.status());
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id +
                        " engine=tree-v2 checkpoint=1 generation=" +
                        std::to_string(checkpointed.value()
                                           .checkpoint.snapshot.head.generation) +
                        " record=" +
                        bytes_hex(checkpointed.value().checkpoint.record) +
                        " conflicts=0 graph-floor=1\n"));
            }

            case local::ControlOperation::sync_tree_pin:
            case local::ControlOperation::sync_tree_unpin: {
                if (request.payload.size() < 34U ||
                    request.payload.size() > 97U || !identity_ || !sodium_) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync pin request is malformed"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() != 1U + namespace_bytes + 32U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync pin namespace encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(1U + namespace_bytes));
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync pin namespace id is invalid"});
                }
                sync::Digest record{};
                std::copy_n(request.payload.begin() +
                                static_cast<std::ptrdiff_t>(1U + namespace_bytes),
                            record.size(), record.begin());
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request, Status{ErrorCode::unsupported,
                                        "sync pins require tree-v2"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                sync::TreeV2MaintenanceStore maintenance(
                    policy.value().root, tree_witness.value());
                auto state =
                    request.operation ==
                            local::ControlOperation::sync_tree_pin
                        ? maintenance.pin(policy.value(), record, *identity_,
                                          *sodium_, transaction.value())
                        : maintenance.unpin(policy.value(), record, *identity_,
                                            *sodium_, transaction.value());
                if (!state) return response_for(request, state.status());
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id + " decision=" +
                        (request.operation ==
                                 local::ControlOperation::sync_tree_pin
                             ? "pinned"
                             : "unpinned") +
                        " pins=" + std::to_string(state.value().pins.size()) +
                        " mutation=" +
                        std::to_string(state.value().mutation) + "\n"));
            }

            case local::ControlOperation::sync_tree_maintenance_show:
            case local::ControlOperation::sync_tree_restore: {
                const std::string namespace_id(request.payload.begin(),
                                               request.payload.end());
                if (!sync::valid_namespace_id(namespace_id) || !identity_ ||
                    !sodium_) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync maintenance namespace is invalid"});
                }
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request, Status{ErrorCode::unsupported,
                                        "sync maintenance requires tree-v2"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                if (request.operation ==
                    local::ControlOperation::sync_tree_restore) {
                    auto restored = sync::restore_tree_v2_quarantine(
                        policy.value(), *sodium_, transaction.value(),
                        tree_witness.value());
                    if (!restored.ok())
                        return response_for(request, restored.status);
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            "namespace=" + namespace_id +
                            " engine=tree-v2 restored=" +
                            std::to_string(restored.restored) +
                            " restored-bytes=" +
                            std::to_string(restored.restored_bytes) +
                            " already-present=" +
                            std::to_string(restored.already_present) + "\n"));
                }
                sync::TreeV2MaintenanceStore maintenance(
                    policy.value().root, tree_witness.value());
                auto state = maintenance.load(
                    policy.value(), identity_->public_key(), *sodium_,
                    transaction.value());
                if (!state) return response_for(request, state.status());
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " mutation=" << state.value().mutation
                       << " pins=" << state.value().pins.size()
                       << " cutoffs=" << state.value().cutoffs.size() << '\n';
                for (const sync::Digest &pin : state.value().pins)
                    output << "pin=" << bytes_hex(pin) << '\n';
                for (const sync::TreeV2WriterCutoff &cutoff :
                     state.value().cutoffs) {
                    output << "cutoff-writer=" << bytes_hex(cutoff.writer)
                           << " generation=" << cutoff.generation
                           << " record=" << bytes_hex(cutoff.record) << '\n';
                }
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_tree_history: {
                if (request.payload.size() < 3U ||
                    request.payload.size() > 66U || !identity_ || !sodium_) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-history request is malformed"});
                }
                const std::uint16_t limit = read_u16(request.payload, 0U);
                const std::string namespace_id(request.payload.begin() + 2,
                                               request.payload.end());
                if (limit == 0U || limit > 128U ||
                    !sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-history requires a valid namespace and limit 1..128"});
                }
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request, Status{ErrorCode::unsupported,
                                        "sync-history requires tree-v2"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                if (tree_witness.value()) {
                    const Status fresh = tree_witness.value()->verify_read(
                        policy.value(), transaction.value());
                    if (!fresh.ok()) return response_for(request, fresh);
                }
                auto history = sync::list_tree_v2_history(
                    policy.value(), identity_->public_key(), *sodium_,
                    transaction.value());
                if (!history) return response_for(request, history.status());
                const std::size_t shown =
                    std::min<std::size_t>(limit, history.value().size());
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " engine=tree-v2 retained=" << history.value().size()
                       << " shown=" << shown
                       << " omitted=" << (history.value().size() - shown)
                       << " order=writer-generation-desc quarantined=excluded"
                       << " backup=0\n";
                for (std::size_t index = 0U; index < shown; ++index) {
                    const sync::TreeV2Revision &revision =
                        history.value()[index];
                    output << "record=" << bytes_hex(revision.record)
                           << " writer=" << bytes_hex(revision.writer)
                           << " generation=" << revision.generation
                           << " previous=" << bytes_hex(revision.previous)
                           << " manifest=" << bytes_hex(revision.manifest)
                           << " paths=" << revision.paths
                           << " files=" << revision.files
                           << " conflicts=" << revision.conflicts
                           << " checkpoint=" << (revision.checkpoint ? 1 : 0)
                           << " current=" << (revision.current ? 1 : 0)
                           << " pinned=" << (revision.pinned ? 1 : 0) << '\n';
                }
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_tree_diff: {
                if (request.payload.size() < 66U ||
                    request.payload.size() > 129U || !sodium_) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-diff request is malformed"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() != 1U + namespace_bytes + 64U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-diff namespace encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() + static_cast<std::ptrdiff_t>(
                                                    1U + namespace_bytes));
                sync::Digest from{};
                sync::Digest to{};
                std::copy_n(request.payload.begin() + static_cast<std::ptrdiff_t>(
                                                        1U + namespace_bytes),
                            from.size(), from.begin());
                std::copy_n(request.payload.end() -
                                static_cast<std::ptrdiff_t>(to.size()),
                            to.size(), to.begin());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-diff namespace is invalid"});
                }
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request, Status{ErrorCode::unsupported,
                                        "sync-diff requires tree-v2"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                if (tree_witness.value()) {
                    const Status fresh = tree_witness.value()->verify_read(
                        policy.value(), transaction.value());
                    if (!fresh.ok()) return response_for(request, fresh);
                }
                auto diff = sync::diff_tree_v2_records(
                    policy.value(), from, to, *sodium_, transaction.value());
                if (!diff) return response_for(request, diff.status());
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " engine=tree-v2 from=" << bytes_hex(from)
                       << " to=" << bytes_hex(to)
                       << " from-manifest=" << bytes_hex(diff.value().from_manifest)
                       << " to-manifest=" << bytes_hex(diff.value().to_manifest)
                       << " changes=" << diff.value().entries.size()
                       << " added=" << diff.value().added
                       << " removed=" << diff.value().removed
                       << " modified=" << diff.value().modified
                       << " projected-content-changes="
                       << diff.value().projected_content_changes
                       << " from-conflicts=" << diff.value().from_conflicts
                       << " to-conflicts=" << diff.value().to_conflicts << '\n';
                std::size_t shown = 0U;
                constexpr std::size_t soft_limit = 56U * 1024U;
                for (const sync::TreeV2DiffEntry &entry : diff.value().entries) {
                    std::ostringstream line;
                    line << "path-hex=" << path_hex(entry.path)
                         << " change=" << sync::tree_v2_diff_kind_name(entry.kind)
                         << " from-candidates=" << entry.from_candidates
                         << " to-candidates=" << entry.to_candidates
                         << " projected-content-changed="
                         << (entry.projected_content_changed ? 1 : 0) << '\n';
                    const std::string rendered = line.str();
                    if (output.str().size() + rendered.size() > soft_limit)
                        break;
                    output << rendered;
                    ++shown;
                }
                output << "shown=" << shown
                       << " omitted=" << (diff.value().entries.size() - shown)
                       << '\n';
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_tree_conflicts: {
                if (request.payload.size() < 2U ||
                    request.payload.size() > 97U || !sodium_) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-conflicts request is malformed"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    (request.payload.size() != 1U + namespace_bytes &&
                     request.payload.size() != 1U + namespace_bytes + 32U)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-conflicts namespace encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() + static_cast<std::ptrdiff_t>(
                                                    1U + namespace_bytes));
                std::optional<sync::Digest> record;
                if (request.payload.size() == 1U + namespace_bytes + 32U) {
                    record.emplace();
                    std::copy_n(request.payload.end() - 32, 32U,
                                record->begin());
                }
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-conflicts namespace is invalid"});
                }
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "sync-conflicts requires tree-v2"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                if (tree_witness.value()) {
                    const Status fresh = tree_witness.value()->verify_read(
                        policy.value(), transaction.value());
                    if (!fresh.ok()) return response_for(request, fresh);
                }
                auto conflicts = sync::tree_v2_conflicts(
                    policy.value(), record, *sodium_, transaction.value());
                if (!conflicts)
                    return response_for(request, conflicts.status());
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " engine=tree-v2 scope="
                       << (record ? bytes_hex(*record) : "current")
                       << " conflicts=" << conflicts.value().size() << '\n';
                std::size_t shown = 0U;
                constexpr std::size_t soft_limit = 56U * 1024U;
                for (const sync::TreeV2Conflict &conflict : conflicts.value()) {
                    std::ostringstream block;
                    block << "path-hex=" << path_hex(conflict.path)
                          << " candidates=" << conflict.candidates.size() << '\n';
                    for (const sync::TreeV2Entry &candidate :
                         conflict.candidates) {
                        block << " candidate-writer="
                              << bytes_hex(candidate.origin.writer)
                              << " generation=" << candidate.origin.generation
                              << " kind="
                              << sync::tree_v2_entry_kind_name(candidate.kind)
                              << " content=" << bytes_hex(candidate.content)
                              << " bytes=" << candidate.content_bytes
                              << " executable="
                              << (candidate.executable ? 1 : 0)
                              << " owner-mode="
                              << static_cast<unsigned int>(candidate.owner_mode)
                              << '\n';
                    }
                    const std::string rendered = block.str();
                    if (output.str().size() + rendered.size() > soft_limit)
                        break;
                    output << rendered;
                    ++shown;
                }
                output << "shown=" << shown
                       << " omitted=" << (conflicts.value().size() - shown)
                       << '\n';
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_tree_restore_plan:
            case local::ControlOperation::sync_tree_restore_forward: {
                if (request.payload.size() < 34U ||
                    request.payload.size() > 129U || !identity_ || !sodium_ ||
                    sync_automation_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync forward restore request is malformed"});
                }
                const bool apply =
                    request.operation ==
                    local::ControlOperation::sync_tree_restore_forward;
                const std::size_t namespace_bytes = request.payload[0U];
                const std::size_t tail_bytes = apply ? 64U : 32U;
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() !=
                        1U + namespace_bytes + tail_bytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync forward restore namespace encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() + static_cast<std::ptrdiff_t>(
                                                    1U + namespace_bytes));
                sync::Digest target{};
                std::copy_n(request.payload.begin() + static_cast<std::ptrdiff_t>(
                                                        1U + namespace_bytes),
                            target.size(), target.begin());
                sync::Digest expected_plan{};
                if (apply) {
                    std::copy_n(request.payload.end() - 32, 32U,
                                expected_plan.begin());
                }
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync forward restore namespace is invalid"});
                }
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_, sync_automation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "sync forward restore requires tree-v2"});
                }
                auto automations = live_sync_automation_policies();
                if (!automations)
                    return response_for(request, automations.status());
                const auto automation = std::find_if(
                    automations.value().begin(), automations.value().end(),
                    [&namespace_id](const auto &candidate) {
                        return candidate.namespace_id == namespace_id &&
                               (candidate.mode ==
                                    sync::SyncAutomationMode::writable ||
                                candidate.mode ==
                                    sync::SyncAutomationMode::bidirectional);
                    });
                if (automation == automations.value().end()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync forward restore requires writable automation"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                if (!apply) {
                    auto plan = sync::plan_tree_v2_restore_forward(
                        policy.value(), target, automation->source_path,
                        *identity_, *sodium_, transaction.value(),
                        tree_witness.value());
                    if (!plan) return response_for(request, plan.status());
                    return response_for(
                        request, Status::success(),
                        local::text_payload(render_tree_v2_restore_plan(
                            namespace_id, plan.value())));
                }
                auto restored = sync::restore_tree_v2_forward(
                    policy.value(), target, expected_plan,
                    automation->source_path, *identity_, *sodium_,
                    transaction.value(), tree_witness.value());
                if (!restored)
                    return response_for(request, restored.status());
                std::ostringstream output;
                output << render_tree_v2_restore_plan(
                              namespace_id, restored.value().plan)
                       << "applied=1 record="
                       << bytes_hex(restored.value().publication.record)
                       << " generation="
                       << restored.value().publication.snapshot.head.generation
                       << " previous="
                       << bytes_hex(restored.value()
                                        .publication.snapshot.head.previous)
                       << " worktree-exchanged="
                       << (restored.value().reconciliation.workspace_exchanged
                               ? 1
                               : 0)
                       << " rollback=0\n";
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_tree_writer_cutoff: {
                if (request.payload.size() < 34U ||
                    request.payload.size() > 97U || !identity_ || !sodium_ ||
                    sync_automation_store_ == nullptr) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync writer cutoff is malformed"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() != 1U + namespace_bytes + 32U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync writer cutoff encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(1U + namespace_bytes));
                sync::PrincipalId target{};
                std::copy_n(request.payload.begin() +
                                static_cast<std::ptrdiff_t>(1U + namespace_bytes),
                            target.size(), target.begin());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync writer cutoff namespace is invalid"});
                }
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_, sync_automation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request, Status{ErrorCode::unsupported,
                                        "sync writer cutoff requires tree-v2"});
                }
                auto automations = live_sync_automation_policies();
                if (!automations)
                    return response_for(request, automations.status());
                const auto automation = std::find_if(
                    automations.value().begin(), automations.value().end(),
                    [&namespace_id](const auto &candidate) {
                        return candidate.namespace_id == namespace_id &&
                               (candidate.mode ==
                                    sync::SyncAutomationMode::writable ||
                                candidate.mode ==
                                    sync::SyncAutomationMode::bidirectional);
                    });
                if (automation == automations.value().end()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync writer cutoff requires writable automation"});
                }
                auto transaction =
                    sync::SyncNamespaceTransaction::acquire(policy.value());
                if (!transaction)
                    return response_for(request, transaction.status());
                auto tree_witness = tree_v2_state_witness(policy.value());
                if (!tree_witness)
                    return response_for(request, tree_witness.status());
                sync::TreeV2MaintenanceStore maintenance(
                    policy.value().root, tree_witness.value());
                auto maintenance_state = maintenance.load(
                    policy.value(), identity_->public_key(), *sodium_,
                    transaction.value());
                if (!maintenance_state)
                    return response_for(request, maintenance_state.status());
                const bool already_cutoff = std::any_of(
                    maintenance_state.value().cutoffs.begin(),
                    maintenance_state.value().cutoffs.end(),
                    [&target](const sync::TreeV2WriterCutoff &cutoff) {
                        return cutoff.writer == target;
                    });
                if (!already_cutoff) {
                    auto checkpointed = sync::checkpoint_tree_v2_workspace(
                        policy.value(), automation->source_path, *identity_,
                        *sodium_, transaction.value(), tree_witness.value());
                    if (!checkpointed)
                        return response_for(request, checkpointed.status());
                }
                auto cutoff = sync::cutoff_tree_v2_writer(
                    policy.value(), target, *identity_, *sodium_,
                    transaction.value(), tree_witness.value());
                if (!cutoff) return response_for(request, cutoff.status());

                sync::SyncAutomationSpec next =
                    static_cast<const sync::SyncAutomationSpec &>(*automation);
                next.source_principals.erase(
                    std::remove(next.source_principals.begin(),
                                next.source_principals.end(), target),
                    next.source_principals.end());
                if (next.mode == sync::SyncAutomationMode::bidirectional &&
                    next.source_principals.empty())
                    next.mode = sync::SyncAutomationMode::writable;
                auto stored =
                    sync_automation_store_->put(next, *identity_, *sodium_);
                if (!stored) {
                    return response_for(
                        request,
                        Status{stored.status().code(),
                               "writer cutoff is durable; automation update "
                               "failed: " +
                                   stored.status().message()});
                }
                const Status witnessed = commit_sync_policy_mutation(
                    "writer-cutoff automation update committed");
                if (!witnessed.ok())
                    return response_for(request, witnessed);
                const Status reloaded = reload_sync_automation();
                if (!reloaded.ok()) return response_for(request, reloaded);
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id + " cutoff-writer=" +
                        bytes_hex(cutoff.value().writer) + " generation=" +
                        std::to_string(cutoff.value().generation) +
                        " record=" + bytes_hex(cutoff.value().record) +
                        " branch-retired=1 terminal=1\n"));
            }

            case local::ControlOperation::sync_cancel: {
                if (request.payload.size() != 8U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-cancel requires one 64-bit job id"});
                }
                if (sync_subscriber_ == nullptr) {
                    return response_for(request,
                                        Status{ErrorCode::unavailable,
                                               "synchronization is not enabled"});
                }
                const std::uint64_t job_id = read_u64(request.payload);
                if (job_id == 0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync pull job identifier zero is reserved"});
                }
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                const auto content_pulls =
                    sync_content_subscriber_ != nullptr
                        ? sync_content_subscriber_->snapshot()
                        : std::vector<sync::SyncContentPullSnapshot>{};
                const bool content_job = std::any_of(
                    content_pulls.begin(), content_pulls.end(),
                    [job_id](const sync::SyncContentPullSnapshot &pull) {
                        return pull.job_id == job_id;
                    });
                const auto tree_pulls =
                    sync_tree_subscriber_ != nullptr
                        ? sync_tree_subscriber_->snapshot()
                        : std::vector<sync::TreeV2PullSnapshot>{};
                const bool tree_job =
                    std::any_of(tree_pulls.begin(), tree_pulls.end(),
                                [job_id](const sync::TreeV2PullSnapshot &pull) {
                                    return pull.job_id == job_id;
                                });
                const auto range_pulls = sync_subscriber_->snapshot();
                const bool range_job =
                    std::any_of(range_pulls.begin(), range_pulls.end(),
                                [job_id](const sync::SyncPullSnapshot &pull) {
                                    return pull.job_id == job_id;
                                });
                if (static_cast<unsigned int>(content_job) +
                        static_cast<unsigned int>(tree_job) +
                        static_cast<unsigned int>(range_job) >
                    1U) {
                    return response_for(
                        request, Status{ErrorCode::protocol_error,
                                        "sync job identifier aliases two engines"});
                }
                const Status cancelled =
                    content_job ? sync_content_subscriber_->cancel_pull(job_id)
                    : tree_job  ? sync_tree_subscriber_->cancel_pull(job_id)
                                : sync_subscriber_->cancel_pull(job_id);
                if (!cancelled.ok()) {
                    return response_for(request, cancelled);
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "sync-cancelled job=" + std::to_string(job_id) + "\n"));
            }

            case local::ControlOperation::sync_content_source_add: {
                if (request.payload.size() != 12U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-source-add requires job id u64 and friend u32"});
                }
                const std::uint64_t job_id = read_u64(request.payload);
                const std::uint32_t friend_number = read_u32(
                    std::span<const std::uint8_t>{request.payload}.subspan(8U));
                if (job_id == 0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync pull job identifier zero is reserved"});
                }
                const auto content_pulls =
                    sync_content_subscriber_ != nullptr
                        ? sync_content_subscriber_->snapshot()
                        : std::vector<sync::SyncContentPullSnapshot>{};
                const bool content_job = std::any_of(
                    content_pulls.begin(), content_pulls.end(),
                    [job_id](const auto &pull) {
                        return pull.job_id == job_id;
                    });
                const auto tree_pulls =
                    sync_tree_subscriber_ != nullptr
                        ? sync_tree_subscriber_->snapshot()
                        : std::vector<sync::TreeV2PullSnapshot>{};
                const bool tree_job = std::any_of(
                    tree_pulls.begin(), tree_pulls.end(),
                    [job_id](const auto &pull) {
                        return pull.job_id == job_id;
                    });
                if (content_job == tree_job) {
                    return response_for(
                        request,
                        Status{content_job ? ErrorCode::protocol_error
                                           : ErrorCode::not_found,
                               content_job
                                   ? "sync source job aliases two engines"
                                   : "sync source job is absent"});
                }
                auto session = sessions_.get(friend_number);
                if (!session ||
                    !protocol::is_application_ready(session.value()) ||
                    (session.value().negotiated.shared_features &
                     protocol::feature_bit(
                         tree_job
                             ? protocol::Feature::state_sync_tree_v2
                             : protocol::Feature::state_sync_content_v2)) ==
                        0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               tree_job
                                   ? "source peer has not negotiated state-sync-tree-v2"
                                   : "source peer has not negotiated state-sync-content-v2"});
                }
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                auto context =
                    sync_peer_context_locked(friend_number, session.value());
                if (!context)
                    return response_for(request, context.status());
                if (tree_job) {
                    const Status added = sync_tree_subscriber_->add_source(
                        job_id, context.value());
                    if (!added.ok()) return response_for(request, added);
                    std::uint32_t sources = 0U;
                    for (const sync::TreeV2PullSnapshot &pull :
                         sync_tree_subscriber_->snapshot()) {
                        if (pull.job_id == job_id) {
                            sources = pull.sources;
                            break;
                        }
                    }
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            "sync-source-added job=" +
                            std::to_string(job_id) + " friend=" +
                            std::to_string(friend_number) + " sources=" +
                            std::to_string(sources) +
                            " frames=0 engine=tree-v2 frontier=frozen "
                            "carrier=primary\n"));
                }
                auto frames = sync_content_subscriber_->add_source(
                    job_id, context.value());
                if (!frames)
                    return response_for(request, frames.status());
                for (const sync::SyncContentDispatch &frame : frames.value()) {
                    const Status queued =
                        send_sync_frame(frame.context, frame.frame);
                    if (!queued.ok())
                        return response_for(request, queued);
                }
                std::uint32_t sources = 0U;
                for (const sync::SyncContentPullSnapshot &pull :
                     sync_content_subscriber_->snapshot()) {
                    if (pull.job_id == job_id) {
                        sources = pull.sources;
                        break;
                    }
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "sync-source-added job=" + std::to_string(job_id) +
                        " friend=" + std::to_string(friend_number) +
                        " sources=" + std::to_string(sources) +
                        " frames=" +
                        std::to_string(frames.value().size()) +
                        " engine=content-v2 head=frozen carrier=primary\n"));
            }

            case local::ControlOperation::sync_content_pull_multi:
            case local::ControlOperation::sync_content_pull_multi_route: {
                constexpr std::uint8_t maximum_auxiliary_sources = 15U;
                const bool routed = request.operation ==
                    local::ControlOperation::sync_content_pull_multi_route;
                const std::size_t prefix_bytes = routed ? 2U : 1U;
                if (request.payload.size() < prefix_bytes + 9U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-pull-multi requires source count, "
                                        "friend numbers, and namespace id"});
                }
                sync::SyncRouteClassConstraint route_class =
                    sync::SyncRouteClassConstraint::any;
                if (routed) {
                    const std::uint8_t encoded = request.payload[0U];
                    if (encoded < static_cast<std::uint8_t>(
                                      sync::SyncRouteClassConstraint::
                                          tox_native) ||
                        encoded > static_cast<std::uint8_t>(
                                      sync::SyncRouteClassConstraint::
                                          tox_i2p)) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "sync-pull-multi-route requires a named route class"});
                    }
                    route_class =
                        static_cast<sync::SyncRouteClassConstraint>(encoded);
                }
                const std::uint8_t auxiliary_count =
                    request.payload[routed ? 1U : 0U];
                if (auxiliary_count == 0U ||
                    auxiliary_count > maximum_auxiliary_sources) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-pull-multi auxiliary source count "
                                        "is invalid"});
                }
                const std::size_t friend_bytes =
                    4U * (static_cast<std::size_t>(auxiliary_count) + 1U);
                const std::size_t namespace_offset =
                    prefix_bytes + friend_bytes;
                if (request.payload.size() < namespace_offset + 1U ||
                    request.payload.size() > namespace_offset + 64U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-pull-multi payload shape is invalid"});
                }
                std::vector<std::uint32_t> friend_numbers;
                friend_numbers.reserve(
                    static_cast<std::size_t>(auxiliary_count) + 1U);
                for (std::size_t index = 0U;
                     index <= static_cast<std::size_t>(auxiliary_count);
                     ++index) {
                    const std::uint32_t friend_number = read_u32(
                        std::span<const std::uint8_t>{request.payload}.subspan(
                            prefix_bytes + index * 4U, 4U));
                    if (!routed &&
                        std::find(friend_numbers.begin(), friend_numbers.end(),
                                  friend_number) != friend_numbers.end()) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "sync-pull-multi friend numbers must be unique"});
                    }
                    friend_numbers.push_back(friend_number);
                }
                const std::string namespace_id(
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(namespace_offset),
                    request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-pull-multi namespace id is invalid"});
                }
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                const bool tree_v2 =
                    policy.value().engine == sync::Engine::tree_v2;
                if (!tree_v2 &&
                    policy.value().engine != sync::Engine::content_v2) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "sync-pull-multi requires content-v2 or tree-v2"});
                }
                if (tree_v2 && routed) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "tree-v2 multi-source currently uses primary authority lanes"});
                }
                if ((tree_v2 && sync_tree_subscriber_ == nullptr) ||
                    (!tree_v2 && sync_content_subscriber_ == nullptr)) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               tree_v2
                                   ? "tree-v2 synchronization is not enabled"
                                   : "content-v2 synchronization is not enabled"});
                }
                std::vector<protocol::PeerSessionSnapshot> sessions;
                sessions.reserve(friend_numbers.size());
                for (const std::uint32_t friend_number : friend_numbers) {
                    auto session = sessions_.get(friend_number);
                    if (!session ||
                        !protocol::is_application_ready(session.value()) ||
                        (session.value().negotiated.shared_features &
                         protocol::feature_bit(
                             protocol::Feature::state_sync_v1)) == 0U ||
                        (session.value().negotiated.shared_features &
                         protocol::feature_bit(
                             tree_v2
                                 ? protocol::Feature::state_sync_tree_v2
                                 : protocol::Feature::state_sync_content_v2)) ==
                            0U) {
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "source peer has not negotiated "
                                   + std::string(
                                       tree_v2 ? "state-sync-tree-v2"
                                               : "state-sync-content-v2")});
                    }
                    sessions.push_back(std::move(session).value());
                }
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                std::vector<sync::SyncPeerContext> contexts;
                contexts.reserve(friend_numbers.size());
                for (std::size_t index = 0U; index < friend_numbers.size();
                     ++index) {
                    auto context = sync_peer_context_locked(
                        friend_numbers[index], sessions[index]);
                    if (!context)
                        return response_for(request, context.status());
                    contexts.push_back(std::move(context).value());
                }
                if (tree_v2) {
                    if (sync_automation_store_ == nullptr || !identity_ ||
                        !sodium_) {
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "tree-v2 writable automation is not enabled"});
                    }
                    std::filesystem::path worktree;
                    {
                        std::scoped_lock automation_lock(
                            sync_automation_mutex_);
                        auto automations = live_sync_automation_policies();
                        if (!automations) {
                            return response_for(request,
                                                automations.status());
                        }
                        const auto automation = std::find_if(
                            automations.value().begin(),
                            automations.value().end(),
                            [&namespace_id, &contexts](const auto &candidate) {
                                if (candidate.namespace_id != namespace_id ||
                                    candidate.mode !=
                                        sync::SyncAutomationMode::
                                            bidirectional) {
                                    return false;
                                }
                                return std::all_of(
                                    contexts.begin(), contexts.end(),
                                    [&candidate](const auto &context) {
                                        return std::binary_search(
                                            candidate.source_principals.begin(),
                                            candidate.source_principals.end(),
                                            context.peer_authority
                                                .remote_principal);
                                    });
                            });
                        if (automation == automations.value().end()) {
                            return response_for(
                                request,
                                Status{ErrorCode::unavailable,
                                       "tree-v2 namespace has no matching multi-source bidirectional policy"});
                        }
                        worktree = automation->source_path;
                    }
                    auto initial = sync_tree_subscriber_->begin_pull(
                        contexts.front(), namespace_id, worktree);
                    if (!initial) {
                        return response_for(request, initial.status());
                    }
                    const std::uint64_t job_id =
                        initial.value().frame.message_id;
                    for (std::size_t index = 1U; index < contexts.size();
                         ++index) {
                        const Status added =
                            sync_tree_subscriber_->add_source(
                                job_id, contexts[index]);
                        if (!added.ok()) {
                            const Status cancelled =
                                sync_tree_subscriber_->cancel_pull(job_id);
                            return response_for(
                                request,
                                cancelled.ok() ? added : cancelled);
                        }
                    }
                    const Status queued = send_sync_frame(
                        initial.value().context, initial.value().frame);
                    if (!queued.ok()) {
                        const Status cancelled =
                            sync_tree_subscriber_->cancel_pull(job_id);
                        return response_for(
                            request,
                            cancelled.ok() ? queued : cancelled);
                    }
                    std::set<security::SigningPublicKey> principals;
                    for (const auto &context : contexts) {
                        principals.insert(
                            context.peer_authority.remote_principal);
                    }
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            "sync-request-queued job=" +
                            std::to_string(job_id) + " namespace=" +
                            namespace_id +
                            " frames=1 engine=tree-v2 carrier=primary "
                            "frontier-source=primary availability=exact-probe "
                            "source-principals=" +
                            std::to_string(principals.size()) +
                            " source-carriers=" +
                            std::to_string(contexts.size()) + " sources=" +
                            std::to_string(contexts.size()) +
                            " atomic=1\n"));
                }
                std::vector<sync::SyncPeerContext> source_contexts = contexts;
                if (routed) {
                    std::vector<AuxiliarySyncCarrierState> candidates =
                        current_auxiliary_sync_carriers();
                    candidates.erase(
                        std::remove_if(
                            candidates.begin(), candidates.end(),
                            [](const AuxiliarySyncCarrierState &candidate) {
                                return !candidate
                                            .content_transfer_negotiated;
                            }),
                        candidates.end());
                    std::vector<security::SigningPublicKey>
                        requested_principals;
                    requested_principals.reserve(contexts.size());
                    for (const sync::SyncPeerContext &context : contexts) {
                        requested_principals.push_back(
                            context.peer_authority.remote_principal);
                    }
                    auto selected_routes =
                        sync::select_distinct_sync_routes(
                            config_.sync.route_selection_policy, candidates,
                            requested_principals, 1U, route_class);
                    if (!selected_routes) {
                        return response_for(request,
                                            selected_routes.status());
                    }
                    for (std::size_t index = 0U;
                         index < source_contexts.size(); ++index) {
                        auto auxiliary = auxiliary_sync_context_locked(
                            selected_routes.value()[index].carrier,
                            contexts[index]
                                .peer_authority.remote_principal);
                        if (!auxiliary)
                            return response_for(request, auxiliary.status());
                        source_contexts[index] =
                            std::move(auxiliary).value();
                    }
                }
                auto initial = sync_content_subscriber_->begin_pull(
                    contexts.front(), namespace_id);
                if (!initial)
                    return response_for(request, initial.status());
                const std::uint64_t job_id = initial.value().frame.message_id;
                if (routed) {
                    const Status bound =
                        sync_content_subscriber_->bind_source_carrier(
                            job_id, source_contexts.front());
                    if (!bound.ok()) {
                        const Status cancelled =
                            sync_content_subscriber_->cancel_pull(job_id);
                        return response_for(
                            request, cancelled.ok() ? bound : cancelled);
                    }
                }
                for (std::size_t index = 1U; index < source_contexts.size();
                     ++index) {
                    auto added = sync_content_subscriber_->add_source(
                        job_id, source_contexts[index]);
                    if (!added || !added.value().empty()) {
                        const Status cancelled =
                            sync_content_subscriber_->cancel_pull(job_id);
                        if (!cancelled.ok())
                            return response_for(request, cancelled);
                        return response_for(
                            request,
                            added ? Status{ErrorCode::internal_error,
                                           "atomic content source registration "
                                           "dispatched before the HEAD"}
                                  : added.status());
                    }
                }
                const Status queued = send_sync_frame(
                    initial.value().context, initial.value().frame);
                if (!queued.ok()) {
                    const Status cancelled =
                        sync_content_subscriber_->cancel_pull(job_id);
                    return response_for(request,
                                        cancelled.ok() ? queued : cancelled);
                }
                std::set<security::SigningPublicKey> source_principals;
                for (const sync::SyncPeerContext &context : contexts) {
                    source_principals.insert(
                        context.peer_authority.remote_principal);
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "sync-request-queued job=" + std::to_string(job_id) +
                        " namespace=" + namespace_id + " frames=1 " +
                        "engine=content-v2 carrier=" +
                        (routed ? std::string(sync::to_string(route_class))
                                : std::string{"primary"}) +
                        " head-carrier=primary failover=" +
                        (routed ? std::string{"fail-closed"}
                                : std::string{"none"}) +
                        " source-principals=" +
                        std::to_string(source_principals.size()) +
                        " source-carriers=" +
                        std::to_string(contexts.size()) +
                        " sources=" + std::to_string(contexts.size()) +
                        " atomic=1\n"));
            }

            case local::ControlOperation::sync_content_replica_import: {
                constexpr std::size_t head_bytes = sync::kSignedHeadBytes;
                if (request.payload.size() < 1U + 1U + head_bytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-replica-import payload is incomplete"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                const std::size_t head_offset = 1U + namespace_bytes;
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() != head_offset + head_bytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-replica-import payload shape is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(head_offset));
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-replica-import namespace is invalid"});
                }
                if (sync_content_publisher_ == nullptr || !identity_ ||
                    !sodium_) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "content-v2 synchronization is not enabled"});
                }
                auto head = sync::decode_signed_head(
                    std::span<const std::uint8_t>{request.payload}.subspan(
                        head_offset, head_bytes));
                if (!head) return response_for(request, head.status());
                std::scoped_lock maintenance_lock(
                    sync_namespace_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                if (policy.value().engine != sync::Engine::content_v2) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "sync-replica-import requires content-v2"});
                }
                auto candidate = sync::verified_candidate_head(
                    policy.value(), head.value(), *sodium_);
                if (!candidate)
                    return response_for(request, candidate.status());
                sync::AcceptedHead expected{
                    candidate.value().namespace_id,
                    candidate.value().writer,
                    candidate.value().engine,
                    candidate.value().generation,
                    candidate.value().record,
                    candidate.value().parent,
                    candidate.value().artifact,
                    candidate.value().manifest,
                    candidate.value().artifact_bytes,
                    candidate.value().manifest_bytes};
                sync::SyncContentCoordinator coordinator(
                    policy.value(), expected,
                    sync::sync_content_object_path(
                        policy.value(), head.value().manifest),
                    sync::sync_content_store_root(policy.value()),
                    sync::sync_content_staging_root(policy.value()));
                const Status prepared = coordinator.prepare();
                if (!prepared.ok()) {
                    return response_for(
                        request,
                        Status{prepared.code(),
                               "sync replica manifest graph is not ready: " +
                                   prepared.message()});
                }
                sync::ReplicaHeadStore replicas(policy.value().root);
                auto imported = replicas.import_head(
                    policy.value(), head.value(), *identity_, *sodium_);
                if (!imported)
                    return response_for(request, imported.status());
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "sync-replica-imported namespace=" + namespace_id +
                        " generation=" +
                        std::to_string(head.value().generation) +
                        " record=" + bytes_hex(imported.value().record) +
                        " writer=" + bytes_hex(head.value().writer) +
                        " decision=" +
                        std::string(sync::replica_head_import_decision_name(
                            imported.value().decision)) +
                        " authority=availability-only\n"));
            }

            case local::ControlOperation::sync_automation_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-automation payload must be empty"});
                }
                if (sync_automation_store_ == nullptr || !identity_ ||
                    !sodium_) {
                    return response_for(request, Status::success(),
                                        local::text_payload("enabled=0\n"));
                }
                std::scoped_lock automation_lock(sync_automation_mutex_);
                auto policies = live_sync_automation_policies();
                if (!policies)
                    return response_for(request, policies.status());
                const auto runtimes = sync_automation_scheduler_.snapshot();
                std::size_t active = 0U;
                for (const auto &policy : policies.value()) {
                    if (policy.mode != sync::SyncAutomationMode::disabled)
                        ++active;
                }
                std::ostringstream output;
                output << "enabled=1 policies=" << policies.value().size()
                       << " active=" << active << '\n';
                for (const sync::SyncAutomationPolicy &policy :
                     policies.value()) {
                    const auto runtime = std::find_if(
                        runtimes.begin(), runtimes.end(),
                        [&policy](const auto &candidate) {
                            return candidate.namespace_id ==
                                   policy.namespace_id;
                        });
                    output << "namespace=" << policy.namespace_id
                           << " mode="
                           << sync::sync_automation_mode_name(policy.mode)
                           << " activation="
                           << sync::sync_automation_activation_name(
                                  policy.activation)
                           << " record-format="
                           << static_cast<unsigned int>(policy.record_format)
                           << " generation=" << policy.generation
                           << " interval-ms=" << policy.interval_ms;
                    if (policy.mode == sync::SyncAutomationMode::publish) {
                        const auto *path_bytes =
                            reinterpret_cast<const std::uint8_t *>(
                                policy.source_path.data());
                        output << " source-path-hex="
                               << bytes_hex(std::span<const std::uint8_t>{
                                      path_bytes, policy.source_path.size()});
                    } else if (policy.mode ==
                               sync::SyncAutomationMode::follow) {
                        output << " source-principal="
                               << bytes_hex(policy.source_principals.front());
                    } else if (policy.mode ==
                               sync::SyncAutomationMode::writable) {
                        const auto *path_bytes =
                            reinterpret_cast<const std::uint8_t *>(
                                policy.source_path.data());
                        output << " source-path-hex="
                               << bytes_hex(std::span<const std::uint8_t>{
                                      path_bytes, policy.source_path.size()});
                    } else if (policy.mode ==
                               sync::SyncAutomationMode::bidirectional) {
                        const auto *path_bytes =
                            reinterpret_cast<const std::uint8_t *>(
                                policy.source_path.data());
                        output << " source-principals="
                               << policy.source_principals.size();
                        for (std::size_t index = 0U;
                             index < policy.source_principals.size(); ++index) {
                            output << " source-principal-" << index << '='
                                   << bytes_hex(
                                          policy.source_principals[index]);
                        }
                        output << " source-path-hex="
                               << bytes_hex(std::span<const std::uint8_t>{
                                      path_bytes, policy.source_path.size()});
                    }
                    if (runtime != runtimes.end()) {
                        output << " periodic-busy="
                               << (runtime->periodic_busy ? 1 : 0)
                               << " activation-busy="
                               << (runtime->activation_busy ? 1 : 0)
                               << " source-publish-pending="
                               << (runtime->source_publish_pending ? 1 : 0)
                               << " periodic-attempts="
                               << runtime->periodic_attempts
                               << " periodic-successes="
                               << runtime->periodic_successes
                               << " periodic-failures="
                               << runtime->periodic_failures
                               << " activation-attempts="
                               << runtime->activation_attempts
                               << " activation-successes="
                               << runtime->activation_successes
                               << " activation-failures="
                               << runtime->activation_failures
                               << " last-periodic-error="
                               << static_cast<unsigned int>(
                                      runtime->last_periodic_error)
                               << " last-activation-error="
                               << static_cast<unsigned int>(
                                      runtime->last_activation_error);
                    }
                    output << '\n';
                }
                const std::string rendered = output.str();
                if (rendered.size() > local::kControlMaxPayloadSize) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "sync automation listing exceeds local control capacity"});
                }
                return response_for(request, Status::success(),
                                    local::text_payload(rendered));
            }

            case local::ControlOperation::sync_automation_publish: {
                if (sync_automation_store_ == nullptr || !identity_ ||
                    !sodium_) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync automation is not enabled"});
                }
                if (request.payload.size() < 7U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-auto-publish payload is incomplete"});
                }
                const std::uint32_t interval_ms = read_u32(request.payload);
                const bool extended = (request.payload[4U] & 0x80U) != 0U;
                const std::size_t namespace_bytes =
                    static_cast<std::size_t>(request.payload[4U] & 0x7fU);
                const std::uint8_t create_mode =
                    extended && request.payload.size() > 5U
                        ? request.payload[5U]
                        : 1U;
                const std::size_t namespace_offset = extended ? 6U : 5U;
                const std::size_t path_offset =
                    namespace_offset + namespace_bytes;
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() <= path_offset || create_mode < 1U ||
                    create_mode > 2U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-auto-publish namespace encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(namespace_offset),
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(path_offset));
                auto source = decode_absolute_path(request.payload, path_offset);
                if (!source)
                    return response_for(request, source.status());
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                if (std::find(policy.value().writers.begin(),
                              policy.value().writers.end(),
                              identity_->public_key()) ==
                    policy.value().writers.end()) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "local device is not a namespace writer"});
                }
                sync::SyncAutomationSpec spec;
                spec.namespace_id = namespace_id;
                spec.mode = sync::SyncAutomationMode::publish;
                spec.source_path = source.value().lexically_normal().string();
                spec.interval_ms = interval_ms;
                std::scoped_lock automation_lock(sync_automation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto stored = sync_automation_store_->put(spec, *identity_,
                                                          *sodium_);
                if (!stored)
                    return response_for(request, stored.status());
                const Status witnessed = commit_sync_policy_mutation(
                    "sync publication automation committed");
                if (!witnessed.ok())
                    return response_for(request, witnessed);
                const Status reloaded = reload_sync_automation();
                if (!reloaded.ok())
                    return response_for(request, reloaded);
                notify_ratox_service();
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id + " decision=" +
                        std::string(sync::sync_automation_store_decision_name(
                            stored.value().decision)) +
                        " generation=" +
                        std::to_string(stored.value().policy.generation) +
                        " mode=publish\n"));
            }

            case local::ControlOperation::sync_automation_follow: {
                if (sync_automation_store_ == nullptr || !identity_ ||
                    !sodium_ || authority_sessions_ == nullptr ||
                    authority_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync automation is not enabled"});
                }
                if (request.payload.size() < 10U ||
                    request.payload.size() > 73U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-follow payload is invalid"});
                }
                const std::uint32_t interval_ms = read_u32(request.payload);
                const std::uint8_t encoded_activation = request.payload[4U];
                if (encoded_activation != 1U && encoded_activation != 2U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-follow activation is invalid"});
                }
                const std::uint32_t friend_number = read_u32(
                    std::span<const std::uint8_t>{request.payload}.subspan(5U));
                const std::string namespace_id(request.payload.begin() + 9,
                                               request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-follow namespace id is invalid"});
                }
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                if (encoded_activation == 2U &&
                    policy.value().activation != sync::ActivationMode::manual) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "namespace policy does not permit activation"});
                }
                security::SigningPublicKey source_principal{};
                {
                    auto session = sessions_.get(friend_number);
                    if (!session ||
                        !protocol::is_application_ready(session.value()) ||
                        (session.value().negotiated.shared_features &
                         protocol::feature_bit(
                             protocol::Feature::state_sync_v1)) == 0U) {
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "sync-follow peer is not application-ready"});
                    }
                    std::scoped_lock authority_effect_lock(
                        ratox_authority_effect_mutex_);
                    auto context = sync_peer_context_locked(friend_number,
                                                            session.value());
                    if (!context)
                        return response_for(request, context.status());
                    const auto authorized = sync::evaluate_sync_authorization(
                        sync::SyncOperation::publish, policy.value(),
                        context.value().authority,
                        context.value().peer_authority);
                    if (!authorized.authorized()) {
                        return response_for(
                            request,
                            Status{ErrorCode::protocol_error,
                                   "sync-follow source is not an authorized publisher"});
                    }
                    source_principal =
                        context.value().peer_authority.remote_principal;
                }
                sync::SyncAutomationSpec spec;
                spec.namespace_id = namespace_id;
                spec.mode = sync::SyncAutomationMode::follow;
                spec.activation = encoded_activation == 1U
                    ? sync::SyncAutomationActivation::pull_only
                    : sync::SyncAutomationActivation::verified;
                spec.source_principals = {source_principal};
                spec.interval_ms = interval_ms;
                std::scoped_lock automation_lock(sync_automation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto stored = sync_automation_store_->put(spec, *identity_,
                                                          *sodium_);
                if (!stored)
                    return response_for(request, stored.status());
                const Status witnessed = commit_sync_policy_mutation(
                    "sync follow automation committed");
                if (!witnessed.ok())
                    return response_for(request, witnessed);
                const Status reloaded = reload_sync_automation();
                if (!reloaded.ok())
                    return response_for(request, reloaded);
                notify_ratox_service();
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id + " decision=" +
                        std::string(sync::sync_automation_store_decision_name(
                            stored.value().decision)) +
                        " generation=" +
                        std::to_string(stored.value().policy.generation) +
                        " mode=follow activation=" +
                        std::string(sync::sync_automation_activation_name(
                            stored.value().policy.activation)) +
                        " source-principal=" + bytes_hex(source_principal) +
                        "\n"));
            }

            case local::ControlOperation::sync_automation_remove: {
                if (sync_automation_store_ == nullptr || !identity_ ||
                    !sodium_) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync automation is not enabled"});
                }
                const std::string namespace_id(request.payload.begin(),
                                               request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync automation namespace id is invalid"});
                }
                std::scoped_lock automation_lock(sync_automation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto stored = sync_automation_store_->disable(
                    namespace_id, *identity_, *sodium_);
                if (!stored)
                    return response_for(request, stored.status());
                const Status witnessed = commit_sync_policy_mutation(
                    "sync automation disable committed");
                if (!witnessed.ok())
                    return response_for(request, witnessed);
                const Status reloaded = reload_sync_automation();
                if (!reloaded.ok())
                    return response_for(request, reloaded);
                notify_ratox_service();
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id + " decision=" +
                        std::string(sync::sync_automation_store_decision_name(
                            stored.value().decision)) +
                        " generation=" +
                        std::to_string(stored.value().policy.generation) +
                        " mode=disabled\n"));
            }

            case local::ControlOperation::sync_create: {
                if (sync_automation_store_ == nullptr || !identity_ ||
                    !sodium_ || sync_publisher_ == nullptr ||
                    sync_subscriber_ == nullptr ||
                    config_.sync.policy_store_root.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "synchronization automation is not enabled"});
                }
                if (request.payload.size() < 7U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-create payload is incomplete"});
                }
                const std::uint32_t interval_ms = read_u32(request.payload);
                const bool extended = (request.payload[4U] & 0x80U) != 0U;
                const std::size_t namespace_bytes = request.payload[4U] & 0x7fU;
                const std::uint8_t create_mode =
                    extended && request.payload.size() > 5U
                        ? request.payload[5U]
                        : 1U;
                const bool selective = create_mode == 3U;
                const std::size_t namespace_offset = selective ? 11U
                                                    : extended ? 6U : 5U;
                const std::size_t path_offset =
                    namespace_offset + namespace_bytes;
                const std::size_t selective_path_bytes =
                    selective && request.payload.size() >= 8U
                        ? read_u16(request.payload, 6U)
                        : 0U;
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    (extended && (request.payload.size() <= 5U ||
                                  (create_mode != 1U && create_mode != 2U &&
                                   create_mode != 3U))) ||
                    (selective &&
                     (request.payload.size() < 11U ||
                      selective_path_bytes == 0U ||
                      selective_path_bytes >
                          sync::kMaximumSyncAutomationPathBytes ||
                      request.payload.size() <
                          path_offset + selective_path_bytes)) ||
                    (!selective && request.payload.size() <= path_offset)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-create namespace encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(namespace_offset),
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(path_offset));
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-create namespace id is invalid"});
                }
                Result<std::filesystem::path> source =
                    selective
                        ? decode_absolute_path(
                              std::span<const std::uint8_t>{request.payload}
                                  .subspan(path_offset,
                                           selective_path_bytes),
                              0U)
                        : decode_absolute_path(request.payload, path_offset);
                if (!source)
                    return response_for(request, source.status());
                sync::TreeV2ProjectionPolicy projection;
                if (selective) {
                    projection.metadata = static_cast<sync::TreeV2MetadataMode>(
                        request.payload[8U]);
                    const std::size_t include_count = request.payload[9U];
                    const std::size_t exclude_count = request.payload[10U];
                    if (include_count > sync::kMaximumTreeV2SelectionRules ||
                        exclude_count > sync::kMaximumTreeV2SelectionRules ||
                        include_count + exclude_count >
                            sync::kMaximumTreeV2SelectionRules * 2U) {
                        return response_for(
                            request,
                            Status{ErrorCode::resource_exhausted,
                                   "sync-create selection rule count exceeds its bound"});
                    }
                    std::size_t rule_offset =
                        path_offset + selective_path_bytes;
                    const auto decode_rules =
                        [&](std::size_t count,
                            std::vector<std::string> &destination) -> Status {
                        for (std::size_t index = 0U; index < count; ++index) {
                            if (rule_offset > request.payload.size() ||
                                request.payload.size() - rule_offset < 2U) {
                                return Status{ErrorCode::invalid_argument,
                                              "sync-create selection rule is truncated"};
                            }
                            const std::size_t bytes =
                                read_u16(request.payload, rule_offset);
                            rule_offset += 2U;
                            if (bytes == 0U ||
                                bytes > request.payload.size() - rule_offset) {
                                return Status{ErrorCode::invalid_argument,
                                              "sync-create selection rule length is invalid"};
                            }
                            destination.emplace_back(
                                request.payload.begin() +
                                    static_cast<std::ptrdiff_t>(rule_offset),
                                request.payload.begin() +
                                    static_cast<std::ptrdiff_t>(rule_offset + bytes));
                            rule_offset += bytes;
                        }
                        return Status::success();
                    };
                    Status decoded = decode_rules(include_count,
                                                  projection.includes);
                    if (decoded.ok())
                        decoded = decode_rules(exclude_count,
                                               projection.excludes);
                    if (!decoded.ok() || rule_offset != request.payload.size()) {
                        return response_for(
                            request,
                            decoded.ok()
                                ? Status{ErrorCode::invalid_argument,
                                         "sync-create selection payload has trailing bytes"}
                                : decoded);
                    }
                }
                struct stat source_metadata {};
                if (::lstat(source.value().c_str(), &source_metadata) != 0) {
                    return response_for(
                        request,
                        Status{ErrorCode::io_error,
                               "unable to inspect sync-create source: " +
                                   std::string(std::strerror(errno))});
                }
                if (S_ISLNK(source_metadata.st_mode) ||
                    (!S_ISREG(source_metadata.st_mode) &&
                     !S_ISDIR(source_metadata.st_mode))) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-create source must be one regular file or directory"});
                }
                std::error_code canonical_error;
                const std::filesystem::path canonical_source =
                    std::filesystem::canonical(source.value(),
                                               canonical_error);
                if (canonical_error) {
                    return response_for(
                        request,
                        Status{ErrorCode::io_error,
                               "unable to resolve sync-create source: " +
                                   canonical_error.message()});
                }

                sync::NamespacePolicy policy;
                policy.id = namespace_id;
                if (create_mode >= 2U && !S_ISDIR(source_metadata.st_mode)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-create read-write requires a directory"});
                }
                policy.engine = create_mode >= 2U ? sync::Engine::tree_v2
                                : S_ISDIR(source_metadata.st_mode)
                                    ? sync::Engine::treepack_v1
                                    : sync::Engine::content_v2;
                policy.activation = sync::ActivationMode::manual;
                policy.writers = {identity_->public_key()};
                policy.projection = std::move(projection);
                auto managed = sync::managed_namespace_root(
                    config_.sync.policy_store_root, namespace_id);
                if (!managed)
                    return response_for(request, managed.status());
                if (path_at_or_below(managed.value(), canonical_source) ||
                    path_at_or_below(canonical_source, managed.value())) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-create source and managed state roots must not overlap"});
                }
                policy.root = managed.value().generic_string();
                const Status valid_policy =
                    sync::validate_namespace_policy(policy);
                if (!valid_policy.ok())
                    return response_for(request, valid_policy);

                sync::SyncAutomationSpec automation;
                automation.namespace_id = namespace_id;
                automation.mode = create_mode >= 2U
                                      ? sync::SyncAutomationMode::writable
                                      : sync::SyncAutomationMode::publish;
                automation.source_path = canonical_source.string();
                automation.interval_ms = interval_ms;
                const Status valid_automation =
                    sync::validate_sync_automation_spec(automation);
                if (!valid_automation.ok())
                    return response_for(request, valid_automation);

                if (config_.security.witness_sync_guarded_state) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::unavailable,
                            "sync-create is closed while per-namespace witnessing is active; stop, commit policy, enroll the namespace, and restart"});
                }

                std::scoped_lock management_lock(
                    sync_namespace_mutation_mutex_, sync_automation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto existing = sync_namespaces_.resolve(namespace_id);
                if (existing && existing.value() != policy) {
                    return response_for(
                        request, Status{ErrorCode::unavailable,
                                        "sync-create namespace already "
                                        "exists with a different policy"});
                }
                if (!existing &&
                    existing.status().code() != ErrorCode::not_found) {
                    return response_for(request, existing.status());
                }
                auto automations = live_sync_automation_policies();
                if (!automations)
                    return response_for(request, automations.status());
                const auto prior_automation = std::find_if(
                    automations.value().begin(), automations.value().end(),
                    [&namespace_id](const auto &candidate) {
                        return candidate.namespace_id == namespace_id;
                    });
                if (prior_automation != automations.value().end() &&
                    static_cast<const sync::SyncAutomationSpec &>(
                        *prior_automation) != automation) {
                    return response_for(
                        request, Status{ErrorCode::unavailable,
                                        "sync-create automation already "
                                        "exists with a different policy"});
                }
                auto prepared_root = sync::prepare_managed_namespace_root(
                    config_.sync.policy_store_root, namespace_id,
                    static_cast<std::uint32_t>(::geteuid()));
                if (!prepared_root)
                    return response_for(request, prepared_root.status());
                auto installed = sync::install_namespace_policy(
                    config_.sync.policy_store_root, policy,
                    static_cast<std::uint32_t>(::geteuid()));
                if (!installed) {
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync-create namespace installation failed");
                    if (!reconciled.ok())
                        return response_for(request, reconciled);
                    return response_for(request, installed.status());
                }
                const Status namespace_witnessed =
                    commit_sync_policy_mutation(
                        "sync-create namespace installation committed");
                if (!namespace_witnessed.ok())
                    return response_for(request, namespace_witnessed);
                const Status reconciled = reconcile_sync_namespace_registry(
                    "sync-create namespace installation committed");
                if (!reconciled.ok())
                    return response_for(request, reconciled);
                auto stored = sync_automation_store_->put(
                    automation, *identity_, *sodium_);
                if (!stored) {
                    return response_for(
                        request,
                        Status{stored.status().code(),
                               "namespace installed but automatic publication failed: " +
                               stored.status().message()});
                }
                const Status automation_witnessed =
                    commit_sync_policy_mutation(
                        "sync-create automation committed");
                if (!automation_witnessed.ok())
                    return response_for(request, automation_witnessed);
                const Status reloaded = reload_sync_automation();
                if (!reloaded.ok())
                    return response_for(request, reloaded);
                if (create_mode >= 2U) {
                    auto transaction =
                        sync::SyncNamespaceTransaction::acquire(policy);
                    if (!transaction) {
                        return response_for(
                            request,
                            Status{transaction.status().code(),
                                   "read-write namespace is installed; initial "
                                   "workspace "
                                   "reconciliation failed: " +
                                       transaction.status().message()});
                    }
                    auto initial = reconcile_tree_v2_workspace_cached(
                        policy, canonical_source, transaction.value());
                    if (!initial) {
                        return response_for(
                            request, Status{initial.status().code(),
                                            "read-write namespace is "
                                            "installed; initial workspace "
                                            "reconciliation failed: " +
                                                initial.status().message()});
                    }
                }
                notify_ratox_service();
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id + " decision=" +
                        std::string(
                            installed.value().disposition ==
                                    sync::NamespaceInstallDisposition::installed
                                ? "created"
                                : "duplicate") +
                        " engine=" +
                        std::string(sync::engine_name(policy.engine)) +
                        " access=" +
                        std::string(create_mode >= 2U ? "read-write"
                                                      : "sole-writer") +
                        (create_mode >= 2U
                             ? " metadata=" + std::string(
                                   sync::tree_v2_metadata_mode_name(
                                       policy.projection.metadata)) +
                                   " includes=" +
                                   std::to_string(
                                       policy.projection.includes.size()) +
                                   " excludes=" +
                                   std::to_string(
                                       policy.projection.excludes.size())
                             : std::string{}) +
                        " root=" + policy.root + " automation=" +
                        std::string(sync::sync_automation_store_decision_name(
                            stored.value().decision)) +
                        " generation=" +
                        std::to_string(stored.value().policy.generation) +
                        "\n"));
            }

            case local::ControlOperation::sync_share_prepare:
            case local::ControlOperation::sync_share_read_write_prepare: {
                const bool read_write =
                    request.operation ==
                    local::ControlOperation::sync_share_read_write_prepare;
                constexpr std::size_t prefix_bytes =
                    4U + security::kSigningPublicKeyBytes;
                if (request.payload.size() < prefix_bytes + 1U ||
                    request.payload.size() > prefix_bytes + 64U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-share prepare payload is invalid"});
                }
                if (authority_ == nullptr || authority_sessions_ == nullptr ||
                    sync_publisher_ == nullptr || sync_subscriber_ == nullptr ||
                    (read_write && (sync_tree_publisher_ == nullptr ||
                                    sync_tree_subscriber_ == nullptr ||
                                    sync_automation_store_ == nullptr ||
                                    !identity_ || !sodium_))) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync-share services are unavailable"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                security::SigningPublicKey owner{};
                std::copy_n(request.payload.begin() + 4, owner.size(),
                            owner.begin());
                const std::string namespace_id(
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(prefix_bytes),
                    request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-share namespace id is invalid"});
                }
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                if (read_write &&
                    policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::unsupported,
                            "read-write sharing requires a tree-v2 namespace"});
                }
                auto peer = sync_share_peer_device(friend_number);
                if (!peer)
                    return response_for(request, peer.status());
                if (std::find(policy.value().subscribers.begin(),
                              policy.value().subscribers.end(),
                              peer.value()) ==
                        policy.value().subscribers.end() &&
                    policy.value().subscribers.size() >=
                        sync::kMaximumNamespacePrincipals) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "sync namespace subscriber bound is exhausted"});
                }
                if (read_write &&
                    std::find(policy.value().writers.begin(),
                              policy.value().writers.end(),
                              peer.value()) == policy.value().writers.end() &&
                    policy.value().writers.size() >=
                        sync::kTreeV2WireMaximumWriters) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "tree-v2 writer inventory bound is exhausted"});
                }
                if (read_write) {
                    std::scoped_lock automation_lock(sync_automation_mutex_);
                    auto candidate = sync_bidirectional_spec_with_peer(
                        namespace_id, peer.value());
                    if (!candidate)
                        return response_for(request, candidate.status());
                }

                constexpr std::uint64_t subscribe =
                    static_cast<std::uint64_t>(
                        security::Capability::sync_subscribe);
                constexpr std::uint64_t publish = static_cast<std::uint64_t>(
                    security::Capability::sync_publish);
                const std::uint64_t required =
                    subscribe | (read_write ? publish : 0U);
                const security::AuthoritySnapshot snapshot =
                    authority_->snapshot();
                constexpr std::uint64_t manage =
                    static_cast<std::uint64_t>(
                        security::Capability::manage_principals);
                const auto recalled_owner = std::find_if(
                    snapshot.principals.begin(), snapshot.principals.end(),
                    [&owner](const security::PrincipalState &candidate) {
                        return candidate.public_key == owner;
                    });
                if (recalled_owner == snapshot.principals.end() ||
                    !recalled_owner->active ||
                    recalled_owner->role != security::PrincipalRole::owner ||
                    (recalled_owner->capabilities & manage) == 0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "sync-share RecallRoot does not reconstruct the active owner"});
                }
                const auto existing_principal = std::find_if(
                    snapshot.principals.begin(), snapshot.principals.end(),
                    [&peer](const security::PrincipalState &candidate) {
                        return candidate.public_key == peer.value();
                    });
                const bool already_authorized =
                    existing_principal != snapshot.principals.end() &&
                    existing_principal->active &&
                    (existing_principal->capabilities & required) == required;
                std::vector<std::uint8_t> response;
                response.reserve(
                    1U + peer.value().size() +
                    (already_authorized
                         ? 0U
                         : security::kAuthorityRecordBodyBytes));
                response.push_back(already_authorized ? 0U : 1U);
                response.insert(response.end(), peer.value().begin(),
                                peer.value().end());
                if (!already_authorized) {
                    security::AuthorityPrepareRequest mutation;
                    mutation.action = security::AuthorityAction::grant;
                    mutation.issuer = owner;
                    mutation.subject = peer.value();
                    if (existing_principal != snapshot.principals.end() &&
                        existing_principal->active) {
                        mutation.role = existing_principal->role;
                        mutation.capabilities =
                            existing_principal->capabilities | required;
                        if ((mutation.capabilities &
                             ~security::role_capability_ceiling(
                                 mutation.role,
                                 security::AuthorityLedgerFormat::v3)) != 0U) {
                            mutation.role = security::PrincipalRole::automation;
                        }
                        if ((mutation.capabilities &
                             ~security::role_capability_ceiling(
                                 mutation.role,
                                 security::AuthorityLedgerFormat::v3)) != 0U) {
                            mutation.role =
                                security::PrincipalRole::administrator;
                        }
                    } else {
                        mutation.role =
                            read_write ? security::PrincipalRole::automation
                                       : security::PrincipalRole::viewer;
                        mutation.capabilities = required;
                    }
                    auto body = authority_->prepare(mutation);
                    if (!body)
                        return response_for(request, body.status());
                    response.insert(response.end(), body.value().begin(),
                                    body.value().end());
                }
                return response_for(request, Status::success(),
                                    std::move(response));
            }

            case local::ControlOperation::sync_share_commit:
            case local::ControlOperation::sync_share_read_write_commit: {
                const bool read_write =
                    request.operation ==
                    local::ControlOperation::sync_share_read_write_commit;
                constexpr std::size_t base_prefix = 5U;
                if (request.payload.size() <
                    base_prefix + 1U + security::kSigningPublicKeyBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-share commit payload is incomplete"});
                }
                if (authority_ == nullptr || authority_sessions_ == nullptr ||
                    sync_publisher_ == nullptr || sync_subscriber_ == nullptr ||
                    (read_write && (sync_tree_publisher_ == nullptr ||
                                    sync_tree_subscriber_ == nullptr ||
                                    sync_automation_store_ == nullptr ||
                                    !identity_ || !sodium_))) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync-share services are unavailable"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                const std::size_t namespace_bytes = request.payload[4U];
                const std::size_t principal_offset = 5U + namespace_bytes;
                const std::size_t record_offset =
                    principal_offset + security::kSigningPublicKeyBytes;
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    (request.payload.size() != record_offset &&
                     request.payload.size() !=
                         record_offset + security::kAuthorityRecordBytes)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-share commit encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 5,
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(principal_offset));
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-share namespace id is invalid"});
                }
                security::SigningPublicKey principal{};
                std::copy_n(
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(principal_offset),
                    principal.size(), principal.begin());
                auto current_peer = sync_share_peer_device(friend_number);
                if (!current_peer)
                    return response_for(request, current_peer.status());
                if (current_peer.value() != principal) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "sync-share peer principal changed after preparation"});
                }

                // Repeat the non-mutating automation preflight before accepting
                // a signed authority mutation. This prevents a stale prepare or
                // a second peer from leaving a partially committed grant merely
                // because the local pull policy cannot represent it.
                if (read_write) {
                    auto policy = sync_namespaces_.resolve(namespace_id);
                    if (!policy)
                        return response_for(request, policy.status());
                    const bool already_writer =
                        std::binary_search(policy.value().writers.begin(),
                                           policy.value().writers.end(),
                                           principal);
                    if (!already_writer &&
                        policy.value().writers.size() >=
                            sync::kTreeV2WireMaximumWriters) {
                        return response_for(
                            request,
                            Status{ErrorCode::resource_exhausted,
                                   "tree-v2 writer inventory bound is exhausted"});
                    }
                    std::scoped_lock automation_lock(sync_automation_mutex_);
                    auto candidate = sync_bidirectional_spec_with_peer(
                        namespace_id, principal);
                    if (!candidate)
                        return response_for(request, candidate.status());
                }

                bool grant_committed = false;
                if (request.payload.size() != record_offset) {
                    security::AuthorityRecordBytes record{};
                    std::copy_n(
                        request.payload.begin() +
                            static_cast<std::ptrdiff_t>(record_offset),
                        record.size(), record.begin());
                    auto decoded = security::decode_authority_record(record);
                    constexpr std::uint64_t subscribe =
                        static_cast<std::uint64_t>(
                            security::Capability::sync_subscribe);
                    constexpr std::uint64_t publish =
                        static_cast<std::uint64_t>(
                            security::Capability::sync_publish);
                    const std::uint64_t required =
                        subscribe | (read_write ? publish : 0U);
                    if (!decoded ||
                        decoded.value().action !=
                            security::AuthorityAction::grant ||
                        decoded.value().subject != principal ||
                        (decoded.value().capabilities & required) != required) {
                        return response_for(
                            request, Status{ErrorCode::protocol_error,
                                            "sync-share signed grant does not "
                                            "authorize the prepared access"});
                    }
                    const Status appended =
                        append_local_authority_record(record);
                    if (!appended.ok())
                        return response_for(request, appended);
                    grant_committed = true;
                }
                constexpr std::uint64_t subscribe =
                    static_cast<std::uint64_t>(
                        security::Capability::sync_subscribe);
                constexpr std::uint64_t publish = static_cast<std::uint64_t>(
                    security::Capability::sync_publish);
                const std::uint64_t required =
                    subscribe | (read_write ? publish : 0U);
                const security::AuthoritySnapshot authority =
                    authority_->snapshot();
                const auto authorized = std::find_if(
                    authority.principals.begin(), authority.principals.end(),
                    [&principal](const security::PrincipalState &candidate) {
                        return candidate.public_key == principal;
                    });
                if (authorized == authority.principals.end() ||
                    !authorized->active ||
                    (authorized->capabilities & required) != required) {
                    return response_for(
                        request, Status{ErrorCode::protocol_error,
                                        "sync-share authority is not durable"});
                }

                // The network publisher takes this same fence before it
                // evaluates authority or touches its replay cache. Hold it
                // through replay retirement and the durable additive policy
                // update so no request can retain an intermediate denial.
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                std::scoped_lock management_lock(sync_namespace_mutation_mutex_,
                                                 sync_automation_mutex_);
                std::scoped_lock witness_lock(sync_policy_mutation_mutex_);
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) {
                    return response_for(
                        request,
                        Status{policy.status().code(),
                               (grant_committed
                                    ? "subscriber grant committed; "
                                    : "") +
                                   policy.status().message()});
                }
                if (read_write &&
                    policy.value().engine != sync::Engine::tree_v2) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::unsupported,
                            "read-write sharing requires a tree-v2 namespace"});
                }
                std::optional<sync::SyncAutomationSpec> next_automation;
                if (read_write) {
                    auto candidate = sync_bidirectional_spec_with_peer(
                        namespace_id, principal);
                    if (!candidate) {
                        return response_for(
                            request,
                            Status{candidate.status().code(),
                                   (grant_committed
                                        ? "sync authority is durable; "
                                        : "") +
                                       candidate.status().message()});
                    }
                    next_automation = std::move(candidate).value();
                }
                const bool already_subscriber =
                    std::find(policy.value().subscribers.begin(),
                              policy.value().subscribers.end(),
                              principal) != policy.value().subscribers.end();
                const bool already_writer =
                    std::find(policy.value().writers.begin(),
                              policy.value().writers.end(),
                              principal) != policy.value().writers.end();
                const bool membership_change =
                    !already_subscriber || (read_write && !already_writer);
                sync::NamespaceUpdateDisposition disposition =
                    sync::NamespaceUpdateDisposition::duplicate;
                if (membership_change) {
                    if ((!already_subscriber &&
                         policy.value().subscribers.size() >=
                             sync::kMaximumNamespacePrincipals) ||
                        (read_write && !already_writer &&
                         policy.value().writers.size() >=
                             sync::kTreeV2WireMaximumWriters)) {
                        return response_for(
                            request,
                            Status{ErrorCode::resource_exhausted,
                                   "sync authority is durable but namespace "
                                   "membership bound is exhausted"});
                    }
                    const Status ready =
                        read_write
                            ? sync_tree_subscriber_->namespace_mutation_ready(
                                  namespace_id)
                            : sync_subscriber_->namespace_mutation_ready(
                                  namespace_id);
                    if (!ready.ok()) {
                        return response_for(
                            request,
                            Status{ready.code(), "sync authority is durable; " +
                                                     ready.message()});
                    }
                    // Replay-cache retention is distinct from transfer
                    // lifetime. Adding a principal does not revoke any
                    // existing transfer authority. Retire only this namespace
                    // so a repeated request is evaluated against the successor
                    // policy. Destructive policy mutations retain their
                    // stronger disconnect/drain requirement.
                    if (policy.value().engine == sync::Engine::tree_v2) {
                        static_cast<void>(
                            sync_tree_publisher_
                                ->retire_namespace_replays_for_additive_share(
                                    namespace_id));
                    } else {
                        static_cast<void>(
                            sync_publisher_
                                ->retire_namespace_replays_for_additive_share(
                                    namespace_id));
                    }
                    if (!already_subscriber)
                        policy.value().subscribers.push_back(principal);
                    if (read_write && !already_writer)
                        policy.value().writers.push_back(principal);
                    std::sort(policy.value().subscribers.begin(),
                              policy.value().subscribers.end());
                    std::sort(policy.value().writers.begin(),
                              policy.value().writers.end());
                    auto updated = sync::update_namespace_policy(
                        config_.sync.policy_store_root, policy.value(),
                        static_cast<std::uint32_t>(::geteuid()));
                    if (!updated) {
                        const Status reconciled =
                            reconcile_sync_namespace_registry(
                                "sync-share namespace update failed");
                        if (!reconciled.ok())
                            return response_for(request, reconciled);
                        return response_for(
                            request, Status{updated.status().code(),
                                            "sync authority is durable; " +
                                                updated.status().message()});
                    }
                    const Status witnessed = commit_sync_policy_mutation(
                        "sync-share namespace update committed");
                    if (!witnessed.ok())
                        return response_for(request, witnessed);
                    disposition = updated.value().disposition;
                    const Status reconciled =
                        reconcile_sync_namespace_registry(
                            "sync-share namespace update committed");
                    if (!reconciled.ok())
                        return response_for(request, reconciled);
                }
                std::optional<sync::SyncAutomationStoreResult>
                    automation_result;
                if (read_write) {
                    auto stored = sync_automation_store_->put(
                        *next_automation, *identity_, *sodium_);
                    if (!stored) {
                        return response_for(
                            request,
                            Status{
                                stored.status().code(),
                                "read-write namespace membership is durable; " +
                                    stored.status().message()});
                    }
                    const Status witnessed = commit_sync_policy_mutation(
                        "sync-share automation update committed");
                    if (!witnessed.ok())
                        return response_for(request, witnessed);
                    automation_result = std::move(stored).value();
                    const Status reloaded = reload_sync_automation();
                    if (!reloaded.ok()) return response_for(request, reloaded);
                    notify_ratox_service();
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "namespace=" + namespace_id +
                        " access=" + (read_write ? "read-write" : "read-only") +
                        " principal=" + bytes_hex(principal) + " authority=" +
                        (grant_committed ? "granted" : "present") +
                        " membership=" +
                        (disposition ==
                                 sync::NamespaceUpdateDisposition::updated
                             ? "added"
                             : "present") +
                        (read_write
                             ? " automation=" +
                                   std::string(
                                       sync::
                                           sync_automation_store_decision_name(
                                               automation_result->decision))
                             : "") +
                        "\n"));
            }

            case local::ControlOperation::sync_status: {
                if (!request.payload.empty()) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-status payload must be empty"});
                }
                if (sync_publisher_ == nullptr || sync_subscriber_ == nullptr) {
                    return response_for(request, Status::success(),
                                        local::text_payload("enabled=0\n"));
                }
                const sync::RegistrySnapshot namespaces =
                    sync_namespaces_.snapshot();
                const auto publisher_observation = sync_publisher_->try_snapshot();
                const bool publisher_busy = !publisher_observation.has_value();
                const sync::SyncPublisherSnapshot publisher =
                    publisher_observation.value_or(sync::SyncPublisherSnapshot{});
                const auto pulls = sync_subscriber_->snapshot();
                const auto automation =
                    sync_automation_scheduler_.snapshot();
                const std::size_t automatic_publishers =
                    static_cast<std::size_t>(std::count_if(
                        automation.begin(), automation.end(),
                        [](const auto &runtime) {
                            return runtime.mode ==
                                   sync::SyncAutomationMode::publish;
                        }));
                const std::size_t automatic_followers =
                    static_cast<std::size_t>(std::count_if(
                        automation.begin(), automation.end(),
                        [](const auto &runtime) {
                            return runtime.mode ==
                                   sync::SyncAutomationMode::follow;
                        }));
                const std::size_t automatic_bidirectional =
                    static_cast<std::size_t>(std::count_if(
                        automation.begin(), automation.end(),
                        [](const auto &runtime) {
                            return runtime.mode ==
                                   sync::SyncAutomationMode::bidirectional;
                        }));
                const std::size_t automatic_writable = static_cast<std::size_t>(
                    std::count_if(automation.begin(), automation.end(),
                                  [](const auto &runtime) {
                                      return runtime.mode ==
                                             sync::SyncAutomationMode::writable;
                                  }));
                const std::uint64_t automation_failures =
                    std::accumulate(
                        automation.begin(), automation.end(), 0ULL,
                        [](std::uint64_t total, const auto &runtime) {
                            return total + runtime.periodic_failures +
                                   runtime.activation_failures;
                        });
                const auto content_publisher_observation =
                    sync_content_publisher_ != nullptr
                        ? sync_content_publisher_->try_snapshot()
                        : std::optional<sync::SyncContentPublisherSnapshot>{};
                const bool content_publisher_busy =
                    sync_content_publisher_ != nullptr &&
                    !content_publisher_observation.has_value();
                const sync::SyncContentPublisherSnapshot content_publisher =
                    content_publisher_observation.value_or(
                        sync::SyncContentPublisherSnapshot{});
                const auto content_pulls =
                    sync_content_subscriber_ != nullptr
                        ? sync_content_subscriber_->snapshot()
                        : std::vector<sync::SyncContentPullSnapshot>{};
                const sync::TreeV2PublisherSnapshot tree_publisher =
                    sync_tree_publisher_ != nullptr
                        ? sync_tree_publisher_->snapshot()
                        : sync::TreeV2PublisherSnapshot{};
                const auto tree_pulls =
                    sync_tree_subscriber_ != nullptr
                        ? sync_tree_subscriber_->snapshot()
                        : std::vector<sync::TreeV2PullSnapshot>{};
                const sync::TreeV2SubscriberSnapshot tree_subscriber =
                    sync_tree_subscriber_ != nullptr
                        ? sync_tree_subscriber_->statistics()
                        : sync::TreeV2SubscriberSnapshot{};
                const std::vector<AuxiliarySyncCarrierState>
                    auxiliary_ready_routes = current_auxiliary_sync_carriers();
                const std::vector<routes::WorkerTransferSnapshot>
                    auxiliary_transfers =
                        route_worker_supervisor_ != nullptr
                            ? route_worker_supervisor_->transfers()
                            : std::vector<routes::WorkerTransferSnapshot>{};
                std::size_t queued_work = 0U;
                std::size_t queued_terminals = 0U;
                std::size_t active_work = 0U;
                std::uint64_t admitted_work = 0U;
                std::uint64_t completed_work = 0U;
                std::uint64_t rejected_work = 0U;
                std::uint64_t discarded_work = 0U;
                {
                    std::scoped_lock work_lock(sync_work_mutex_);
                    queued_work = sync_work_queue_.size();
                    queued_terminals = sync_terminal_work_queue_.size();
                    active_work = sync_work_active_;
                    admitted_work = sync_work_admitted_;
                    completed_work = sync_work_completed_;
                    rejected_work = sync_work_rejected_;
                    discarded_work = sync_work_discarded_;
                }
                std::ostringstream output;
                output
                    << "enabled=1 feature=state-sync-v1"
                    << " range-feature=state-sync-ranges-v1"
                    << " namespaces=" << namespaces.namespaces
                    << " content-feature="
                    << (sync_content_publisher_ != nullptr &&
                                sync_content_subscriber_ != nullptr
                            ? "state-sync-content-v2"
                            : "disabled")
                    << " content-lane-cap="
                    << config_.sync.maximum_content_lanes << " tree-feature="
                    << (sync_tree_publisher_ != nullptr &&
                                sync_tree_subscriber_ != nullptr
                            ? "state-sync-tree-v2"
                            : "disabled")
                    << " tree-lane-cap=" << config_.sync.maximum_tree_lanes
                    << " publisher-busy=" << (publisher_busy ? 1 : 0)
                    << " publisher-replays=" << publisher.retained_replays
                    << " head-requests=" << publisher.head_requests
                    << " object-requests=" << publisher.object_requests
                    << " range-requests=" << publisher.range_requests
                    << " denials=" << publisher.denials
                    << " replay-hits=" << publisher.replay_hits
                    << " replay-conflicts=" << publisher.replay_conflicts
                    << " replay-evictions=" << publisher.replay_evictions
                    << " file-offers=" << publisher.file_offers
                    << " range-file-offers=" << publisher.range_file_offers
                    << " range-bytes-offered=" << publisher.range_bytes_offered
                    << " pull-jobs=" << pulls.size()
                    << " automation-publishers=" << automatic_publishers
                    << " automation-followers=" << automatic_followers
                    << " automation-bidirectional=" << automatic_bidirectional
                    << " automation-writable=" << automatic_writable
                    << " automation-failures=" << automation_failures
                    << " content-publisher-busy="
                    << (content_publisher_busy ? 1 : 0)
                    << " content-publisher-replays="
                    << content_publisher.retained_replays
                    << " content-object-requests="
                    << content_publisher.object_requests
                    << " content-availability-requests="
                    << content_publisher.availability_requests
                    << " content-denials=" << content_publisher.denials
                    << " content-replay-hits=" << content_publisher.replay_hits
                    << " content-replay-evictions="
                    << content_publisher.replay_evictions
                    << " content-replay-conflicts="
                    << content_publisher.replay_conflicts
                    << " content-file-offers=" << content_publisher.file_offers
                    << " content-pull-jobs=" << content_pulls.size()
                    << " tree-publisher-replays="
                    << tree_publisher.retained_replays
                    << " tree-replay-evictions="
                    << tree_publisher.replay_evictions
                    << " tree-inventory-requests="
                    << tree_publisher.inventory_requests
                    << " tree-object-requests="
                    << tree_publisher.object_requests
                    << " tree-denials=" << tree_publisher.denials
                    << " tree-file-offers=" << tree_publisher.file_offers
                    << " tree-pull-jobs=" << tree_pulls.size()
                    << " tree-file-commit-batches="
                    << tree_subscriber.file_commit_batches
                    << " tree-file-objects-committed="
                    << tree_subscriber.file_objects_committed
                    << " tree-largest-file-commit-batch="
                    << tree_subscriber.largest_file_commit_batch
                    << " tree-cas-full-inventory-scans="
                    << tree_subscriber.cas_full_inventory_scans
                    << " tree-cas-inventory-objects-inspected="
                    << tree_subscriber.cas_inventory_objects_inspected
                    << " tree-late-offers-cancelled="
                    << tree_subscriber.late_offers_cancelled
                    << " tree-retired-offer-ids="
                    << tree_subscriber.retired_offer_ids
                    << " tree-retired-offer-evictions="
                    << tree_subscriber.retired_offer_evictions
                    << " auxiliary-ready-routes="
                    << auxiliary_ready_routes.size()
                    << " worker-queued=" << queued_work
                    << " terminal-queued=" << queued_terminals
                    << " worker-active=" << active_work
                    << " worker-admitted=" << admitted_work
                    << " worker-completed=" << completed_work
                    << " worker-rejected=" << rejected_work
                    << " worker-discarded=" << discarded_work
                    << " auxiliary-carrier-losses="
                    << sync_auxiliary_carrier_losses_.load(
                           std::memory_order_relaxed)
                    << " auxiliary-reassignments="
                    << sync_auxiliary_reassignments_.load(
                           std::memory_order_relaxed)
                    << " auxiliary-stale-terminals="
                    << sync_auxiliary_stale_terminals_.load(
                           std::memory_order_relaxed)
                    << " auxiliary-recoveries="
                    << sync_auxiliary_recoveries_.load(
                           std::memory_order_relaxed)
                    << " auxiliary-route-policy="
                    << sync::to_string(config_.sync.route_selection_policy)
                    << " auxiliary-failover-policy="
                    << sync::to_string(config_.sync.route_failover_policy)
                    << " auxiliary-fail-closed-jobs="
                    << sync_auxiliary_fail_closed_jobs_.load(
                           std::memory_order_relaxed)
                    << " auxiliary-fixed-selections="
                    << sync_auxiliary_fixed_selections_.load(
                           std::memory_order_relaxed)
                    << " auxiliary-adaptive-selections="
                    << sync_auxiliary_adaptive_selections_.load(
                           std::memory_order_relaxed)
                    << " qualification-fault="
                    << (sync_qualification_fault_injected_.load(
                            std::memory_order_relaxed)
                            ? 1
                            : 0)
                    << " qualification-fault-count="
                    << sync_qualification_fault_count_.load(
                           std::memory_order_relaxed)
                    << " qualification-fault-position="
                    << sync_qualification_fault_position_.load(
                           std::memory_order_relaxed)
                    << " qualification-fault-route="
                    << (sync_qualification_fault_injected_.load(
                            std::memory_order_relaxed)
                            ? bytes_hex(sync_qualification_fault_route_key_)
                            : "none")
                    << " qualification-fault-worker="
                    << (sync_qualification_fault_injected_.load(
                            std::memory_order_relaxed)
                            ? std::to_string(
                                  sync_qualification_fault_worker_id_)
                            : "none")
                    << " qualification-fault-affected-jobs="
                    << sync_qualification_affected_job_count_.load(
                           std::memory_order_relaxed)
                    << " qualification-deferred-frames="
                    << sync_qualification_deferred_frame_count_.load(
                           std::memory_order_relaxed)
                    << " qualification-deferred-frame-releases="
                    << sync_qualification_deferred_frame_releases_.load(
                           std::memory_order_relaxed)
                    << " qualification-fault-armed="
                    << (sync_qualification_fault_armed_.load(
                            std::memory_order_relaxed)
                            ? 1
                            : 0)
                    << " qualification-fault-after-cancel="
                    << (sync_qualification_fault_injected_.load(
                            std::memory_order_relaxed) &&
                                config_.sync
                                    .qualification_stop_after_cancelled_pull
                            ? 1
                            : 0)
                    << '\n';
                for (const AuxiliarySyncCarrierState &route :
                     auxiliary_ready_routes) {
                    output << "auxiliary-route="
                           << bytes_hex(route.carrier.route_key)
                           << " worker=" << route.carrier.worker_id
                           << " friend=" << route.carrier.friend_number
                           << " epoch=" << route.carrier.online_epoch
                           << " principal=" << bytes_hex(route.remote_principal)
                           << " admitted-work=" << route.admitted_work
                           << " maximum-work=" << route.maximum_work
                           << " range-negotiated="
                           << (route.range_transfer_negotiated ? 1 : 0)
                           << " content-negotiated="
                           << (route.content_transfer_negotiated ? 1 : 0)
                           << '\n';
                }
                for (const sync::SyncPullSnapshot &pull : pulls) {
                    std::size_t carrier_active_receives = 0U;
                    std::uint64_t carrier_receive_position = 0U;
                    std::uint64_t carrier_receive_bytes = 0U;
                    if (pull.transfer_carrier.carrier_class ==
                        sync::SyncCarrierClass::auxiliary) {
                        for (const routes::WorkerTransferSnapshot &transfer :
                             auxiliary_transfers) {
                            if (transfer.route_key !=
                                    pull.transfer_carrier.route_key ||
                                transfer.worker_id !=
                                    pull.transfer_carrier.worker_id ||
                                transfer.transfer.direction !=
                                    FileTransferDirection::incoming ||
                                transfer.transfer.state !=
                                    FileTransferState::active ||
                                !transfer.transfer.has_file_id ||
                                std::find(pull.transfer_file_ids.begin(),
                                          pull.transfer_file_ids.end(),
                                          transfer.transfer.file_id) ==
                                    pull.transfer_file_ids.end()) {
                                continue;
                            }
                            ++carrier_active_receives;
                            carrier_receive_position += transfer.transfer.position;
                            carrier_receive_bytes += transfer.transfer.file_size;
                        }
                    }
                    output
                        << "job=" << pull.job_id << " friend=" << pull.friend_number
                        << " epoch=" << pull.online_epoch << " carrier="
                        << (pull.transfer_carrier.carrier_class ==
                                    sync::SyncCarrierClass::auxiliary
                                ? "auxiliary"
                                : "primary")
                        << " carrier-route="
                        << bytes_hex(pull.transfer_carrier.route_key)
                        << " carrier-worker=" << pull.transfer_carrier.worker_id
                        << " carrier-friend=" << pull.transfer_carrier.friend_number
                        << " carrier-epoch=" << pull.transfer_carrier.online_epoch
                        << " carrier-generation="
                        << pull.transfer_carrier.remote_route_generation
                        << " carrier-coordinator="
                        << bytes_hex(
                               pull.transfer_carrier.remote_coordinator_route_key)
                        << " carrier-primary-epoch="
                        << pull.transfer_carrier.primary_authority_online_epoch
                        << " failover="
                        << sync::to_string(pull.route_failover_policy)
                        << " route-class=" << sync::to_string(pull.route_class)
                        << " namespace=" << pull.namespace_id
                        << " state=" << sync::sync_pull_state_name(pull.state)
                        << " head-generation=" << pull.head_generation
                        << " head-record=" << bytes_hex(pull.head_record)
                        << " requested=" << pull.requested_objects
                        << " admitted=" << pull.admitted_offers
                        << " pending-offers=" << pull.pending_offers
                        << " admission-retries=" << pull.admission_retries
                        << " object-result-retries=" << pull.object_result_retries
                        << " committed=" << pull.committed_objects
                        << " scheduler-attempts=" << pull.scheduler_attempts
                        << " scheduler-attempt-bound="
                        << pull.scheduler_attempt_bound
                        << " retained-partials=" << pull.retained_partials
                        << " retained-attempts=" << pull.retained_attempts
                        << " retained-bytes=" << pull.retained_bytes
                        << " retention-fallbacks=" << pull.retention_fallbacks
                        << " resumed-attempts=" << pull.resumed_attempts
                        << " resumed-bytes=" << pull.resumed_bytes
                        << " restart-resumed-attempts="
                        << pull.restart_resumed_attempts
                        << " restart-resumed-bytes=" << pull.restart_resumed_bytes
                        << " carrier-active-receives=" << carrier_active_receives
                        << " carrier-receive-position=" << carrier_receive_position
                        << " carrier-receive-bytes=" << carrier_receive_bytes
                        << " range-transfer=" << (pull.range_transfer ? 1 : 0)
                        << " range-lane-active=" << (pull.range_lane_active ? 1 : 0)
                        << " range-attempt=" << pull.range_attempt_id
                        << " range-message=" << pull.range_message_id
                        << " range-bundle-bytes=" << pull.range_bundle_bytes
                        << " range-fallback=" << (pull.range_fallback ? 1 : 0)
                        << " range-retries=" << pull.range_retries
                        << " range-discarded-bytes=" << pull.range_discarded_bytes
                        << " range-retained-bytes=" << pull.range_retained_bytes
                        << " range-resumed-bytes=" << pull.range_resumed_bytes
                        << " range-restart-resumed-attempts="
                        << pull.range_restart_resumed_attempts
                        << " range-restart-resumed-bytes="
                        << pull.range_restart_resumed_bytes
                        << " range-restart-suffix-bytes="
                        << pull.range_restart_suffix_bytes
                        << " range-retention-fallbacks="
                        << pull.range_retention_fallbacks
                        << " range-count=" << pull.range_count
                        << " range-reused-bytes=" << pull.range_reused_bytes
                        << " range-fetched-bytes=" << pull.range_fetched_bytes
                        << " detail=" << std::quoted(pull.detail) << '\n';
                }
                for (const sync::SyncContentPullSnapshot &pull : content_pulls) {
                    output << "content-job=" << pull.job_id
                           << " friend=" << pull.friend_number
                           << " epoch=" << pull.online_epoch
                           << " namespace=" << pull.namespace_id << " state="
                           << sync::sync_content_pull_state_name(pull.state)
                           << " head-generation=" << pull.head_generation
                           << " head-record=" << bytes_hex(pull.head_record)
                           << " phase=" << sync::sync_content_phase_name(pull.phase)
                           << " requested=" << pull.requested_objects
                           << " committed=" << pull.committed_objects
                           << " reused=" << pull.reused_objects
                           << " fetched-bytes=" << pull.fetched_bytes
                           << " sources=" << pull.sources
                           << " source-carrier="
                           << (pull.primary_source_carrier.carrier_class ==
                                       sync::SyncCarrierClass::auxiliary
                                   ? "auxiliary"
                                   : "primary")
                           << " source-route="
                           << bytes_hex(pull.primary_source_carrier.route_key)
                           << " source-worker="
                           << pull.primary_source_carrier.worker_id
                           << " availability-requests="
                           << pull.availability_requests
                           << " availability-results="
                           << pull.availability_results
                           << " active-lanes=" << pull.active_lanes
                           << " active-file="
                           << (pull.active_file_id ? bytes_hex(*pull.active_file_id)
                                                   : "none")
                           << " active-file-number="
                           << (pull.active_file_number
                                   ? std::to_string(*pull.active_file_number)
                                   : "none")
                           << " detail=" << std::quoted(pull.detail) << '\n';
                    for (const sync::SyncContentSourceSnapshot &source :
                         pull.source_carriers) {
                        output
                            << "content-source-job=" << pull.job_id
                            << " source-id=" << source.source_id
                            << " friend=" << source.friend_number
                            << " epoch=" << source.online_epoch
                            << " principal="
                            << bytes_hex(source.stable_principal)
                            << " authority-route="
                            << bytes_hex(source.authority_route_key)
                            << " carrier="
                            << (source.transfer_carrier.carrier_class ==
                                        sync::SyncCarrierClass::auxiliary
                                    ? "auxiliary"
                                    : "primary")
                            << " route="
                            << bytes_hex(source.transfer_carrier.route_key)
                            << " worker="
                            << source.transfer_carrier.worker_id
                            << " carrier-friend="
                            << source.transfer_carrier.friend_number
                            << " carrier-epoch="
                            << source.transfer_carrier.online_epoch
                            << " route-generation="
                            << source.transfer_carrier.remote_route_generation
                            << " remote-coordinator="
                            << bytes_hex(source.transfer_carrier
                                             .remote_coordinator_route_key)
                            << " primary-authority-epoch="
                            << source.transfer_carrier
                                   .primary_authority_online_epoch
                            << " requested=" << source.requested_objects
                            << " committed=" << source.committed_objects
                            << " fetched-bytes=" << source.fetched_bytes
                            << '\n';
                    }
                    for (const sync::SyncContentLaneSnapshot &lane :
                         pull.lane_bindings) {
                        output
                            << "content-lane-job=" << pull.job_id
                            << " request=" << lane.request_id
                            << " source-id=" << lane.source_id
                            << " kind="
                            << static_cast<unsigned>(lane.kind)
                            << " index=" << lane.logical_index
                            << " bytes=" << lane.object_bytes
                            << " file=" << bytes_hex(lane.file_id)
                            << " file-number="
                            << (lane.file_number
                                    ? std::to_string(*lane.file_number)
                                    : "none")
                            << " carrier="
                            << (lane.transfer_carrier.carrier_class ==
                                        sync::SyncCarrierClass::auxiliary
                                    ? "auxiliary"
                                    : "primary")
                            << " route="
                            << bytes_hex(lane.transfer_carrier.route_key)
                            << " worker=" << lane.transfer_carrier.worker_id
                            << " root=" << (lane.root_manifest ? 1 : 0)
                            << " admitted="
                            << (lane.transport_admitted ? 1 : 0) << '\n';
                    }
                }
                for (const sync::TreeV2PullSnapshot &pull : tree_pulls) {
                    output
                        << "tree-job=" << pull.job_id
                        << " friend=" << pull.friend_number
                        << " epoch=" << pull.online_epoch
                        << " namespace=" << pull.namespace_id
                        << " state="
                        << sync::tree_v2_pull_state_name(pull.state)
                        << " custody="
                        << (pull.custody_complete ? "complete" : "partial")
                        << " manifest-file-objects="
                        << pull.manifest_file_objects
                        << " selected-file-objects="
                        << pull.selected_file_objects
                        << " skipped-file-objects="
                        << pull.skipped_file_objects
                        << " selected-paths=" << pull.selected_paths
                        << " skipped-paths=" << pull.skipped_paths
                        << " sources=" << pull.sources
                        << " availability-requests="
                        << pull.availability_requests
                        << " availability-results="
                        << pull.availability_results
                        << " absent-results=" << pull.absent_results
                        << " unavailable-results="
                        << pull.unavailable_results
                        << " active-lanes=" << pull.active_lanes
                        << " staged-file-objects="
                        << pull.staged_file_objects
                        << " file-commit-batches="
                        << pull.file_commit_batches
                        << " largest-file-commit-batch="
                        << pull.largest_file_commit_batch
                        << " cas-full-inventory-scans="
                        << pull.cas_full_inventory_scans
                        << " cas-inventory-objects-inspected="
                        << pull.cas_inventory_objects_inspected
                        << " requested=" << pull.requested_objects
                        << " committed=" << pull.committed_objects
                        << " reused=" << pull.reused_objects
                        << " fetched-bytes=" << pull.fetched_bytes
                        << " accepted-branches=" << pull.accepted_branches
                        << " conflicts=" << pull.conflicts
                        << " reconcile-local-events="
                        << pull.reconciliation.local_events
                        << " reconcile-branch-advances="
                        << pull.reconciliation.branch_advances
                        << " reconcile-source-inspected="
                        << pull.reconciliation.source_inspected_entries
                        << " reconcile-source-hashed="
                        << pull.reconciliation.source_hashed_file_digests
                        << " reconcile-source-reused="
                        << pull.reconciliation.source_reused_file_digests
                        << " reconcile-cas-inspected="
                        << pull.reconciliation.cas_inspected_objects
                        << " reconcile-cas-inspected-bytes="
                        << pull.reconciliation.cas_inspected_bytes
                        << " reconcile-cas-installed="
                        << pull.reconciliation.cas_installed_objects
                        << " reconcile-cas-installed-bytes="
                        << pull.reconciliation.cas_installed_bytes
                        << " reconcile-cas-reused="
                        << pull.reconciliation.cas_reused_objects
                        << " reconcile-projection-dirs="
                        << pull.reconciliation.projection_directories
                        << " reconcile-projection-files="
                        << pull.reconciliation.projection_files
                        << " reconcile-projection-bytes="
                        << pull.reconciliation.projection_bytes
                        << " reconcile-projection-conflict-files="
                        << pull.reconciliation.projection_conflict_files
                        << " reconcile-projection-conflict-tombstones="
                        << pull.reconciliation.projection_conflict_tombstones
                        << " reconcile-projection-preserved-entries="
                        << pull.reconciliation
                               .projection_preserved_unselected_entries
                        << " reconcile-projection-preserved-dirs="
                        << pull.reconciliation
                               .projection_preserved_unselected_directories
                        << " reconcile-projection-preserved-files="
                        << pull.reconciliation
                               .projection_preserved_unselected_files
                        << " reconcile-projection-preserved-bytes="
                        << pull.reconciliation
                               .projection_preserved_unselected_bytes
                        << " active-file="
                        << (pull.active_file_id
                                ? bytes_hex(*pull.active_file_id)
                                : "none")
                        << " active-file-number="
                        << (pull.active_file_number
                                ? std::to_string(*pull.active_file_number)
                                : "none")
                        << " detail=" << std::quoted(pull.detail) << '\n';
                    for (const sync::TreeV2LaneSnapshot &lane :
                         pull.lane_bindings) {
                        output
                            << "tree-lane-job=" << pull.job_id
                            << " request=" << lane.request_id
                            << " source-id=" << lane.source_id
                            << " kind="
                            << static_cast<unsigned>(lane.kind)
                            << " bytes=" << lane.object_bytes
                            << " file=" << bytes_hex(lane.file_id)
                            << " file-number="
                            << (lane.file_number
                                    ? std::to_string(*lane.file_number)
                                    : "none")
                            << " admitted="
                            << (lane.transport_admitted ? 1 : 0) << '\n';
                    }
                    for (const sync::TreeV2SourceSnapshot &source :
                         pull.source_snapshots) {
                        output
                            << "tree-source-job=" << pull.job_id
                            << " source-id=" << source.source_id
                            << " friend=" << source.friend_number
                            << " epoch=" << source.online_epoch
                            << " principal="
                            << bytes_hex(source.stable_principal)
                            << " online=" << (source.online ? 1 : 0)
                            << " requested=" << source.requested_objects
                            << " offered=" << source.offered_objects
                            << " absent=" << source.absent_objects
                            << " unavailable="
                            << source.unavailable_objects
                            << " committed=" << source.committed_objects
                            << " fetched-bytes=" << source.fetched_bytes
                            << '\n';
                    }
                }
                const std::string rendered = output.str();
                if (rendered.size() > local::kControlMaxPayloadSize) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "sync status exceeds local control capacity"});
                }
                return response_for(request, Status::success(),
                                    local::text_payload(rendered));
            }

            case local::ControlOperation::sync_pull:
            case local::ControlOperation::sync_pull_policy:
            case local::ControlOperation::sync_pull_route_policy: {
                const bool explicit_route_class =
                    request.operation ==
                    local::ControlOperation::sync_pull_route_policy;
                const bool explicit_failover =
                    request.operation != local::ControlOperation::sync_pull;
                const std::size_t prefix_bytes = 4U +
                                                 (explicit_failover ? 1U : 0U) +
                                                 (explicit_route_class ? 1U : 0U);
                if (request.payload.size() < prefix_bytes + 1U ||
                    request.payload.size() > prefix_bytes + 64U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-pull requires failover policy, friend "
                               "number, and one namespace id"});
                }
                if (sync_subscriber_ == nullptr) {
                    return response_for(request,
                                        Status{ErrorCode::unavailable,
                                               "synchronization is not enabled"});
                }
                sync::SyncRouteFailoverPolicy failover_policy =
                    config_.sync.route_failover_policy;
                sync::SyncRouteClassConstraint route_class =
                    sync::SyncRouteClassConstraint::any;
                std::size_t payload_offset = 0U;
                if (explicit_route_class) {
                    const std::uint8_t encoded = request.payload[0U];
                    if (encoded < static_cast<std::uint8_t>(
                                      sync::SyncRouteClassConstraint::any) ||
                        encoded > static_cast<std::uint8_t>(
                                      sync::SyncRouteClassConstraint::
                                          tox_i2p)) {
                        return response_for(
                            request, Status{ErrorCode::invalid_argument,
                                            "sync-pull route class is invalid"});
                    }
                    route_class =
                        static_cast<sync::SyncRouteClassConstraint>(encoded);
                    payload_offset = 1U;
                }
                if (explicit_failover) {
                    const std::uint8_t encoded = request.payload[payload_offset];
                    if (encoded != static_cast<std::uint8_t>(
                                       sync::SyncRouteFailoverPolicy::available) &&
                        encoded !=
                            static_cast<std::uint8_t>(
                                sync::SyncRouteFailoverPolicy::fail_closed)) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "sync-pull failover policy is invalid"});
                    }
                    failover_policy =
                        static_cast<sync::SyncRouteFailoverPolicy>(encoded);
                    ++payload_offset;
                }
                const std::uint32_t friend_number =
                    read_u32(std::span<const std::uint8_t>{request.payload}.subspan(
                        payload_offset));
                const std::string namespace_id(
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(payload_offset + 4U),
                    request.payload.end());
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-pull namespace id is invalid"});
                }
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) {
                    return response_for(request, policy.status());
                }
                auto session = sessions_.get(friend_number);
                if (!session || !protocol::is_application_ready(session.value()) ||
                    (session.value().negotiated.shared_features &
                     protocol::feature_bit(protocol::Feature::state_sync_v1)) ==
                        0U) {
                    return response_for(
                        request, Status{ErrorCode::unavailable,
                                        "peer has not negotiated state-sync-v1"});
                }
                std::scoped_lock authority_effect_lock(
                    ratox_authority_effect_mutex_);
                auto context =
                    sync_peer_context_locked(friend_number, session.value());
                if (!context) {
                    return response_for(request, context.status());
                }
                if (policy.value().engine == sync::Engine::tree_v2) {
                    if (sync_tree_subscriber_ == nullptr ||
                        sync_automation_store_ == nullptr || !identity_ ||
                        !sodium_) {
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "tree-v2 synchronization is not enabled"});
                    }
                    if (explicit_failover || explicit_route_class) {
                        return response_for(request,
                                            Status{ErrorCode::unsupported,
                                                   "tree-v2 currently uses its "
                                                   "primary authority lane"});
                    }
                    if ((session.value().negotiated.shared_features &
                         protocol::feature_bit(
                             protocol::Feature::state_sync_tree_v2)) == 0U) {
                        return response_for(
                            request,
                            Status{
                                ErrorCode::unavailable,
                                "peer has not negotiated state-sync-tree-v2"});
                    }
                    std::filesystem::path worktree;
                    {
                        std::scoped_lock automation_lock(
                            sync_automation_mutex_);
                        auto automations = live_sync_automation_policies();
                        if (!automations)
                            return response_for(request, automations.status());
                        const auto automation = std::find_if(
                            automations.value().begin(),
                            automations.value().end(),
                            [&namespace_id, &context](const auto &candidate) {
                                return candidate.namespace_id == namespace_id &&
                                       candidate.mode ==
                                           sync::SyncAutomationMode::
                                               bidirectional &&
                                       std::binary_search(
                                           candidate.source_principals.begin(),
                                           candidate.source_principals.end(),
                                           context.value()
                                               .peer_authority.remote_principal);
                            });
                        if (automation == automations.value().end()) {
                            return response_for(
                                request,
                                Status{ErrorCode::unavailable,
                                       "tree-v2 namespace has no matching "
                                       "bidirectional policy"});
                        }
                        worktree = automation->source_path;
                    }
                    for (const sync::TreeV2PullSnapshot &pull :
                         sync_tree_subscriber_->snapshot()) {
                        if (pull.friend_number == friend_number &&
                            pull.online_epoch == session.value().online_epoch &&
                            pull.namespace_id == namespace_id &&
                            pull.worktree == worktree &&
                            (pull.state ==
                                 sync::TreeV2PullState::awaiting_inventory ||
                             pull.state ==
                                 sync::TreeV2PullState::awaiting_object)) {
                            return response_for(
                                request, Status::success(),
                                local::text_payload(
                                    "sync-request-pending job=" +
                                    std::to_string(pull.job_id) +
                                    " namespace=" + namespace_id +
                                    " frames=0 engine=tree-v2 carrier=primary "
                                    "writable=1\n"));
                        }
                    }
                    auto initial = sync_tree_subscriber_->begin_pull(
                        context.value(), namespace_id, worktree);
                    if (!initial)
                        return response_for(request, initial.status());
                    const Status queued = send_sync_frame(
                        initial.value().context, initial.value().frame);
                    if (!queued.ok()) return response_for(request, queued);
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            "sync-request-queued job=" +
                            std::to_string(initial.value().frame.message_id) +
                            " namespace=" + namespace_id +
                            " frames=1 engine=tree-v2 carrier=primary "
                            "writable=1\n"));
                }
                if (policy.value().engine == sync::Engine::content_v2) {
                    if (sync_content_subscriber_ == nullptr) {
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "content-v2 synchronization is not enabled"});
                    }
                    if (explicit_failover && !explicit_route_class) {
                        return response_for(
                            request,
                            Status{ErrorCode::unsupported,
                                   "content-v2 failover policy requires an "
                                   "exact auxiliary route class"});
                    }
                    if (explicit_route_class &&
                        (route_class ==
                             sync::SyncRouteClassConstraint::any ||
                         failover_policy != sync::SyncRouteFailoverPolicy::
                                                fail_closed)) {
                        return response_for(
                            request,
                            Status{ErrorCode::unsupported,
                                   "content-v2 auxiliary routing requires a "
                                   "named route class and fail-closed policy"});
                    }
                    if ((session.value().negotiated.shared_features &
                         protocol::feature_bit(
                             protocol::Feature::state_sync_content_v2)) == 0U) {
                        return response_for(
                            request,
                            Status{
                                ErrorCode::unavailable,
                                "peer has not negotiated state-sync-content-v2"});
                    }
                    auto initial = sync_content_subscriber_->begin_pull(
                        context.value(), namespace_id);
                    std::vector<sync::SyncContentDispatch> frames;
                    if (initial) {
                        frames.push_back(std::move(initial).value());
                    } else if (initial.status().code() == ErrorCode::unavailable) {
                        auto retried = sync_content_subscriber_->retry_pull(
                            context.value(), namespace_id);
                        if (!retried) {
                            return response_for(request, retried.status());
                        }
                        frames = std::move(retried).value();
                    } else {
                        return response_for(request, initial.status());
                    }
                    std::uint64_t job_id = 0U;
                    sync::SyncTransferCarrier content_carrier;
                    for (const sync::SyncContentPullSnapshot &pull :
                         sync_content_subscriber_->snapshot()) {
                        if (pull.friend_number == friend_number &&
                            pull.online_epoch == session.value().online_epoch &&
                            pull.namespace_id == namespace_id) {
                            job_id = pull.job_id;
                            content_carrier = pull.primary_source_carrier;
                            break;
                        }
                    }
                    if (job_id == 0U) {
                        return response_for(
                            request,
                            Status{ErrorCode::internal_error,
                                   "content pull lost its live job identity"});
                    }
                    if (frames.empty()) {
                        if (explicit_route_class) {
                            return response_for(
                                request,
                                Status{
                                    ErrorCode::unavailable,
                                    "content pull has no unanswered request to retry"});
                        }
                        return response_for(
                            request, Status::success(),
                            local::text_payload(
                                "sync-request-pending job=" +
                                std::to_string(job_id) + " namespace=" +
                                namespace_id +
                                " frames=0 engine=content-v2 carrier=primary "
                                "head-carrier=primary failover=none\n"));
                    }
                    std::string carrier_name = "primary";
                    std::string content_failover = "none";
                    if (explicit_route_class) {
                        std::vector<AuxiliarySyncCarrierState> candidates =
                            current_auxiliary_sync_carriers();
                        candidates.erase(
                            std::remove_if(
                                candidates.begin(), candidates.end(),
                                [](const AuxiliarySyncCarrierState &candidate) {
                                    return !candidate
                                                .content_transfer_negotiated;
                                }),
                            candidates.end());
                        if (content_carrier.carrier_class ==
                            sync::SyncCarrierClass::primary) {
                            auto selected = sync::select_sync_route(
                                config_.sync.route_selection_policy,
                                candidates,
                                context.value()
                                    .peer_authority.remote_principal,
                                std::nullopt, 1U, route_class);
                            if (!selected) {
                                return response_for(request,
                                                    selected.status());
                            }
                            auto auxiliary = auxiliary_sync_context_locked(
                                selected.value().carrier,
                                context.value()
                                    .peer_authority.remote_principal);
                            if (!auxiliary) {
                                return response_for(request,
                                                    auxiliary.status());
                            }
                            const Status bound =
                                sync_content_subscriber_->bind_source_carrier(
                                    job_id, auxiliary.value());
                            if (!bound.ok()) {
                                return response_for(request, bound);
                            }
                        } else {
                            const auto retained = std::find_if(
                                candidates.begin(), candidates.end(),
                                [&content_carrier, route_class](
                                    const AuxiliarySyncCarrierState &candidate) {
                                    return candidate.carrier ==
                                               content_carrier &&
                                           sync::sync_route_class_matches(
                                               route_class,
                                               candidate.network);
                                });
                            if (retained == candidates.end()) {
                                return response_for(
                                    request,
                                    Status{
                                        ErrorCode::unavailable,
                                        "frozen auxiliary content carrier is "
                                        "not ready in the requested class"});
                            }
                        }
                        carrier_name = std::string(
                            sync::to_string(route_class));
                        content_failover = "fail-closed";
                    }
                    for (const sync::SyncContentDispatch &frame : frames) {
                        const Status queued =
                            send_sync_frame(frame.context, frame.frame);
                        if (!queued.ok()) {
                            return response_for(request, queued);
                        }
                    }
                    // An active pull can have every control result while its
                    // file receive is still in flight. That is healthy
                    // pending work, not an automation failure: exponential
                    // retry backoff here can otherwise hide the next HEAD.
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            std::string("sync-request-queued job=") +
                            std::to_string(job_id) +
                            " namespace=" + namespace_id +
                            " frames=" + std::to_string(frames.size()) +
                            " engine=content-v2 carrier=" + carrier_name +
                            " head-carrier=primary failover=" +
                            content_failover + "\n"));
                }
                auto initial = sync_subscriber_->begin_pull(
                    context.value(), namespace_id, failover_policy, route_class);
                std::vector<protocol::Frame> frames;
                if (initial) {
                    frames.push_back(std::move(initial).value());
                } else if (initial.status().code() == ErrorCode::unavailable) {
                    for (const sync::SyncPullSnapshot &pull :
                         sync_subscriber_->snapshot()) {
                        if (pull.friend_number == friend_number &&
                            pull.online_epoch == session.value().online_epoch &&
                            pull.namespace_id == namespace_id) {
                            context.value().transfer_carrier =
                                pull.transfer_carrier;
                            if (pull.transfer_carrier.carrier_class ==
                                sync::SyncCarrierClass::auxiliary) {
                                auto auxiliary = auxiliary_sync_context_locked(
                                    pull.transfer_carrier,
                                    context.value()
                                        .peer_authority.remote_principal);
                                if (!auxiliary) {
                                    return response_for(request,
                                                        auxiliary.status());
                                }
                                context.value() = std::move(auxiliary).value();
                            }
                            break;
                        }
                    }
                    auto retried =
                        sync_subscriber_->retry_pull(context.value(), namespace_id,
                                                     failover_policy, route_class);
                    if (!retried) {
                        return response_for(request, retried.status());
                    }
                    frames = std::move(retried).value();
                } else {
                    return response_for(request, initial.status());
                }
                for (const protocol::Frame &frame : frames) {
                    const Status queued = send_sync_frame(context.value(), frame);
                    if (!queued.ok()) {
                        return response_for(request, queued);
                    }
                }
                std::uint64_t job_id = 0U;
                for (const sync::SyncPullSnapshot &pull :
                     sync_subscriber_->snapshot()) {
                    if (pull.friend_number == friend_number &&
                        pull.online_epoch == session.value().online_epoch &&
                        pull.namespace_id == namespace_id) {
                        job_id = pull.job_id;
                        break;
                    }
                }
                if (job_id == 0U) {
                    return response_for(
                        request, Status{ErrorCode::internal_error,
                                        "sync pull lost its live job identity"});
                }
                // Empty retry output means the active job is waiting only on
                // its already-admitted transport receive. Report a successful
                // pending observation so periodic follow does not back off.
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        std::string(frames.empty()
                                        ? "sync-request-pending job="
                                        : "sync-request-queued job=") +
                        std::to_string(job_id) +
                        " namespace=" + namespace_id +
                        " frames=" + std::to_string(frames.size()) + " failover=" +
                        std::string(sync::to_string(failover_policy)) +
                        " route-class=" +
                        std::string(sync::to_string(route_class)) + "\n"));
            }

            case local::ControlOperation::sync_publish: {
                if (sync_publisher_ == nullptr || !identity_ || !sodium_) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "synchronization is not enabled"});
                }
                if (request.payload.size() < 3U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-publish requires a namespace and absolute file path"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                const std::size_t path_offset = 1U + namespace_bytes;
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() <= path_offset) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-publish namespace encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() +
                        static_cast<std::ptrdiff_t>(path_offset));
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-publish namespace id is invalid"});
                }
                auto source = decode_absolute_path(
                    request.payload, path_offset);
                if (!source) return response_for(request, source.status());
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy) return response_for(request, policy.status());
                if (policy.value().engine == sync::Engine::tree_v2) {
                    auto transaction =
                        sync::SyncNamespaceTransaction::acquire(policy.value());
                    if (!transaction)
                        return response_for(request, transaction.status());
                    auto tree_witness =
                        tree_v2_state_witness(policy.value());
                    if (!tree_witness)
                        return response_for(request, tree_witness.status());
                    auto reconciled = reconcile_tree_v2_workspace_cached(
                        policy.value(), source.value(), transaction.value(),
                        tree_witness.value());
                    if (!reconciled)
                        return response_for(request, reconciled.status());
                    return response_for(
                        request, Status::success(),
                        local::text_payload(
                            "sync-published namespace=" + namespace_id +
                            " engine=tree-v2 local-events=" +
                            std::to_string(reconciled.value().local_events) +
                            " branch-advances=" +
                            std::to_string(reconciled.value().branch_advances) +
                            " conflicts=" +
                            std::to_string(reconciled.value().conflicts) +
                            " source-inspected=" +
                            std::to_string(
                                reconciled.value()
                                    .source_inspected_entries) +
                            " source-hashed=" +
                            std::to_string(
                                reconciled.value()
                                    .source_hashed_file_digests) +
                            " source-reused=" +
                            std::to_string(
                                reconciled.value()
                                    .source_reused_file_digests) +
                            " cas-inspected=" +
                            std::to_string(
                                reconciled.value().cas_inspected_objects) +
                            " cas-inspected-bytes=" +
                            std::to_string(
                                reconciled.value().cas_inspected_bytes) +
                            " cas-installed=" +
                            std::to_string(
                                reconciled.value().cas_installed_objects) +
                            " cas-installed-bytes=" +
                            std::to_string(
                                reconciled.value().cas_installed_bytes) +
                            " cas-reused=" +
                            std::to_string(
                                reconciled.value().cas_reused_objects) +
                            " projection-dirs=" +
                            std::to_string(
                                reconciled.value().projection_directories) +
                            " projection-files=" +
                            std::to_string(
                                reconciled.value().projection_files) +
                            " projection-bytes=" +
                            std::to_string(
                                reconciled.value().projection_bytes) +
                            " projection-conflict-files=" +
                            std::to_string(
                                reconciled.value()
                                    .projection_conflict_files) +
                            " projection-conflict-tombstones=" +
                            std::to_string(
                                reconciled.value()
                                    .projection_conflict_tombstones) +
                            " projection-preserved-entries=" +
                            std::to_string(
                                reconciled.value()
                                    .projection_preserved_unselected_entries) +
                            " projection-preserved-dirs=" +
                            std::to_string(
                                reconciled.value()
                                    .projection_preserved_unselected_directories) +
                            " projection-preserved-files=" +
                            std::to_string(
                                reconciled.value()
                                    .projection_preserved_unselected_files) +
                            " projection-preserved-bytes=" +
                            std::to_string(
                                reconciled.value()
                                    .projection_preserved_unselected_bytes) +
                            "\n"));
                }
                if (policy.value().engine == sync::Engine::content_v2) {
                    auto witness = sync_guarded_state_witness(policy.value());
                    if (!witness)
                        return response_for(request, witness.status());
                    sync::SignedHeadStore head_store(
                        policy.value().root, witness.value());
                    sync::SyncContentPublicationConfig content_config;
                    content_config.maximum_chunk_bytes =
                        static_cast<std::uint32_t>(std::min<std::uint64_t>(
                            content_config.maximum_chunk_bytes,
                            std::min(
                                policy.value().quotas.maximum_artifact_bytes,
                                policy.value().quotas.maximum_staging_bytes)));
                    content_config.minimum_chunk_bytes = std::min(
                        content_config.minimum_chunk_bytes,
                        content_config.maximum_chunk_bytes);
                    content_config.average_chunk_bytes = std::clamp(
                        content_config.average_chunk_bytes,
                        content_config.minimum_chunk_bytes,
                        content_config.maximum_chunk_bytes);
                    sync::SyncContentPublicationSeams content_seams;
                    content_seams.cancel_requested = [this] {
                        return !running_.load() ||
                            shutdown_requested_.load();
                    };
                    auto published =
                        sync::publish_local_content_revision(
                            policy.value(), source.value(), *identity_,
                            *sodium_, head_store, content_config,
                            std::move(content_seams));
                    if (!published) {
                        return response_for(request, published.status());
                    }
                    const auto &result = published.value();
                    std::ostringstream output;
                    output << "namespace=" << namespace_id
                           << " generation="
                           << result.publication.head.generation
                           << " record="
                           << bytes_hex(result.publication.record)
                           << " artifact=" << bytes_hex(result.artifact)
                           << " manifest=" << bytes_hex(result.manifest)
                           << " artifact-bytes="
                           << result.artifact_bytes
                           << " manifest-bytes="
                           << result.manifest_bytes
                           << " duplicate="
                           << (result.publication.duplicate ? 1 : 0)
                           << " kind=content-v2 format="
                           << (result.format ==
                                       sync::SyncContentPublicationFormat::flat
                                   ? "flat"
                                   : "paged")
                           << " chunks=" << result.chunks
                           << " pages=" << result.pages
                           << " objects=" << result.unique_objects
                           << " objects-installed="
                           << result.objects_installed
                           << " objects-reused="
                           << result.objects_reused
                           << " bytes-copied=" << result.bytes_copied
                           << '\n';
                    return response_for(
                        request, Status::success(),
                        local::text_payload(output.str()));
                }
                if (policy.value().engine != sync::Engine::range_v1 &&
                    policy.value().engine != sync::Engine::treepack_v1) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "sync-publish supports range-v1 files and "
                               "treepack-v1 directories"});
                }
                std::filesystem::path publication_artifact = source.value();
                std::optional<sync::SyncTreepackStats> tree_stats;
                std::unique_ptr<ScopedExactFileRemoval> remove_tree;
                if (policy.value().engine == sync::Engine::treepack_v1) {
                    auto tree_workspace = allocate_sync_publication_workspace(
                        policy.value(), ".treepack");
                    if (!tree_workspace) {
                        return response_for(request, tree_workspace.status());
                    }
                    publication_artifact = tree_workspace.value();
                    remove_tree = std::make_unique<ScopedExactFileRemoval>(
                        publication_artifact);
                    auto packed = sync::build_sync_treepack(
                        policy.value(), source.value(), publication_artifact);
                    if (!packed) {
                        return response_for(request, packed.status());
                    }
                    tree_stats = packed.value();
                }
                auto workspace = allocate_sync_publication_workspace(
                    policy.value(), ".range-index");
                if (!workspace) {
                    return response_for(request, workspace.status());
                }
                ScopedExactFileRemoval remove_manifest(workspace.value());
                auto manifest = sync::build_sync_range_manifest(
                    policy.value(), publication_artifact, workspace.value());
                if (!manifest) {
                    return response_for(request, manifest.status());
                }
                sync::SyncInstallSeams seams;
                seams.hash_file = sync::hash_sync_file_sha256;
                seams.cancel_requested = [this] {
                    return !running_.load() || shutdown_requested_.load();
                };
                const sync::NamespacePolicy frozen_policy = policy.value();
                seams.validate_revision_sources =
                    [frozen_policy](
                        const std::filesystem::path &artifact,
                        const std::filesystem::path &manifest_path,
                        const sync::Digest &artifact_digest,
                        std::uint64_t artifact_bytes,
                        std::uint64_t manifest_bytes) {
                        return sync::verify_sync_range_manifest(
                            frozen_policy, artifact, manifest_path,
                            artifact_digest, artifact_bytes,
                            manifest_bytes);
                    };
                auto witness = sync_guarded_state_witness(policy.value());
                if (!witness)
                    return response_for(request, witness.status());
                sync::SignedHeadStore head_store(
                    policy.value().root, witness.value());
                auto published = sync::publish_local_revision(
                    {policy.value(), publication_artifact, workspace.value()},
                    *identity_, *sodium_, head_store, seams);
                if (!published) {
                    return response_for(request, published.status());
                }
                const auto &result = published.value().publication;
                std::ostringstream output;
                output << "namespace=" << namespace_id
                       << " generation=" << result.head.generation
                       << " record=" << bytes_hex(result.record)
                       << " artifact=" << bytes_hex(result.head.artifact)
                       << " manifest=" << bytes_hex(result.head.manifest)
                       << " artifact-bytes="
                       << result.head.artifact_bytes
                       << " manifest-bytes="
                       << result.head.manifest_bytes
                       << " duplicate="
                       << (result.duplicate ? 1 : 0);
                if (tree_stats.has_value()) {
                    output << " kind=treepack"
                           << " directories=" << tree_stats->directories
                           << " files=" << tree_stats->files
                           << " content-bytes=" << tree_stats->content_bytes;
                }
                output << '\n';
                return response_for(
                    request, Status::success(),
                    local::text_payload(output.str()));
            }

            case local::ControlOperation::sync_activate: {
                if (sync_subscriber_ == nullptr || !identity_ || !sodium_) {
                    return response_for(request,
                                        Status{ErrorCode::unavailable,
                                               "synchronization is not enabled"});
                }
                if (request.payload.empty()) {
                    return response_for(request,
                                        Status{ErrorCode::invalid_argument,
                                               "sync-activate requires a namespace "
                                               "and exact HEAD record"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                if (namespace_bytes == 0U || namespace_bytes > 64U ||
                    request.payload.size() !=
                        1U + namespace_bytes + sync::Digest{}.size()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "sync-activate payload encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() + 1 +
                        static_cast<std::ptrdiff_t>(namespace_bytes));
                if (!sync::valid_namespace_id(namespace_id)) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "sync-activate namespace id is invalid"});
                }
                sync::Digest expected{};
                std::copy_n(request.payload.begin() + 1 +
                                static_cast<std::ptrdiff_t>(namespace_bytes),
                            expected.size(), expected.begin());
                auto policy = sync_namespaces_.resolve(namespace_id);
                if (!policy)
                    return response_for(request, policy.status());
                sync::SyncActivationSeams seams;
                std::optional<sync::SyncTreeActivationResult> tree_activation;
                seams.hash_file = sync::hash_sync_file_sha256;
                auto witness = sync_guarded_state_witness(policy.value());
                if (!witness)
                    return response_for(request, witness.status());
                seams.guarded_state_witness = witness.value();
                if (policy.value().engine == sync::Engine::content_v2) {
                    seams.resolve_artifact_path =
                        [](const sync::NamespacePolicy &namespace_policy,
                           const sync::AcceptedHead &accepted) {
                            return Result<std::filesystem::path>{
                                sync::sync_content_object_path(namespace_policy,
                                                               accepted.artifact)};
                        };
                    seams.resolve_manifest_path =
                        [](const sync::NamespacePolicy &namespace_policy,
                           const sync::AcceptedHead &accepted) {
                            return Result<std::filesystem::path>{
                                sync::sync_content_object_path(namespace_policy,
                                                               accepted.manifest)};
                        };
                    seams.validate_revision = sync::verify_sync_content_revision;
                } else {
                    seams.validate_revision =
                        [](const sync::NamespacePolicy &namespace_policy,
                           const sync::AcceptedHead &accepted,
                           const std::filesystem::path &artifact,
                           const std::filesystem::path &manifest) {
                            return sync::verify_sync_range_manifest(
                                namespace_policy, artifact, manifest,
                                accepted.artifact, accepted.artifact_bytes,
                                accepted.manifest_bytes);
                        };
                }
                if (policy.value().engine == sync::Engine::treepack_v1) {
                    seams.project_revision =
                        [&tree_activation](
                            const sync::NamespacePolicy &namespace_policy,
                            const sync::ActivatedRevision &revision,
                            const std::filesystem::path &artifact,
                            const sync::SyncNamespaceTransaction &transaction) {
                            auto projected = sync::materialize_sync_treepack(
                                namespace_policy, revision, artifact, transaction);
                            if (!projected)
                                return projected.status();
                            tree_activation = projected.value();
                            return Status::success();
                        };
                }
                auto activated = sync::activate_staged_artifact(
                    {policy.value(), expected}, *identity_, *sodium_, seams);
                if (!activated) {
                    return response_for(request, activated.status());
                }
                if (!activated.value().active() || !activated.value().revision) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "sync activation refused: " +
                                   std::string(sync::activation_decision_name(
                                       activated.value().decision))});
                }
                const sync::ActivatedRevision &revision =
                    *activated.value().revision;
                std::ostringstream output;
                output << "namespace=" << namespace_id << " decision="
                       << sync::activation_decision_name(activated.value().decision)
                       << " generation=" << revision.generation
                       << " record=" << bytes_hex(revision.record)
                       << " artifact=" << bytes_hex(revision.artifact)
                       << " artifact-bytes=" << revision.artifact_bytes;
                if (tree_activation.has_value()) {
                    output << " kind=treepack"
                           << " directories=" << tree_activation->tree.directories
                           << " files=" << tree_activation->tree.files
                           << " content-bytes="
                           << tree_activation->tree.content_bytes
                           << " materialized="
                           << (tree_activation->materialized ? 1 : 0)
                           << " already-current="
                           << (tree_activation->already_current ? 1 : 0)
                           << " recovered-staging-trees="
                           << tree_activation->recovered_staging_trees
                           << " recovered-pointer-temporaries="
                           << tree_activation->recovered_pointer_temporaries
                           << " pruned-revision-trees="
                           << tree_activation->pruned_revision_trees;
                }
                output << '\n';
                return response_for(request, Status::success(),
                                    local::text_payload(output.str()));
            }

            case local::ControlOperation::update_status: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "update-status payload must be empty"});
                }
                std::scoped_lock update_lock(update_operation_mutex_);
                auto rendered = render_update_status();
                return rendered.ok()
                    ? response_for(request, Status::success(),
                                   std::move(rendered).value())
                    : response_for(request, rendered.status());
            }

            case local::ControlOperation::update_stage: {
                if (update_store_ == nullptr || !identity_.has_value() ||
                    !sodium_.has_value()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "signed updates are not enabled"});
                }
                if (request.payload.empty()) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "update-stage requires a namespace "
                                        "and exact accepted HEAD record"});
                }
                const std::size_t namespace_bytes = request.payload[0U];
                if (namespace_bytes == 0U || namespace_bytes > 63U ||
                    request.payload.size() !=
                        1U + namespace_bytes + sync::Digest{}.size()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "update-stage payload encoding is invalid"});
                }
                const std::string namespace_id(
                    request.payload.begin() + 1,
                    request.payload.begin() + 1 +
                        static_cast<std::ptrdiff_t>(namespace_bytes));
                sync::Digest expected_head{};
                std::copy_n(
                    request.payload.begin() + 1 +
                        static_cast<std::ptrdiff_t>(namespace_bytes),
                    expected_head.size(), expected_head.begin());
                std::scoped_lock update_lock(update_operation_mutex_);
                auto staged = stage_update_head(namespace_id, expected_head);
                if (!staged.ok()) {
                    return response_for(request, staged.status());
                }
                auto rendered = render_update_status();
                if (!rendered.ok()) {
                    return response_for(request, rendered.status());
                }
                std::string output =
                    "staged=" +
                    std::to_string(staged.value().duplicate ? 0 : 1) +
                    " manifest-record=" +
                    bytes_hex(
                        staged.value().state.candidate.manifest_record) +
                    "\n" + local::payload_text(rendered.value());
                return response_for(
                    request, Status::success(),
                    local::text_payload(output));
            }

            case local::ControlOperation::update_apply: {
                if (update_store_ == nullptr ||
                    !protocol_incarnation_lease_.has_value()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "signed updates are not enabled"});
                }
                if (request.payload.size() != sync::Digest{}.size()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "update-apply requires one exact manifest record"});
                }
                sync::Digest expected{};
                std::copy(request.payload.begin(), request.payload.end(),
                          expected.begin());
                std::scoped_lock update_lock(update_operation_mutex_);
                auto applied = update_store_->apply(
                    expected, protocol_incarnation_lease_->incarnation());
                if (!applied.ok()) {
                    return response_for(request, applied.status());
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        "health-token=" +
                        security::hex(applied.value().health_token) +
                        " restart-required=1 candidate-sequence=" +
                        std::to_string(
                            applied.value().state.candidate.sequence) +
                        "\n"));
            }

            case local::ControlOperation::update_confirm: {
                if (update_store_ == nullptr ||
                    !protocol_incarnation_lease_.has_value()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "signed updates are not enabled"});
                }
                if (request.payload.size() != update::HealthToken{}.size()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "update-confirm requires one exact health token"});
                }
                update::HealthToken token{};
                std::copy(request.payload.begin(), request.payload.end(),
                          token.begin());
                std::scoped_lock update_lock(update_operation_mutex_);
                if (update_store_->policy().payload_kind ==
                    update::PayloadKind::linux_service_v1) {
                    const Status observed =
                        update_service_adapter_ == nullptr
                            ? Status{
                                  ErrorCode::unavailable,
                                  "linux service adapter is absent"}
                            : update_service_adapter_->poll();
                    const std::optional<update::UpdateState> state =
                        update_store_->snapshot();
                    const update::LinuxServiceSnapshot service =
                        update_service_adapter_ == nullptr
                            ? update::LinuxServiceSnapshot{}
                            : update_service_adapter_->snapshot();
                    if (!observed.ok() ||
                        update_service_adapter_ == nullptr ||
                        !update_service_adapter_->healthy() ||
                        !service.candidate || !state.has_value() ||
                        state->phase !=
                            update::UpdatePhase::awaiting_health ||
                        service.release_sequence !=
                            state->candidate.sequence) {
                        security::secure_wipe(token);
                        return response_for(
                            request,
                            Status{ErrorCode::unavailable,
                                   "linux-service-v1 confirmation requires "
                                   "the live exact ready candidate"});
                    }
                }
                auto confirmed = update_store_->confirm(
                    token, protocol_incarnation_lease_->incarnation());
                security::secure_wipe(token);
                if (!confirmed.ok()) {
                    return response_for(request, confirmed.status());
                }
                if (update_service_adapter_ != nullptr) {
                    const Status promoted =
                        update_service_adapter_->mark_confirmed();
                    if (!promoted.ok()) {
                        return response_for(
                            request,
                            Status{promoted.code(),
                                   "update confirmed but linux service "
                                   "adapter promotion failed: " +
                                       promoted.message()});
                    }
                }
                {
                    std::scoped_lock lock(update_health_mutex_);
                    update_health_deadline_.reset();
                }
                auto rendered = render_update_status();
                return rendered.ok()
                    ? response_for(request, Status::success(),
                                   std::move(rendered).value())
                    : response_for(request, rendered.status());
            }

            case local::ControlOperation::update_gc: {
                if (update_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::unavailable,
                               "signed updates are not enabled"});
                }
                if (request.payload.size() != 1U ||
                    request.payload.front() > 1U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "update-gc requires dry-run or quarantine"});
                }
                const update::UpdateRetentionMode mode =
                    request.payload.front() == 0U
                        ? update::UpdateRetentionMode::dry_run
                        : update::UpdateRetentionMode::quarantine;
                std::scoped_lock update_lock(update_operation_mutex_);
                auto retained = update_store_->retain_slots(mode);
                if (!retained.ok()) {
                    return response_for(request, retained.status());
                }
                const update::UpdateRetentionResult &result =
                    retained.value();
                std::ostringstream output;
                output << "mode="
                       << (mode == update::UpdateRetentionMode::dry_run
                               ? "dry-run"
                               : "quarantine")
                       << " state-generation=" << result.state_generation
                       << " active-slots=" << result.active_slots
                       << " protected-slots=" << result.protected_slots
                       << " eligible-slots=" << result.eligible_slots
                       << " eligible-bytes=" << result.eligible_bytes
                       << " quarantined-slots="
                       << result.quarantined_slots
                       << " quarantined-bytes="
                       << result.quarantined_bytes
                       << " prior-quarantine-slots="
                       << result.prior_quarantine_slots
                       << " purge=absent\n";
                return response_for(
                    request, Status::success(),
                    local::text_payload(output.str()));
            }

            case local::ControlOperation::shutdown:
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument, "shutdown payload must be empty"});
                }
                {
                    std::scoped_lock durable_lock(durable_command_mutex_);
                    command_admission_open_.store(false);
                }
                shutdown_requested_.store(true);
                return response_for(
                    request, Status::success(), local::text_payload("shutdown-requested\n"));

            case local::ControlOperation::self_profile: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "self-profile payload must be empty"});
                }
                auto profile = refresh_profile();
                if (!profile) {
                    return response_for(request, profile.status());
                }
                auto encoded = local::encode_self_profile(profile.value());
                if (!encoded) {
                    return response_for(request, encoded.status());
                }
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(), std::move(encoded).value());
            }

            case local::ControlOperation::self_set_name: {
                if (request.payload.size() > toxcore::abi::kMaxNameLength) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "self name exceeds 128 bytes"});
                }
                const Status changed = transport_.set_self_name(request.payload);
                if (!changed.ok()) {
                    return response_for(request, changed);
                }
                auto profile = refresh_profile();
                if (!profile) {
                    return response_for(request, profile.status());
                }
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(), local::text_payload("profile-name-updated\n"));
            }

            case local::ControlOperation::self_set_status_message: {
                if (request.payload.size() > toxcore::abi::kMaxStatusMessageLength) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "self status message exceeds 1007 bytes"});
                }
                const Status changed =
                    transport_.set_self_status_message(request.payload);
                if (!changed.ok()) {
                    return response_for(request, changed);
                }
                auto profile = refresh_profile();
                if (!profile) {
                    return response_for(request, profile.status());
                }
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(),
                    local::text_payload("profile-status-message-updated\n"));
            }

            case local::ControlOperation::self_set_status: {
                if (request.payload.size() != 1U || request.payload[0] > 2U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "self status must be one byte: 0=available, 1=away, 2=busy"});
                }
                const PresenceStatus presence =
                    request.payload[0] == 1U ? PresenceStatus::away
                    : request.payload[0] == 2U ? PresenceStatus::busy
                                               : PresenceStatus::available;
                const Status changed = transport_.set_self_status(presence);
                if (!changed.ok()) {
                    return response_for(request, changed);
                }
                auto profile = refresh_profile();
                if (!profile) {
                    return response_for(request, profile.status());
                }
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(), local::text_payload("profile-status-updated\n"));
            }

            case local::ControlOperation::transport_peer_request: {
                if (request.payload.size() <= toxcore::abi::kAddressSize ||
                    request.payload.size() > toxcore::abi::kAddressSize +
                                                 toxcore::abi::kMaxFriendRequestLength) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-peer-request requires a 38-byte "
                               "Tox address and a 1..921-byte message"});
                }
                const std::span<const std::uint8_t> address(
                    request.payload.data(), toxcore::abi::kAddressSize);
                const std::span<const std::uint8_t> message(
                    request.payload.data() + toxcore::abi::kAddressSize,
                    request.payload.size() - toxcore::abi::kAddressSize);
                auto friend_number = request_transport_peer(
                    address, message, "control-socket");
                if (!friend_number) {
                    return response_for(request, friend_number.status());
                }
                return response_for(
                    request, Status::success(), u32_payload(friend_number.value()));
            }

            case local::ControlOperation::transport_peer_add: {
                if (request.payload.size() != toxcore::abi::kPublicKeySize) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-peer-accept requires one 32-byte Tox public key"});
                }
                auto friend_number = accept_transport_peer(
                    request.payload, false, "control-socket",
                    "peer-add-norequest");
                if (!friend_number) {
                    return response_for(request, friend_number.status());
                }
                return response_for(
                    request, Status::success(), u32_payload(friend_number.value()));
            }

            case local::ControlOperation::transport_peer_remove: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-peer-remove requires one uint32 friend number"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                const Status removed = remove_transport_peer(
                    friend_number, "control-socket");
                if (!removed.ok()) {
                    return response_for(request, removed);
                }
                return response_for(
                    request, Status::success(), local::text_payload("transport-peer-removed\n"));
            }

            case local::ControlOperation::transport_peer_remove_key: {
                if (request.payload.size() != toxcore::abi::kPublicKeySize) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-peer-remove-key requires one "
                               "32-byte Tox public key"});
                }
                const Status removed = remove_transport_peer_by_public_key(
                    request.payload, "control-socket");
                if (!removed.ok()) {
                    return response_for(request, removed);
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload("transport-peer-removed\n"));
            }

            case local::ControlOperation::transport_peer_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-peer-list payload must be empty"});
                }
                auto peers = refresh_peers();
                if (!peers) {
                    return response_for(request, peers.status());
                }
                publish_snapshot_best_effort();
                auto encoded = local::encode_peer_list(peers.value());
                if (!encoded) {
                    return response_for(request, encoded.status());
                }
                return response_for(
                    request, Status::success(), std::move(encoded).value());
            }

            case local::ControlOperation::transport_friend_request_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "friend-request-list payload must be empty"});
                }
                auto encoded = local::encode_friend_request_list(
                    pending_friend_requests());
                if (!encoded) {
                    return response_for(request, encoded.status());
                }
                return response_for(
                    request, Status::success(), std::move(encoded).value());
            }

            case local::ControlOperation::transport_friend_request_reject: {
                if (request.payload.size() != toxcore::abi::kPublicKeySize) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "friend-request-reject requires one 32-byte public key"});
                }
                const Status forgotten = reject_pending_friend_request(
                    request.payload, "control-socket");
                return response_for(
                    request, forgotten,
                    local::text_payload("friend-request-rejected\n"));
            }

            case local::ControlOperation::transport_friend_request_accept: {
                if (request.payload.size() != toxcore::abi::kPublicKeySize) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "friend-request-accept requires one 32-byte public key"});
                }
                auto friend_number = accept_transport_peer(
                    request.payload, true, "control-socket",
                    "request-accept");
                if (!friend_number) {
                    return response_for(request, friend_number.status());
                }
                return response_for(
                    request, Status::success(),
                    u32_payload(friend_number.value()));
            }

            case local::ControlOperation::transport_send_message: {
                if (request.payload.size() <= 5U ||
                    request.payload.size() >
                        5U + toxcore::abi::kMaxMessageLength) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-send-message requires friend "
                               "number, kind, and 1..1372 message bytes"});
                }
                const std::uint8_t raw_kind = request.payload[4U];
                if (raw_kind > 1U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport message kind must be 0=normal or 1=action"});
                }
                const TextMessageKind kind = raw_kind == 1U
                                                 ? TextMessageKind::action
                                                 : TextMessageKind::normal;
                std::vector<std::uint8_t> message(
                    request.payload.begin() + 5, request.payload.end());
                auto message_id = send_human_message(
                    read_u32(request.payload), kind, message);
                if (!message_id) {
                    return response_for(request, message_id.status());
                }
                return response_for(
                    request, Status::success(), u32_payload(message_id.value()));
            }

            case local::ControlOperation::transport_message_probe: {
                if (request.payload.size() <= 8U ||
                    request.payload.size() >
                        8U + toxcore::abi::kMaxMessageLength) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "transport-message-probe requires friend number, "
                            "timeout, and 1..1372 message bytes"});
                }
                const std::uint32_t timeout_ms =
                    read_u32(std::span<const std::uint8_t>(request.payload).subspan(4U));
                if (timeout_ms == 0U || timeout_ms > 600000U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-message-probe timeout must be 1..600000 ms"});
                }
                const std::vector<std::uint8_t> message(
                    request.payload.begin() + 8, request.payload.end());
                auto result = probe_human_message(
                    read_u32(request.payload),
                    std::chrono::milliseconds(timeout_ms), message);
                if (!result) {
                    return response_for(request, result.status());
                }
                std::vector<std::uint8_t> payload;
                payload.reserve(12U);
                append_u32(payload, result.value().first);
                append_u64(payload, result.value().second);
                return response_for(
                    request, Status::success(), std::move(payload));
            }

            case local::ControlOperation::transport_packet_probe: {
                if (request.payload.size() != 9U ||
                    (request.payload[8U] != 1U && request.payload[8U] != 2U)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-packet-probe requires friend number, "
                               "timeout, and 1=lossless or 2=lossy"});
                }
                const std::uint32_t timeout_ms =
                    read_u32(std::span<const std::uint8_t>(request.payload).subspan(4U));
                if (timeout_ms == 0U || timeout_ms > 600000U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-packet-probe timeout must be 1..600000 ms"});
                }
                const interactive::ProbeCarrier carrier = request.payload[8U] == 2U
                    ? interactive::ProbeCarrier::lossy
                    : interactive::ProbeCarrier::lossless;
                auto result = probe_custom_packet(
                    read_u32(request.payload), carrier,
                    std::chrono::milliseconds(timeout_ms));
                if (!result) {
                    return response_for(request, result.status());
                }
                std::vector<std::uint8_t> payload;
                payload.reserve(16U);
                append_u64(payload, result.value().first);
                append_u64(payload, result.value().second);
                return response_for(
                    request, Status::success(), std::move(payload));
            }

            case local::ControlOperation::transport_packet_probe_burst: {
                if ((request.payload.size() != 13U &&
                     request.payload.size() != 15U) ||
                    (request.payload[8U] != 1U && request.payload[8U] != 2U)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-packet-probe-burst requires friend, "
                               "deadline, carrier, count, and spacing"});
                }
                const std::uint32_t deadline_ms = read_u32(
                    std::span<const std::uint8_t>(request.payload).subspan(4U));
                const std::uint16_t count = read_u16(request.payload, 9U);
                const std::uint16_t spacing_ms = read_u16(request.payload, 11U);
                const std::uint16_t packet_size = request.payload.size() == 15U
                    ? read_u16(request.payload, 13U)
                    : static_cast<std::uint16_t>(interactive::kProbePacketSize);
                if (deadline_ms == 0U || deadline_ms > 10000U ||
                    count == 0U || count > 128U || spacing_ms > 1000U ||
                    packet_size < interactive::kProbePacketSize ||
                    packet_size > interactive::kMaximumResearchProbePacketSize) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "packet probe burst requires deadline "
                                        "1..10000 ms, count "
                                        "1..128, spacing 0..1000 ms, and "
                                        "packet size 10..1200 bytes"});
                }
                const interactive::ProbeCarrier carrier = request.payload[8U] == 2U
                    ? interactive::ProbeCarrier::lossy
                    : interactive::ProbeCarrier::lossless;
                auto result = probe_custom_packet_burst(
                    read_u32(request.payload), carrier, count,
                    std::chrono::milliseconds(spacing_ms),
                    std::chrono::milliseconds(deadline_ms), packet_size);
                if (!result) {
                    return response_for(request, result.status());
                }
                std::vector<std::uint8_t> payload;
                payload.reserve(2U + result.value().size() * 24U);
                append_u16(
                    payload,
                    static_cast<std::uint16_t>(result.value().size()));
                for (const PacketProbeObservation &observation : result.value()) {
                    append_u16(payload, observation.ordinal);
                    append_u64(payload, observation.nonce);
                    append_u64(payload, observation.rtt_us);
                    append_u16(payload, observation.arrival_rank);
                    append_u16(payload, observation.copies);
                    append_u16(
                        payload,
                        static_cast<std::uint16_t>(observation.send_error));
                }
                return response_for(
                    request, Status::success(), std::move(payload));
            }

            case local::ControlOperation::transport_route_health: {
                if (!request.payload.empty() && request.payload.size() != 8U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-route-health accepts an empty "
                               "payload or friend number and timeout"});
                }
                std::uint32_t timeout_ms = 0U;
                if (!request.payload.empty()) {
                    timeout_ms = read_u32(
                        std::span<const std::uint8_t>(request.payload)
                            .subspan(4U));
                    if (timeout_ms == 0U || timeout_ms > 600000U) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "transport-route-health heartbeat timeout "
                                   "must be 1..600000 ms"});
                    }
                }

                const local::RuntimeSnapshot current = snapshot();
                auto observation = routes::observe_route_health(
                    config_.transport.network,
                    config_.transport.socks5_proxy,
                    current.self_connection,
                    std::chrono::milliseconds(250));
                if (!observation) {
                    return response_for(request, observation.status());
                }
                if (!request.payload.empty()) {
                    auto heartbeat = probe_custom_packet(
                        read_u32(request.payload),
                        interactive::ProbeCarrier::lossless,
                        std::chrono::milliseconds(timeout_ms));
                    if (heartbeat) {
                        routes::record_application_response(
                            observation.value(), heartbeat.value().second);
                    } else {
                        routes::record_application_failure(
                            observation.value(), heartbeat.status().code());
                    }
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(routes::render_route_health(
                        observation.value())));
            }

            case local::ControlOperation::transport_route_target_health: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "transport-route-target-health requires one timeout"});
                }
                const std::uint32_t timeout_ms = read_u32(request.payload);
                if (timeout_ms == 0U || timeout_ms > 5000U) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "transport-route-target-health timeout must be 1..5000 ms"});
                }
                if (!is_strict_socks_tox_route(
                        config_.transport.network.tox_route) ||
                    config_.transport.tcp_relays.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "route target health requires an explicit "
                               "strict routed-Tox TCP relay"});
                }
                const local::RuntimeSnapshot current = snapshot();
                const auto &relay = config_.transport.tcp_relays.front();
                auto observation = routes::observe_route_target_health(
                    config_.transport.network,
                    config_.transport.socks5_proxy,
                    Socks5ProxyEndpoint{relay.host, relay.port},
                    current.self_connection,
                    std::chrono::milliseconds(timeout_ms));
                if (!observation) {
                    return response_for(request, observation.status());
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(routes::render_route_target_health(
                        observation.value())));
            }

            case local::ControlOperation::transport_set_typing: {
                if (request.payload.size() != 5U || request.payload[4U] > 1U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-set-typing requires friend number and 0/1 byte"});
                }
                const Status changed = transport_.set_typing(
                    read_u32(request.payload), request.payload[4U] != 0U);
                return response_for(
                    request, changed,
                    local::text_payload(request.payload[4U] != 0U
                                            ? "typing-on\n"
                                            : "typing-off\n"));
            }

            case local::ControlOperation::transport_send_lossless: {
                if (request.payload.size() <= 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "transport-send-lossless requires a friend number and packet"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                std::vector<std::uint8_t> packet(
                    request.payload.begin() + 4, request.payload.end());
                // The payload-size guard above implies one packet byte, but
                // keep the vector invariant explicit at the access site. GCC
                // release diagnostics do not preserve that relationship
                // through vector construction and correctly make an unchecked
                // front() a warnings-as-errors boundary.
                std::optional<protocol::Frame> decoded_iotox;
                if (!packet.empty() &&
                    packet.front() == protocol::kToxLosslessPacketId) {
                    auto frame = protocol::decode(packet);
                    if (!frame) {
                        return response_for(request, frame.status());
                    }
                    if (frame.value().type ==
                            protocol::MessageType::authority_challenge ||
                        frame.value().type ==
                            protocol::MessageType::authority_proof) {
                        return response_for(
                            request,
                            Status{
                                ErrorCode::unsupported,
                                "authority challenge/proof frames are reserved "
                                "to the canonical authority machinery"});
                    }
                    auto session = sessions_.get(friend_number);
                    if (!session) {
                        return response_for(request, session.status());
                    }
                    const Status admitted =
                        protocol::validate_application_frame_for_session(
                            session.value(), frame.value());
                    if (!admitted.ok()) {
                        return response_for(request, admitted);
                    }
                    decoded_iotox = std::move(frame).value();
                }
                const Status queued =
                    transport_.send_lossless(friend_number, packet);
                if (!queued.ok()) {
                    return response_for(request, queued);
                }
                if (decoded_iotox) {
                    record_protocol_frame(
                        friend_number, "outgoing", *decoded_iotox);
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload("queued-to-toxcore\n"));
            }

            case local::ControlOperation::protocol_send_hello: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "protocol-send-hello requires one uint32 friend number"});
                }
                const Status sent = send_hello(read_u32(request.payload));
                return response_for(
                    request, sent,
                    local::text_payload("canonical-hello-queued\n"));
            }

            case local::ControlOperation::protocol_send_confirmation: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "protocol-send-confirmation requires one "
                               "uint32 friend number"});
                }
                // This is an explicit operator retry, not merely a request to
                // advance the automatic state machine. send_confirmation()
                // reuses the first per-epoch message ID and exact canonical
                // payload, so a retry cannot rewrite the transcript.
                const Status sent = send_confirmation(read_u32(request.payload));
                return response_for(
                    request, sent,
                    local::text_payload("transcript-confirmation-queued\n"));
            }

            case local::ControlOperation::protocol_session_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "protocol-session-list payload must be empty"});
                }
                auto rendered = render_sessions(sessions_.list());
                if (!rendered) {
                    return response_for(request, rendered.status());
                }
                return response_for(
                    request, Status::success(), std::move(rendered).value());
            }

            case local::ControlOperation::protocol_session_show: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "protocol-session-show requires one uint32 friend number"});
                }
                auto session = sessions_.get(read_u32(request.payload));
                if (!session) {
                    return response_for(request, session.status());
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        local::RuntimeTree::render_peer_session(
                            session.value())));
            }

            case local::ControlOperation::identity_show: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "identity-show payload must be empty"});
                }
                if (!identity_ || !sodium_) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "stable IoTox identity is not initialized"});
                }
                std::ostringstream output;
                output << "device-public-key=" << identity_->public_key_hex() << '\n'
                       << "identity-path=" << identity_->path().string() << '\n'
                       << "algorithm=Ed25519\n"
                       << "sodium-provider=" << sodium_->loaded_path() << '\n'
                       << "sodium-version=" << sodium_->version() << '\n'
                       << "secret-at-rest=private-plaintext-seed-mode-0600\n";
                return response_for(
                    request, Status::success(), local::text_payload(output.str()));
            }

            case local::ControlOperation::authority_show: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-show payload must be empty"});
                }
                if (authority_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority ledger is not initialized"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        security::render_authority_snapshot(authority_->snapshot())));
            }

            case local::ControlOperation::authority_principal_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-principal-list payload must be empty"});
                }
                if (authority_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority ledger is not initialized"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        security::render_principals(authority_->snapshot())));
            }

            case local::ControlOperation::authority_prepare: {
                if (authority_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority ledger is not initialized"});
                }
                auto decoded = security::decode_authority_prepare_request(request.payload);
                if (!decoded) {
                    return response_for(request, decoded.status());
                }
                auto body = authority_->prepare(decoded.value());
                if (!body) {
                    return response_for(request, body.status());
                }
                return response_for(
                    request, Status::success(),
                    std::vector<std::uint8_t>(body.value().begin(), body.value().end()));
            }

            case local::ControlOperation::authority_append: {
                if (request.payload.size() != security::kAuthorityRecordBytes) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "authority-append requires one "
                                        "complete 256-byte signed record"});
                }
                if (authority_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority ledger is not initialized"});
                }
                security::AuthorityRecordBytes record{};
                std::copy(request.payload.begin(), request.payload.end(), record.begin());
                const Status appended = append_local_authority_record(record);
                if (!appended.ok()) {
                    return response_for(request, appended);
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        security::render_authority_snapshot(authority_->snapshot())));
            }

            case local::ControlOperation::authority_session_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-session-list payload must be empty"});
                }
                if (authority_sessions_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session machinery is not initialized"});
                }
                auto rendered = render_authority_sessions(
                    authority_sessions_->list());
                return rendered
                    ? response_for(request, Status::success(),
                                   std::move(rendered).value())
                    : response_for(request, rendered.status());
            }

            case local::ControlOperation::authority_session_show: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-session-show requires one uint32 friend number"});
                }
                if (authority_sessions_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session machinery is not initialized"});
                }
                auto session = authority_sessions_->get(
                    read_u32(request.payload));
                if (!session) {
                    return response_for(request, session.status());
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        security::render_peer_authority(session.value())));
            }

            case local::ControlOperation::authority_challenge_send: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-challenge-send requires one uint32 friend number"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                const Status synchronized =
                    synchronize_authority_session(friend_number);
                if (!synchronized.ok()) {
                    return response_for(request, synchronized);
                }
                const Status sent = send_authority_challenge(friend_number);
                return response_for(
                    request, sent,
                    local::text_payload("authority-challenge-queued\n"));
            }

            case local::ControlOperation::authority_proof_prepare: {
                if (request.payload.size() !=
                    4U + security::kSigningPublicKeyBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-proof-prepare requires friend "
                               "number plus 32-byte claimant key"});
                }
                if (authority_sessions_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session machinery is not initialized"});
                }
                security::SigningPublicKey claimant{};
                std::copy_n(request.payload.begin() + 4,
                            claimant.size(), claimant.begin());
                const std::uint32_t friend_number = read_u32(request.payload);
                auto current = authority_sessions_->get(friend_number);
                if (!current) {
                    return response_for(request, current.status());
                }
                const security::SigningPublicKey zero{};
                const bool replacing_ordinary_claimant =
                    current.value().local_claimant_principal != zero &&
                    current.value().local_claimant_principal != claimant;
                auto body = replacing_ordinary_claimant && identity_.has_value() &&
                        current.value().local_claimant_principal ==
                            identity_->public_key()
                    ? authority_sessions_->prepare_recovery_proof_body(
                          friend_number, identity_->public_key(), claimant,
                          unix_time_ms())
                    : authority_sessions_->prepare_proof_body(
                          friend_number, claimant, unix_time_ms());
                if (!body) {
                    publish_authority_sessions_best_effort();
                    return response_for(request, body.status());
                }
                publish_authority_sessions_best_effort();
                return response_for(
                    request, Status::success(),
                    std::vector<std::uint8_t>(
                        body.value().begin(), body.value().end()));
            }

            case local::ControlOperation::authority_proof_send: {
                if (request.payload.size() !=
                    4U + security::kAuthorityProofBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-proof-send requires friend "
                               "number plus one 256-byte signed proof"});
                }
                security::AuthorityProofBytes proof{};
                std::copy_n(request.payload.begin() + 4,
                            proof.size(), proof.begin());
                const std::uint32_t friend_number = read_u32(request.payload);
                const Status sent = send_authority_proof(
                    friend_number, proof);
                if (!sent.ok()) {
                    return response_for(request, sent);
                }
                auto session = authority_sessions_->get(friend_number);
                return session
                    ? response_for(
                          request, Status::success(),
                          local::text_payload(
                              security::render_peer_authority(
                                  session.value())))
                    : response_for(request, session.status());
            }

            case local::ControlOperation::authority_device_proof_send: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "authority-device-proof-send requires one "
                               "uint32 friend number"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                const Status sent = send_device_authority_proof(friend_number);
                if (!sent.ok()) {
                    return response_for(request, sent);
                }
                auto authority_session = authority_sessions_->get(friend_number);
                return authority_session
                    ? response_for(
                          request, Status::success(),
                          local::text_payload(
                              security::render_peer_authority(
                                  authority_session.value())))
                    : response_for(request, authority_session.status());
            }

            case local::ControlOperation::command_issue: {
                constexpr std::size_t kLegacyCommandIssueBytes = 5U;
                constexpr std::size_t kCommandIssueBytes = 14U;
                constexpr std::size_t kCommandIssueWithArgumentBytes = 15U;
                constexpr std::size_t kCommandIssueWithUpdateHeadBytes =
                    14U + protocol::kUpdateHeadRecordBytes;
                if (request.payload.size() != kLegacyCommandIssueBytes &&
                    request.payload.size() != kCommandIssueBytes &&
                    request.payload.size() !=
                        kCommandIssueWithArgumentBytes &&
                    request.payload.size() !=
                        kCommandIssueWithUpdateHeadBytes) {
                    return response_for(request,
                                        Status{ErrorCode::invalid_argument,
                                               "command-issue requires friend, "
                                               "operation, optional "
                                               "priority plus TTL, and an "
                                               "operation-specific argument"});
                }
                const auto operation = static_cast<protocol::CommandOperation>(
                    request.payload[4U]);
                if (!protocol::command_operation_policy(operation).has_value()) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               "command-issue operation is not registered"});
                }
                protocol::CommandRequest command_request;
                command_request.operation = operation;
                if (operation ==
                    protocol::CommandOperation::profile_status_set) {
                    if (request.payload.size() !=
                            kCommandIssueWithArgumentBytes ||
                        request.payload[14U] > static_cast<std::uint8_t>(
                            protocol::CommandRequest::ProfileStatus::busy)) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "profile.status.set requires one bounded "
                                   "desired-status argument"});
                    }
                    command_request.desired_profile_status =
                        static_cast<protocol::CommandRequest::ProfileStatus>(
                            request.payload[14U]);
                } else if (operation ==
                           protocol::CommandOperation::update_stage) {
                    if (request.payload.size() !=
                        kCommandIssueWithUpdateHeadBytes) {
                        return response_for(
                            request,
                            Status{ErrorCode::invalid_argument,
                                   "update.stage requires one exact accepted HEAD argument"});
                    }
                    protocol::UpdateHeadRecord head{};
                    std::copy_n(request.payload.begin() + 14U,
                                head.size(), head.begin());
                    command_request.expected_update_head = head;
                } else if (request.payload.size() ==
                               kCommandIssueWithArgumentBytes ||
                           request.payload.size() ==
                               kCommandIssueWithUpdateHeadBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "this command operation does not accept an argument"});
                }
                const bool has_scheduling = request.payload.size() !=
                    kLegacyCommandIssueBytes;
                const CommandPriority priority = has_scheduling
                    ? static_cast<CommandPriority>(request.payload[5U])
                    : CommandPriority::normal;
                const std::uint64_t ttl_ms = has_scheduling
                    ? read_u64(request.payload, 6U)
                    : 0U;
                const std::uint32_t friend_number = read_u32(request.payload);
                auto admitted = admit_outgoing_command(
                    friend_number, command_request, priority, ttl_ms);
                if (!admitted) {
                    return response_for(request, admitted.status());
                }
                if (operation == protocol::CommandOperation::device_describe) {
                    static_cast<void>(send_device_describe_request(
                        friend_number, true));
                } else {
                    static_cast<void>(send_generic_command_request(
                        friend_number, command_request, true));
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(render_command_record(admitted.value())));
            }

            case local::ControlOperation::authority_remote_delegation_send: {
                if (request.payload.size() !=
                    4U + security::kAuthorityRecordBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote delegation send requires friend "
                               "number and 256-byte signed record"});
                }
                security::AuthorityRecordBytes record{};
                std::copy(request.payload.begin() + 4,
                          request.payload.end(), record.begin());
                const Status sent = send_remote_delegation_record(
                    read_u32(request.payload), record);
                return response_for(
                    request, sent,
                    sent.ok() ? local::text_payload(
                                    "remote-delegation-queued\n")
                              : std::vector<std::uint8_t>{});
            }

            case local::ControlOperation::authority_remote_delegation_prepare: {
                constexpr std::size_t kPayloadBytes =
                    4U + security::kSigningPublicKeyBytes + 1U + 3U + 8U;
                if (request.payload.size() != kPayloadBytes) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "remote delegation prepare requires friend, owner "
                            "key, role, reserved bytes, and capabilities"});
                }
                if (authority_sessions_ == nullptr || !identity_.has_value()) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session or identity is not initialized"});
                }
                if (request.payload[37U] != 0U || request.payload[38U] != 0U ||
                    request.payload[39U] != 0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote delegation reserved bytes must be zero"});
                }
                security::SigningPublicKey owner{};
                std::copy_n(request.payload.begin() + 4, owner.size(), owner.begin());
                const auto role = static_cast<security::PrincipalRole>(
                    request.payload[36U]);
                const std::uint64_t capabilities = read_u64(
                    std::span<const std::uint8_t>(request.payload).subspan(40U, 8U));
                auto peer = authority_sessions_->get(read_u32(request.payload));
                if (!peer) {
                    return response_for(request, peer.status());
                }
                if (!peer.value().connected || !peer.value().feature_negotiated ||
                    peer.value().claimant_state !=
                        security::AuthorityClaimantState::proof_sent ||
                    peer.value().local_claimant_principal != owner) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "the reconstructed owner must first prove "
                               "itself to this connected peer"});
                }
                if (role == security::PrincipalRole::none ||
                    role == security::PrincipalRole::owner) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote self-delegation requires a non-owner role"});
                }
                const std::uint64_t peer_capability_mask =
                    security::authority_capability_mask(
                        peer.value().peer_authority_format);
                if (capabilities == 0U ||
                    (capabilities & ~peer_capability_mask) != 0U ||
                    (capabilities & ~security::role_capability_ceiling(
                                        role,
                                        peer.value().peer_authority_format)) !=
                        0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote self-delegation capabilities exceed the "
                               "exact peer ledger format or role ceiling"});
                }
                if (peer.value().peer_authority_sequence ==
                    std::numeric_limits<std::uint64_t>::max()) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "peer authority sequence is exhausted"});
                }
                security::AuthorityRecord record;
                record.format = peer.value().peer_authority_format;
                record.action = security::AuthorityAction::grant;
                record.role = role;
                record.sequence = peer.value().peer_authority_sequence + 1U;
                record.ownership_epoch = peer.value().peer_authority_epoch;
                record.capabilities = capabilities;
                record.device = peer.value().peer_verifier_device;
                record.issuer = owner;
                record.subject = identity_->public_key();
                record.previous_digest = peer.value().peer_authority_tail_digest;
                auto body = security::encode_authority_record_body(record);
                return body
                    ? response_for(request, Status::success(),
                          std::vector<std::uint8_t>(body.value().begin(), body.value().end()))
                    : response_for(request, body.status());
            }

            case local::ControlOperation::authority_remote_delegation_retry: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote delegation retry requires one uint32 friend number"});
                }
                const Status sent = retry_remote_delegation_record(
                    read_u32(request.payload));
                return response_for(
                    request, sent,
                    sent.ok() ? local::text_payload(
                                    "remote-delegation-requeued\n")
                              : std::vector<std::uint8_t>{});
            }

            case local::ControlOperation::authority_remote_delegation_show: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote delegation show requires one uint32 friend number"});
                }
                std::scoped_lock lock(delegation_mutex_);
                const auto found = outgoing_delegations_.find(
                    read_u32(request.payload));
                if (found == outgoing_delegations_.end()) {
                    return response_for(
                        request,
                        Status{ErrorCode::not_found,
                               "no frozen remote delegation exists for this friend"});
                }
                std::ostringstream output;
                output << "state="
                       << (found->second.result.has_value()
                               ? "result-received"
                               : "awaiting-result")
                       << '\n'
                       << "peer-public-key="
                       << found->second.transport_public_key << '\n'
                       << "request-message-id="
                       << found->second.request_message_id << '\n';
                if (found->second.result.has_value()) {
                    output << "outcome="
                           << protocol::to_string(
                                  found->second.result->outcome)
                           << '\n'
                           << "authority-epoch="
                           << found->second.result->ownership_epoch << '\n'
                           << "authority-sequence="
                           << found->second.result->authority_sequence << '\n'
                           << "authority-tail-digest="
                           << security::hex(
                                  found->second.result->authority_tail_digest)
                           << '\n';
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(output.str()));
            }

            case local::ControlOperation::authority_remote_revocation_prepare: {
                constexpr std::size_t kPayloadBytes =
                    4U + security::kSigningPublicKeyBytes * 2U;
                if (request.payload.size() != kPayloadBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote revocation prepare requires friend, "
                               "owner key, and subject key"});
                }
                if (authority_sessions_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session machinery is not initialized"});
                }
                security::SigningPublicKey owner{};
                security::SigningPublicKey subject{};
                std::copy_n(request.payload.begin() + 4, owner.size(),
                            owner.begin());
                std::copy_n(request.payload.begin() + 36, subject.size(),
                            subject.begin());
                auto peer = authority_sessions_->get(read_u32(request.payload));
                if (!peer) {
                    return response_for(request, peer.status());
                }
                if (!peer.value().connected ||
                    !peer.value().feature_negotiated ||
                    peer.value().claimant_state !=
                        security::AuthorityClaimantState::proof_sent ||
                    peer.value().local_claimant_principal != owner) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "the reconstructed owner must first prove "
                               "itself to this connected peer"});
                }
                if (peer.value().peer_authority_sequence ==
                    std::numeric_limits<std::uint64_t>::max()) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "peer authority sequence is exhausted"});
                }
                security::AuthorityRecord record;
                record.format = peer.value().peer_authority_format;
                record.action = security::AuthorityAction::revoke;
                record.role = security::PrincipalRole::none;
                record.sequence = peer.value().peer_authority_sequence + 1U;
                record.ownership_epoch = peer.value().peer_authority_epoch;
                record.device = peer.value().peer_verifier_device;
                record.issuer = owner;
                record.subject = subject;
                record.previous_digest =
                    peer.value().peer_authority_tail_digest;
                auto body = security::encode_authority_record_body(record);
                return body
                    ? response_for(
                          request, Status::success(),
                          std::vector<std::uint8_t>(
                              body.value().begin(), body.value().end()))
                    : response_for(request, body.status());
            }

            case local::ControlOperation::authority_remote_successor_prepare: {
                constexpr std::size_t kLegacyPayloadBytes =
                    4U + security::kSigningPublicKeyBytes * 2U;
                constexpr std::size_t kPayloadBytes =
                    kLegacyPayloadBytes + sizeof(std::uint64_t);
                if (request.payload.size() != kLegacyPayloadBytes &&
                    request.payload.size() != kPayloadBytes) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "remote successor prepare requires "
                                        "friend, current owner key, "
                                        "successor key, and optional exact "
                                        "owner capabilities"});
                }
                if (authority_sessions_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session machinery is not initialized"});
                }
                security::SigningPublicKey owner{};
                security::SigningPublicKey successor{};
                std::copy_n(request.payload.begin() + 4, owner.size(),
                            owner.begin());
                std::copy_n(request.payload.begin() + 36, successor.size(),
                            successor.begin());
                const std::uint64_t successor_capabilities =
                    request.payload.size() == kPayloadBytes
                    ? read_u64(std::span<const std::uint8_t>(request.payload)
                                   .subspan(kLegacyPayloadBytes, 8U))
                    : security::kAuthorityV1Capabilities;
                if ((successor_capabilities &
                     security::kConstitutionalOwnerCapabilities) !=
                        security::kConstitutionalOwnerCapabilities ||
                    (successor_capabilities &
                     ~security::kAuthorityV3Capabilities) != 0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "successor capabilities must contain every "
                               "constitutional owner bit and no unknown bit"});
                }
                if (owner == successor) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "successor owner must differ from the current owner"});
                }
                auto peer = authority_sessions_->get(read_u32(request.payload));
                if (!peer) {
                    return response_for(request, peer.status());
                }
                if (!peer.value().connected ||
                    !peer.value().feature_negotiated ||
                    peer.value().claimant_state !=
                        security::AuthorityClaimantState::proof_sent ||
                    peer.value().local_claimant_principal != owner) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "the current owner must first prove itself "
                               "to this connected peer"});
                }
                if ((successor_capabilities &
                     ~security::authority_capability_mask(
                         peer.value().peer_authority_format)) != 0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "successor capabilities exceed the exact "
                               "peer authority ledger format"});
                }
                if (peer.value().peer_authority_sequence ==
                    std::numeric_limits<std::uint64_t>::max()) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "peer authority sequence is exhausted"});
                }
                security::AuthorityRecord record;
                record.format = peer.value().peer_authority_format;
                record.action = security::AuthorityAction::grant;
                record.role = security::PrincipalRole::owner;
                record.sequence = peer.value().peer_authority_sequence + 1U;
                record.ownership_epoch = peer.value().peer_authority_epoch;
                record.capabilities = successor_capabilities;
                record.device = peer.value().peer_verifier_device;
                record.issuer = owner;
                record.subject = successor;
                record.previous_digest =
                    peer.value().peer_authority_tail_digest;
                auto body = security::encode_authority_record_body(record);
                return body
                    ? response_for(
                          request, Status::success(),
                          std::vector<std::uint8_t>(
                              body.value().begin(), body.value().end()))
                    : response_for(request, body.status());
            }

            case local::ControlOperation::authority_remote_epoch_transition_prepare: {
                constexpr std::size_t kLegacyPayloadBytes =
                    4U + security::kSigningPublicKeyBytes;
                constexpr std::size_t kPayloadBytes =
                    kLegacyPayloadBytes + sizeof(std::uint64_t);
                if (request.payload.size() != kLegacyPayloadBytes &&
                    request.payload.size() != kPayloadBytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "remote epoch transition prepare requires "
                               "friend, successor "
                               "key, and optional exact owner capabilities"});
                }
                if (authority_sessions_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session machinery is not initialized"});
                }
                security::SigningPublicKey successor{};
                std::copy_n(request.payload.begin() + 4, successor.size(),
                            successor.begin());
                const std::uint64_t successor_capabilities =
                    request.payload.size() == kPayloadBytes
                    ? read_u64(std::span<const std::uint8_t>(request.payload)
                                   .subspan(kLegacyPayloadBytes, 8U))
                    : security::kAuthorityV1Capabilities;
                if ((successor_capabilities &
                     security::kConstitutionalOwnerCapabilities) !=
                        security::kConstitutionalOwnerCapabilities ||
                    (successor_capabilities &
                     ~security::kAuthorityV3Capabilities) != 0U) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "epoch transition capabilities must contain every "
                            "constitutional owner bit and no unknown bit"});
                }
                auto peer = authority_sessions_->get(read_u32(request.payload));
                if (!peer) {
                    return response_for(request, peer.status());
                }
                if (!peer.value().connected ||
                    !peer.value().feature_negotiated ||
                    peer.value().claimant_state !=
                        security::AuthorityClaimantState::proof_sent ||
                    peer.value().local_claimant_principal != successor) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "the nominated successor must first prove "
                               "itself to this connected peer"});
                }
                if ((successor_capabilities &
                     ~security::authority_capability_mask(
                         peer.value().peer_authority_format)) != 0U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "epoch transition capabilities exceed the "
                               "exact peer authority ledger format"});
                }
                if (peer.value().peer_authority_epoch ==
                    std::numeric_limits<std::uint64_t>::max()) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "peer ownership epoch is exhausted"});
                }
                security::AuthorityRecord record;
                record.format = peer.value().peer_authority_format;
                record.action = security::AuthorityAction::epoch_transition;
                record.role = security::PrincipalRole::owner;
                record.sequence = 1U;
                record.ownership_epoch = peer.value().peer_authority_epoch + 1U;
                record.capabilities = successor_capabilities;
                record.device = peer.value().peer_verifier_device;
                record.issuer = successor;
                record.subject = successor;
                record.previous_digest =
                    peer.value().peer_authority_tail_digest;
                auto body = security::encode_authority_record_body(record);
                return body
                    ? response_for(
                          request, Status::success(),
                          std::vector<std::uint8_t>(
                              body.value().begin(), body.value().end()))
                    : response_for(request, body.status());
            }

            case local::ControlOperation::authority_remote_migration_prepare:
            case local::ControlOperation::
                authority_remote_v3_migration_prepare: {
                const bool migrate_v3 =
                    request.operation ==
                    local::ControlOperation::
                        authority_remote_v3_migration_prepare;
                constexpr std::size_t kV2PayloadBytes =
                    4U + security::kSigningPublicKeyBytes;
                constexpr std::size_t kV3PayloadBytes =
                    kV2PayloadBytes + sizeof(std::uint64_t);
                const std::size_t expected_payload_bytes =
                    migrate_v3 ? kV3PayloadBytes : kV2PayloadBytes;
                if (request.payload.size() != expected_payload_bytes) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               migrate_v3 ? "remote authority v3 migration "
                                            "prepare requires friend, "
                                            "current owner key, and exact "
                                            "current capabilities"
                                          : "remote authority migration "
                                            "prepare requires friend and "
                                            "current owner key"});
                }
                if (authority_sessions_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "authority session machinery is not initialized"});
                }
                security::SigningPublicKey owner{};
                std::copy_n(request.payload.begin() + 4, owner.size(),
                            owner.begin());
                auto peer = authority_sessions_->get(read_u32(request.payload));
                if (!peer) {
                    return response_for(request, peer.status());
                }
                if (!peer.value().connected ||
                    !peer.value().feature_negotiated ||
                    peer.value().claimant_state !=
                        security::AuthorityClaimantState::proof_sent ||
                    peer.value().local_claimant_principal != owner) {
                    return response_for(
                        request,
                        Status{ErrorCode::protocol_error,
                               "the current owner must first prove itself "
                               "to this connected peer"});
                }
                if (!peer.value().authority_v2_negotiated ||
                    (migrate_v3 && !peer.value().authority_v3_negotiated)) {
                    return response_for(
                        request,
                        Status{ErrorCode::unsupported,
                               migrate_v3
                                   ? "peer session did not negotiate "
                                     "authority-ledger-v3 migration support"
                                   : "peer session did not negotiate "
                                     "authority-ledger-v2 migration support"});
                }
                if (peer.value().peer_authority_format !=
                    (migrate_v3 ? security::AuthorityLedgerFormat::v2
                                : security::AuthorityLedgerFormat::v1)) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::protocol_error,
                            migrate_v3
                                ? "peer authority ledger is not an unmigrated v2 head"
                                : "peer authority ledger is not an unmigrated v1 head"});
                }
                if (peer.value().peer_authority_sequence ==
                    std::numeric_limits<std::uint64_t>::max()) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "peer authority sequence is exhausted"});
                }
                security::AuthorityRecord record;
                record.format = migrate_v3
                                    ? security::AuthorityLedgerFormat::v3
                                    : security::AuthorityLedgerFormat::v2;
                record.action = migrate_v3
                                    ? security::AuthorityAction::migrate_v3
                                    : security::AuthorityAction::migrate_v2;
                record.role = security::PrincipalRole::owner;
                record.sequence = peer.value().peer_authority_sequence + 1U;
                record.ownership_epoch = peer.value().peer_authority_epoch;
                record.capabilities =
                    migrate_v3 ? read_u64(std::span<const std::uint8_t>(
                                              request.payload)
                                              .subspan(kV2PayloadBytes, 8U))
                               : security::kAuthorityV1Capabilities;
                if (migrate_v3 && (record.capabilities &
                                   ~security::kAuthorityV2Capabilities) != 0U) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "authority v3 migration capabilities exceed the v2 mask"});
                }
                record.device = peer.value().peer_verifier_device;
                record.issuer = owner;
                record.subject = owner;
                record.previous_digest =
                    peer.value().peer_authority_tail_digest;
                auto body = security::encode_authority_record_body(record);
                return body
                    ? response_for(
                          request, Status::success(),
                          std::vector<std::uint8_t>(
                              body.value().begin(), body.value().end()))
                    : response_for(request, body.status());
            }

            case local::ControlOperation::protocol_device_describe: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "device-describe requires one uint32 friend number"});
                }
                auto description = send_device_describe_request(
                    read_u32(request.payload));
                return description
                    ? response_for(
                          request, Status::success(),
                          local::text_payload(
                              protocol::render_peer_description(
                                  description.value())))
                    : response_for(request, description.status());
            }

            case local::ControlOperation::protocol_peer_description_show: {
                if (request.payload.size() != 4U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "peer-description requires one uint32 friend number"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                auto description = peer_description(friend_number);
                if (!description) {
                    return response_for(request, description.status());
                }
                // This read is also an exact projection barrier: the same
                // immutable snapshot is committed to the ratox-style tree and
                // returned on the control socket.
                auto key = peer_key_for(friend_number);
                if (!key) {
                    return response_for(request, key.status());
                }
                const Status projected = runtime_.publish_peer_description(
                    key.value(), description.value());
                if (!projected.ok()) {
                    return response_for(request, projected);
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        protocol::render_peer_description(
                            description.value())));
            }

            case local::ControlOperation::command_store_show: {
                if (!request.payload.empty()) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "command-store-show payload must be empty"});
                }
                if (command_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "durable command store is not initialized"});
                }
                const std::string rendered =
                    render_command_snapshot(command_store_->snapshot());
                if (rendered.size() > local::kControlMaxPayloadSize) {
                    return response_for(
                        request,
                        Status{ErrorCode::resource_exhausted,
                               "rendered command store exceeds local control "
                               "capacity; inspect the runtime commands tree"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(rendered));
            }

            case local::ControlOperation::command_record_show: {
                constexpr std::size_t kCommandRecordKeyBytes =
                    1U + kCommandPeerKeyBytes + 8U + 8U;
                if (request.payload.size() != kCommandRecordKeyBytes) {
                    return response_for(
                        request,
                        Status{
                            ErrorCode::invalid_argument,
                            "command-record-show requires a direction, 32-byte "
                            "peer key, sender epoch, and message id"});
                }
                const auto direction =
                    static_cast<CommandDirection>(request.payload.front());
                if (direction != CommandDirection::incoming &&
                    direction != CommandDirection::outgoing) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "command-record-show direction is invalid"});
                }
                if (command_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "durable command store is not initialized"});
                }
                DurableCommandKey key;
                key.direction = direction;
                std::copy_n(request.payload.begin() + 1,
                            key.peer_public_key.size(),
                            key.peer_public_key.begin());
                key.sender_epoch = read_u64(
                    request.payload, 1U + kCommandPeerKeyBytes);
                key.message_id = read_u64(
                    request.payload, 1U + kCommandPeerKeyBytes + 8U);
                auto record = command_store_->find(key);
                if (!record) {
                    return response_for(request, record.status());
                }
                if (!record.value().has_value()) {
                    return response_for(
                        request,
                        Status{ErrorCode::not_found,
                               "durable command record was not found"});
                }
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        render_command_record(record.value().value())));
            }

            case local::ControlOperation::command_cancel: {
                constexpr std::size_t kCommandRecordKeyBytes =
                    1U + kCommandPeerKeyBytes + 8U + 8U;
                if (request.payload.size() != kCommandRecordKeyBytes ||
                    request.payload.front() !=
                        static_cast<std::uint8_t>(CommandDirection::outgoing)) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "command-cancel requires an outgoing peer "
                               "key, sender epoch, and message id"});
                }
                if (command_store_ == nullptr) {
                    return response_for(
                        request,
                        Status{ErrorCode::internal_error,
                               "durable command store is not initialized"});
                }
                DurableCommandKey key;
                key.direction = CommandDirection::outgoing;
                std::copy_n(request.payload.begin() + 1,
                            key.peer_public_key.size(),
                            key.peer_public_key.begin());
                key.sender_epoch = read_u64(
                    request.payload, 1U + kCommandPeerKeyBytes);
                key.message_id = read_u64(
                    request.payload, 1U + kCommandPeerKeyBytes + 8U);
                std::scoped_lock durable_lock(durable_command_mutex_);
                auto cancelled = command_store_->cancel_before_start(
                    key, command_schedule_time_ms());
                if (!cancelled) {
                    return response_for(request, cancelled.status());
                }
                const Status projected = refresh_command_projection();
                if (!projected.ok()) {
                    return response_for(request, projected);
                }
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(),
                    local::text_payload(
                        render_command_record(cancelled.value())));
            }

            case local::ControlOperation::transport_file_send_path: {
                if (request.payload.size() <= 4U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "file-send requires a friend number and absolute path"});
                }
                auto path = decode_absolute_path(request.payload, 4U);
                if (!path) {
                    return response_for(request, path.status());
                }
                auto transfer = transfers_.send_path(read_u32(request.payload), path.value());
                if (!transfer) {
                    return response_for(request, transfer.status());
                }
                refresh_transfer_snapshot();
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(),
                    local::text_payload(render_file_transfer(transfer.value()) + "\n"));
            }

            case local::ControlOperation::transport_file_receive_path: {
                if (request.payload.size() <= 8U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "file-receive requires friend number, file "
                               "number, and absolute path"});
                }
                auto path = decode_absolute_path(request.payload, 8U);
                if (!path) {
                    return response_for(request, path.status());
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                const std::uint32_t file_number =
                    read_u32(std::span<const std::uint8_t>{request.payload}.subspan(4U));
                auto transfer = transfers_.receive_to_path(
                    friend_number, file_number, path.value());
                if (!transfer) {
                    return response_for(request, transfer.status());
                }
                refresh_transfer_snapshot();
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(),
                    local::text_payload(render_file_transfer(transfer.value()) + "\n"));
            }

            case local::ControlOperation::transport_file_cancel: {
                if (request.payload.size() != 8U) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "file-cancel requires friend number and file number"});
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                const std::uint32_t file_number =
                    read_u32(std::span<const std::uint8_t>{request.payload}.subspan(4U));
                const auto sync_before = incoming_transfer_for(
                    transfers_.list(), friend_number, file_number);
                auto controlled = transfers_.control(
                    friend_number, file_number, TransferControl::cancel);
                service_sync_local_cancel_best_effort(
                    friend_number, file_number, sync_before,
                    controlled ? Status::success() : controlled.status());
                refresh_transfer_snapshot();
                publish_snapshot_best_effort();
                return controlled
                    ? response_for(
                          request, Status::success(),
                          local::text_payload(
                              render_file_transfer(controlled.value()) + "\n"))
                    : response_for(request, controlled.status());
            }

            case local::ControlOperation::transport_file_control: {
                if (request.payload.size() != 9U) {
                    return response_for(
                        request,
                        Status{ErrorCode::invalid_argument,
                               "file-control requires friend number, file "
                               "number, and action byte"});
                }
                auto control = decode_transfer_control_byte(request.payload[8U]);
                if (!control) {
                    return response_for(request, control.status());
                }
                const std::uint32_t friend_number = read_u32(request.payload);
                const std::uint32_t file_number =
                    read_u32(std::span<const std::uint8_t>{request.payload}.subspan(4U));
                const auto sync_before =
                    control.value() == TransferControl::cancel
                        ? incoming_transfer_for(
                              transfers_.list(), friend_number, file_number)
                        : std::optional<FileTransferRecord>{};
                auto controlled = transfers_.control(
                    friend_number, file_number, control.value());
                if (control.value() == TransferControl::cancel) {
                    service_sync_local_cancel_best_effort(
                        friend_number, file_number, sync_before,
                        controlled ? Status::success()
                                   : controlled.status());
                }
                refresh_transfer_snapshot();
                publish_snapshot_best_effort();
                return controlled
                    ? response_for(
                          request, Status::success(),
                          local::text_payload(
                              render_file_transfer(controlled.value()) + "\n"))
                    : response_for(request, controlled.status());
            }

            case local::ControlOperation::transport_file_list: {
                if (!request.payload.empty()) {
                    return response_for(
                        request, Status{ErrorCode::invalid_argument,
                                        "file-list payload must be empty"});
                }

                // `files` is the authoritative live-transfer read. Commit the
                // same manager snapshot to the ratox-style tree and aggregate
                // status before replying, so an empty response cannot race a
                // stale `transfers/` entry or stale active/offer count.
                refresh_transfer_snapshot();
                publish_snapshot_best_effort();
                return response_for(
                    request, Status::success(), render_transfers(transfers_.list()));
            }
        }
        return response_for(
            request, Status{ErrorCode::unsupported, "local control operation is not implemented"});
    }

